// ─── Alpha canvas setup ───────────────────────────────────────────
const alphaCanvas = document.getElementById("alphaCanvas");
const alphaCtx    = alphaCanvas.getContext("2d");
let alphaWidth    = 0;
let alphaHeight   = 0;
let alphaResizeRecoveryTimer = 0;

function scheduleAlphaResizeRecovery(delay = 120) {
  if (alphaResizeRecoveryTimer) window.clearTimeout(alphaResizeRecoveryTimer);
  alphaResizeRecoveryTimer = window.setTimeout(() => {
    alphaResizeRecoveryTimer = 0;
    if (activeSection !== "alpha" || alphaSection?.hidden) return;
    alphaRenderFailed = false;
    if (!resizeAlphaCanvas()) {
      scheduleAlphaResizeRecovery(Math.min(420, delay + 80));
      return;
    }
    scheduleAlphaRender({ force: true });
  }, Math.max(16, delay));
}

function resizeAlphaCanvas() {
  const dpr  = window.devicePixelRatio || 1;
  const rect = alphaCanvas.getBoundingClientRect();
  if (rect.width < 2 || rect.height < 2) {
    alphaWidth = 0;
    alphaHeight = 0;
    alphaCanvas.width = 0;
    alphaCanvas.height = 0;
    return false;
  }
  alphaWidth  = Math.round(rect.width  * dpr);
  alphaHeight = Math.round(rect.height * dpr);
  alphaCanvas.width  = alphaWidth;
  alphaCanvas.height = alphaHeight;
  alphaCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
  return true;
}

window.addEventListener("resize", () => {
  if (activeSection !== "alpha") return;
  alphaRenderFailed = false;
  resizeAlphaCanvas();
  scheduleAlphaRender({ force: true });
  scheduleAlphaResizeRecovery(120);
});
window.addEventListener("beforeunload", () => saveAlphaCanvasSessionState());
if (typeof ResizeObserver !== "undefined" && alphaCanvas?.parentElement) {
  const alphaStageObserver = new ResizeObserver(() => {
    if (activeSection !== "alpha") return;
    alphaRenderFailed = false;
    resizeAlphaCanvas();
    scheduleAlphaRender({ force: true });
    scheduleAlphaResizeRecovery(80);
  });
  alphaStageObserver.observe(alphaCanvas.parentElement);
}

