function ensureTradingBrokerLogoBadge() {
  if (!workspaceCrumb || !workspaceFolderName) return null;
  let badge = workspaceCrumb.querySelector(".trading-broker-header-badge");
  if (badge) return badge;
  badge = document.createElement("span");
  badge.className = "trading-broker-header-badge";
  badge.setAttribute("aria-hidden", "true");
  const logo = document.createElement("span");
  logo.className = "trading-broker-logo-mark";
  badge.appendChild(logo);
  workspaceFolderName.insertAdjacentElement("beforebegin", badge);
  return badge;
}

function syncTradingBrokerLogoBadge(kind = "") {
  const badge = ensureTradingBrokerLogoBadge();
  if (!badge) return;
  const logo = badge.firstElementChild;
  const normalizedKind = String(kind || "").trim().toLowerCase();
  badge.hidden = !normalizedKind;
  if (!(logo instanceof HTMLElement)) return;
  logo.className = "trading-broker-logo-mark";
  if (normalizedKind) logo.classList.add(`trading-broker-logo-${normalizedKind}`);
}
