function setCanvasDropdownScrim(open) {
  alphaCanvasWrap?.classList.toggle("dropdown-scrim-active", !!open);
  if (canvasDropdownScrim) canvasDropdownScrim.hidden = !open;
}

if (typeof window !== "undefined") {
  window.__forgeSetDropdownScrim = setCanvasDropdownScrim;
}

function setProfileMenuOpen(open) {
  if (!profileMenu || !profileBtn) return;
  profileMenu.hidden = !open;
  profileBtn.setAttribute("aria-expanded", String(!!open));
  setCanvasDropdownScrim(!!open);
}

profileBtn?.addEventListener("click", (e) => {
  e.stopPropagation();
  setProfileMenuOpen(profileMenu?.hidden);
});

document.addEventListener("click", (e) => {
  if (!profileMenu || profileMenu.hidden) return;
  if (e.target?.closest?.("#profileMenu, #profileBtn")) return;
  setProfileMenuOpen(false);
});

window.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && profileMenu && !profileMenu.hidden) setProfileMenuOpen(false);
});

profileMenu?.addEventListener("click", (e) => {
  const btn = e.target?.closest?.("[data-profile-action]");
  if (!btn) return;
  const action = btn.dataset.profileAction;
  setProfileMenuOpen(false);
  if (action === "mcp") {
    if (typeof openMcpOverlay === "function") openMcpOverlay();
    return;
  }
  if (action === "docs") {
    if (typeof openDocsOverlay === "function") openDocsOverlay();
    return;
  }
  if (action === "daemon") {
    if (typeof openDocsOverlay === "function") openDocsOverlay({ scrollTo: "docs-daemon" });
    return;
  }
  if (action === "settings" || action === "api") {
    if (typeof openProviderOverlay === "function") openProviderOverlay();
    return;
  }
  if (action === "voice-api") {
    if (typeof openProviderOverlay === "function") openProviderOverlay({ focus: "voice" });
    return;
  }
  if (action === "archive") {
    openArchiveOverlay();
    return;
  }
  // Other profile surfaces are still stubs.
  console.log(`[profile-menu] action=${action}`);
});

// ── Archive overlay ───────────────────────────────────────────────
const archiveOverlay = document.getElementById("archiveOverlay");
const archiveList = document.getElementById("archiveList");
const archiveEmpty = document.getElementById("archiveEmpty");

function archivedForgeJobs() {
  return forgeJobs
    .filter((j) => String(j.status || "").toLowerCase() === "archived")
    .sort((a, b) => {
      const ms = (j) => j.lastModifiedMs || j.last_modified_ms || j.createdMs || j.created_ms || 0;
      return ms(b) - ms(a);
    });
}

function renderArchiveList() {
  if (!archiveList || !archiveEmpty) return;
  const archived = archivedForgeJobs();
  if (!archived.length) {
    archiveList.innerHTML = "";
    archiveList.hidden = true;
    archiveEmpty.hidden = false;
    return;
  }
  archiveEmpty.hidden = true;
  archiveList.hidden = false;
  archiveList.innerHTML = "";
  for (const job of archived) {
    const jobId = job.jobId || job.job_id || "";
    const row = document.createElement("div");
    row.className = "archive-item";
    row.dataset.jobId = jobId;
    const title = document.createElement("div");
    title.className = "archive-item-title";
    title.textContent = forgeJobLabel(job);
    const ms = job.lastModifiedMs || job.last_modified_ms || job.createdMs || job.created_ms || 0;
    const meta = document.createElement("div");
    meta.className = "archive-item-meta";
    meta.textContent = ms ? new Date(ms).toLocaleString() : "—";
    const actions = document.createElement("div");
    actions.className = "archive-item-actions";
    const restoreBtn = document.createElement("button");
    restoreBtn.type = "button";
    restoreBtn.className = "archive-item-btn";
    restoreBtn.textContent = "Restore";
    restoreBtn.addEventListener("click", async () => {
      try {
        await updateForgeJobAction("restore", null, jobId);
        renderArchiveList();
      } catch (_) {/* already logged */}
    });
    const deleteBtn = document.createElement("button");
    deleteBtn.type = "button";
    deleteBtn.className = "archive-item-btn danger";
    deleteBtn.textContent = "Delete";
    deleteBtn.addEventListener("click", async () => {
      try {
        await updateForgeJobAction("delete", null, jobId);
        renderArchiveList();
      } catch (_) {/* already logged */}
    });
    actions.appendChild(restoreBtn);
    actions.appendChild(deleteBtn);
    row.appendChild(title);
    row.appendChild(meta);
    row.appendChild(actions);
    archiveList.appendChild(row);
  }
}

function openArchiveOverlay() {
  if (!archiveOverlay) return;
  if (typeof libraryOverlay !== "undefined" && libraryOverlay && !libraryOverlay.hidden && typeof closeLibraryOverlay === "function") closeLibraryOverlay();
  if (typeof programsOverlay !== "undefined" && programsOverlay && !programsOverlay.hidden && typeof closeProgramsOverlay === "function") closeProgramsOverlay();
  if (typeof docsOverlay !== "undefined" && docsOverlay && !docsOverlay.hidden && typeof closeDocsOverlay === "function") closeDocsOverlay();
  archiveOverlay.hidden = false;
  renderArchiveList();
}

function closeArchiveOverlay() {
  if (archiveOverlay) archiveOverlay.hidden = true;
}

window.addEventListener("keydown", (event) => {
  if (event.key === "Escape" && archiveOverlay && !archiveOverlay.hidden) {
    closeArchiveOverlay();
  }
});

document.addEventListener("click", (event) => {
  if (!archiveOverlay || archiveOverlay.hidden) return;
  if (event.target === archiveOverlay) closeArchiveOverlay();
});

