const docsOverlay     = document.getElementById("docsOverlay");
const docsClose       = document.getElementById("docsClose");
const docsContent     = document.getElementById("docsContent");
const alphaPanelEl    = document.querySelector(".alpha-panel");
const alphaDocsToc    = document.getElementById("alphaDocsToc");
const docsTocLinks    = document.querySelectorAll(".panel-docs-toc-link");

function setTopbarDocsMode(on) {
  if (typeof canvasTopbar !== "undefined") {
    canvasTopbar?.classList.toggle("topbar-docs-mode", !!on);
  }
}

function setAlphaPanelDocsMode(on) {
  alphaPanelEl?.classList.toggle("docs-mode", !!on);
  if (alphaDocsToc) alphaDocsToc.hidden = !on;
}

function openDocsOverlay(options) {
  if (!docsOverlay) return;
  if (typeof libraryOverlay !== "undefined" && libraryOverlay && !libraryOverlay.hidden && typeof closeLibraryOverlay === "function") closeLibraryOverlay();
  if (typeof programsOverlay !== "undefined" && programsOverlay && !programsOverlay.hidden && typeof closeProgramsOverlay === "function") closeProgramsOverlay();
  if (typeof mcpOverlay !== "undefined" && mcpOverlay && !mcpOverlay.hidden && typeof closeMcpOverlay === "function") closeMcpOverlay();
  if (typeof providerOverlay !== "undefined" && providerOverlay && !providerOverlay.hidden && typeof closeProviderOverlay === "function") closeProviderOverlay();
  docsOverlay.hidden = false;
  setTopbarDocsMode(true);
  setAlphaPanelDocsMode(true);

  const targetId = options && options.scrollTo;
  if (targetId) {
    const target = document.getElementById(targetId);
    if (target && docsContent) {
      requestAnimationFrame(() => {
        docsContent.scrollTo({ top: target.offsetTop - 24, behavior: "auto" });
      });
    }
    docsTocLinks.forEach((l) => l.classList.toggle("active", l.dataset.target === targetId));
  } else {
    if (docsContent) docsContent.scrollTop = 0;
    docsTocLinks.forEach((l, i) => l.classList.toggle("active", i === 0));
  }
}

function closeDocsOverlay() {
  if (docsOverlay) docsOverlay.hidden = true;
  setTopbarDocsMode(false);
  setAlphaPanelDocsMode(false);
}

docsClose?.addEventListener("click", closeDocsOverlay);

docsTocLinks.forEach((link) => {
  link.addEventListener("click", (e) => {
    e.preventDefault();
    const targetId = link.dataset.target;
    const target = targetId ? document.getElementById(targetId) : null;
    if (target && docsContent) {
      docsContent.scrollTo({ top: target.offsetTop - 24, behavior: "smooth" });
    }
    docsTocLinks.forEach((l) => l.classList.toggle("active", l === link));
  });
});

// Scroll-spy: highlight active TOC entry based on scroll position.
docsContent?.addEventListener("scroll", () => {
  if (!docsContent) return;
  const scrollTop = docsContent.scrollTop;
  let activeId = null;
  docsTocLinks.forEach((link) => {
    const targetId = link.dataset.target;
    const target = targetId ? document.getElementById(targetId) : null;
    if (target && target.offsetTop - 80 <= scrollTop) activeId = targetId;
  });
  if (activeId) {
    docsTocLinks.forEach((l) => l.classList.toggle("active", l.dataset.target === activeId));
  }
});

window.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && docsOverlay && !docsOverlay.hidden) closeDocsOverlay();
});
