const forgeCustomScrollbarBindings = new Map();

function pruneForgeCustomScrollbarBindings() {
  for (const [scroller, binding] of forgeCustomScrollbarBindings.entries()) {
    if (scroller?.isConnected && binding?.rail?.isConnected) continue;
    scroller?.removeEventListener?.("scroll", binding?.onScroll);
    scroller?.removeEventListener?.("input", binding?.onInput);
    binding?.resizeObserver?.disconnect?.();
    binding?.mutationObserver?.disconnect?.();
    if (binding?.raf) cancelAnimationFrame(binding.raf);
    forgeCustomScrollbarBindings.delete(scroller);
  }
}

function createForgeScrollbarElements() {
  const rail = document.createElement("div");
  rail.className = "forge-rail-scrollbar";
  const thumb = document.createElement("div");
  thumb.className = "forge-rail-scrollbar-thumb";
  rail.appendChild(thumb);
  return { rail, thumb };
}

function syncForgeCustomScrollbarBinding(binding) {
  if (!binding?.scroller || !binding.rail || !binding.thumb) return;
  if (binding.scroller === alphaLogLayer && isTradingPanelActive()) {
    binding.rail.classList.add("is-hidden");
    binding.thumb.style.height = "0px";
    binding.thumb.style.transform = "translateY(0px)";
    return;
  }
  const viewportHeight = binding.scroller.clientHeight;
  const contentHeight = binding.scroller.scrollHeight;
  const scrollRange = Math.max(contentHeight - viewportHeight, 0);
  if (viewportHeight <= 0 || scrollRange <= 1) {
    binding.rail.classList.add("is-hidden");
    binding.thumb.style.height = "0px";
    binding.thumb.style.transform = "translateY(0px)";
    return;
  }
  const railHeight = binding.rail.clientHeight;
  if (railHeight <= 0) {
    binding.rail.classList.add("is-hidden");
    return;
  }
  const thumbHeight = Math.max(32, Math.round((viewportHeight / contentHeight) * railHeight));
  const travel = Math.max(railHeight - thumbHeight, 0);
  const progress = Math.min(Math.max(binding.scroller.scrollTop / scrollRange, 0), 1);
  binding.rail.classList.remove("is-hidden");
  binding.thumb.style.height = `${thumbHeight}px`;
  binding.thumb.style.transform = `translateY(${Math.round(travel * progress)}px)`;
}

function queueForgeCustomScrollbarSync(scroller) {
  const binding = forgeCustomScrollbarBindings.get(scroller);
  if (!binding) return;
  if (binding.raf) cancelAnimationFrame(binding.raf);
  binding.raf = requestAnimationFrame(() => {
    binding.raf = 0;
    syncForgeCustomScrollbarBinding(binding);
  });
}

function bindForgeCustomScrollbar(scroller, rail, thumb, options = {}) {
  pruneForgeCustomScrollbarBindings();
  if (!scroller || !rail || !thumb) return null;
  const current = forgeCustomScrollbarBindings.get(scroller);
  if (current && current.rail === rail && current.thumb === thumb) {
    queueForgeCustomScrollbarSync(scroller);
    return current;
  }
  if (current) {
    scroller.removeEventListener("scroll", current.onScroll);
    scroller.removeEventListener("input", current.onInput);
    current.resizeObserver?.disconnect?.();
    current.mutationObserver?.disconnect?.();
    if (current.raf) cancelAnimationFrame(current.raf);
  }
  const binding = {
    scroller,
    rail,
    thumb,
    raf: 0,
    resizeObserver: null,
    mutationObserver: null,
    onScroll: () => queueForgeCustomScrollbarSync(scroller),
    onInput: () => queueForgeCustomScrollbarSync(scroller),
  };
  scroller.addEventListener("scroll", binding.onScroll, { passive: true });
  if (scroller instanceof HTMLTextAreaElement) {
    scroller.addEventListener("input", binding.onInput);
  }
  if (typeof ResizeObserver !== "undefined") {
    binding.resizeObserver = new ResizeObserver(() => queueForgeCustomScrollbarSync(scroller));
    binding.resizeObserver.observe(scroller);
    if (rail.parentElement && rail.parentElement !== scroller) {
      binding.resizeObserver.observe(rail.parentElement);
    }
  }
  if (!(scroller instanceof HTMLTextAreaElement) && options.observeMutations !== false && typeof MutationObserver !== "undefined") {
    binding.mutationObserver = new MutationObserver(() => queueForgeCustomScrollbarSync(scroller));
    binding.mutationObserver.observe(scroller, { childList: true, subtree: true, characterData: true });
  }
  forgeCustomScrollbarBindings.set(scroller, binding);
  queueForgeCustomScrollbarSync(scroller);
  return binding;
}

window.__forgeCreateScrollbarElements = createForgeScrollbarElements;
window.__forgeBindCustomScrollbar = bindForgeCustomScrollbar;

