function estimateLlmTokensFromBytes(bytes) {
  const n = Math.max(0, Number(bytes) || 0);
  return Math.round(n / 4);
}

function compactTokenCount(tokens) {
  const n = Math.max(0, Math.round(Number(tokens) || 0));
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(n >= 10_000_000 ? 0 : 1)}M`;
  if (n >= 1_000) return `${(n / 1_000).toFixed(n >= 100_000 ? 0 : 1)}k`;
  return String(n);
}

function normalizeAgentName(name) {
  const raw = String(name || "Unknown agent");
  const lower = raw.toLowerCase();
  if (lower.includes("claude")) return "Claude";
  if (lower.includes("codex") || lower.includes("openai")) return "Codex";
  return raw.replace(/[-_]+/g, " ").replace(/\bmcp\b/ig, "").trim() || "Agent";
}

function agentBrand(name) {
  const lower = String(name || "").toLowerCase();
  if (lower.includes("claude") || lower.includes("anthropic")) return "claude";
  if (lower.includes("codex") || lower.includes("openai") || lower.includes("chatgpt")) return "codex";
  if (lower.includes("forge")) return "forge";
  return "generic";
}

