// Pool of agent display names used to fill the {other} placeholder.
const CANVAS_KNOWN_AGENT_NAMES = ["Codex", "Gemini", "Claude"];

// Each agent's "boss" — used to fill the {ceo} placeholder so Codex only
// pings Sam Altman, Claude only Dario Amodei, Gemini only Sundar Pichai.
const CANVAS_AGENT_CEOS = {
  codex: "Sam Altman",
  openai: "Sam Altman",
  gpt: "Sam Altman",
  gemini: "Sundar Pichai",
  google: "Sundar Pichai",
  claude: "Dario Amodei",
  anthropic: "Dario Amodei",
};

function resolveCanvasThinkingPhrase(rawPhrase) {
  if (!rawPhrase) return "";
  let phrase = rawPhrase;
  const selfLabel = String(
    forgeCanvasChatPendingAssistants[0]?.label || ""
  ).toLowerCase();
  if (phrase.includes("{other}")) {
    const others = CANVAS_KNOWN_AGENT_NAMES.filter(
      (n) => n.toLowerCase() !== selfLabel
    );
    const pick = others[Math.floor(Math.random() * others.length)] || "the others";
    phrase = phrase.replace(/\{other\}/g, pick);
  }
  if (phrase.includes("{ceo}")) {
    const ceoKey = Object.keys(CANVAS_AGENT_CEOS).find((k) => selfLabel.includes(k));
    const ceo = ceoKey ? CANVAS_AGENT_CEOS[ceoKey] : "their CEO";
    phrase = phrase.replace(/\{ceo\}/g, ceo);
  }
  return phrase;
}

// QWERTY adjacency for believable typos. Drawn fresh on every tick.
const KEYBOARD_NEIGHBORS = {
  a: "qwsz", b: "vghn", c: "xdfv", d: "serfcx", e: "wrsdf",
  f: "drtgvc", g: "ftyhbv", h: "gyujnb", i: "uojk", j: "huiknm",
  k: "jiolm", l: "kop", m: "njk", n: "bhjm", o: "ipkl",
  p: "ol", q: "wa", r: "etdf", s: "awedxz", t: "ryfg",
  u: "yihj", v: "cfgb", w: "qeas", x: "zsdc", y: "tuhg",
  z: "asx",
};

function pickTypoChar(intended) {
  const lower = intended.toLowerCase();
  const neighbors = KEYBOARD_NEIGHBORS[lower];
  if (!neighbors) return null;
  return neighbors[Math.floor(Math.random() * neighbors.length)];
}

let canvasThinkingPhraseIdx = -1;
let canvasThinkingTimer = null;
let canvasThinkingDisplayText = "";
let canvasThinkingTargetText = "";
let canvasThinkingPhase = "idle"; // idle | typing | hold | erasing
let canvasThinkingCorrectIndex = 0;
let canvasThinkingTypoQueue = 0;

// Phrases that should never appear for certain agents (e.g. Codex shouldn't
// dunk on its own product family). The key is the phrase string; the value
// is a list of substrings that, if found in the current agent's label,
// disqualify that phrase. Capped retries keep the loop bounded.
const CANVAS_PHRASE_AGENT_BLOCKLIST = {
  "is dunking on the latest GPT release": ["codex", "openai", "gpt"],
};

function isPhraseBlockedForAgent(phrase, selfLabelLower) {
  const blocks = CANVAS_PHRASE_AGENT_BLOCKLIST[phrase];
  if (!blocks) return false;
  return blocks.some((token) => selfLabelLower.includes(token));
}

function pickRandomThinkingPhrase(excludeIdx) {
  if (CANVAS_THINKING_PHRASES.length <= 1) return 0;
  const selfLabel = String(
    forgeCanvasChatPendingAssistants[0]?.label || ""
  ).toLowerCase();
  let nextIdx;
  let retries = 0;
  do {
    nextIdx = Math.floor(Math.random() * CANVAS_THINKING_PHRASES.length);
    retries++;
    if (retries > 30) break; // safety net — never spin forever
  } while (
    nextIdx === excludeIdx
    || isPhraseBlockedForAgent(CANVAS_THINKING_PHRASES[nextIdx], selfLabel)
  );
  return nextIdx;
}

function currentCanvasThinkingPhrase() {
  return canvasThinkingDisplayText;
}

function isCanvasThinkingActive() {
  return canvasThinkingPhase !== "idle";
}

function triggerCanvasThinkingRender() {
  alphaCanvasPendingVersion += 1;
  alphaLogRenderedVersion = -1;
  scheduleAlphaRender?.();
}

function scheduleCanvasThinkingTick(delay) {
  if (canvasThinkingTimer) clearTimeout(canvasThinkingTimer);
  canvasThinkingTimer = setTimeout(canvasThinkingTick, delay);
}

function canvasThinkingTick() {
  canvasThinkingTimer = null;
  // Rotation only runs while at least one assistant is pending.
  if (!forgeCanvasChatPendingAssistants.length) {
    stopCanvasThinkingRotation();
    triggerCanvasThinkingRender();
    return;
  }
  let nextDelay = 60;
  if (canvasThinkingPhase === "typing") {
    // Mid-typo recovery: backspace the wrong chars before resuming.
    if (canvasThinkingTypoQueue > 0) {
      canvasThinkingDisplayText = canvasThinkingDisplayText.slice(0, -1);
      canvasThinkingTypoQueue -= 1;
      // Slight pause once the correction is finished — like a real typist
      // pausing to verify before continuing.
      nextDelay = canvasThinkingTypoQueue === 0
        ? 200 + Math.random() * 140
        : 32 + Math.random() * 18;
    } else if (canvasThinkingCorrectIndex < canvasThinkingTargetText.length) {
      const idx = canvasThinkingCorrectIndex;
      const expectedChar = canvasThinkingTargetText[idx];
      const roll = Math.random();
      // ~3.5% per char → about one typo every ~28 chars on average. Plenty
      // of phrases will type cleanly; longer ones may catch one or two.
      const typoChance = /[a-zA-Z]/.test(expectedChar) ? 0.035 : 0;
      if (roll < typoChance) {
        const wrong = pickTypoChar(expectedChar);
        if (wrong) {
          canvasThinkingDisplayText += wrong;
          // ~40% of typos catch one extra char before the typist notices,
          // so the correction is 2 backspaces instead of 1.
          if (Math.random() < 0.4 && idx + 1 < canvasThinkingTargetText.length) {
            canvasThinkingDisplayText += canvasThinkingTargetText[idx + 1];
            canvasThinkingTypoQueue = 2;
          } else {
            canvasThinkingTypoQueue = 1;
          }
          // Brief beat as the typist realises the slip.
          nextDelay = 90 + Math.random() * 80;
        } else {
          canvasThinkingDisplayText += expectedChar;
          canvasThinkingCorrectIndex += 1;
          nextDelay = 32 + Math.random() * 28;
        }
      } else if (roll < typoChance + 0.07) {
        // ~7% slowdown — short hesitation, char still typed correctly.
        canvasThinkingDisplayText += expectedChar;
        canvasThinkingCorrectIndex += 1;
        nextDelay = 220 + Math.random() * 220;
      } else if (roll < typoChance + 0.09) {
        // ~2% deeper pause — like the typist lost their train of thought.
        canvasThinkingDisplayText += expectedChar;
        canvasThinkingCorrectIndex += 1;
        nextDelay = 600 + Math.random() * 500;
      } else {
        // Normal cadence with subtle jitter.
        canvasThinkingDisplayText += expectedChar;
        canvasThinkingCorrectIndex += 1;
        // Extra mini-pause after spaces (~25% of word boundaries) — humans
        // breathe between words.
        if (expectedChar === " " && Math.random() < 0.25) {
          nextDelay = 160 + Math.random() * 140;
        } else {
          nextDelay = 32 + Math.random() * 28;
        }
      }
    } else {
      canvasThinkingPhase = "hold";
      nextDelay = 5500; // hold the full phrase ~5.5s
    }
  } else if (canvasThinkingPhase === "hold") {
    canvasThinkingPhase = "erasing";
    nextDelay = 80;
  } else if (canvasThinkingPhase === "erasing") {
    if (canvasThinkingDisplayText.length > 0) {
      canvasThinkingDisplayText = canvasThinkingDisplayText.slice(0, -1);
      // Backspace is faster + uniform, like a held key.
      nextDelay = 16 + Math.random() * 10;
    } else {
      // Pick a new random phrase, never repeating the previous one.
      canvasThinkingPhraseIdx = pickRandomThinkingPhrase(canvasThinkingPhraseIdx);
      canvasThinkingTargetText = resolveCanvasThinkingPhrase(CANVAS_THINKING_PHRASES[canvasThinkingPhraseIdx]);
      canvasThinkingCorrectIndex = 0;
      canvasThinkingTypoQueue = 0;
      canvasThinkingPhase = "typing";
      nextDelay = 240; // brief blank gap before the next phrase types in
    }
  }
  triggerCanvasThinkingRender();
  scheduleCanvasThinkingTick(nextDelay);
}

// Safe / neutral phrases used ONLY as the first phrase of a thinking
// session — the cheeky and inter-LLM lines kick in only after the first
// erase/refresh cycle, so the opening reads professional.
const CANVAS_THINKING_FIRST_PHRASES = [
  "is thinking",
  "is pondering",
  "is working on it",
  "is processing",
];

function startCanvasThinkingRotation() {
  if (canvasThinkingPhase !== "idle") return;
  // First phrase is always a safe one. The phrase index stays at -1 so
  // the next phrase picked (in the erase→type transition) draws from the
  // full pool — the cheeky/borderline lines start appearing from then on.
  canvasThinkingPhraseIdx = -1;
  canvasThinkingTargetText = CANVAS_THINKING_FIRST_PHRASES[
    Math.floor(Math.random() * CANVAS_THINKING_FIRST_PHRASES.length)
  ];
  canvasThinkingDisplayText = "";
  canvasThinkingCorrectIndex = 0;
  canvasThinkingTypoQueue = 0;
  canvasThinkingPhase = "typing";
  // 1-second pause before the first character types in.
  scheduleCanvasThinkingTick(1000);
}

function stopCanvasThinkingRotation() {
  if (canvasThinkingTimer) {
    clearTimeout(canvasThinkingTimer);
    canvasThinkingTimer = null;
  }
  canvasThinkingPhase = "idle";
  canvasThinkingDisplayText = "";
  canvasThinkingTargetText = "";
  canvasThinkingCorrectIndex = 0;
  canvasThinkingTypoQueue = 0;
}

function setCanvasChatPendingAssistants(targets = []) {
  forgeCanvasChatPendingAssistants = Array.from(targets || [])
    .map((target) => ({
      label: target.label || canvasChatTargetLabel(target.runtime || forgeCanvasChatTargetMode),
      runtime: target.runtime || "",
    }))
    .filter((target) => target.label);
  alphaCanvasPendingVersion += 1;
  alphaLogRenderedVersion = -1;
  scheduleAlphaRender();
  if (forgeCanvasChatPendingAssistants.length) {
    startCanvasThinkingRotation();
    scrollAlphaTranscriptToLive?.({ smooth: true, force: true });
  } else {
    stopCanvasThinkingRotation();
  }
}

function shortHash(value, left = 8, right = 6) {
  const s = String(value || "");
  if (!s) return "pending";
  if (s.length <= left + right + 1) return s;
  return `${s.slice(0, left)}…${s.slice(-right)}`;
}

function formatCount(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return "—";
  return n.toLocaleString("fr-FR");
}

function formatBytes(value) {
  const n = Math.max(0, Number(value) || 0);
  if (n < 1024) return `${n} B`;
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`;
  return `${(n / 1024 / 1024).toFixed(1)} MB`;
}

function formatDurationMs(ms) {
  const total = Math.max(0, Math.round((Number(ms) || 0) / 1000));
  const minutes = Math.floor(total / 60);
  const seconds = total % 60;
  if (minutes <= 0) return `${seconds}s`;
  return `${minutes}m ${seconds.toString().padStart(2, "0")}s`;
}

function cleanAlphaLogLine(raw) {
  return String(raw || "").replace(/^\[mcp:[^\]]+\]\s*/, "").trimEnd();
}

function isAgentIntroLogLine(line) {
  const s = String(line || "").trim();
  return (
    /^[^:]{1,64}:\s+I'm going to\b/i.test(s) ||
    /\bis starting\b.*\bin this Forge session\./i.test(s) ||
    /\bis taking over this session\b/i.test(s)
  );
}

function isProgramStageLogLine(line) {
  const s = String(line || "").trim().toLowerCase();
  return (
    s.startsWith("selecting a forge program") ||
    s.startsWith("creating a forge program") ||
    s.startsWith("program selected:") ||
    s.startsWith("programs selected") ||
    s.startsWith("program created:") ||
    s.startsWith("programs created") ||
    s.startsWith("forge will reuse program") ||
    s.startsWith("[program] running") ||
    s.startsWith("[program] saved")
  );
}

function programLineFromLog(line) {
  const s = String(line || "").trim();
  const lower = s.toLowerCase();
  if (lower.startsWith("program selected:") || lower.startsWith("programs selected")) {
    return { text: s.replace(/^programs?/i, (word) => word[0].toUpperCase() + word.slice(1).toLowerCase()), state: "done" };
  }
  if (lower.startsWith("program created:") || lower.startsWith("programs created")) {
    return { text: s.replace(/^programs?/i, (word) => word[0].toUpperCase() + word.slice(1).toLowerCase()), state: "done" };
  }
  if (lower.startsWith("forge will reuse program")) {
    return { text: s.replace(/^Forge will reuse/i, "Program selected:"), state: "done" };
  }
  if (lower.startsWith("[program] saved")) {
    return { text: s.replace(/^\[program\]\s*saved/i, "Program created:"), state: "done" };
  }
  if (lower.startsWith("creating a forge program")) {
    return { text: s, state: "running" };
  }
  if (lower.startsWith("[program] running")) {
    return { text: "Selecting a Forge program for this session...", state: "running" };
  }
  if (lower.startsWith("selecting a forge program")) {
    return { text: s, state: "running" };
  }
  return null;
}

function computeNarrative(lines, manifest = {}) {
  let intro = "";
  let programLine = null;
  for (const raw of lines) {
    const line = cleanAlphaLogLine(raw).trim();
    if (!line) continue;
    if (!intro && isAgentIntroLogLine(line)) intro = line;
    const candidate = programLineFromLog(line);
    if (candidate) {
      if (!programLine || candidate.state === "done") programLine = candidate;
    }
  }
  if (!programLine) {
    const hash = manifest.program_hash || manifest.programHash || manifest.long_program_hash || manifest.strategy_hash;
    if (hash) {
      const programName = manifest.program?.title || manifest.title || "Forge program";
      programLine = { text: `Program selected: ${programName}`, state: "done" };
    }
  }
  return { intro, programLine };
}

function selectedJobDurationMs(job, manifest) {
  if (alphaRunState.phase === "running" && alphaRunState.startTime) {
    return performance.now() - alphaRunState.startTime;
  }
  const created = Number(manifest?.created_ms || manifest?.createdMs || 0);
  const modified = Number(job?.lastModifiedMs || job?.last_modified_ms || 0);
  if (created > 0 && modified >= created) return modified - created;
  return null;
}

function jobHoldoutSummary(manifest) {
  if (alphaRunState.report) {
    return {
      target: alphaRunState.report.holdout_target_hit_pct,
      trades: alphaRunState.report.holdout_total_trades,
      longTrades: alphaRunState.report.holdout_long_trades,
      shortTrades: alphaRunState.report.holdout_short_trades,
      pnl: alphaRunState.report.holdout_total_pnl_points,
      success: !!alphaRunState.report.success,
    };
  }
  const holdout = manifest?.holdout || {};
  return {
    target: holdout.target_hit_pct,
    trades: holdout.trades,
    longTrades: holdout.long_trades,
    shortTrades: holdout.short_trades,
    pnl: holdout.pnl_points,
    success: String(manifest?.status || "").toLowerCase() === "completed",
  };
}

function lineTone(line) {
  const s = String(line || "").toLowerCase();
  if (s.includes("error") || s.includes("failed")) return "danger";
  if (s.includes("warn") || s.includes("pending") || s.includes("waiting")) return "pending";
  if (s.includes("ready") || s.includes("completed") || s.includes("[ok]") || s.includes("✓")) return "done";
  if (s.includes("calculating") || s.includes("training") || s.includes("synthesizing") || s.includes("depth")) return "active";
  return "neutral";
}

function lineGroup(line) {
  const s = String(line || "").toLowerCase();
  if (s.includes("vwap") || s.includes("rsi") || s.includes("atr") || s.includes("adx") || s.includes("stochastic") || s.includes("feature")) return "Feature matrix";
  if (s.includes("long/short") || s.includes("label")) return "Labels";
  if (s.includes("detector") || s.includes("synth") || s.includes("candidate") || s.includes("pairing")) return "Synthesis";
  if (s.includes("holdout") || s.includes("train") || s.includes("strategy") || s.includes("pnl") || s.includes("trades")) return "Result";
  if (s.includes("parse") || s.includes("ohlc") || s.includes("candles") || s.includes("upload")) return "Input";
  return "Compute";
}

function groupedVisibleLogs(lines) {
  const groups = [];
  for (const raw of lines) {
    const line = cleanAlphaLogLine(raw);
    if (!line.trim() || isAlphaBoilerplateLogLine(line)) continue;
    const groupName = lineGroup(line);
    let group = groups[groups.length - 1];
    if (!group || group.name !== groupName) {
      group = { name: groupName, lines: [] };
      groups.push(group);
    }
    group.lines.push(line);
  }
  return groups;
}

function isAlphaBoilerplateLogLine(line) {
  const s = String(line || "").trim().toLowerCase();
  if (!s) return true;
  return (
    isAgentIntroLogLine(line) ||
    isProgramStageLogLine(line) ||
    isForgeInternalExecutionLogLine(line) ||
    s.startsWith("forge ui:") ||
    s.startsWith("forge tools:") ||
    s.startsWith("codex bridge") ||
    s.startsWith("program selected:") ||
    s.startsWith("working for") ||
    s === "compute" ||
    s === "input" ||
    s === "synthesis" ||
    s.startsWith("pending empty session created") ||
    s.startsWith("pending upload session updated") ||
    s.startsWith("reading the candles") ||
    s.startsWith("synthesis") ||
    s === "pending upload session created" ||
    s.startsWith("creating mcp pending calculation session") ||
    s.startsWith("mcp pending session created") ||
    s.startsWith("files=") ||
    s.startsWith("primary=") ||
    s.startsWith("bytes=") ||
    s.includes("waiting for mcp agent to claim calculation") ||
    s.startsWith("candles loaded :") ||
    s.startsWith("chart overlays computed :") ||
    s.startsWith("upload :") ||
    s.startsWith("input :") ||
    s.startsWith("result : bars=")
  );
}

function hasAlphaComputeStarted(status, visibleGroups) {
  if (status === "completed" || status === "done" || status === "failed" || status === "error") {
    return true;
  }
  return visibleGroups.some((group) => group.lines.some((line) => {
    const s = String(line || "").toLowerCase();
    return (
      s.includes("reading the candles") ||
      s.includes("preparing the backtest") ||
      s.includes("running the metric toolbox") ||
      s.includes("metric ") ||
      s.includes("synthesis") ||
      s.includes("synth") ||
      s.includes("materializing") ||
      s.includes("building binary") ||
      s.includes("beam search") ||
      s.includes("evaluating") ||
      s.includes("holdout metrics") ||
      s.includes("walk-forward") ||
      s.includes("strategy")
    );
  }));
}

function makeProofRow(label, value, status = "neutral") {
  const row = createUiEl("div", `proof-row ${status}`);
  row.appendChild(createUiEl("span", "proof-state"));
  row.appendChild(createUiEl("span", "proof-label", label));
  row.appendChild(createUiEl("code", "proof-value", value || "pending"));
  return row;
}

function selectedManifestText() {
  return JSON.stringify(selectedForgeJobManifest || {}, null, 2);
}

function selectedProofObject() {
  const job = currentForgeJob();
  const manifest = selectedForgeJobManifest || {};
  return {
    job_id: selectedForgeJobId || manifest.job_id || null,
    title: job ? forgeJobLabel(job) : manifest.title || alphaDocState.fileName || "Forge compute",
    status: job?.status || manifest.status || alphaRunState.phase,
    verified_at: new Date().toISOString(),
    input: {
      file_path: manifest.file_path || job?.filePath || job?.file_path || null,
      bytes: manifest.bytes || alphaDocState.fileSize || null,
      file_hash: manifest.file_hash || null,
      local_hash_check: alphaVerificationState || null,
    },
    result: {
      strategy_hash: manifest.strategy_hash || alphaRunState.report?.strategy_hash || null,
      bars: manifest.bars || job?.bars || alphaDocState.candles.length || null,
      holdout: manifest.holdout || null,
    },
    artifacts: {
      manifest_path: manifest.manifest_path || null,
      manifest_bytes: manifest.manifest_bytes || null,
      log_path: manifest.log_path || null,
      log_bytes: manifest.log_bytes || null,
      metrics_path: manifest.metrics_path || null,
      proof_path: manifest.proof_path || null,
      visual_mapping_path: manifest.visual_mapping_path || null,
      visualization_3d_index_path: manifest.visualization_3d_index_path || null,
      visual_mapping: manifest.visual_mapping || null,
      artifacts_3d: manifest.artifacts_3d || [],
      visual_selection: alpha3dSelectionSummary?.() || null,
    },
  };
}

function selectedVisualMappingSummary() {
  const manifest = selectedForgeJobManifest || {};
  const mapping = manifest.visual_mapping || manifest.mcp_result?.visual_mapping || null;
  const artifacts3d = Array.isArray(manifest.artifacts_3d)
    ? manifest.artifacts_3d
    : Array.isArray(manifest.mcp_result?.artifacts_3d)
      ? manifest.mcp_result.artifacts_3d
      : [];
  const visualization = manifest.visualization_3d || manifest.mcp_result?.visualization_3d || null;
  return {
    available: !!(mapping?.available || manifest.visual_mapping_path || artifacts3d.length || visualization?.available),
    kind: mapping?.kind || (artifacts3d.length ? "alpha_result_visual_mapping" : ""),
    version: mapping?.version || "",
    path: mapping?.path || manifest.visual_mapping_path || "",
    hash: mapping?.hash || "",
    viewCount: Number(mapping?.view_count || mapping?.viewCount || visualization?.mode_count || artifacts3d.length || 0),
    artifactCount: artifacts3d.length,
    indexPath: visualization?.index_path || manifest.visualization_3d_index_path || "",
    indexHash: visualization?.index_hash || "",
  };
}

function refreshAlphaCanvasAfterLayoutChange() {
  if (activeSection !== "alpha") return;
  requestAnimationFrame(() => {
    alphaRenderFailed = false;
    resizeAlphaCanvas();
    scheduleAlphaRender({ force: true });
  });
  window.setTimeout(() => {
    alphaRenderFailed = false;
    resizeAlphaCanvas();
    scheduleAlphaRender({ force: true });
    scheduleAlphaResizeRecovery(90);
  }, 220);
}

function setAlphaSidebarCollapsed(collapsed) {
  alphaSidebarCollapsed = !!collapsed;
  alphaContent?.classList.toggle("sidebar-collapsed", alphaSidebarCollapsed);
  alphaSidebarToggle?.classList.toggle("collapsed", alphaSidebarCollapsed);
  alphaSidebarToggle?.setAttribute("aria-expanded", String(!alphaSidebarCollapsed));
  const label = alphaSidebarCollapsed ? "Show left panel" : "Hide left panel";
  alphaSidebarToggle?.setAttribute("aria-label", label);
  alphaSidebarToggle?.setAttribute("title", label);
  refreshAlphaCanvasAfterLayoutChange();
}

function isBoomViewportOpen() {
  return !!bangerView && !bangerView.hidden;
}

function tradingPanelBridge() {
  if (typeof window === "undefined") return null;
  const bridge = window.__forgeTradingPanelBridge;
  return bridge && typeof bridge === "object" ? bridge : null;
}

function isTradingPanelActive() {
  try {
    return !!tradingPanelBridge()?.isActive?.();
  } catch (_) {
    return false;
  }
}

function defaultAlphaRightPanelMode() {
  return (isBoomViewportOpen() || isTradingPanelActive()) ? "console" : "proof";
}

function currentAlphaConsoleField() {
  if (alphaConsoleState.language === "kasm") return "kasmDraft";
  if (alphaConsoleState.language === "pine") return "pineDraft";
  return "rustDraft";
}

function currentAlphaConsoleDraft() {
  return alphaConsoleState[currentAlphaConsoleField()] || "";
}

function setCurrentAlphaConsoleDraft(text) {
  alphaConsoleState[currentAlphaConsoleField()] = String(text || "");
  alphaConsoleRenderedKey = "";
}

function alphaConsoleHash(text) {
  const source = String(text || "");
  let hash = 2166136261;
  for (let index = 0; index < source.length; index += 1) {
    hash ^= source.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return `fx${(hash >>> 0).toString(16).padStart(8, "0")}`;
}

function alphaConsolePlaceholder(language) {
  if (isTradingPanelActive()) {
    const template = tradingPanelBridge()?.consoleTemplate?.(language);
    if (typeof template === "string" && template.trim()) return template;
  }
  if (language === "kasm") {
    return [
      'scene "boom"',
      "use selection active",
      "use region active",
      "",
      "query vertex -> edges -> faces -> cells",
      'tool modifier.apply type=\"solidify\" thickness=0.24',
      "tool animation.export_js",
    ].join("\n");
  }
  return [
    "boom_println(boom_script_hash());",
    'boom_println(boom_context_json());',
  ].join("\n");
}

function stableAlphaConsoleValue(value) {
  if (Array.isArray(value)) return value.map(stableAlphaConsoleValue);
  if (value && typeof value === "object") {
    const out = {};
    for (const key of Object.keys(value).sort()) out[key] = stableAlphaConsoleValue(value[key]);
    return out;
  }
  return value;
}

function stableAlphaConsoleStringify(value) {
  return JSON.stringify(stableAlphaConsoleValue(value));
}

function getAlphaBoomConsoleContext() {
  if (isTradingPanelActive()) {
    try {
      const context = tradingPanelBridge()?.consoleContext?.();
      if (context) return context;
    } catch (err) {
      console.warn("[trading-console] context fetch failed", err);
    }
  }
  try {
    if (typeof window.__forgeBoomConsoleContext === "function") {
      return window.__forgeBoomConsoleContext() || null;
    }
  } catch (err) {
    console.warn("[boom-console] context fetch failed", err);
  }
  const spatialTools = window.__forgeBoomSpatialTools;
  const region = typeof spatialTools?.activeRegion === "function" ? spatialTools.activeRegion() : null;
  const graph = window.__forgeBoomKasmSnapshot || null;
  return {
    active: isBoomViewportOpen(),
    workspaceMode: isBoomViewportOpen() ? "design" : "idle",
    propertyTab: "",
    editMode: "",
    activeItem: null,
    selection: null,
    region: region ? {
      hash: region.hash || "",
      cellCount: region.cellHashes?.length || 0,
      vertexCount: region.vertexIds?.length || 0,
      faceCount: region.faceIds?.length || 0,
    } : null,
    kasm: graph,
    commandCatalogSize: Array.isArray(window.__forgeBoomCommandCatalog) ? window.__forgeBoomCommandCatalog.length : 0,
    uiContractHash: window.__forgeBoomUiContract?.hash || "",
  };
}

function alphaConsoleContextInsertion(language, context = getAlphaBoomConsoleContext()) {
  if (isTradingPanelActive()) {
    const insertion = tradingPanelBridge()?.consoleContextInsertion?.(language, context);
    if (typeof insertion === "string" && insertion.trim()) {
      return insertion.endsWith("\n") ? insertion : `${insertion}\n`;
    }
  }
  const lines = [];
  if (language === "kasm") {
    lines.push("# BOOM context");
    if (context?.activeItem?.id) lines.push(`use object ${JSON.stringify(context.activeItem.id)}`);
    if (context?.selection?.hash) lines.push(`use selection ${JSON.stringify(context.selection.hash)}`);
    if (context?.region?.hash) lines.push(`use region ${JSON.stringify(context.region.hash)}`);
    if (context?.kasm?.objectHash) lines.push(`use graph ${JSON.stringify(context.kasm.objectHash)}`);
    if (context?.uiContractHash) lines.push(`use ui_contract ${JSON.stringify(context.uiContractHash)}`);
  } else {
    lines.push("// BOOM context");
    if (context?.activeItem?.id) lines.push(`let active_object = "${context.activeItem.id}";`);
    if (context?.selection?.hash) lines.push(`let selection_hash = "${context.selection.hash}";`);
    if (context?.region?.hash) lines.push(`let region_hash = "${context.region.hash}";`);
    if (context?.kasm?.objectHash) lines.push(`let graph_hash = "${context.kasm.objectHash}";`);
    if (context?.uiContractHash) lines.push(`let ui_contract_hash = "${context.uiContractHash}";`);
  }
  return `${lines.join("\n")}\n`;
}

function prepareAlphaConsoleRun() {
  const language = alphaConsoleState.language;
  const script = currentAlphaConsoleDraft().trim();
  const context = getAlphaBoomConsoleContext();
  const bridge = tradingPanelBridge();
  const payload = {
    language,
    tool: isTradingPanelActive()
      ? bridge?.prepareToolName?.(language) || `trading.script.${language}.prepare`
      : language === "kasm"
        ? "boom.script.kasm.prepare"
        : "boom.script.rust.prepare",
    scriptHash: alphaConsoleHash(script),
    bytes: script.length,
    boom: context,
  };
  alphaConsoleState.outputKind = "prepared";
  alphaConsoleState.lastPreparedHash = payload.scriptHash;
  alphaConsoleState.lastPreparedLanguage = language;
  alphaConsoleState.output = alphaConsoleTerminalLog("prepared", {
    language,
    scriptHash: payload.scriptHash,
    bytes: payload.bytes,
    route: alphaConsoleRouteLabel(language),
    boom: context,
  });
  alphaConsoleRenderedKey = "";
}

function alphaConsoleTokenize(line) {
  return String(line || "").match(/"([^"\\]|\\.)*"|'([^'\\]|\\.)*'|\S+/g) || [];
}

function alphaConsoleParseScalar(raw) {
  const token = String(raw || "");
  if (!token) return "";
  if ((token.startsWith('"') && token.endsWith('"')) || (token.startsWith("'") && token.endsWith("'"))) {
    try {
      if (token.startsWith("'")) return JSON.parse(`"${token.slice(1, -1).replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`);
      return JSON.parse(token);
    } catch (_) {
      return token.slice(1, -1);
    }
  }
  if (token === "true") return true;
  if (token === "false") return false;
  if (token === "null") return null;
  const asNumber = Number(token);
  return Number.isFinite(asNumber) && token !== "" ? asNumber : token;
}

function alphaConsoleParseAssignments(tokens) {
  const payload = {};
  for (const token of tokens) {
    const eqIndex = token.indexOf("=");
    if (eqIndex <= 0) continue;
    const key = token.slice(0, eqIndex);
    const value = token.slice(eqIndex + 1);
    payload[key] = alphaConsoleParseScalar(value);
  }
  return payload;
}

function alphaConsoleNormalizeTool(toolName) {
  const normalized = String(toolName || "").trim();
  if (!normalized) return "";
  return normalized.startsWith("boom.") ? normalized : `boom.${normalized}`;
}

async function runAlphaKasmConsole() {
  const executeTool = window.__forgeBoomExecuteTool;
  if (typeof executeTool !== "function") {
    throw new Error("BOOM runtime is not active. Open BOOM before running a KASM script.");
  }
  const script = currentAlphaConsoleDraft();
  const steps = [];
  const refs = {};
  const lines = String(script || "").split(/\r?\n/);
  for (let index = 0; index < lines.length; index += 1) {
    const rawLine = lines[index];
    const line = rawLine.trim();
    if (!line || line.startsWith("#") || line.startsWith("//")) continue;
    const tokens = alphaConsoleTokenize(line);
    if (!tokens.length) continue;
    const head = tokens[0];
    if (head === "scene") {
      steps.push({ line: index + 1, command: "scene", detail: tokens.slice(1).join(" ") });
      continue;
    }
    if (head === "use") {
      const kind = tokens[1] || "";
      const target = tokens.slice(2).join(" ");
      refs[kind] = target || "active";
      steps.push({ line: index + 1, command: "use", kind, target: refs[kind] });
      continue;
    }
    if (head === "query") {
      const queryText = tokens.slice(1).join(" ");
      let result = null;
      if (queryText === "region_from_selection" || queryText === "face_from_selection") {
        result = executeTool("boom.query.region_from_selection", { activate: true });
      } else if (
        queryText === "volume_region_from_selection"
        || queryText === "vertex -> edges -> faces -> cells"
      ) {
        result = executeTool("boom.query.volume_region_from_selection", { activate: true });
      } else {
        result = { ok: false, error: "unsupported_query", query: queryText };
      }
      steps.push({ line: index + 1, command: "query", query: queryText, result });
      continue;
    }
    if (head === "tool") {
      const toolName = alphaConsoleNormalizeTool(tokens[1]);
      const payload = alphaConsoleParseAssignments(tokens.slice(2));
      const result = executeTool(toolName, payload);
      steps.push({ line: index + 1, command: "tool", tool: toolName, payload, result });
      continue;
    }
    steps.push({ line: index + 1, command: "unknown", raw: line });
  }
  return {
    language: "kasm",
    status: "ok",
    scriptHash: alphaConsoleHash(script),
    steps,
    boom: getAlphaBoomConsoleContext(),
  };
}

async function runAlphaRustConsole() {
  const invoke = window.__TAURI__?.core?.invoke;
  if (!invoke) {
    throw new Error("Tauri invoke is unavailable. Rust console runs require the Forge desktop app.");
  }
  const script = currentAlphaConsoleDraft();
  const context = getAlphaBoomConsoleContext();
  const response = await invoke("banger_run_rust_console", {
    request: {
      script,
      contextJson: stableAlphaConsoleStringify(context),
      scriptHash: alphaConsoleHash(script),
    },
  });
  return {
    language: "rust",
    tool: "banger_run_rust_console",
    ...response,
  };
}

async function runAlphaConsole() {
  const bridge = tradingPanelBridge();
  alphaConsoleState.outputKind = "running";
  alphaConsoleState.output = alphaConsoleTerminalLog("running", {
    language: alphaConsoleState.language,
    scriptHash: alphaConsoleHash(currentAlphaConsoleDraft()),
  });
  alphaConsoleRenderedKey = "";
  renderAlphaConsolePanel();
  try {
    const result = isTradingPanelActive() && typeof bridge?.runConsole === "function"
      ? await bridge.runConsole(alphaConsoleState.language, currentAlphaConsoleDraft(), {
        scriptHash: alphaConsoleHash(currentAlphaConsoleDraft()),
        context: getAlphaBoomConsoleContext(),
      })
      : alphaConsoleState.language === "kasm"
        ? await runAlphaKasmConsole()
        : await runAlphaRustConsole();
    alphaConsoleState.outputKind = "executed";
    alphaConsoleState.output = alphaConsoleTerminalLog("executed", result);
  } catch (err) {
    alphaConsoleState.outputKind = "error";
    alphaConsoleState.output = alphaConsoleTerminalLog("error", {
      language: alphaConsoleState.language,
      scriptHash: alphaConsoleHash(currentAlphaConsoleDraft()),
      message: err?.message || String(err || "Console run failed"),
    });
  }
  alphaConsoleRenderedKey = "";
  renderAlphaConsolePanel();
}

function setAlphaRightPanelMode(mode, options = {}) {
  const nextMode = isTradingPanelActive()
    ? (mode === "orders" ? "orders" : "console")
    : (mode === "console" ? "console" : "proof");
  alphaRightPanelMode = nextMode;
  alphaProofRenderedKey = "";
  alphaConsoleRenderedKey = "";
  if (alphaProofPanelOpen && !options.skipRender) {
    renderAlphaRightPanel();
  }
}

function renderAlphaRightPanelTabs() {
  if (!alphaRightPanelTabs) return;
  const tabs = isTradingPanelActive()
    ? [
      { id: "console", label: "Console" },
      { id: "orders", label: "Orders" },
    ]
    : [
      { id: "proof", label: "Verification" },
      { id: "console", label: "Console" },
    ];
  alphaRightPanelTabs.innerHTML = "";
  for (const tab of tabs) {
    const button = createUiEl("button", `proof-panel-tab${alphaRightPanelMode === tab.id ? " is-active" : ""}`, tab.label);
    button.type = "button";
    button.setAttribute("role", "tab");
    button.setAttribute("aria-selected", String(alphaRightPanelMode === tab.id));
    button.dataset.rightPanelMode = tab.id;
    alphaRightPanelTabs.appendChild(button);
  }
}

function alphaConsoleRouteLabel(language) {
  if (isTradingPanelActive()) {
    return tradingPanelBridge()?.routeLabel?.(language)
      || (language === "pine" ? "trading / pinescript draft" : `trading / ${language}`);
  }
  return language === "kasm" ? "boom live tools + kasm graph" : "forge runtime / rustc";
}

function alphaConsoleTerminalLog(kind, payload = {}) {
  const lines = [];
  const language = String(payload.language || alphaConsoleState.language || "rust").toUpperCase();
  const scriptHash = payload.scriptHash || payload.script_hash || "";
  const runHash = payload.runHash || payload.run_hash || "";
  const status = payload.status || "";
  if (kind === "idle") {
    if (isTradingPanelActive()) {
      return [
        "[hash-log] idle",
        "[hint] hash to snapshot the trading context, then run to execute.",
      ].join("\n");
    }
    return [
      "[hash-log] idle",
      "[hint] hash to snapshot the BOOM context, then run to execute.",
    ].join("\n");
  }
  if (kind === "running") {
    lines.push(`[run] ${language}`);
    if (scriptHash) lines.push(`[hash] ${scriptHash}`);
    lines.push(`[route] ${alphaConsoleRouteLabel(alphaConsoleState.language)}`);
    lines.push("[status] executing");
    return lines.join("\n");
  }
  if (kind === "prepared") {
    lines.push(`[hash] ${scriptHash || alphaConsoleHash(currentAlphaConsoleDraft())}`);
    lines.push(`[lang] ${language}`);
    lines.push(`[route] ${payload.route || alphaConsoleRouteLabel(alphaConsoleState.language)}`);
    lines.push(`[bytes] ${formatCount(payload.bytes || currentAlphaConsoleDraft().length || 0)}`);
    if (payload.boom?.region?.hash) lines.push(`[region] ${payload.boom.region.hash}`);
    if (payload.boom?.selection?.hash) lines.push(`[selection] ${payload.boom.selection.hash}`);
    if (payload.boom?.kasm?.objectHash) lines.push(`[graph] ${payload.boom.kasm.objectHash}`);
    if (payload.boom?.uiContractHash) lines.push(`[ui] ${payload.boom.uiContractHash}`);
    return lines.join("\n");
  }
  if (kind === "executed") {
    if (scriptHash) lines.push(`[hash] ${scriptHash}`);
    lines.push(`[lang] ${language}`);
    lines.push(`[route] ${alphaConsoleRouteLabel(alphaConsoleState.language)}`);
    if (status) lines.push(`[status] ${status}`);
    if (runHash) lines.push(`[run] ${runHash}`);
    if (payload.exit_code != null || payload.exitCode != null) {
      lines.push(`[exit] ${payload.exit_code ?? payload.exitCode}`);
    }
    if (Array.isArray(payload.steps)) {
      lines.push(`[steps] ${formatCount(payload.steps.length)}`);
    }
    if (payload.stored_at || payload.storedAt) {
      lines.push(`[store] ${payload.stored_at || payload.storedAt}`);
    }
    const stdout = String(payload.stdout || "").trim();
    const stderr = String(payload.stderr || "").trim();
    if (stdout) {
      lines.push("");
      lines.push("[stdout]");
      lines.push(stdout);
    }
    if (stderr) {
      lines.push("");
      lines.push("[stderr]");
      lines.push(stderr);
    }
    if (!stdout && !stderr && !Array.isArray(payload.steps)) {
      lines.push("");
      lines.push("[result]");
      lines.push(JSON.stringify(payload, null, 2));
    }
    return lines.join("\n");
  }
  if (kind === "error") {
    lines.push(`[lang] ${language}`);
    lines.push("[status] error");
    if (scriptHash) lines.push(`[hash] ${scriptHash}`);
    lines.push("");
    lines.push(String(payload.message || "console run failed"));
    return lines.join("\n");
  }
  return JSON.stringify(payload, null, 2);
}

function buildAlphaConsoleLogBody(output, outputKind) {
  const body = createUiEl(
    "div",
    `proof-console-logbody${outputKind === "prepared" || outputKind === "executed" ? " is-ready" : ""}`
  );
  const lines = String(output || alphaConsoleTerminalLog("idle")).split(/\r?\n/);
  for (const line of lines) {
    const row = createUiEl("div", "proof-console-logline");
    const match = line.match(/^(\[[^\]]+\])(\s*)(.*)$/);
    if (match) {
      const tag = createUiEl("span", "proof-console-logtag", match[1]);
      row.appendChild(tag);
      if (match[2]) row.appendChild(document.createTextNode(match[2]));
      if (match[3]) row.appendChild(createUiEl("span", "proof-console-logtext", match[3]));
    } else {
      row.appendChild(document.createTextNode(line || " "));
    }
    body.appendChild(row);
  }
  return body;
}

function renderAlphaConsolePanel() {
  if (!alphaProofContent || !alphaProofPanelOpen || alphaRightPanelMode !== "console") return;
  if (!isTradingPanelActive() && alphaConsoleState.language === "pine") {
    alphaConsoleState.language = "rust";
  }
  const script = currentAlphaConsoleDraft();
  const renderKey = JSON.stringify({
    language: alphaConsoleState.language,
    script,
    output: alphaConsoleState.output,
    outputKind: alphaConsoleState.outputKind,
    preparedHash: alphaConsoleState.lastPreparedHash,
  });
  if (renderKey === alphaConsoleRenderedKey) return;
  alphaConsoleRenderedKey = renderKey;
  alphaProofContent.innerHTML = "";

  const shell = createUiEl("div", "proof-console");
  const split = createUiEl("div", "proof-console-split");

  const editorWrap = createUiEl("section", "proof-console-pane proof-console-pane-editor");
  const editorStrip = createUiEl("div", "proof-console-strip");
  const langSwitch = createUiEl("div", "proof-console-langswitch");
  const languageDefs = isTradingPanelActive()
    ? [
      ["pine", "Pine"],
      ["rust", "Rust"],
      ["kasm", "KASM"],
    ]
    : [
      ["rust", "Rust"],
      ["kasm", "KASM"],
    ];
  for (const [language, label] of languageDefs) {
    const button = createUiEl(
      "button",
      `proof-console-lang${alphaConsoleState.language === language ? " is-active" : ""}`,
      label
    );
    button.type = "button";
    button.dataset.consoleLanguage = language;
    langSwitch.appendChild(button);
  }
  const actions = createUiEl("div", "proof-console-actions");
  const actionDefs = [
    ["console-insert-context", "Context"],
    ["console-prepare", "Hash"],
    ["console-run", "Run"],
    ["console-clear", "Clear"],
  ];
  for (const [action, label] of actionDefs) {
    const button = createUiEl("button", `proof-console-action${action === "console-run" ? " is-primary" : ""}`, label);
    button.type = "button";
    button.dataset.consoleAction = action;
    actions.appendChild(button);
  }
  editorStrip.appendChild(langSwitch);
  editorStrip.appendChild(actions);
  editorWrap.appendChild(editorStrip);
  const textarea = createUiEl("textarea", "proof-console-textarea");
  textarea.dataset.consoleField = "script";
  textarea.setAttribute("spellcheck", "false");
  textarea.setAttribute("autocomplete", "off");
  textarea.setAttribute("autocapitalize", "off");
  textarea.setAttribute("aria-label", `${alphaConsoleState.language.toUpperCase()} script console`);
  textarea.placeholder = alphaConsolePlaceholder(alphaConsoleState.language);
  textarea.value = script;
  const editorScrollShell = createUiEl("div", "forge-scroll-shell proof-console-scrollshell");
  const { rail: editorRail, thumb: editorThumb } = createForgeScrollbarElements();
  editorScrollShell.appendChild(textarea);
  editorScrollShell.appendChild(editorRail);
  editorWrap.appendChild(editorScrollShell);
  split.appendChild(editorWrap);

  const outputSection = createUiEl("section", "proof-console-pane proof-console-pane-log");
  const outputStrip = createUiEl("div", "proof-console-strip proof-console-strip-log");
  outputStrip.appendChild(createUiEl("div", "proof-console-logmeta", alphaConsoleState.outputKind || "idle"));
  outputSection.appendChild(outputStrip);
  const outputBody = buildAlphaConsoleLogBody(alphaConsoleState.output, alphaConsoleState.outputKind);
  const outputScrollShell = createUiEl("div", "forge-scroll-shell proof-console-scrollshell");
  const { rail: outputRail, thumb: outputThumb } = createForgeScrollbarElements();
  outputScrollShell.appendChild(outputBody);
  outputScrollShell.appendChild(outputRail);
  outputSection.appendChild(outputScrollShell);
  split.appendChild(outputSection);

  shell.appendChild(split);
  alphaProofContent.appendChild(shell);
  requestAnimationFrame(() => {
    bindForgeCustomScrollbar(textarea, editorRail, editorThumb, { observeMutations: false });
    bindForgeCustomScrollbar(outputBody, outputRail, outputThumb);
    queueForgeCustomScrollbarSync(alphaProofContent);
  });
}

function renderAlphaRightPanel() {
  const tradingActive = isTradingPanelActive();
  const webExplorerActive = typeof isWebExplorerUiActive === "function" && isWebExplorerUiActive();
  alphaProofPanel?.classList.toggle("console-mode", alphaRightPanelMode === "console" && !tradingActive && !webExplorerActive);
  if (alphaRightPanelKicker) {
    alphaRightPanelKicker.textContent = tradingActive
      ? "Trading"
      : webExplorerActive
        ? "WebExplorer"
      : alphaRightPanelMode === "console"
        ? "Console"
        : "Right panel";
  }
  if (alphaRightPanelTitle) {
    alphaRightPanelTitle.textContent = tradingActive
      ? (alphaRightPanelMode === "orders" ? "Order entry" : "Pine / Rust / KASM")
      : webExplorerActive
        ? (alphaRightPanelMode === "console" ? "Web console" : "Proof HUD")
      : alphaRightPanelMode === "console"
        ? "Rust / KASM"
        : "Verification";
  }
  renderAlphaRightPanelTabs();
  if (tradingActive && alphaRightPanelMode === "orders") {
    alphaProofContent.innerHTML = "";
    tradingPanelBridge()?.renderOrders?.(alphaProofContent);
    queueForgeCustomScrollbarSync(alphaProofContent);
    return;
  }
  if (webExplorerActive && alphaRightPanelMode === "proof") {
    renderWebExplorerProofPanel();
    queueForgeCustomScrollbarSync(alphaProofContent);
    return;
  }
  if (alphaRightPanelMode === "console") renderAlphaConsolePanel();
  else renderAlphaProofPanel();
  queueForgeCustomScrollbarSync(alphaProofContent);
}

if (typeof window !== "undefined") {
  window.__forgeSetRightPanelMode = (mode = "proof", open = true) => {
    setAlphaRightPanelMode(mode, { skipRender: !alphaProofPanelOpen });
    if (open) setAlphaProofPanelOpen(true);
  };
}

function setAlphaProofPanelOpen(open) {
  alphaProofPanelOpen = !!open;
  if (alphaProofPanel) {
    alphaProofPanel.hidden = false;
    alphaProofPanel.setAttribute("aria-hidden", String(!alphaProofPanelOpen));
  }
  alphaContent?.classList.toggle("proof-open", alphaProofPanelOpen);
  alphaProofToggle?.classList.toggle("active", alphaProofPanelOpen);
  alphaProofToggle?.setAttribute("aria-label", alphaProofPanelOpen ? "Close right panel" : "Open right panel");
  alphaProofToggle?.setAttribute("title", alphaProofPanelOpen ? "Close right panel" : "Open right panel");
  if (alphaProofPanelOpen) {
    alphaProofRenderedKey = "";
    alphaConsoleRenderedKey = "";
    renderAlphaRightPanel();
  }
  refreshAlphaCanvasAfterLayoutChange();
  scheduleAlphaRender();
}

function makeProofSection(title, rows, note = "") {
  const section = createUiEl("section", "proof-section");
  section.appendChild(createUiEl("h3", "proof-section-title", title));
  for (const row of rows) {
    section.appendChild(makeProofRow(row.label, row.value, row.status));
  }
  if (note) section.appendChild(createUiEl("p", "proof-note", note));
  return section;
}

function invalidateWebExplorerProofPanel() {
  alphaProofRenderedKey = "";
  if (alphaProofPanelOpen && alphaRightPanelMode === "proof" && typeof isWebExplorerUiActive === "function" && isWebExplorerUiActive()) {
    renderAlphaRightPanel();
  }
}

function webExplorerProofMs(value) {
  const n = Number(value || 0);
  return Number.isFinite(n) && n > 0 ? `${n.toFixed(n >= 100 ? 0 : 1)} ms` : "not measured";
}

function webExplorerProofUs(value) {
  const n = Number(value || 0);
  if (!Number.isFinite(n) || n <= 0) return "not measured";
  return n >= 1000 ? `${(n / 1000).toFixed(n >= 100000 ? 0 : 2)} ms` : `${Math.round(n)} us`;
}

function webExplorerProofShortUrl(value) {
  const text = String(value || "").trim();
  if (!text) return "not loaded";
  return text.length > 84 ? `${text.slice(0, 42)}…${text.slice(-32)}` : text;
}

function webExplorerProofGpuSummary() {
  const gpus = Array.isArray(forgeHardwareInfo?.gpus) ? forgeHardwareInfo.gpus : [];
  if (!gpus.length) return "not detected";
  return gpus.map((gpu) => formatGpuName(gpu)).join(" / ");
}

function webExplorerProofDigest() {
  const snapshot = webExplorerMemorySnapshot || {};
  const stats = webExplorerProofStats || {};
  const proof = stats.lastAnalysisProof || {};
  const renderer = stats.rendererProbe || {};
  const bounds = stats.lastNativeBounds || snapshot.viewport || {};
  return [
    "WEBEXPLORER_PROOF_V1",
    `url=${String(webExplorerSnapshot?.currentUrl || snapshot.currentUrl || "")}`,
    `webview=live-native visible=${!!stats.nativeVisible} bounds=${Math.round(Number(bounds.width || 0))}x${Math.round(Number(bounds.height || 0))}@${Math.round(Number(bounds.x || 0))},${Math.round(Number(bounds.y || 0))}`,
    `renderer_process=parent:${renderer.parentPid || "unknown"} webview2:${renderer.webview2ProcessCount ?? "not-probed"} gpu_engine=${renderer.gpuEngine || "not-probed"}`,
    `forge_gpus=${webExplorerProofGpuSummary()}`,
    `capture=nodes:${stats.lastAnalysisNodeCount || snapshot.nodeCount || 0} visible:${stats.lastAnalysisVisibleCount || 0} commits:${stats.domCommitCount || 0} dom_ms:${Number(proof.domCaptureElapsedMs || stats.lastDomCommit?.captureElapsedMs || 0).toFixed(2)} analysis_us:${Number(proof.analysisElapsedUs || 0).toFixed(0)}`,
    `reuse=analysis_hit:${!!proof.analysisCacheHit} atlas:${proof.atlasCacheChecked ? (proof.atlasCacheHit ? "hit" : "miss") : "not-ready"} kasm_executed:${proof.kasmJobsExecuted || 0} kasm_avoided:${proof.kasmJobsAvoided || 0}`,
    `tree=${String(stats.lastTreeHash || snapshot.treeHash || "").slice(0, 20)} blocks=${stats.lastAnalysisBlockCount || 0} render=${stats.lastRenderMode || "native"}`,
    `policy=2 idle captures, 1800 node cap, mutation capture off, clone export off unless FORGE_WEBEXPLORER_AUTO_EXPORT=1`,
  ].join("\n");
}

function renderWebExplorerProofPanel() {
  if (!alphaProofContent || !alphaProofPanelOpen || alphaRightPanelMode !== "proof") return;
  const snapshot = webExplorerMemorySnapshot || {};
  const stats = webExplorerProofStats || {};
  const proof = stats.lastAnalysisProof || {};
  const renderer = stats.rendererProbe || {};
  const bounds = stats.lastNativeBounds || snapshot.viewport || {};
  const hardwareGpuCount = Array.isArray(forgeHardwareInfo?.gpus) ? forgeHardwareInfo.gpus.length : 0;
  const key = JSON.stringify({
    url: webExplorerSnapshot?.currentUrl || snapshot.currentUrl || "",
    tree: stats.lastTreeHash || snapshot.treeHash || "",
    nodes: stats.lastAnalysisNodeCount || snapshot.nodeCount || 0,
    commits: stats.domCommitCount || 0,
    analysisMs: Math.round(Number(stats.lastAnalysisMs || 0)),
    nativePresentCount: stats.nativePresentCount || 0,
    nativeVisible: !!stats.nativeVisible,
    bounds,
    proof,
    rendererPid: renderer.parentPid || 0,
    rendererCount: renderer.webview2ProcessCount || 0,
    rendererEngine: renderer.gpuEngine || "",
    hardwareGpuCount,
    hardware: forgeHardwareInfo?.gpus?.map((gpu) => `${gpu.name}:${gpu.backend}`).join("|") || "",
  });
  if (key === alphaProofRenderedKey) return;
  alphaProofRenderedKey = key;
  alphaProofContent.innerHTML = "";

  const actions = createUiEl("div", "proof-actions webexplorer-proof-actions");
  const refreshButton = createUiEl("button", "compute-action", "Refresh proof");
  refreshButton.type = "button";
  refreshButton.dataset.webexplorerProofAction = "refresh";
  actions.appendChild(refreshButton);
  const copyButton = createUiEl("button", "compute-action", "Copy digest");
  copyButton.type = "button";
  copyButton.dataset.webexplorerProofAction = "copy-digest";
  actions.appendChild(copyButton);
  alphaProofContent.appendChild(actions);

  alphaProofContent.appendChild(makeProofSection("WebView proof", [
    { label: "Mode", value: "live native WebView", status: stats.nativeVisible ? "ok" : "neutral" },
    { label: "URL", value: webExplorerProofShortUrl(webExplorerSnapshot?.currentUrl || snapshot.currentUrl), status: webExplorerSnapshot?.currentUrl || snapshot.currentUrl ? "ok" : "neutral" },
    { label: "Bounds", value: bounds?.width ? `${Math.round(bounds.width)}x${Math.round(bounds.height)} @ ${Math.round(bounds.x || 0)},${Math.round(bounds.y || 0)}` : "not placed", status: bounds?.width ? "ok" : "neutral" },
    { label: "Native sync", value: `${formatCount(stats.nativePresentCount || 0)} present · ${formatCount(stats.nativeHideCount || 0)} hide`, status: stats.nativePresentCount ? "ok" : "neutral" },
    { label: "WebView2 proc", value: renderer.webview2ProcessCount != null ? `${formatCount(renderer.webview2ProcessCount)} process · parent ${renderer.parentPid || "?"}` : "not probed", status: renderer.webview2ProcessCount ? "ok" : "neutral" },
    { label: "GPU engine", value: renderer.gpuEngine || "Windows sample pending", status: renderer.gpuEngine && !/not active|pending/i.test(renderer.gpuEngine) ? "ok" : "neutral" },
  ], renderer.error ? `Renderer probe: ${renderer.error}` : "This proves the WebView is live and bounded. GPU engine is a Windows/WebView2 process sample, separate from Forge compute routing."));

  alphaProofContent.appendChild(makeProofSection("Forge GPU proof", [
    { label: "Detected GPUs", value: hardwareGpuCount ? webExplorerProofGpuSummary() : "not detected yet", status: hardwareGpuCount ? "ok" : "neutral" },
    { label: "CUDA", value: forgeHardwareInfo?.cuda_enabled ? "enabled" : "not active / unknown", status: forgeHardwareInfo?.cuda_enabled ? "ok" : "neutral" },
    { label: "NVRTC", value: forgeHardwareInfo?.nvrtc_available ? "available" : "not available / not needed for cuda_min", status: forgeHardwareInfo?.nvrtc_available ? "ok" : "neutral" },
    { label: "Backend", value: forgeHardwareInfo?.cuda_enabled ? "CUDA available" : (hardwareGpuCount ? "WGPU/CPU route available" : "CPU fallback"), status: forgeHardwareInfo?.cuda_enabled || hardwareGpuCount ? "ok" : "neutral" },
    { label: "Dual compute", value: hardwareGpuCount >= 2 ? "possible for compatible heavy KASM batches" : "single GPU or not proven", status: hardwareGpuCount >= 2 ? "ok" : "neutral" },
  ], "These are Forge compute capabilities. They are separate from WebView page rendering."));

  alphaProofContent.appendChild(makeProofSection("Capture cost", [
    { label: "DOM commits", value: formatCount(stats.domCommitCount || 0), status: stats.domCommitCount ? "ok" : "neutral" },
    { label: "Last commit", value: stats.lastDomCommit?.nodeCount != null ? `${formatCount(stats.lastDomCommit.nodeCount)} nodes · ${stats.lastDomCommit.source || "dom"}` : "pending", status: stats.lastDomCommit?.nodeCount ? "ok" : "neutral" },
    { label: "DOM capture", value: webExplorerProofMs(proof.domCaptureElapsedMs || stats.lastDomCommit?.captureElapsedMs), status: proof.domCaptureElapsedMs || stats.lastDomCommit?.captureElapsedMs ? "ok" : "neutral" },
    { label: "Rust commit", value: webExplorerProofUs(proof.rustCommitElapsedUs || stats.lastDomCommit?.rustCommitElapsedUs), status: proof.rustCommitElapsedUs || stats.lastDomCommit?.rustCommitElapsedUs ? "ok" : "neutral" },
    { label: "Analysis IPC", value: webExplorerProofMs(stats.lastAnalysisMs), status: stats.lastAnalysisMs ? "ok" : "neutral" },
    { label: "Analysis core", value: webExplorerProofUs(proof.analysisElapsedUs), status: proof.analysisElapsedUs ? "ok" : "neutral" },
    { label: "Visible nodes", value: stats.lastAnalysisVisibleCount ? `${formatCount(stats.lastAnalysisVisibleCount)} / ${formatCount(stats.lastAnalysisNodeCount)}` : "pending", status: stats.lastAnalysisVisibleCount ? "ok" : "neutral" },
    { label: "Blocks", value: stats.lastAnalysisBlockCount ? `${formatCount(stats.lastAnalysisBlockCount)} · ${stats.lastPageProfile || "generic"}` : "none", status: stats.lastAnalysisBlockCount ? "ok" : "neutral" },
    { label: "Clone export", value: stats.lastAutoExportEnabled ? "debug enabled" : "off", status: stats.lastAutoExportEnabled ? "warn" : "ok" },
  ], "Current policy: two idle captures, 1800 node cap, mutation recapture disabled. Deep extraction should move behind explicit /web_extract."));

  alphaProofContent.appendChild(makeProofSection("KASM / Atlas reuse", [
    { label: "Analysis cache", value: `${proof.analysisCacheHit ? "hit" : "miss"} · ${formatCount(proof.analysisCacheHits || 0)} hits / ${formatCount(proof.analysisCacheMisses || 0)} misses`, status: proof.analysisCacheHit ? "ok" : "neutral" },
    { label: "Cache budget", value: `${formatCount(proof.analysisCacheEntries || 0)} / ${formatCount(proof.analysisCacheMaxEntries || 0)} entries · ${formatBytes(proof.analysisCacheEstimatedBytes || 0)} / ${formatBytes(proof.analysisCacheMaxBytes || 0)}`, status: proof.analysisCacheEntries <= proof.analysisCacheMaxEntries ? "ok" : "warn" },
    { label: "Evictions", value: formatCount(proof.analysisCacheEvictions || 0), status: proof.analysisCacheEvictions ? "ok" : "neutral" },
    { label: "Atlas cache", value: proof.atlasCacheChecked ? `${proof.atlasCacheHit ? "hit" : "miss"} · ${formatCount(proof.atlasCacheHits || 0)} hits / ${formatCount(proof.atlasCacheMisses || 0)} misses` : "backend not warm yet", status: proof.atlasCacheHit ? "ok" : "neutral" },
    { label: "KASM jobs", value: `${formatCount(proof.kasmJobsExecuted || 0)} executed · ${formatCount(proof.kasmJobsAvoided || 0)} avoided`, status: proof.kasmJobsAvoided ? "ok" : "neutral" },
    { label: "Classifier", value: `${formatCount(proof.classifierKasmExecuted || 0)} executed · ${formatCount(proof.classifierKasmAvoided || 0)} avoided · ${formatCount(proof.classifierCacheEntries || 0)} cached`, status: proof.classifierKasmAvoided ? "ok" : "neutral" },
    { label: "Cache key", value: shortHash(proof.treeHash || stats.lastTreeHash || snapshot.treeHash || "", 12, 8), status: proof.treeHash || stats.lastTreeHash || snapshot.treeHash ? "ok" : "neutral" },
  ], proof.note || "The speed moat is to hash memory trees and cache ranked plans before the LLM sees them."));

  if (stats.lastError) {
    alphaProofContent.appendChild(makeProofSection("Last error", [
      { label: "Message", value: stats.lastError, status: "warn" },
    ]));
  }
}

function renderAlphaProofPanel() {
  if (!alphaProofContent || !alphaProofPanelOpen || alphaRightPanelMode !== "proof") return;
  const manifest = selectedForgeJobManifest || {};
  const job = currentForgeJob();
  const key = JSON.stringify({
    job: selectedForgeJobId,
    manifestId: selectedForgeJobManifestId,
    status: alphaVerificationState?.status,
    mcp: manifest?.mcp_result?.available,
    visualMapping: manifest?.visual_mapping?.hash || manifest?.visual_mapping_path || "",
    artifacts3d: Array.isArray(manifest?.artifacts_3d) ? manifest.artifacts_3d.length : 0,
    visualSelection: alpha3dState?.selection ? `${alpha3dState.selection.mode}:${alpha3dState.selection.vertexIndex}:${alpha3dState.selection.selectedAtMs}` : "",
    logs: alphaForgeLogs.length,
    contextAccounting: manifest?.context_accounting?.avoided_bytes || job?.context_accounting?.avoided_bytes || "",
    computeAvoided: JSON.stringify(manifest?.compute_avoided || job?.compute_avoided || manifest?.context_accounting?.compute_avoided || {}),
  });
  if (key === alphaProofRenderedKey) return;
  alphaProofRenderedKey = key;
  alphaProofContent.innerHTML = "";

  const actions = createUiEl("div", "proof-actions");
  const actionDefs = [
    ["verify", "Verify hashes"],
    ["download-proof", "Download verification"],
    ["download-visual-mapping", "Download visual mapping"],
    ["copy-visual-artifacts", "Copy artifact refs"],
    ["inject-mcp", manifest?.mcp_result?.available ? "MCP injected" : "Inject into MCP"],
  ];
  const visualMapping = selectedVisualMappingSummary();
  for (const [action, label] of actionDefs) {
    const button = createUiEl("button", "compute-action", label);
    button.type = "button";
    button.dataset.computeAction = action;
    if ((action === "download-proof" || action === "inject-mcp") && !selectedForgeJobId) button.disabled = true;
    if ((action === "download-visual-mapping" || action === "copy-visual-artifacts") && !visualMapping.available) button.disabled = true;
    if (action === "inject-mcp" && manifest?.mcp_result?.available) button.disabled = true;
    actions.appendChild(button);
  }
  alphaProofContent.appendChild(actions);

  alphaProofContent.appendChild(makeProofSection("Input identity", [
    { label: "Job id", value: shortHash(selectedForgeJobId || manifest.job_id, 12, 8), status: selectedForgeJobId ? "ok" : "neutral" },
    { label: "File hash", value: shortHash(manifest.file_hash), status: alphaVerificationState?.status === "verified" ? "ok" : alphaVerificationState?.status === "warning" ? "warn" : "neutral" },
    { label: "Local check", value: alphaVerificationState?.actualHash ? shortHash(alphaVerificationState.actualHash) : "not run", status: alphaVerificationState?.status === "verified" ? "ok" : alphaVerificationState?.status === "warning" ? "warn" : "neutral" },
    { label: "Bytes", value: formatBytes(manifest.bytes || alphaDocState.fileSize), status: manifest.bytes || alphaDocState.fileSize ? "ok" : "neutral" },
  ], alphaVerificationState?.message || "Verify recomputes the local Forge file fingerprint and compares it with the manifest."));

  alphaProofContent.appendChild(makeProofSection("Result integrity", [
    { label: "Status", value: job?.status || manifest.status || alphaRunState.phase || "idle", status: String(job?.status || manifest.status).includes("completed") ? "ok" : "neutral" },
    { label: "Strategy hash", value: shortHash(manifest.strategy_hash || alphaRunState.report?.strategy_hash), status: manifest.strategy_hash || alphaRunState.report?.strategy_hash ? "ok" : "neutral" },
    { label: "Bars", value: formatCount(manifest.bars || job?.bars || alphaDocState.candles.length), status: manifest.bars || alphaDocState.candles.length ? "ok" : "neutral" },
    { label: "Holdout", value: manifest.holdout?.target_hit_pct != null ? `${Number(manifest.holdout.target_hit_pct).toFixed(1)}% · ${formatCount(manifest.holdout.trades)} trades` : "pending", status: manifest.holdout ? "ok" : "neutral" },
  ], "These values are read from the persisted result manifest, not from the visible transcript text."));

  alphaProofContent.appendChild(makeProofSection("Artifacts", [
    { label: "Manifest", value: `${formatBytes(manifest.manifest_bytes)} · ${shortHash(manifest.manifest_path, 16, 12)}`, status: selectedForgeJobManifest ? "ok" : "neutral" },
    { label: "Full log", value: `${formatBytes(manifest.log_bytes || alphaForgeLogs.join("\n").length)} · not sent to LLM`, status: "ok" },
    { label: "MCP result", value: manifest?.mcp_result?.available ? "available to agent" : "not injected", status: manifest?.mcp_result?.available ? "ok" : "neutral" },
    { label: "Agent", value: (manifest.agents || job?.agents || [])[0]?.name || "unknown", status: (manifest.agents || job?.agents || []).length ? "ok" : "neutral" },
  ], "The agent can receive a compact reference instead of raw CSV/log payloads."));

  const context = manifest?.context_accounting || manifest?.contextAccounting || jobContextAccounting(job) || {};
  const saved = context?.tokens_saved || context?.tokensSaved || {};
  const tokenTypical = Number(saved?.typical || context?.estimated_tokens || context?.estimatedTokens || 0);
  const tokenLow = Number(saved?.low || context?.estimated_tokens_low || context?.estimatedTokensLow || 0);
  const tokenHigh = Number(saved?.high || context?.estimated_tokens_high || context?.estimatedTokensHigh || 0);
  if (tokenTypical || context?.avoided_bytes) {
    alphaProofContent.appendChild(makeProofSection("Token economy", [
      { label: "Mode", value: saved?.mode || context?.token_mode || "estimated", status: saved?.mode === "exact" ? "ok" : "neutral" },
      { label: "Saved", value: tokenTypical ? `${compactTokenCount(tokenTypical)} tokens` : "pending", status: tokenTypical ? "ok" : "neutral" },
      { label: "Range", value: tokenLow || tokenHigh ? `${compactTokenCount(tokenLow || tokenTypical)} - ${compactTokenCount(tokenHigh || tokenTypical)}` : "not available", status: tokenLow || tokenHigh ? "ok" : "neutral" },
      { label: "Bytes avoided", value: formatBytes(saved?.bytes_not_sent || context?.avoided_bytes), status: context?.avoided_bytes ? "ok" : "neutral" },
      { label: "Raw input", value: formatBytes(saved?.raw_input_bytes_not_sent || context?.raw_input_bytes_not_sent || context?.csv_bytes), status: "ok" },
      { label: "Logs/artifacts", value: `${formatBytes((saved?.log_bytes_not_sent || context?.log_bytes_not_sent || context?.log_bytes || 0))} / ${formatBytes((saved?.artifact_bytes_not_sent || context?.artifact_bytes_not_sent || context?.artifact_bytes || 0))}`, status: "ok" },
    ], "Bytes are exact. Tokens are estimated unless the calling agent supplies its exact tokenizer count."));
  }

  const compute = manifest?.compute_avoided || job?.compute_avoided || context?.compute_avoided || manifest?.execution?.toolbox?.compute_avoided || {};
  if (compute && Object.keys(compute).length) {
    alphaProofContent.appendChild(makeProofSection("Compute counters", [
      { label: "Engine", value: compute.engine || compute.program_kind || compute.mode || "Forge", status: "ok" },
      { label: "Candidates", value: compute.candidates_evaluated != null ? formatCount(compute.candidates_evaluated) : formatCount(compute.metric_count), status: compute.candidates_evaluated != null || compute.metric_count != null ? "ok" : "neutral" },
      { label: "Combinations", value: compute.combinations_tried != null ? formatCount(compute.combinations_tried) : compute.operations_unit || "metric invocations", status: compute.combinations_tried != null ? "ok" : "neutral" },
      { label: "Cache hits", value: compute.cache_hits?.total != null ? formatCount(compute.cache_hits.total) : formatCount(compute.cache_hit_count), status: (compute.cache_hits?.total || compute.cache_hit_count) ? "ok" : "neutral" },
      { label: "GPU dispatch", value: compute.gpu_jobs_dispatched != null ? `${formatCount(compute.gpu_jobs_dispatched)} dispatched · ${formatCount(compute.gpu_jobs_skipped_by_cache)} skipped` : "not applicable", status: compute.gpu_jobs_dispatched ? "ok" : "neutral" },
      { label: "Elapsed", value: compute.elapsed_ms != null ? `${Number(compute.elapsed_ms).toFixed(3)} ms` : "see live logs", status: compute.elapsed_ms != null ? "ok" : "neutral" },
    ], compute.note || "These are Forge executor counters, not invented token equivalents."));
  }

  alphaProofContent.appendChild(makeProofSection("Visual mapping", [
    { label: "Contract", value: visualMapping.available ? `${visualMapping.version || "forge.visual_mapping.v1"} · ${visualMapping.kind || "linked result view"}` : "not exported yet", status: visualMapping.available ? "ok" : "neutral" },
    { label: "Views", value: visualMapping.viewCount ? `${formatCount(visualMapping.viewCount)} mapped view${visualMapping.viewCount === 1 ? "" : "s"}` : "pending", status: visualMapping.viewCount ? "ok" : "neutral" },
    { label: "3D files", value: visualMapping.artifactCount ? `${formatCount(visualMapping.artifactCount)} downloadable .ply refs` : "none", status: visualMapping.artifactCount ? "ok" : "neutral" },
    { label: "Mapping hash", value: shortHash(visualMapping.hash), status: visualMapping.hash ? "ok" : "neutral" },
    { label: "Mapping file", value: shortHash(visualMapping.path, 18, 14), status: visualMapping.path ? "ok" : "neutral" },
    { label: "3D index", value: visualMapping.indexHash ? `${shortHash(visualMapping.indexHash)} · ${shortHash(visualMapping.indexPath, 16, 12)}` : shortHash(visualMapping.indexPath, 16, 12), status: visualMapping.indexPath ? "ok" : "neutral" },
  ], "The map is tied to compute artifacts by hash. Agents should attach/import these references, not paste point clouds, metrics or proofs into chat."));

  const selection = alpha3dSelectionSummary?.();
  if (selection) {
    alphaProofContent.appendChild(makeProofSection("3D selection", [
      { label: "Mode", value: selection.mode, status: "ok" },
      { label: "Vertex", value: `#${formatCount(selection.vertex_index)}${selection.point_index != null ? ` · point #${formatCount(selection.point_index)}` : ""}`, status: "ok" },
      { label: "Bar/cell", value: selection.bar_index != null ? `bar #${formatCount(selection.bar_index)}${selection.role ? ` · ${selection.role}` : ""}` : selection.cell || "not mapped", status: selection.bar_index != null || selection.cell ? "ok" : "neutral" },
      { label: "World", value: selection.world ? `${selection.world.map((v) => Number(v).toFixed(3)).join(", ")}` : "pending", status: selection.world ? "ok" : "neutral" },
      { label: "Artifact", value: selection.artifact_hash ? shortHash(selection.artifact_hash) : "preview only", status: selection.artifact_hash ? "ok" : "neutral" },
      { label: "Mapping", value: selection.mapping_hash ? shortHash(selection.mapping_hash) : shortHash(selection.mapping_path, 16, 12), status: selection.mapping_hash || selection.mapping_path ? "ok" : "neutral" },
    ], "Clicking the 3D canvas selects a compact reference into the current visual mapping. It does not inline the source file or point cloud."));
  }
}

function downloadTextFile(fileName, text, type = "application/json") {
  const blob = new Blob([text], { type });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = fileName;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 500);
}

async function verifySelectedJob() {
  const manifest = selectedForgeJobManifest || {};
  const expectedHash = manifest.file_hash == null ? "" : String(manifest.file_hash);
  const primary = alphaSessionFiles[0];
  let actualHash = "";
  let ok = false;
  let message = "No local source file loaded for hash verification.";
  try {
    if (primary && expectedHash) {
      const buf = primary.arrayBuffer
        ? await primary.arrayBuffer()
        : new TextEncoder().encode(await primary.text()).buffer;
      actualHash = computeQuickFileHashDecimal(buf);
      ok = actualHash === expectedHash;
      message = ok ? "Input hash matches manifest." : "Input hash mismatch.";
    } else if (!expectedHash) {
      message = "Manifest does not expose an input hash yet.";
    }
  } catch (err) {
    message = `Verification failed: ${err}`;
  }
  alphaVerificationState = {
    status: ok ? "verified" : "warning",
    expectedHash,
    actualHash,
    message,
  };
  alphaLogRenderedVersion = -1;
  alphaProofRenderedKey = "";
  renderAlphaProofPanel();
  scheduleAlphaRender();
}

async function handleComputeTranscriptAction(action) {
  const title = (currentForgeJob() ? forgeJobLabel(currentForgeJob()) : alphaDocState.fileName || "forge-compute")
    .replace(/[^\w.-]+/g, "_")
    .replace(/^_+|_+$/g, "") || "forge-compute";
  if (action === "verify") {
    await verifySelectedJob();
  } else if (action === "open-proof") {
    setAlphaRightPanelMode("proof", { skipRender: true });
    setAlphaProofPanelOpen(true);
  } else if (action === "download-manifest") {
    downloadTextFile(`${title}.manifest.json`, selectedManifestText(), "application/json");
  } else if (action === "download-proof") {
    downloadTextFile(`${title}.proof.json`, JSON.stringify(selectedProofObject(), null, 2), "application/json");
  } else if (action === "download-visual-mapping") {
    if (!selectedForgeJobId || !window.__TAURI__?.core?.invoke) return;
    const artifact = await window.__TAURI__.core.invoke("read_forge_job_artifact_text", {
      jobId: selectedForgeJobId,
      kind: "visual_mapping",
    });
    downloadTextFile(artifact?.fileName || `${title}.visual_mapping.json`, artifact?.text || "", "application/json");
  } else if (action === "copy-visual-artifacts") {
    const manifest = selectedForgeJobManifest || {};
    const refs = {
      job_id: selectedForgeJobId || manifest.job_id || null,
      visual_mapping: selectedVisualMappingSummary(),
      artifacts_3d: manifest.artifacts_3d || manifest.mcp_result?.artifacts_3d || [],
      content_policy: {
        download_by_reference_only: true,
        do_not_inline_point_clouds_metrics_or_proofs: true,
      },
    };
    await navigator.clipboard.writeText(JSON.stringify(refs, null, 2));
  } else if (action === "inject-mcp") {
    if (!selectedForgeJobId || !window.__TAURI__?.core?.invoke) return;
    selectedForgeJobManifest = await window.__TAURI__.core.invoke("publish_forge_job_to_mcp", {
      jobId: selectedForgeJobId,
    });
    selectedForgeJobManifestId = selectedForgeJobId;
    alphaProofRenderedKey = "";
    updateAlpha3dResultOverlay?.();
    renderAlphaProofPanel();
  } else if (action === "download-log") {
    downloadTextFile(`${title}.log.txt`, alphaForgeLogs.join("\n"), "text/plain");
  } else if (action === "download-source") {
    const primary = alphaSessionFiles[0];
    if (!primary?.text) return;
    downloadTextFile(primary.name || `${title}.csv`, await primary.text(), "text/csv");
  }
}

function appendCanvasChatMessage(role, text, meta = {}) {
  const cleanText = redactCanvasSecrets(text).trim();
  if (!cleanText) return null;
  const nextMeta = { ...(meta || {}) };
  if (!nextMeta.planetVisual && role === "assistant") {
    const planetVisual = inferPlanetVisualFromText(cleanText);
    if (planetVisual) nextMeta.planetVisual = planetVisual;
  }
  const targetSessionId = String(meta?.sessionJobId || "").trim();
  const currentSessionId = currentAlphaSessionJobId();
  const last = alphaCanvasChatMessages[alphaCanvasChatMessages.length - 1];
  const turnId = nextMeta?.turnId || "";
  if (
    (!targetSessionId || !currentSessionId || targetSessionId === currentSessionId)
    && last?.role === role
    && last.text === cleanText
    && (last.meta?.turnId || "") === turnId
  ) {
    return last;
  }
  const message = {
    id: ++alphaCanvasChatSeq,
    role,
    text: cleanText,
    meta: nextMeta,
    at: new Date().toISOString(),
  };
  if (targetSessionId && targetSessionId !== currentSessionId) {
    appendAlphaCanvasStoredSessionMessage(targetSessionId, message);
    renderForgeJobs();
    return message;
  }
  alphaCanvasChatMessages.push(message);
  trimArrayInPlace(alphaCanvasChatMessages, 80);
  const shouldVoiceSync = role === "assistant" && !meta?.attachmentOnly && forgeVoiceSettings().autoSpeak;
  startCanvasAssistantTyping(message, { pauseUntilVoice: shouldVoiceSync, voiceSync: shouldVoiceSync });
  saveAlphaCanvasSessionState();
  alphaCanvasChatVersion += 1;
  alphaLogRenderedVersion = -1;
  // Once a conversation has started, retire the rotating prompt suggestions —
  // the user is now talking to the LLM, not browsing examples.
  if (typeof stopCanvasChatPlaceholderAnimation === "function") {
    stopCanvasChatPlaceholderAnimation();
  }
  if (typeof clearAllCanvasChatPlaceholders === "function") {
    clearAllCanvasChatPlaceholders();
  }
  syncAlphaDropSurface?.();
  scheduleAlphaRender();
  if (shouldVoiceSync) {
    void speakForgeCanvasText(cleanText, null, {
      onAudioReady: () => releaseCanvasAssistantTyping(message),
      onFail: () => releaseCanvasAssistantTyping(message),
    });
  }
  if (role === "assistant") {
    void ensureAssistantSpatialMentions(message);
  }
  return message;
}

function firstStringValue(...values) {
  for (const value of values) {
    const text = String(value || "").trim();
    if (text) return text;
  }
  return "";
}

function forgeToolResultSummary(payload) {
  return payload?.data?.summary || payload?.data || {};
}

function forgeToolResultJobId(summary) {
  const result = summary?.result || {};
  return firstStringValue(
    summary?.jobId,
    summary?.job_id,
    result?.data?.job?.job_id,
    result?.data?.job?.jobId,
    result?.data?.job_id,
    result?.data?.jobId,
    result?.data?.manifest?.job_id,
    result?.data?.manifest?.jobId,
    result?.job?.job_id,
    result?.job?.jobId,
    result?.job_id,
    result?.jobId,
    result?.manifest?.job_id,
    result?.manifest?.jobId
  );
}

function forgeToolResultProgramHash(summary) {
  const result = summary?.result || {};
  return firstStringValue(
    summary?.programHash,
    summary?.program_hash,
    result?.data?.program?.program_hash,
    result?.data?.program?.programHash,
    result?.data?.program_hash,
    result?.data?.programHash,
    result?.program?.program_hash,
    result?.program?.programHash,
    result?.program_hash,
    result?.programHash
  );
}

function canvasLiveComputeFinal(status) {
  return ["completed", "done", "failed", "error", "aborted", "cancelled", "canceled", "completed_with_metric_errors", "completed_with_visual_view_errors", "completed_with_unresolved_ops"]
    .includes(String(status || "").toLowerCase());
}

function hasActiveCanvasLiveCompute() {
  for (const state of alphaCanvasLiveComputes.values()) {
    if (!canvasLiveComputeFinal(state.status)) return true;
  }
  return false;
}

function activeCanvasLiveComputeJobId() {
  let latest = null;
  for (const state of alphaCanvasLiveComputes.values()) {
    if (canvasLiveComputeFinal(state.status)) continue;
    if (!latest || Number(state.updatedAt || 0) > Number(latest.updatedAt || 0)) latest = state;
  }
  return latest?.jobId || "";
}

function detachCanvasTurnForLiveCompute(turnId) {
  const id = String(turnId || "").trim();
  if (!id) return;
  alphaCanvasDetachedComputeTurns.add(id);
  if (forgeCanvasChatActiveTurnId === id) {
    setCanvasChatPendingAssistants([]);
    forgeCanvasChatActiveTurnId = "";
    forgeCanvasChatActiveSessionId = "";
    forgeCanvasChatAbortController = null;
    setCanvasChatBusy(false);
  } else {
    syncCanvasChatSendState();
  }
}

function canvasTurnDetachedForLiveCompute(turnId) {
  return alphaCanvasDetachedComputeTurns.has(String(turnId || "").trim());
}

function isForgeInternalExecutionLogLine(line) {
  const s = String(line || "").trim();
  if (!s) return true;
  return (
    /\b(routing|scorings|work items|cuda|atlas-cache|cache in \d|dispatched=|skipped=|avoided|ns\/job|ns\/work-item|gpu|opcode_hits|pair_hits|atlas_hits|combinations=|candidates=|depth \d+\/\d+)\b/i.test(s) ||
    /\bskip_prepass|recognizers|structured\/atlas|direct beam search|memo lookup\b/i.test(s)
  );
}

function shouldDisplayLiveComputeLine(line) {
  const s = String(line || "").trim();
  if (!s) return false;
  const lower = s.toLowerCase();
  if (/^(forge ui|forge tools|codex bridge|program selected|selecting a forge program|working for|compute$|input$|synthesis$)/i.test(s)) return false;
  if (/^pending (empty session created|upload session updated|session updated)/i.test(s)) return false;
  if (/^(store_dir|atlas_path|llm_context_policy|context_accounting|manifest_path|safe_next_call)=/.test(lower)) return false;
  if (isForgeInternalExecutionLogLine(s)) return false;
  if (/\b(forge backend|backend cache|kasm|mcp|tauri|stderr|stdout|artifact path|manifest|source content|raw content|bytes kept outside|token|toolbox|working directory)\b/i.test(s)) return false;
  if (/^\[?(forge-internal|mcp:|codex|gemini|claude)/i.test(s)) return false;
  return /(candle|ohlcv|reading|preparing|running|label|example|long_pos|short_pos|metric|signal|band|vwap|ema|rsi|atr|adx|stoch|volatility|volume|z[- ]?score|std|deviation|window|feature|classifier|train|training|holdout|score|scoring|loss|best|pnl|target|synthesis|detector|regime|correlation|cluster|pca|map|axis|formula|calcul|math|algorithm)/i.test(s);
}

function liveComputeString(value) {
  return String(value ?? "").trim();
}

function liveComputeCompactParams(params) {
  if (!params || typeof params !== "object" || Array.isArray(params)) return "";
  const entries = Object.entries(params)
    .filter(([key, value]) => value !== null && value !== undefined && !["formula", "equation", "expression", "math", "algorithm", "method", "procedure"].includes(key))
    .slice(0, 8)
    .map(([key, value]) => `${key}=${typeof value === "object" ? JSON.stringify(value) : value}`);
  return entries.join(", ");
}

function liveComputeMetricInputs(metric) {
  if (Array.isArray(metric?.inputs)) return metric.inputs.map(liveComputeString).filter(Boolean);
  const one = liveComputeString(metric?.input);
  return one ? one.split(",").map((part) => part.trim()).filter(Boolean) : [];
}

function liveComputeMetricFormula(metric) {
  for (const key of ["formula", "equation", "expression", "math"]) {
    const value = liveComputeString(metric?.[key]);
    if (value) return value;
  }
  for (const key of ["formula", "equation", "expression", "math"]) {
    const value = liveComputeString(metric?.params?.[key]);
    if (value) return value;
  }
  const op = liveComputeString(metric?.op) || "custom_metric";
  const inputs = liveComputeMetricInputs(metric);
  const args = inputs.length ? inputs.join(", ") : "inputs";
  const params = liveComputeCompactParams(metric?.params);
  return params ? `${op}(${args}; ${params})` : `${op}(${args})`;
}

function liveComputeMetricAlgorithm(metric) {
  for (const key of ["algorithm", "method", "procedure"]) {
    const value = liveComputeString(metric?.[key]);
    if (value) return value;
  }
  for (const key of ["algorithm", "method", "procedure"]) {
    const value = liveComputeString(metric?.params?.[key]);
    if (value) return value;
  }
  return "";
}

function liveComputeMetricRow(metric, idx = 0) {
  if (!metric || typeof metric !== "object") return null;
  const label = liveComputeString(metric.label)
    || liveComputeString(metric.tag)
    || liveComputeString(metric.name)
    || liveComputeString(metric.output)
    || liveComputeString(metric.op)
    || `metric ${idx + 1}`;
  const formula = liveComputeString(metric.formula) || liveComputeMetricFormula(metric);
  const algorithm = liveComputeString(metric.algorithm) || liveComputeMetricAlgorithm(metric);
  const feeds = Array.isArray(metric.feeds) ? metric.feeds.map(liveComputeString).filter(Boolean) : [];
  const suffix = [
    algorithm ? `algorithm: ${algorithm}` : "",
    feeds.length ? `feeds -> ${feeds.slice(0, 4).join(", ")}` : "",
  ].filter(Boolean).join(" | ");
  return {
    label,
    formula: suffix ? `${formula} | ${suffix}` : formula,
  };
}

function liveComputeMetricArraysFromValue(value, depth = 0, seen = new Set()) {
  if (!value || typeof value !== "object" || depth > 5 || seen.has(value)) return [];
  seen.add(value);
  const arrays = [];
  const maybePush = (arr) => {
    if (!Array.isArray(arr)) return;
    const usable = arr.filter((item) => item && typeof item === "object" && (item.formula || item.op || item.tag || item.output || item.algorithm));
    if (usable.length) arrays.push(usable);
  };
  maybePush(value.metric_contract);
  maybePush(value.metrics);
  maybePush(value.metric_refs);
  maybePush(value.visual_metric_refs);
  if (value.canonical) arrays.push(...liveComputeMetricArraysFromValue(value.canonical, depth + 1, seen));
  if (value.program) arrays.push(...liveComputeMetricArraysFromValue(value.program, depth + 1, seen));
  if (value.visual_program) arrays.push(...liveComputeMetricArraysFromValue(value.visual_program, depth + 1, seen));
  if (value.execution?.toolbox) arrays.push(...liveComputeMetricArraysFromValue(value.execution.toolbox, depth + 1, seen));
  return arrays;
}

function liveComputeMathRows(state) {
  const rows = [];
  const add = (label, formula) => {
    const cleanLabel = liveComputeString(label);
    const cleanFormula = liveComputeString(formula);
    if (cleanLabel && cleanFormula && !rows.some((row) => row.label === cleanLabel)) {
      rows.push({ label: cleanLabel, formula: cleanFormula });
    }
  };
  for (const arr of liveComputeMetricArraysFromValue(state.manifest || state.program || state)) {
    arr.slice(0, 12).forEach((metric, idx) => {
      const row = liveComputeMetricRow(metric, idx);
      if (row) add(row.label, row.formula);
    });
    if (rows.length) break;
  }
  if (!rows.length) {
    add("Metric contract", "Waiting for program metric tags; no formula is inferred from chat or logs.");
  }
  return rows.slice(0, 8);
}

function liveComputeHasRealMathRows(rows) {
  return Array.isArray(rows) && rows.some((row) =>
    String(row?.label || "") !== "Metric contract"
    && !/waiting for program metric tags/i.test(String(row?.formula || ""))
  );
}

function liveComputeVisibleLines(state) {
  return (state.lines || [])
    .map((line) => String(line || "").trim())
    .filter(shouldDisplayLiveComputeLine)
    .slice(-22);
}

function liveComputeCacheRows(state) {
  const rows = [];
  for (const line of state.lines || []) {
    const s = String(line || "").trim();
    if (/identical|already computed|cache|hash|reuse|truly novel|atlas result/i.test(s)) {
      rows.push({
        text: s.replace(/\s+/g, " "),
        redundant: /\b(reused identical|identical mapped|already computed|cache=hit|cache hit|atlas result|reuse|redundant)\b/i.test(s),
      });
    }
  }
  return rows.slice(-4);
}

function ensureCanvasLiveCompute(jobId, turnId = "", options = {}) {
  const normalizedJobId = String(jobId || "").trim();
  if (!normalizedJobId) return null;
  let state = alphaCanvasLiveComputes.get(normalizedJobId);
  if (!state) {
    state = {
      jobId: normalizedJobId,
      turnId: turnId || "",
      title: options.title || "Forge program",
      agentLabel: options.agentLabel || "Forge",
      runtime: options.runtime || forgeCanvasChatTargetMode || "codex",
      status: "running",
      startedAt: Date.now(),
      updatedAt: Date.now(),
      cursor: 0,
      lines: [],
      notified: false,
      stopRequested: false,
    };
    alphaCanvasLiveComputes.set(normalizedJobId, state);
  } else {
    state.turnId = turnId || state.turnId;
    state.title = options.title || state.title;
    state.agentLabel = options.agentLabel || state.agentLabel;
    state.runtime = options.runtime || state.runtime;
    state.updatedAt = Date.now();
  }
  renderCanvasLiveComputeCard();
  syncCanvasChatSendState();
  return state;
}

function renderCanvasLiveComputeCard() {
  if (!alphaCanvasWrap) return;
  const states = Array.from(alphaCanvasLiveComputes.values())
    .sort((a, b) => Number(b.updatedAt || 0) - Number(a.updatedAt || 0));
  const state = states.find((item) => !canvasLiveComputeFinal(item.status)) || states[0] || null;
  const existing = alphaCanvasWrap.querySelector(".canvas-live-compute-card");
  if (!state) {
    existing?.remove();
    alphaCanvasLiveComputeRenderKey = "";
    return;
  }
  const mathRows = liveComputeMathRows(state);
  const hasRealMath = liveComputeHasRealMathRows(mathRows);
  const key = [
    state.jobId,
    state.status,
    state.title,
    state.stopRequested ? "stopping" : "",
    hasRealMath ? mathRows.map((row) => `${row.label}:${row.formula}`).join("|") : "",
  ].join("::");
  if (existing && key === alphaCanvasLiveComputeRenderKey) return;
  alphaCanvasLiveComputeRenderKey = key;

  const card = existing || createUiEl("aside", "canvas-live-compute-card");
  card.dataset.jobId = state.jobId;
  card.classList.toggle("done", canvasLiveComputeFinal(state.status));
  card.classList.toggle("running", !canvasLiveComputeFinal(state.status) && !state.stopRequested);
  card.innerHTML = "";
  const head = createUiEl("div", "canvas-live-compute-head");
  const title = createUiEl("div", "canvas-live-compute-title", state.title || "Forge program");
  const status = createUiEl("div", "canvas-live-compute-status", state.stopRequested ? "Stopping..." : canvasLiveComputeFinal(state.status) ? "Finished" : "Running");
  head.appendChild(title);
  head.appendChild(status);
  card.appendChild(head);

  if (hasRealMath) {
    const math = createUiEl("section", "canvas-live-compute-section math");
    for (const row of mathRows) {
      const item = createUiEl("div", "canvas-live-math-row");
      item.appendChild(createUiEl("span", "canvas-live-math-label", row.label));
      item.appendChild(createUiEl("code", "", row.formula));
      math.appendChild(item);
    }
    card.appendChild(math);
  }
  if (!existing) alphaCanvasWrap.appendChild(card);
}

async function notifyCanvasAgentOfCompletedForgeJob(state, manifest = null) {
  if (!state || state.notified || !window.__TAURI__?.core?.invoke) return;
  state.notified = true;
  const summary = [
    `Forge job ${state.jobId} finished with status=${state.status}.`,
    `Program/card title: ${state.title || "Forge program"}.`,
    "Use only the compact Forge report/manifest context. Do not read raw calculation logs or raw files.",
    "Respond naturally in the existing chat with the useful result, what was learned, and the next best action.",
  ].join("\n");
  try {
    const response = await window.__TAURI__.core.invoke("forge_canvas_assistant_turn", {
      request: {
        message: `INVISIBLE_FORGE_JOB_COMPLETED_EVENT:\n${summary}`,
        jobId: currentAlphaSessionJobId() || selectedForgeJobId || null,
        modelRef: selectedCanvasModelRef?.(state.runtime || forgeCanvasChatTargetMode) || null,
        reasoningEffort: selectedCanvasReasoningEffort?.(state.runtime || forgeCanvasChatTargetMode) || "medium",
        runtime: state.runtime || forgeCanvasChatTargetMode || "codex",
        maxLogLines: 0,
        turnId: `${state.turnId || "forge-compute"}-done`,
      },
    });
    appendCanvasChatMessage("assistant", response?.assistantMessage || "Le calcul Forge est terminé.", {
      turnId: `${state.turnId || "forge-compute"}-done`,
      sessionJobId: currentAlphaSessionJobId() || "",
      agentLabel: canvasChatTargetLabel(state.runtime || forgeCanvasChatTargetMode),
      toolEvents: [{ tool: "forge_run_program", status: "completed" }],
      provider: response?.provider || null,
    });
  } catch (err) {
    appendAlphaForge?.(`[canvas] final compute notification failed: ${err}`);
  }
}

function startCanvasLogFollow(jobId, turnId, options = {}) {
  const normalizedJobId = String(jobId || "").trim();
  if (!normalizedJobId || !window.__TAURI__?.core?.invoke) return;
  const live = ensureCanvasLiveCompute(normalizedJobId, turnId, options);
  const existing = alphaCanvasLogFollowers.get(normalizedJobId);
  if (existing?.timer) clearInterval(existing.timer);
  let cursor = 0;
  const startedAt = Date.now();
  const poll = async () => {
    try {
      const text = String(await window.__TAURI__.core.invoke("read_forge_job_log", {
        jobId: normalizedJobId,
      }) || "").replace(/\r\n/g, "\n");
      if (text.length > cursor) {
        const chunk = text.slice(cursor).trim();
        cursor = text.length;
        if (chunk) {
          const lines = chunk.split("\n").map((line) => line.trim()).filter(Boolean);
          if (live) {
            live.lines.push(...lines);
            live.lines = live.lines.slice(-180);
            live.updatedAt = Date.now();
          }
          renderCanvasLiveComputeCard();
        }
      }
      let manifest = null;
      try {
        manifest = await window.__TAURI__.core.invoke("read_forge_job_manifest", { jobId: normalizedJobId });
      } catch (_) {}
      const manifestStatus = String(manifest?.status || "").toLowerCase();
      const done = canvasLiveComputeFinal(manifestStatus)
        || /(^|\n).*(completed|failed|error|finished|done).*(\n|$)/i.test(text);
      if (live) {
        live.manifest = manifest || live.manifest || null;
        live.program = manifest?.program || live.program || null;
        live.status = manifestStatus || (done ? "completed" : "running");
        live.title = manifest?.title || manifest?.program?.title || live.title;
        live.programTitle = manifest?.program?.title || manifest?.program?.canonical?.title || live.programTitle;
        live.updatedAt = Date.now();
        renderCanvasLiveComputeCard();
      }
      if (done || Date.now() - startedAt > 2 * 60 * 60 * 1000) {
        const state = alphaCanvasLogFollowers.get(normalizedJobId);
        if (state?.timer) clearInterval(state.timer);
        alphaCanvasLogFollowers.delete(normalizedJobId);
        if (live && done) {
          live.status = manifestStatus || "completed";
          renderCanvasLiveComputeCard();
          const completedCleanly = ["", "completed", "done", "completed_with_metric_errors", "completed_with_visual_view_errors", "completed_with_unresolved_ops"]
            .includes(String(live.status || "").toLowerCase());
          if (completedCleanly && !live.completeSoundPlayed) {
            live.completeSoundPlayed = true;
            playForgeUiSound("program-complete");
          }
          void notifyCanvasAgentOfCompletedForgeJob(live, manifest);
        }
        syncCanvasChatSendState();
      }
    } catch (_) {
      const state = alphaCanvasLogFollowers.get(normalizedJobId);
      if (state?.timer) clearInterval(state.timer);
      alphaCanvasLogFollowers.delete(normalizedJobId);
      if (live) {
        live.status = "error";
        live.updatedAt = Date.now();
        renderCanvasLiveComputeCard();
      }
      syncCanvasChatSendState();
    }
  };
  const timer = setInterval(poll, 1000);
  alphaCanvasLogFollowers.set(normalizedJobId, { timer, turnId, live });
  syncCanvasChatSendState();
  void poll();
}

async function applyForgeToolResultToUi(payload) {
  const summary = forgeToolResultSummary(payload);
  const tool = String(summary?.tool || payload?.data?.tool || "").trim();
  const success = payload?.data?.success !== false;
  if (!success) return;
  const jobId = forgeToolResultJobId(summary);
  const programHash = forgeToolResultProgramHash(summary);
  if (tool === "forge_run_program" && jobId) {
    detachCanvasTurnForLiveCompute(payload?.turnId || "");
    const parentSessionId = currentAlphaSessionJobId();
    if (!parentSessionId) selectAlphaForgeSession(jobId);
    appendAlphaForge?.(`[codex] Forge run attached to session ${jobId}.`);
    await pollForgeJobs?.();
    await refreshSelectedForgeJobManifest?.();
    await refreshSelectedForgeJobLog?.();
    scheduleAlphaRender?.();
    startCanvasLogFollow(jobId, payload?.turnId || "", {
      agentLabel: canvasEventTransport(payload) || canvasChatTargetLabel(forgeCanvasChatTargetMode),
      runtime: payload?.data?.runtime || forgeCanvasChatTargetMode,
      title: summary?.programTitle || summary?.program_title || summary?.title || "Forge program",
    });
  }
  if (tool === "forge_create_program" || programHash) {
    appendAlphaForge?.(
      programHash
        ? `[codex] Forge program ready: ${shortHash?.(programHash) || programHash}.`
        : "[codex] Forge program registry updated."
    );
    await refreshProgramsRegistry?.();
  }
}

function canvasEventToolName(payload) {
  const summary = forgeToolResultSummary(payload);
  return firstStringValue(
    summary?.tool,
    payload?.data?.tool,
    payload?.data?.name,
    payload?.data?.item?.tool,
    payload?.data?.params?.item?.tool
  );
}

function canvasEventTransport(payload) {
  const stage = String(payload?.stage || "");
  const explicit = firstStringValue(payload?.data?.runtime, payload?.data?.mode);
  if (explicit && !(stage === "codex_event" && /codex cli/i.test(explicit))) return explicit;
  if (stage === "gemini_cli" || stage === "gemini_event") return "Gemini CLI";
  if (stage === "claude_cli" || stage === "claude_event") return "Claude Code CLI";
  if (stage === "codex_event" || stage === "codex_bridge") return "Codex app-server";
  if (stage.startsWith("forge_tool")) return "Forge dynamic tools";
  return "";
}

function canvasRuntimeToolName(runtime) {
  if (runtime === "gemini") return "gemini_cli";
  if (runtime === "claude") return "claude_cli";
  return "codex_app_server";
}

function isCanvasEventError(payload, message) {
  if (payload?.data?.success === false) return true;
  return /(error|failed|cannot|could not|n'a pas|impossible|erreur)/i.test(String(message || ""));
}

function shouldRenderCanvasToolEvent(payload, message) {
  if (isCanvasEventError(payload, message)) return true;
  const stage = String(payload?.stage || "");
  const tool = canvasEventToolName(payload);
  if (stage === "forge_program_build_step") {
    return false;
  }
  if (stage === "forge_tool_result") {
    return false;
  }
  return false;
}

function compactCanvasToolLabels(events) {
  const labels = [];
  for (const event of Array.isArray(events) ? events : []) {
    const tool = String(event?.tool || "").trim();
    const status = String(event?.status || "").trim();
    let label = "";
    if (tool === "forge_run_program") label = "Forge run";
    else if (tool === "forge_create_program") label = "Program saved";
    else if (tool === "backend_direct") label = "Backend direct";
    else if (tool === "semantic_cache") label = "Local cache";
    else if (tool === "thread_compaction") label = event?.label || "Context compacted";
    else if (tool === "token_usage") label = event?.label || "";
    else if (tool === "gemini_cli") label = status && status !== "ok" ? status : "Gemini CLI";
    else if (tool === "claude_cli") label = status && status !== "ok" ? status : "Claude Code CLI";
    else if (tool === "codex_app_server") label = status && status !== "ok" ? status : "Codex app-server";
    else if (status && status !== "ok" && status !== "not_attempted") label = status;
    if (label && !labels.includes(label)) labels.push(label);
  }
  return labels.slice(0, 3);
}

function codexBridgeUsageSummary(bridge) {
  const usage = bridge?.usage || {};
  const row = usage.last || usage.total || {};
  const input = Number(row.inputTokens || row.input_tokens || 0);
  const cached = Number(row.cachedInputTokens || row.cached_input_tokens || 0);
  const output = Number(row.outputTokens || row.output_tokens || 0);
  const fresh = Math.max(0, input - cached);
  if (!input && !cached && !output) return null;
  return { input, cached, fresh, output };
}

function canvasChatStoredTargetMode() {
  try {
    const value = localStorage.getItem("forge.canvas.chat.target");
    if (value === "both") return "all";
    return ["codex", "gemini", "claude", "all"].includes(value) ? value : "codex";
  } catch (_) {
    return "codex";
  }
}

function canvasChatStoredActiveTargets() {
  try {
    const raw = localStorage.getItem("forge.canvas.chat.targets");
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return null;
    const filtered = parsed.filter((p) => ["codex", "gemini", "claude"].includes(p));
    return filtered.length ? filtered : null;
  } catch (_) {
    return null;
  }
}

function selectedGeminiModelRef() {
  return normalizeGeminiModelRef(geminiProviderModel?.value || storedRuntimeModelRef("forge.gemini.model"));
}

function selectedClaudeModelRef() {
  return normalizeClaudeModelRef(claudeProviderModel?.value || storedRuntimeModelRef("forge.claude.model"));
}

function canvasChatTargetLabel(mode) {
  if (mode === "gemini") return "Gemini";
  if (mode === "claude") return "Claude";
  if (mode === "all") return "All";
  return "Codex";
}

function canvasRuntimeLogoClass(runtime) {
  if (runtime === "gemini") return "provider-logo-gemini";
  if (runtime === "claude") return "provider-logo-claude";
  return "provider-logo-openai";
}

function canvasRuntimeLogoEl(runtime, className = "") {
  return createUiEl("span", `provider-logo ${canvasRuntimeLogoClass(runtime)} ${className}`.trim());
}

function primaryPlanetActionRuntime() {
  if (["codex", "gemini", "claude"].includes(forgeCanvasChatTargetMode)) {
    return forgeCanvasChatTargetMode;
  }
  return activeCanvasChatTargets()[0] || "codex";
}

function syncPlanetLensProviderState() {
  const runtime = primaryPlanetActionRuntime();
  const payload = {
    type: "forge:planet-provider-state",
    runtime,
    runtimeLabel: canvasChatTargetLabel(runtime),
    logoClass: canvasRuntimeLogoClass(runtime),
  };
  [inlinePlanetFrame, marsLensFrame].forEach((frame) => {
    try {
      frame?.contentWindow?.postMessage(payload, "*");
    } catch (_) {}
  });
}

function focusPlanetSpatialMention(mention) {
  const geonodeTag = String(mention?.tag || "").trim();
  const body = String(mention?.body || "mars").trim().toLowerCase();
  if (!geonodeTag || body !== "mars") return;
  const payload = {
    type: "forge:planet-focus",
    geonodeTag,
    locationKey: String(mention?.key || "").trim(),
    parentTag: String(mention?.parentTag || "").trim(),
  };
  if (marsLensView?.classList.contains("is-open")) {
    try { marsLensFrame?.contentWindow?.postMessage(payload, "*"); } catch (_) {}
    return;
  }
  if (!inlinePlanetView?.hidden) {
    try { inlinePlanetFrame?.contentWindow?.postMessage(payload, "*"); } catch (_) {}
    return;
  }
  openMarsLensView(planetSphereUrlForBody("mars", {
    locations: [String(mention?.key || "").trim()].filter(Boolean),
    geonodes: [geonodeTag],
  }));
  window.setTimeout(() => {
    try { marsLensFrame?.contentWindow?.postMessage(payload, "*"); } catch (_) {}
  }, 260);
}

const CANVAS_REASONING_EFFORTS = Object.freeze([
  { value: "medium", label: "Moyen" },
  { value: "high", label: "\u00c9lev\u00e9" },
  { value: "xhigh", label: "Tr\u00e8s approfondi" },
]);

const CANVAS_MODEL_PRESETS = Object.freeze({
  codex: ["gpt-5.3-codex", "gpt-5.5", "gpt-5.4"],
  gemini: ["gemini-3-pro", "gemini-2.5-pro", "gemini-2.5-flash", "gemini-2.0-flash"],
  claude: ["claude-code-default", "opus", "sonnet", "haiku"],
});

/**
 * Returns the set of providers the user has currently activated via the
 * provider toggle buttons. Reads directly from the DOM so it always
 * matches what the user sees lit up. Falls back to ["codex"] if nothing
 * is active (the click handler enforces ≥1 active, but be defensive).
 */
function activeCanvasChatTargets() {
  const order = ["codex", "gemini", "claude"];
  const active = order.filter((target) =>
    forgeCanvasChatTargetBtns.some(
      (btn) => btn.dataset.target === target && btn.classList.contains("active"),
    ),
  );
  return active.length ? active : ["codex"];
}

function canvasRuntimeListForMode(mode = forgeCanvasChatTargetMode) {
  // In "all" mode, only dispatch to the providers actually toggled on
  // (e.g. codex+claude without gemini); single-provider modes stay as-is.
  if (mode === "all") return activeCanvasChatTargets();
  return ["codex", "gemini", "claude"].includes(mode) ? [mode] : ["codex"];
}

function normalizeCanvasReasoningEffort(value) {
  const key = String(value || "")
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[_-]+/g, " ")
    .replace(/\s+/g, " ");
  if (["high", "eleve", "elevated"].includes(key)) return "high";
  if (["xhigh", "extra high", "very high", "tres eleve", "tres approfondi", "approfondi"].includes(key)) return "xhigh";
  return "medium";
}

function canvasReasoningStorageKey(runtime) {
  const safeRuntime = ["codex", "gemini", "claude"].includes(runtime) ? runtime : "codex";
  return `forge.canvas.reasoning.${safeRuntime}`;
}

function selectedCanvasReasoningEffort(runtime = "codex") {
  try {
    return normalizeCanvasReasoningEffort(localStorage.getItem(canvasReasoningStorageKey(runtime)) || "medium");
  } catch (_) {
    return "medium";
  }
}

function setCanvasReasoningEffort(runtime, effort) {
  try {
    localStorage.setItem(canvasReasoningStorageKey(runtime), normalizeCanvasReasoningEffort(effort));
  } catch (_) {}
}

function canvasReasoningEffortLabel(runtime = "codex") {
  const value = selectedCanvasReasoningEffort(runtime);
  return CANVAS_REASONING_EFFORTS.find((entry) => entry.value === value)?.label || "Moyen";
}

function selectedCanvasModelRef(runtime = "codex") {
  if (runtime === "gemini") return selectedGeminiModelRef();
  if (runtime === "claude") return selectedClaudeModelRef();
  return selectedOpenAiModelRef?.() || "gpt-5.3-codex";
}

function setCanvasRuntimeModelRef(runtime, model) {
  if (runtime === "gemini") {
    const normalized = normalizeGeminiModelRef(model);
    setStoredRuntimeModelRef("forge.gemini.model", normalized, normalizeGeminiModelRef);
    if (geminiProviderModel) geminiProviderModel.value = normalized;
  } else if (runtime === "claude") {
    const normalized = normalizeClaudeModelRef(model);
    setStoredRuntimeModelRef("forge.claude.model", normalized, normalizeClaudeModelRef);
    if (claudeProviderModel) claudeProviderModel.value = normalized;
  } else {
    const normalized = normalizeOpenAiModelRef(model);
    setStoredOpenAiModelRef(normalized);
    if (openAiProviderModel) openAiProviderModel.value = normalized;
  }
}

function shortCanvasModelLabel(model) {
  const raw = String(model || "").trim();
  if (!raw) return "model";
  // Prefer the label the backend advertised for this model id (e.g.
  // "Opus 4.7" rather than just "opus"). Falls back to a curated map of
  // versioned defaults so the chip stays accurate when the CLI catalog
  // hasn't been fetched yet.
  const fromCatalog = canvasRuntimeLabelForModel(raw);
  if (fromCatalog) return fromCatalog;
  const lower = raw.toLowerCase();
  if (lower === "gpt-5.3-codex") return "GPT 5.3";
  if (lower === "gpt-5.5") return "GPT 5.5";
  if (lower === "gpt-5.4") return "GPT 5.4";
  if (lower === "claude-code-default") return "Default";
  if (lower === "opus") return "Opus 4.7";
  if (lower === "sonnet") return "Sonnet 4.6";
  if (lower === "haiku") return "Haiku 4.5";
  if (lower.startsWith("gemini-")) {
    return raw
      .replace(/^gemini-/i, "Gemini ")
      .replace(/-/g, " ")
      .replace(/\b\w/g, (ch) => ch.toUpperCase())
      .replace(/\bPro\b/, "Pro")
      .replace(/\bFlash\b/, "Flash");
  }
  return raw;
}

function canvasChatTargetModelLabel(mode = forgeCanvasChatTargetMode) {
  return canvasRuntimeListForMode(mode)
    .map((runtime) => `${canvasChatTargetLabel(runtime)} ${selectedCanvasModelRef(runtime)} · ${canvasReasoningEffortLabel(runtime)}`)
    .join(" + ");
}

function canvasChatModelPillLabel(mode = forgeCanvasChatTargetMode) {
  const runtimes = canvasRuntimeListForMode(mode);
  if (runtimes.length > 1) {
    const efforts = runtimes.map((runtime) => selectedCanvasReasoningEffort(runtime));
    const sharedEffort = efforts.every((effort) => effort === efforts[0]);
    return sharedEffort ? `All · ${canvasReasoningEffortLabel(runtimes[0])}` : "All · custom";
  }
  const runtime = runtimes[0] || "codex";
  return `${shortCanvasModelLabel(selectedCanvasModelRef(runtime))} ${canvasReasoningEffortLabel(runtime)}`;
}

const CANVAS_INLINE_BARREL_ITEM_HEIGHT = 22;

/**
 * Builds the chip's content as two inline scroll-snap "barrels" — one
 * for the model name, one for the effort. Each barrel is a vertically
 * scrollable div that shows a single line at a time; scrolling snaps
 * to the next/previous item. Returns an HTML string injected via
 * innerHTML (every value is escaped).
 */
/**
 * Plain chip label: "<model> <effort>". Clicking the chip opens the
 * legacy dropdown menu pre-targeted on this runtime so the user can
 * choose model + effort there.
 */
function canvasChatModelChipHtml(runtime) {
  const modelLabel = shortCanvasModelLabel(selectedCanvasModelRef(runtime));
  const effortLabel = canvasReasoningEffortLabel(runtime);
  // Flip glyph: a small chevron stack (▲▼) that hints "this cycles".
  // Left flip cycles the model field, right flip cycles the effort.
  const flipSvg = `<svg viewBox="0 0 12 12" aria-hidden="true">`
    + `<path d="M3.5 4.7 6 2.4l2.5 2.3"/>`
    + `<path d="M3.5 7.3 6 9.6l2.5-2.3"/>`
    + `</svg>`;
  return `<button type="button" class="barrel-flip" data-flip="model" tabindex="-1" aria-label="Cycle model">${flipSvg}</button>`
    + `<span class="canvas-chat-model-name">${escapeAttr(modelLabel)}</span>`
    + `<span class="canvas-chat-model-effort">${escapeAttr(effortLabel)}</span>`
    + `<button type="button" class="barrel-flip" data-flip="effort" tabindex="-1" aria-label="Cycle effort">${flipSvg}</button>`;
}

function syncInlineBarrelScroll(barrelEl) {
  if (!barrelEl) return;
  const runtime = barrelEl.dataset.runtime || "codex";
  const type = barrelEl.dataset.barrel;
  const items = Array.from(barrelEl.querySelectorAll(".barrel-inline-item"));
  if (!items.length) return;
  const currentValue = type === "model"
    ? selectedCanvasModelRef(runtime)
    : selectedCanvasReasoningEffort(runtime);
  const idx = Math.max(0, items.findIndex((it) => it.dataset.value === currentValue));
  barrelEl.scrollTop = idx * CANVAS_INLINE_BARREL_ITEM_HEIGHT;
  items.forEach((it, i) => it.classList.toggle("selected", i === idx));
}

function applyBarrelCylinderCurve(barrelEl) {
  // 3D cylinder feel: items rotate around the X axis based on their
  // distance to the centred row. The closer to the centre the more
  // facing-the-user (rotateX 0); the farther the more tilted away.
  const items = barrelEl.querySelectorAll(".barrel-inline-item");
  const itemH = CANVAS_INLINE_BARREL_ITEM_HEIGHT;
  const centerY = barrelEl.scrollTop + barrelEl.clientHeight / 2;
  items.forEach((item, idx) => {
    const itemCenter = idx * itemH + itemH / 2;
    const dist = (itemCenter - centerY) / itemH; // 0 = centre, ±1 = next, ±2 = farther
    const clamped = Math.max(-3, Math.min(3, dist));
    const rotate = clamped * 22; // degrees
    const scale = Math.max(0.62, 1 - Math.abs(clamped) * 0.12);
    const opacity = Math.max(0.18, 1 - Math.abs(clamped) * 0.30);
    item.style.transform = `translateZ(0) rotateX(${-rotate}deg) scale(${scale})`;
    item.style.opacity = String(opacity);
  });
}

function clearBarrelCylinderCurve(barrelEl) {
  barrelEl.querySelectorAll(".barrel-inline-item").forEach((item) => {
    item.style.transform = "";
    item.style.opacity = "";
  });
}

function expandBarrel(barrelEl) {
  if (!barrelEl || barrelEl.classList.contains("expanded")) return;
  // Collapse any other expanded barrels first.
  document.querySelectorAll(".barrel-inline.expanded").forEach((el) => collapseBarrel(el));
  barrelEl.classList.add("expanded");
  // Anchor the centred item to its current scrollTop so the expansion
  // grows around it; recompute the curve immediately.
  const items = barrelEl.querySelectorAll(".barrel-inline-item");
  if (items.length) {
    const idx = Math.min(items.length - 1, Math.max(0, Math.round(barrelEl.scrollTop / CANVAS_INLINE_BARREL_ITEM_HEIGHT)));
    barrelEl.scrollTop = idx * CANVAS_INLINE_BARREL_ITEM_HEIGHT;
  }
  applyBarrelCylinderCurve(barrelEl);
}

function collapseBarrel(barrelEl) {
  if (!barrelEl || !barrelEl.classList.contains("expanded")) return;
  barrelEl.classList.remove("expanded");
  clearBarrelCylinderCurve(barrelEl);
}

function attachInlineBarrelInteractions(barrelEl) {
  if (!barrelEl || barrelEl.dataset.bound === "1") return;
  barrelEl.dataset.bound = "1";
  let scrollTimer = null;
  let collapseTimer = null;
  const settle = () => {
    const items = Array.from(barrelEl.querySelectorAll(".barrel-inline-item"));
    if (!items.length) return;
    const idx = Math.min(items.length - 1, Math.max(0, Math.round(barrelEl.scrollTop / CANVAS_INLINE_BARREL_ITEM_HEIGHT)));
    const target = idx * CANVAS_INLINE_BARREL_ITEM_HEIGHT;
    if (Math.abs(barrelEl.scrollTop - target) > 0.5) {
      barrelEl.scrollTo({ top: target, behavior: "smooth" });
    }
    items.forEach((it, i) => it.classList.toggle("selected", i === idx));
    if (barrelEl.classList.contains("expanded")) {
      applyBarrelCylinderCurve(barrelEl);
    }
    const runtime = barrelEl.dataset.runtime || "codex";
    const type = barrelEl.dataset.barrel;
    const value = items[idx]?.dataset.value;
    if (!value) return;
    if (type === "model") {
      if (selectedCanvasModelRef(runtime) === value) return;
      setCanvasRuntimeModelRef(runtime, value);
      hydrateProviderModelPickers();
    } else {
      if (selectedCanvasReasoningEffort(runtime) === value) return;
      setCanvasReasoningEffort(runtime, value);
    }
    void notifyCanvasRuntimeConfigChanged(runtime);
  };
  barrelEl.addEventListener("scroll", () => {
    if (barrelEl.classList.contains("expanded")) {
      applyBarrelCylinderCurve(barrelEl);
    }
    if (scrollTimer) clearTimeout(scrollTimer);
    scrollTimer = setTimeout(settle, 110);
    // Auto-collapse the expanded barrel ~900ms after the last scroll
    // so the user gets a calm settle before the chip shrinks back.
    if (collapseTimer) clearTimeout(collapseTimer);
    if (barrelEl.classList.contains("expanded")) {
      collapseTimer = setTimeout(() => collapseBarrel(barrelEl), 900);
    }
  });
  barrelEl.addEventListener("click", (event) => {
    // Click expands the barrel into its 3D cylinder form. If a specific
    // item was clicked while expanded, scroll to that item.
    if (!barrelEl.classList.contains("expanded")) {
      event.preventDefault();
      expandBarrel(barrelEl);
      return;
    }
    const item = event.target?.closest?.(".barrel-inline-item");
    if (!item || !barrelEl.contains(item)) return;
    event.preventDefault();
    const items = Array.from(barrelEl.querySelectorAll(".barrel-inline-item"));
    const idx = items.indexOf(item);
    if (idx < 0) return;
    barrelEl.scrollTo({ top: idx * CANVAS_INLINE_BARREL_ITEM_HEIGHT, behavior: "smooth" });
    if (collapseTimer) clearTimeout(collapseTimer);
    collapseTimer = setTimeout(() => collapseBarrel(barrelEl), 380);
  });
}

function attachAllInlineBarrels(scope = document) {
  scope.querySelectorAll(".barrel-inline").forEach((b) => {
    attachInlineBarrelInteractions(b);
    syncInlineBarrelScroll(b);
  });
}

/**
 * Populates the chip with [flip][model][effort][flip]. The chip is
 * cheap enough to fully rebuild on every refresh — there's no scroll
 * state to preserve. The flip icons are wired via event delegation
 * on the chip's parent (anchor).
 */
function populateBarrelChip(chip, runtime) {
  if (!chip || !runtime) return;
  chip.innerHTML = canvasChatModelChipHtml(runtime);
}

function cycleRuntimeField(runtime, field, direction = 1) {
  if (field === "model") {
    const opts = modelOptionsForRuntime(runtime);
    if (!opts.length) return;
    const current = selectedCanvasModelRef(runtime);
    const idx = opts.indexOf(current);
    const next = opts[((idx < 0 ? 0 : idx) + (direction > 0 ? 1 : -1) + opts.length) % opts.length];
    setCanvasRuntimeModelRef(runtime, next);
    hydrateProviderModelPickers();
  } else if (field === "effort") {
    const opts = effortOptionsForRuntime();
    if (!opts.length) return;
    const current = selectedCanvasReasoningEffort(runtime);
    const idx = opts.findIndex((o) => o.value === current);
    const nextOpt = opts[((idx < 0 ? 0 : idx) + (direction > 0 ? 1 : -1) + opts.length) % opts.length];
    setCanvasReasoningEffort(runtime, nextOpt.value);
  }
  void notifyCanvasRuntimeConfigChanged(runtime);
}

function flipLabelTo(labelEl, newText) {
  if (!labelEl) return;
  labelEl.classList.remove("flip-anim");
  void labelEl.offsetWidth; // restart animation
  labelEl.classList.add("flip-anim");
  // Swap text mid-flip (when the card is edge-on) for the illusion
  // of a card flipping to its other side.
  setTimeout(() => {
    labelEl.textContent = newText;
  }, 130);
  setTimeout(() => {
    labelEl.classList.remove("flip-anim");
  }, 320);
}

function syncCanvasChatModelLabel() {
  if (!forgeCanvasChatModelLabel) return;
  const anchor = document.getElementById("forgeCanvasChatModelAnchor");
  if (!anchor) return;
  const runtimes = canvasRuntimeListForMode();
  const fullTitle = canvasChatTargetModelLabel();

  if (runtimes.length <= 1) {
    anchor.querySelectorAll(".canvas-chat-model-chip, .canvas-chat-model-sep").forEach((el) => el.remove());
    const runtime = runtimes[0] || "codex";
    forgeCanvasChatModelLabel.style.display = "";
    populateBarrelChip(forgeCanvasChatModelLabel, runtime);
    forgeCanvasChatModelLabel.removeAttribute("title");
    forgeCanvasChatModelLabel.setAttribute("aria-label", `Model and reasoning: ${fullTitle}`);
    forgeCanvasChatModelLabel.dataset.runtime = runtime;
    return;
  }

  // Multi mode — hide the single button. Reuse existing chips when the
  // active-provider structure is unchanged (just refresh their text).
  // Rebuild only when providers were added/removed/reordered.
  forgeCanvasChatModelLabel.style.display = "none";
  const existingChips = Array.from(anchor.querySelectorAll(".canvas-chat-model-chip"));
  const sameStructure = existingChips.length === runtimes.length
    && runtimes.every((r, i) => existingChips[i]?.dataset.runtime === r);
  if (sameStructure) {
    runtimes.forEach((runtime, i) => {
      const chip = existingChips[i];
      const modelLabel = shortCanvasModelLabel(selectedCanvasModelRef(runtime));
      const effortLabel = canvasReasoningEffortLabel(runtime);
      populateBarrelChip(chip, runtime);
      chip.removeAttribute("title");
      chip.setAttribute("aria-label", `${canvasChatTargetLabel(runtime)} model and reasoning: ${modelLabel} ${effortLabel}`);
    });
    return;
  }
  // Structure changed — wipe and rebuild.
  anchor.querySelectorAll(".canvas-chat-model-chip, .canvas-chat-model-sep").forEach((el) => el.remove());
  runtimes.forEach((runtime, idx) => {
    if (idx > 0) {
      const sep = document.createElement("span");
      sep.className = "canvas-chat-model-sep";
      sep.textContent = "·";
      sep.setAttribute("aria-hidden", "true");
      anchor.insertBefore(sep, forgeCanvasChatModelMenu);
    }
    const chip = document.createElement("div");
    chip.className = "canvas-chat-model canvas-chat-model-chip";
    chip.dataset.runtime = runtime;
    chip.setAttribute("role", "group");
    const modelLabel = shortCanvasModelLabel(selectedCanvasModelRef(runtime));
    const effortLabel = canvasReasoningEffortLabel(runtime);
    populateBarrelChip(chip, runtime);
    chip.removeAttribute("title");
    chip.setAttribute("aria-label", `${canvasChatTargetLabel(runtime)} model and reasoning: ${modelLabel} ${effortLabel}`);
    anchor.insertBefore(chip, forgeCanvasChatModelMenu);
  });
}

function setCanvasModelMenuOpen(open) {
  if (!forgeCanvasChatModelMenu || !forgeCanvasChatModelLabel) return;
  if (open) renderCanvasModelMenu();
  forgeCanvasChatModelMenu.hidden = !open;
  forgeCanvasChatModelLabel.setAttribute("aria-expanded", String(!!open));
  if (!open) {
    document
      .querySelectorAll("#forgeCanvasChatModelAnchor .canvas-chat-model-chip.active-chip")
      .forEach((el) => el.classList.remove("active-chip"));
  }
}

// ── Barrel picker ────────────────────────────────────────────────
// Two vertical scroll-snap wheels — left = model, right = effort. The
// centred row of each wheel is the live selection; selection commits
// as soon as the wheel snaps, persists to localStorage, and (best
// effort) is forwarded to the live CLI wrapper.
const CANVAS_BARREL_ITEM_HEIGHT = 30;

function canvasBarrelPickerEl() {
  return document.getElementById("forgeCanvasChatBarrelPicker");
}

// Cache of models advertised by each CLI wrapper. Filled by
// refreshRuntimeModelCatalog at startup and after toggling providers.
// Stores the raw catalog entries (id + label) keyed by runtime so the
// chip can show "Opus 4.7" instead of just "Opus".
const canvasRuntimeModelCatalog = new Map();
const canvasRuntimeModelLabels = new Map();

function canvasRuntimeLabelForModel(model) {
  if (!model) return "";
  for (const labels of canvasRuntimeModelLabels.values()) {
    const hit = labels.get(String(model));
    if (hit) return hit;
  }
  return "";
}

function modelOptionsForRuntime(runtime) {
  const cliModels = canvasRuntimeModelCatalog.get(runtime);
  const base = Array.isArray(cliModels) && cliModels.length
    ? cliModels.slice()
    : (CANVAS_MODEL_PRESETS[runtime] || []).slice();
  const selected = selectedCanvasModelRef(runtime);
  if (selected && !base.includes(selected)) base.unshift(selected);
  return base;
}

/**
 * Asks the backend which models the runtime's CLI currently advertises
 * (so the barrel actually shows e.g. Opus 4.6 vs 4.7 as the wrapper
 * exposes them). Falls back silently to the hardcoded presets if the
 * backend command is not registered.
 */
async function refreshRuntimeModelCatalog(runtime) {
  const invoke = window.__TAURI__?.core?.invoke;
  if (!invoke) return;
  try {
    const result = await invoke("forge_canvas_list_runtime_models", { runtime });
    if (Array.isArray(result) && result.length) {
      const models = [];
      const labels = new Map();
      for (const entry of result) {
        const id = String(
          typeof entry === "string" ? entry : (entry?.id || entry?.name || ""),
        ).trim();
        if (!id) continue;
        models.push(id);
        const label = String(entry?.label || "").trim();
        if (label) labels.set(id, label);
      }
      if (models.length) {
        canvasRuntimeModelCatalog.set(runtime, models);
        canvasRuntimeModelLabels.set(runtime, labels);
        if (typeof syncCanvasChatModelLabel === "function") {
          syncCanvasChatModelLabel();
        }
      }
    }
  } catch (_) {
    // Backend handler missing — keep using the hardcoded presets.
  }
}

function refreshAllRuntimeModelCatalogs() {
  for (const runtime of ["codex", "gemini", "claude"]) {
    void refreshRuntimeModelCatalog(runtime);
  }
}

function effortOptionsForRuntime() {
  return CANVAS_REASONING_EFFORTS.map((e) => ({ value: e.value, label: e.label }));
}

function buildBarrelColumn(barrelEl, items, currentValue) {
  barrelEl.innerHTML = "";
  const spacerTop = document.createElement("div");
  spacerTop.className = "barrel-spacer";
  barrelEl.appendChild(spacerTop);
  for (const item of items) {
    const node = document.createElement("button");
    node.type = "button";
    node.className = "barrel-item";
    node.dataset.value = item.value;
    node.textContent = item.label;
    node.setAttribute("role", "option");
    if (item.value === currentValue) node.classList.add("selected");
    barrelEl.appendChild(node);
  }
  const spacerBottom = document.createElement("div");
  spacerBottom.className = "barrel-spacer";
  barrelEl.appendChild(spacerBottom);
  const idx = Math.max(0, items.findIndex((it) => it.value === currentValue));
  barrelEl.scrollTop = idx * CANVAS_BARREL_ITEM_HEIGHT;
}

function indexFromBarrelScroll(barrelEl) {
  return Math.round(barrelEl.scrollTop / CANVAS_BARREL_ITEM_HEIGHT);
}

function attachBarrelInteractions(barrelEl, items, onPick) {
  let scrollTimer = null;
  const settle = () => {
    const idx = Math.min(items.length - 1, Math.max(0, indexFromBarrelScroll(barrelEl)));
    const target = idx * CANVAS_BARREL_ITEM_HEIGHT;
    if (Math.abs(barrelEl.scrollTop - target) > 0.5) {
      barrelEl.scrollTo({ top: target, behavior: "smooth" });
    }
    barrelEl.querySelectorAll(".barrel-item.selected").forEach((el) => el.classList.remove("selected"));
    const sel = barrelEl.querySelectorAll(".barrel-item")[idx];
    sel?.classList.add("selected");
    if (items[idx]) onPick(items[idx].value);
  };
  barrelEl.onscroll = () => {
    if (scrollTimer) clearTimeout(scrollTimer);
    scrollTimer = setTimeout(settle, 110);
  };
  barrelEl.onclick = (event) => {
    const item = event.target?.closest?.(".barrel-item");
    if (!item || !barrelEl.contains(item)) return;
    event.preventDefault();
    const idx = Array.from(barrelEl.querySelectorAll(".barrel-item")).indexOf(item);
    if (idx < 0) return;
    barrelEl.scrollTo({ top: idx * CANVAS_BARREL_ITEM_HEIGHT, behavior: "smooth" });
    if (scrollTimer) clearTimeout(scrollTimer);
    scrollTimer = setTimeout(settle, 280);
  };
}

function openCanvasBarrelPicker(runtime) {
  const picker = canvasBarrelPickerEl();
  if (!picker) return;
  if (forgeCanvasChatModelMenu) forgeCanvasChatModelMenu.hidden = true;
  picker.hidden = false;
  picker.dataset.runtime = runtime;
  const runtimeLine = picker.querySelector(".barrel-picker-runtime");
  if (runtimeLine) runtimeLine.textContent = canvasChatTargetLabel(runtime);
  const modelBarrel = picker.querySelector('[data-barrel="model"]');
  const effortBarrel = picker.querySelector('[data-barrel="effort"]');
  if (!modelBarrel || !effortBarrel) return;
  const models = modelOptionsForRuntime(runtime).map((m) => ({ value: m, label: m }));
  const efforts = effortOptionsForRuntime();
  const currentModel = selectedCanvasModelRef(runtime);
  const currentEffort = selectedCanvasReasoningEffort(runtime);
  buildBarrelColumn(modelBarrel, models, currentModel);
  buildBarrelColumn(effortBarrel, efforts, currentEffort);
  attachBarrelInteractions(modelBarrel, models, (value) => {
    setCanvasRuntimeModelRef(runtime, value);
    hydrateProviderModelPickers();
    syncCanvasChatModelLabel();
    void notifyCanvasRuntimeConfigChanged(runtime);
  });
  attachBarrelInteractions(effortBarrel, efforts, (value) => {
    setCanvasReasoningEffort(runtime, value);
    syncCanvasChatModelLabel();
    void notifyCanvasRuntimeConfigChanged(runtime);
  });
}

function closeCanvasBarrelPicker() {
  const picker = canvasBarrelPickerEl();
  if (!picker || picker.hidden) return;
  picker.hidden = true;
  document
    .querySelectorAll("#forgeCanvasChatModelAnchor .canvas-chat-model-chip.active-chip")
    .forEach((el) => el.classList.remove("active-chip"));
}

async function notifyCanvasRuntimeConfigChanged(runtime) {
  const invoke = window.__TAURI__?.core?.invoke;
  if (!invoke) return;
  try {
    await invoke("forge_canvas_set_runtime_config", {
      runtime,
      modelRef: selectedCanvasModelRef(runtime),
      reasoningEffort: selectedCanvasReasoningEffort(runtime),
    });
  } catch (_) {
    // No backend handler — change still applies on next message dispatch.
  }
}

function renderCanvasModelMenu() {
  if (!forgeCanvasChatModelMenu) return;
  forgeCanvasChatModelMenu.innerHTML = "";
  // Show ALL three providers in the tabbar regardless of which are
  // currently active in the chat bar — the user may want to configure
  // model/effort for any LLM independently of toggling its activation.
  const allRuntimes = ["codex", "gemini", "claude"];
  const activeSet = new Set(canvasRuntimeListForMode());
  const stored = forgeCanvasChatModelMenu.dataset.tab;
  const activeRuntime = allRuntimes.includes(stored)
    ? stored
    : (activeSet.size ? [...activeSet][0] : "codex");
  forgeCanvasChatModelMenu.dataset.tab = activeRuntime;

  const tabs = createUiEl("div", "canvas-model-menu-tabs");
  tabs.setAttribute("role", "tablist");
  for (const runtime of allRuntimes) {
    const tab = createUiEl("button", "canvas-model-menu-tab");
    tab.type = "button";
    tab.dataset.tab = runtime;
    tab.setAttribute("role", "tab");
    const isCurrent = runtime === activeRuntime;
    tab.classList.toggle("active", isCurrent);
    tab.classList.toggle("inactive-runtime", !activeSet.has(runtime));
    tab.setAttribute("aria-selected", String(isCurrent));
    tab.appendChild(canvasRuntimeLogoEl(runtime, "canvas-model-menu-logo"));
    tab.appendChild(createUiEl("span", "", canvasChatTargetLabel(runtime)));
    tabs.appendChild(tab);
  }
  forgeCanvasChatModelMenu.appendChild(tabs);

  const effortRow = createUiEl("div", "canvas-model-menu-row");
  effortRow.setAttribute("role", "group");
  for (const effort of CANVAS_REASONING_EFFORTS) {
    const button = createUiEl("button", "canvas-model-menu-choice", effort.label);
    button.type = "button";
    button.dataset.runtime = activeRuntime;
    button.dataset.effort = effort.value;
    button.setAttribute("role", "menuitemradio");
    const active = selectedCanvasReasoningEffort(activeRuntime) === effort.value;
    button.classList.toggle("active", active);
    button.setAttribute("aria-checked", String(active));
    effortRow.appendChild(button);
  }
  forgeCanvasChatModelMenu.appendChild(effortRow);

  const modelList = createUiEl("div", "canvas-model-menu-list");
  const selected = selectedCanvasModelRef(activeRuntime);
  const presets = CANVAS_MODEL_PRESETS[activeRuntime] || [];
  const models = presets.includes(selected) ? presets : [selected, ...presets];
  for (const model of models) {
    const button = createUiEl("button", "canvas-model-menu-item");
    button.type = "button";
    button.dataset.runtime = activeRuntime;
    button.dataset.model = model;
    button.setAttribute("role", "menuitemradio");
    const active = selected === model;
    button.classList.toggle("active", active);
    button.setAttribute("aria-checked", String(active));
    button.appendChild(createUiEl("span", "canvas-model-menu-item-dot"));
    button.appendChild(createUiEl("span", "canvas-model-menu-name", model));
    modelList.appendChild(button);
  }
  forgeCanvasChatModelMenu.appendChild(modelList);
}

function setCanvasChatTargetMode(mode, activeOverride = null) {
  const normalized = mode === "both" ? "all" : mode;
  const next = ["codex", "gemini", "claude", "all"].includes(normalized) ? normalized : "codex";
  forgeCanvasChatTargetMode = next;
  try {
    localStorage.setItem("forge.canvas.chat.target", next);
  } catch (_) {}
  // Resolve which buttons should be visually active. Caller may pass an
  // explicit override (typed combo like ["codex","gemini"]); otherwise
  // default to the mode (single provider, or all 3 for "all").
  let activeSet;
  if (Array.isArray(activeOverride) && activeOverride.length) {
    activeSet = new Set(activeOverride.filter((p) => ["codex", "gemini", "claude"].includes(p)));
    if (activeSet.size === 0) activeSet.add("codex");
  } else if (next === "all") {
    activeSet = new Set(["codex", "gemini", "claude"]);
  } else {
    activeSet = new Set([next]);
  }
  // Persist the active combo separately so the next session restores it
  // exactly (the mode string alone can't distinguish codex+gemini from
  // gemini+claude or all 3).
  try {
    localStorage.setItem("forge.canvas.chat.targets", JSON.stringify([...activeSet]));
  } catch (_) {}
  for (const button of forgeCanvasChatTargetBtns) {
    const target = button.dataset.target;
    const active = activeSet.has(target);
    button.classList.toggle("active", active);
    button.setAttribute("aria-pressed", String(active));
  }
  const all = next === "all";
  const hasCodex = activeSet.has("codex");
  const hasGemini = activeSet.has("gemini");
  const hasClaude = activeSet.has("claude");
  forgeCanvasChat?.classList.toggle("both-mode", all);
  forgeCanvasChat?.classList.toggle("all-mode", all);
  // Inputs visible iff their provider is active. Hidden inputs collapse
  // out of the flex row so the visible ones split the bar evenly.
  if (forgeCanvasChatInput) {
    forgeCanvasChatInput.hidden = !hasCodex;
    forgeCanvasChatInput.disabled = alphaCanvasChatBusy || !hasCodex;
  }
  if (forgeCanvasChatGeminiInput) {
    forgeCanvasChatGeminiInput.hidden = !hasGemini;
    forgeCanvasChatGeminiInput.disabled = alphaCanvasChatBusy || !hasGemini;
  }
  if (forgeCanvasChatClaudeInput) {
    forgeCanvasChatClaudeInput.hidden = !hasClaude;
    forgeCanvasChatClaudeInput.disabled = alphaCanvasChatBusy || !hasClaude;
  }
  // Dividers sit between adjacent visible inputs. The HTML order is
  // codex → divider1 → gemini → divider2 → claude. With flex layout,
  // hidden inputs collapse, so we just need each divider visible iff
  // there are visible inputs on both sides of its position.
  if (forgeCanvasChatPromptDivider) {
    forgeCanvasChatPromptDivider.hidden = !(hasCodex && hasGemini);
  }
  if (forgeCanvasChatPromptDividerClaude) {
    forgeCanvasChatPromptDividerClaude.hidden = !((hasCodex || hasGemini) && hasClaude);
  }
  if (forgeCanvasChatInput) {
    forgeCanvasChatInput.setAttribute("aria-label", all ? "Codex prompt" : `${canvasChatTargetLabel(next)} prompt`);
  }
  syncCanvasChatModelLabel();
  setCanvasModelMenuOpen(false);
  // Reset and restart the placeholder cycler so it picks up the right list
  // (multi-LLM scenarios in "all" mode, single ideas otherwise).
  stopCanvasChatPlaceholderAnimation();
  canvasChatPlaceholderIdx = 0;
  canvasChatPlaceholderCharIdx = 0;
  // In multi mode, start with the LLM names visible so the / dividers read
  // as "Codex / Gemini / Claude" before any scenario types in.
  canvasChatPlaceholderPhase = all ? "names" : "typing";
  if (all) {
    if (forgeCanvasChatInput && !forgeCanvasChatInput.value) forgeCanvasChatInput.placeholder = "Codex";
    if (forgeCanvasChatGeminiInput && !forgeCanvasChatGeminiInput.value) forgeCanvasChatGeminiInput.placeholder = "Gemini";
    if (forgeCanvasChatClaudeInput && !forgeCanvasChatClaudeInput.value) forgeCanvasChatClaudeInput.placeholder = "Claude";
  } else {
    if (forgeCanvasChatInput && !forgeCanvasChatInput.value) forgeCanvasChatInput.placeholder = "";
    if (forgeCanvasChatGeminiInput && !forgeCanvasChatGeminiInput.value) forgeCanvasChatGeminiInput.placeholder = "";
    if (forgeCanvasChatClaudeInput && !forgeCanvasChatClaudeInput.value) forgeCanvasChatClaudeInput.placeholder = "";
  }
  startCanvasChatPlaceholderAnimation();
  autosizeCanvasChatInput();
  syncCanvasChatSendState();
  syncPlanetLensProviderState();
  syncTradingChatInvolvementControls();
}

function codexInputText() {
  return String(forgeCanvasChatInput?.value || "").trim();
}

function geminiCanvasChatText() {
  return String(forgeCanvasChatGeminiInput?.value || "").trim();
}

function claudeCanvasChatText() {
  return String(forgeCanvasChatClaudeInput?.value || "").trim();
}

/**
 * Primary chat text. In single-provider mode this is the active
 * provider's input; in multi mode (mode === "all") we keep returning the
 * codex input as the canonical "primary" so legacy call sites that pre-
 * date the per-provider split don't lose their fallback.
 */
function primaryCanvasChatText() {
  if (forgeCanvasChatTargetMode === "gemini") return geminiCanvasChatText();
  if (forgeCanvasChatTargetMode === "claude") return claudeCanvasChatText();
  return codexInputText();
}

/**
 * Concatenation of all currently visible inputs — used to decide whether
 * there is text to send and to render the user bubble in the chat log.
 */
function currentCanvasChatText() {
  const active = new Set(activeCanvasChatTargets());
  const parts = [];
  if (active.has("codex")) parts.push(codexInputText());
  if (active.has("gemini")) parts.push(geminiCanvasChatText());
  if (active.has("claude")) parts.push(claudeCanvasChatText());
  return parts.filter(Boolean).join(" / ");
}

function canvasChatRuntimeTargets(text, geminiText = "", claudeText = "") {
  if (forgeCanvasChatTargetMode === "all") {
    // Only dispatch to providers actually toggled on. Each provider gets
    // its own per-input text; if a provider's pane is empty, fall back
    // to the first non-empty text so an empty pane never silently sends
    // nothing to that runtime when the user expected a multi-shot.
    const active = new Set(activeCanvasChatTargets());
    const codexText = String(text || "").trim();
    const geminiSide = String(geminiText || "").trim();
    const claudeSide = String(claudeText || "").trim();
    const fallback = codexText || geminiSide || claudeSide;
    const all = [
      { runtime: "codex", label: "Codex", modelRef: selectedOpenAiModelRef?.() || "gpt-5.3-codex", reasoningEffort: selectedCanvasReasoningEffort("codex"), text: codexText || fallback },
      { runtime: "gemini", label: "Gemini", modelRef: selectedGeminiModelRef(), reasoningEffort: selectedCanvasReasoningEffort("gemini"), text: geminiSide || fallback },
      { runtime: "claude", label: "Claude", modelRef: selectedClaudeModelRef(), reasoningEffort: selectedCanvasReasoningEffort("claude"), text: claudeSide || fallback },
    ];
    return all.filter((entry) => active.has(entry.runtime));
  }
  if (forgeCanvasChatTargetMode === "gemini") {
    return [{ runtime: "gemini", label: "Gemini", modelRef: selectedGeminiModelRef(), reasoningEffort: selectedCanvasReasoningEffort("gemini"), text }];
  }
  if (forgeCanvasChatTargetMode === "claude") {
    return [{ runtime: "claude", label: "Claude", modelRef: selectedClaudeModelRef(), reasoningEffort: selectedCanvasReasoningEffort("claude"), text }];
  }
  return [{ runtime: "codex", label: "Codex", modelRef: selectedOpenAiModelRef?.() || "gpt-5.3-codex", reasoningEffort: selectedCanvasReasoningEffort("codex"), text }];
}

function canvasChatInputForRuntime(runtime = "codex") {
  if (runtime === "gemini") return forgeCanvasChatGeminiInput;
  if (runtime === "claude") return forgeCanvasChatClaudeInput;
  return forgeCanvasChatInput;
}

function tradingChatBridge() {
  const candidates = [
    window.__forgeWebExplorerBridge || null,
    window.__forgeTradingChatBridge || null,
  ];
  return candidates.find((bridge) => bridge?.isActive?.()) || null;
}

function isWebExplorerBridgeActive(bridge) {
  return !!bridge && (
    bridge === window.__forgeWebExplorerBridge
    || (bridge?.isActive?.() && isWebExplorerUiActive())
  );
}

function canvasChatInvolvedRuntimeTargets(targets) {
  const bridge = tradingChatBridge();
  if (!bridge?.isActive?.()) {
    return Array.isArray(targets) ? targets.slice() : [];
  }
  return (Array.isArray(targets) ? targets : []).filter((target) => bridge.isRuntimeInvolved?.(target.runtime) !== false);
}

function syncTradingChatInvolvementControls() {
  const bridge = tradingChatBridge();
  const isSurfaceBridge = !!bridge?.isActive?.();
  const involved = !!bridge?.anyRuntimeInvolved?.();
  forgeCanvasChat?.classList.toggle("is-trading-command-mode", isSurfaceBridge && !involved);
  if (forgeCanvasChatLlmModeToggle) {
    const localTitle = isWebExplorerUiActive()
      ? "Web explorer local command mode"
      : "Trading local command mode";
    const llmTitle = isWebExplorerUiActive()
      ? "LLM chat mode"
      : "LLMs involved in Trading chat";
    forgeCanvasChatLlmModeToggle.hidden = !isSurfaceBridge;
    forgeCanvasChatLlmModeToggle.setAttribute("aria-pressed", involved ? "true" : "false");
    forgeCanvasChatLlmModeToggle.setAttribute("title", involved ? llmTitle : localTitle);
    forgeCanvasChatLlmModeToggle.setAttribute("aria-label", involved ? llmTitle : localTitle);
  }
}
if (typeof window !== "undefined") {
  window.__forgeSyncTradingChatInvolvementControls = syncTradingChatInvolvementControls;
}

function primaryCanvasComposerInput() {
  if (forgeCanvasChatTargetMode === "all") {
    const active = activeCanvasChatTargets();
    for (const runtime of active) {
      const input = canvasChatInputForRuntime(runtime);
      if (input && !input.hidden && !input.disabled) return input;
    }
  }
  const single = activeSinglePlaceholderInput();
  if (single && !single.hidden && !single.disabled) return single;
  return [forgeCanvasChatInput, forgeCanvasChatGeminiInput, forgeCanvasChatClaudeInput]
    .find((input) => input && !input.hidden && !input.disabled) || null;
}

function clearCanvasChatComposerInputs() {
  if (forgeCanvasChatInput) forgeCanvasChatInput.value = "";
  if (forgeCanvasChatGeminiInput) forgeCanvasChatGeminiInput.value = "";
  if (forgeCanvasChatClaudeInput) forgeCanvasChatClaudeInput.value = "";
}

function askPlanetGeonodeWithRuntime(item) {
  const runtime = ["codex", "gemini", "claude"].includes(item?.runtime) ? item.runtime : primaryPlanetActionRuntime();
  if (canvasChatBusyInCurrentSession()) return;
  injectAtlasItemIntoChatSlot(item);
  setCanvasChatTargetMode(runtime, [runtime]);
  clearCanvasChatComposerInputs();
  const input = canvasChatInputForRuntime(runtime);
  input?.focus?.({ preventScroll: true });
  autosizeCanvasChatInput();
  syncCanvasChatSendState();
  void sendForgeCanvasChatMessage();
}

function normalizedCanvasMicroText(text) {
  return String(text || "")
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[’']/g, " ")
    .replace(/[^\p{Letter}\p{Number}]+/gu, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizeForLocalIntent(text) {
  return normalizedCanvasMicroText(text);
}

function lastCanvasAssistantNeedsConfirmation() {
  for (let i = alphaCanvasChatMessages.length - 1; i >= 0; i--) {
    const message = alphaCanvasChatMessages[i];
    if (message?.role !== "assistant") continue;
    const text = String(message.text || "").trim();
    return /[?？]\s*$/.test(text);
  }
  return false;
}

