function normalizedIncludesAny(text, phrases) {
  return phrases.some((phrase) => text.includes(phrase));
}

function canvasMicroAsksForgeCapabilities(normalized) {
  return normalizedIncludesAny(normalized, [
    "que peux tu faire avec forge",
    "que peux tu faire dans forge",
    "qu est ce que tu peux faire avec forge",
    "qu est ce que tu peux faire dans forge",
    "qu est ce qu on peut faire avec forge",
    "qu est ce qu on peut faire dans forge",
    "que peut on faire avec forge",
    "que peut on faire dans forge",
    "a quoi sert forge",
    "forge sert a quoi",
    "c est quoi forge",
    "explique forge",
    "concretement dans forge",
    "concretement avec forge",
    "difference avec un wrapper",
    "difference avec wrapper",
    "difference avec claude",
    "difference avec codex",
    "claude desktop",
    "codex desktop",
    "wrapper classique",
    "capacites de forge",
    "possibilites de forge",
    "fonctionnalites de forge",
    "what can forge do",
    "what is forge",
    "why use forge",
    "forge benefits",
  ]);
}

function localCanvasForgeHelpReply(normalized) {
  if (!normalized || normalized.length > 180) return "";
  if (canvasMicroAsksForgeCapabilities(normalized)) return "";
  if (normalizedIncludesAny(normalized, [
    "je comprends pas",
    "je ne comprends pas",
    "je suis perdu",
    "aide moi",
    "besoin d aide",
    "comment utiliser forge",
    "comment marche forge",
    "comment fonctionne forge",
  ])) {
    return "Forge sert à garder les gros fichiers, calculs et preuves côté backend. Tu parles dans le canvas, l’agent lit seulement un contexte compact, lance les programmes Forge quand il faut, et évite d’envoyer les données brutes au LLM.";
  }
  if (normalizedIncludesAny(normalized, [
    "comment ajouter un fichier",
    "comment upload",
    "ajouter un fichier",
    "joindre un fichier",
    "nouveau fichier",
    "session sans fichier",
    "nouvelle session",
    "fichier dans la session",
  ])) {
    return "Pour une session ouverte, utilise le + dans la barre de chat ou sous la card fichier: le fichier est ajouté à la session actuelle. New session sert à repartir dans une autre session, avec ou sans fichier.";
  }
  if (normalizedIncludesAny(normalized, [
    "economise des tokens",
    "economiser des tokens",
    "tokens saved",
    "pourquoi tokens",
    "combien de tokens",
    "8000 tokens",
    "brule des tokens",
    "cout de tokens",
  ])) {
    return "Forge économise les tokens en gardant les fichiers et calculs sur disque. Le LLM reçoit des résumés, références, hashes, logs courts et résultats. Pour les petits messages, Forge répond localement sans appeler Codex, Gemini ou Claude.";
  }
  if (normalizedIncludesAny(normalized, [
    "codex gemini claude",
    "choisir codex",
    "choisir gemini",
    "choisir claude",
    "mode all",
    "les trois modeles",
    "changer de modele",
    "raisonnement moyen",
    "raisonnement eleve",
  ])) {
    return "Dans la barre de chat, tu choisis Codex, Gemini, Claude ou All. Le modèle et l’effort de raisonnement se règlent dans le sélecteur à droite. All sert surtout à comparer ou répartir une tâche, pas aux petits messages.";
  }
  if (normalizedIncludesAny(normalized, [
    "how does forge work",
    "how do i use forge",
    "i dont understand forge",
    "i m lost",
    "help me with forge",
  ])) {
    return "Forge keeps large files, compute and proofs in the backend. You talk in the canvas, agents receive compact context, run Forge programs when needed, and avoid sending raw data to the LLM.";
  }
  if (normalizedIncludesAny(normalized, [
    "how do i upload",
    "attach a file",
    "add a file",
    "new session",
    "session without file",
  ])) {
    return "Use + in the chat bar or under the file card to add a file to the current session. New session starts a separate session, with or without a file.";
  }
  if (normalizedIncludesAny(normalized, [
    "save tokens",
    "token saving",
    "why tokens",
    "token cost",
  ])) {
    return "Forge saves tokens by keeping raw files and heavy computation on disk. The LLM gets compact summaries, references, hashes, short logs and results. Simple messages are answered locally.";
  }
  if (normalizedIncludesAny(normalized, [
    "que es forge",
    "como funciona forge",
    "no entiendo forge",
    "para que sirve forge",
  ])) {
    return "Forge guarda archivos grandes, cálculos y pruebas en el backend. El agente recibe contexto compacto, ejecuta programas Forge cuando hace falta y evita enviar datos brutos al LLM.";
  }
  if (normalizedIncludesAny(normalized, [
    "was ist forge",
    "wie funktioniert forge",
    "ich verstehe forge nicht",
    "wofur ist forge",
  ])) {
    return "Forge hält große Dateien, Berechnungen und Nachweise im Backend. Der Agent bekommt kompakten Kontext, startet Forge-Programme bei Bedarf und sendet keine Rohdaten an das LLM.";
  }
  if (normalizedIncludesAny(normalized, [
    "cos e forge",
    "come funziona forge",
    "non capisco forge",
    "a cosa serve forge",
  ])) {
    return "Forge tiene file grandi, calcoli e prove nel backend. L’agente riceve contesto compatto, avvia programmi Forge quando serve e non invia dati grezzi al LLM.";
  }
  if (normalizedIncludesAny(normalized, [
    "o que e forge",
    "como funciona forge",
    "nao entendo forge",
    "para que serve forge",
  ])) {
    return "Forge mantém arquivos grandes, cálculos e provas no backend. O agente recebe contexto compacto, executa programas Forge quando necessário e evita enviar dados brutos ao LLM.";
  }
  if (normalizedIncludesAny(normalized, ["что такое forge", "как работает forge", "не понимаю forge"])) {
    return "Forge хранит большие файлы, вычисления и доказательства в backend. Агент получает компактный контекст, запускает программы Forge при необходимости и не отправляет сырые данные в LLM.";
  }
  if (normalizedIncludesAny(normalized, ["什么是forge", "forge怎么用", "forge如何工作"])) {
    return "Forge 把大文件、计算和证明保留在后端。智能体只接收紧凑上下文，需要时运行 Forge 程序，避免把原始数据发送给 LLM。";
  }
  if (normalizedIncludesAny(normalized, ["forgeとは", "forgeの使い方", "forgeがわからない"])) {
    return "Forge は大きなファイル、計算、証明をバックエンド側に置きます。エージェントは短い文脈だけを受け取り、必要な時に Forge プログラムを実行します。";
  }
  if (normalizedIncludesAny(normalized, ["ما هو forge", "كيف يعمل forge", "لا افهم forge"])) {
    return "Forge يحتفظ بالملفات الكبيرة والحسابات والإثباتات في الخلفية. يحصل الوكيل على سياق مختصر ويشغل برامج Forge عند الحاجة بدون إرسال البيانات الخام إلى LLM.";
  }
  return "";
}

function localCanvasMicroReply(text) {
  const normalized = normalizedCanvasMicroText(text);
  if (!normalized) return "";
  const forgeHelpReply = localCanvasForgeHelpReply(normalized);
  if (forgeHelpReply) return forgeHelpReply;
  if (normalized.length > 52) return "";
  if (CANVAS_MICRO_CONFIRMATIONS.has(normalized) && lastCanvasAssistantNeedsConfirmation()) return "";
  const intents = ["greeting", "wellbeing", "presence", "ping", "thanks", "praise", "ack", "decline", "bye"];
  for (const pack of CANVAS_MICRO_LANGUAGE_PACKS) {
    for (const intent of intents) {
      if (!pack[intent]?.includes(normalized)) continue;
      return pack.replies?.[intent] || "";
    }
  }
  return "";
}

function localCanvasMicroReplyDelayMs(text) {
  const len = String(text || "").trim().length;
  return 420 + Math.min(520, len * 18) + Math.floor(Math.random() * 180);
}

function localCanvasMicroReplyForTurn(primaryText, geminiText = "", claudeText = "") {
  if (forgeCanvasChatTargetMode !== "all") return localCanvasMicroReply(primaryText);
  const parts = [primaryText, geminiText, claudeText]
    .map((part) => String(part || "").trim())
    .filter(Boolean);
  if (!parts.length) return "";
  const replies = parts.map(localCanvasMicroReply);
  if (replies.some((reply) => !reply)) return "";
  return replies[0] || "Je suis là.";
}

function canvasFallbackRuntimeFromPayload(payload) {
  const data = payload?.data || {};
  const fallback = String(data.fallbackRuntime || data.runtime || "").trim().toLowerCase();
  return ["codex", "gemini", "claude"].includes(fallback) ? fallback : "";
}

function applyCanvasRuntimeFallbackToUi(payload) {
  const data = payload?.data || {};
  const requested = String(data.requestedRuntime || "").trim().toLowerCase();
  const fallback = canvasFallbackRuntimeFromPayload(payload);
  if (!requested || !fallback || requested === fallback) return;
  let changed = false;
  forgeCanvasChatPendingAssistants = forgeCanvasChatPendingAssistants.map((target) => {
    if (String(target?.runtime || "").trim().toLowerCase() !== requested) return target;
    changed = true;
    return {
      ...target,
      runtime: fallback,
      label: `${canvasChatTargetLabel(fallback)} · fallback`,
    };
  });
  if (changed) {
    alphaCanvasPendingVersion += 1;
    alphaLogRenderedVersion = -1;
    scheduleAlphaRender();
  }
  if (forgeCanvasChatTargetMode !== "all" && ["codex", "gemini", "claude"].includes(fallback)) {
    const modelRef = String(data.modelRef || "").trim();
    if (modelRef) setCanvasRuntimeModelRef(fallback, modelRef);
    setCanvasChatTargetMode(fallback, [fallback]);
  }
  void maybeAutoHealProvider(requested, providerWorkbenchStatus(requested), { autoHeal: true });
}

function canvasResponseRuntime(response, target = null) {
  const fallback = String(response?.codexBridge?.fallbackRuntime || "").trim().toLowerCase();
  if (["codex", "gemini", "claude"].includes(fallback)) return fallback;
  const requested = String(response?.codexBridge?.requestedRuntime || target?.runtime || "").trim().toLowerCase();
  if (["codex", "gemini", "claude"].includes(requested)) return requested;
  const runtimeText = String(response?.codexBridge?.runtime || "").toLowerCase();
  if (runtimeText.includes("gemini")) return "gemini";
  if (runtimeText.includes("claude")) return "claude";
  if (runtimeText.includes("codex") || runtimeText.includes("openai")) return "codex";
  const providerModel = String(response?.provider?.modelRef || response?.provider?.model_ref || "").toLowerCase();
  if (providerModel.includes("gemini")) return "gemini";
  if (providerModel.includes("claude") || ["opus", "sonnet", "haiku"].includes(providerModel)) return "claude";
  return "codex";
}

function handleForgeCanvasAssistantEvent(payload) {
  if (!payload || typeof payload !== "object") return;
  if (payload.stage === "runtime_fallback") {
    applyCanvasRuntimeFallbackToUi(payload);
    return;
  }
  const message = String(payload.message || "").trim();
  if (payload.stage === "forge_tool_result") {
    void applyForgeToolResultToUi(payload);
  }
  if (!message) return;
  if (!shouldRenderCanvasToolEvent(payload, message)) return;
  appendCanvasChatMessage("tool", message, {
    turnId: payload.turnId || "",
    programBuildKind: payload.stage === "forge_program_build_step"
      ? String(payload?.data?.kind || "step")
      : "",
    toolEvents: [{
      tool: payload.stage || "codex_event",
      transport: canvasEventTransport(payload),
      kind: payload?.data?.kind || "",
    }],
  });
}

// ── Chapter pins (Claude-Desktop-style bookmark markers) ───────────
// Uses string IDs throughout so the Set never mixes "5" (from
// dataset.messageId) and 5 (raw number from message.id) — that
// mismatch silently kept pins from being toggled correctly.
const canvasChatPinnedIds = new Set();
const canvasChaptersEl = typeof document !== "undefined"
  ? document.getElementById("canvasChapters")
  : null;

function canvasChatPinKey(messageId) {
  if (messageId == null) return "";
  return String(messageId);
}

function isMessagePinned(message) {
  const key = canvasChatPinKey(message?.id);
  return !!key && canvasChatPinnedIds.has(key);
}

function toggleCanvasChatPin(messageId) {
  const key = canvasChatPinKey(messageId);
  if (!key) return;
  if (canvasChatPinnedIds.has(key)) {
    canvasChatPinnedIds.delete(key);
  } else {
    canvasChatPinnedIds.add(key);
  }
  alphaCanvasChatVersion += 1;
  alphaLogRenderedVersion = -1;
  scheduleAlphaRender?.();
  renderCanvasChapters();
}

function chapterPreviewFor(message) {
  const raw = String(message?.text || "").trim().replace(/\s+/g, " ");
  return raw.length > 64 ? `${raw.slice(0, 64)}…` : raw;
}

function renderCanvasChapters() {
  if (!canvasChaptersEl) return;
  const pinned = alphaCanvasChatMessages.filter((m) => isMessagePinned(m));
  if (!pinned.length) {
    canvasChaptersEl.hidden = true;
    canvasChaptersEl.replaceChildren();
    return;
  }
  canvasChaptersEl.hidden = false;
  const fragment = document.createDocumentFragment();
  pinned.forEach((message, idx) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = `canvas-chapter ${message.role === "user" ? "user" : "assistant"}`;
    button.dataset.messageId = String(message.id);
    button.title = chapterPreviewFor(message);
    button.innerHTML = `
      <span class="canvas-chapter-label">${chapterPreviewFor(message).replace(/[<>&"']/g, (c) => ({"<":"&lt;",">":"&gt;","&":"&amp;","\"":"&quot;","'":"&#39;"}[c]))}</span>
    `;
    button.addEventListener("click", () => {
      const target = document.querySelector(`[data-message-id="${message.id}"]`);
      if (target?.scrollIntoView) {
        target.scrollIntoView({ behavior: "smooth", block: "center" });
        target.classList.add("flash");
        setTimeout(() => target.classList.remove("flash"), 1200);
      }
    });
    fragment.appendChild(button);
  });
  canvasChaptersEl.replaceChildren(fragment);
}

// Approximate brand logos for the agent labels — drawn from scratch in
// SVG (no asset files, no licence bundling). Each is a single path that
// fills with currentColor so it inherits the label's text color.
const CANVAS_CHAT_AGENT_ICONS = {
  // Gemini — 4-pointed sparkle with concave curved blades.
  gemini: '<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 1.5C12 8.4 8.4 12 1.5 12 8.4 12 12 15.6 12 22.5 12 15.6 15.6 12 22.5 12 15.6 12 12 8.4 12 1.5Z"/></svg>',
  // Claude / Anthropic — 4-blade asterisk with rounded ends meeting at the centre.
  claude: '<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M11.4 2.4c0 4.5-.7 7.1-3 8.2-.9.4-1.9.6-3.6.7-.5 0-.8.3-.8.7s.3.7.8.7c1.7.1 2.7.3 3.6.7 2.3 1.1 3 3.7 3 8.2 0 .4.2.6.6.6s.6-.2.6-.6c0-4.5.7-7.1 3-8.2.9-.4 1.9-.6 3.6-.7.5 0 .8-.3.8-.7s-.3-.7-.8-.7c-1.7-.1-2.7-.3-3.6-.7-2.3-1.1-3-3.7-3-8.2 0-.4-.2-.6-.6-.6s-.6.2-.6.6Z"/></svg>',
  // Codex / OpenAI — hexagonal knot, simplified.
  codex: '<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 1.5 20.66 6.5V16.5L12 21.5 3.34 16.5V6.5Z"/></svg>',
};

function canvasChatAgentIconHtml(role, label) {
  if (!label) return null;
  if (role === "user") return null;
  const key = String(label).toLowerCase();
  if (key.includes("gemini")) return CANVAS_CHAT_AGENT_ICONS.gemini;
  if (key.includes("claude")) return CANVAS_CHAT_AGENT_ICONS.claude;
  if (key.includes("codex") || key.includes("openai") || key.includes("gpt")) {
    return CANVAS_CHAT_AGENT_ICONS.codex;
  }
  return null;
}

function buildCanvasChatNameElement(role, label) {
  const wrap = createUiEl("div", "canvas-chat-name");
  const iconHtml = canvasChatAgentIconHtml(role, label);
  if (iconHtml) {
    const icon = document.createElement("span");
    icon.className = "canvas-chat-name-icon";
    icon.innerHTML = iconHtml;
    wrap.appendChild(icon);
  }
  wrap.appendChild(document.createTextNode(label));
  return wrap;
}

function canvasProgramBuildIconHtml(kind) {
  const icons = {
    math: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 6h14" /><path d="M8 6c3 3 3 9 0 12" /><path d="M5 18h14" /><path d="M14 10l4 4" /><path d="M18 10l-4 4" /></svg>',
    tool: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 5h16v14H4z" /><path d="m7 9 3 3-3 3" /><path d="M13 16h4" /></svg>',
    edit: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 20h4l11-11-4-4L4 16v4z" /><path d="m14 6 4 4" /></svg>',
    compiled: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 6 9 17l-5-5" /></svg>',
    repair: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3 2 21h20L12 3z" /><path d="M12 9v5" /><path d="M12 18h.01" /></svg>',
  };
  return icons[kind] || icons.tool;
}

function buildCanvasSpatialMentionPill(mention, textOverride = "") {
  const pill = document.createElement("button");
  pill.type = "button";
  pill.className = "canvas-spatial-pill";
  pill.dataset.spatialTag = String(mention?.tag || "");
  pill.dataset.spatialBody = String(mention?.body || "mars");
  pill.dataset.spatialKey = String(mention?.key || "");
  pill.dataset.spatialKind = String(mention?.kind || "geonode");
  if (mention?.parentTag) pill.dataset.spatialParentTag = String(mention.parentTag);
  pill.title = String(mention?.label || mention?.tag || "Spatial mention");
  pill.textContent = textOverride || String(mention?.renderText || mention?.label || mention?.tag || "GeoNode");
  return pill;
}

function appendCanvasPlainTextWithSpatialMentions(target, source, spatialMentions = []) {
  const text = String(source || "");
  const mentions = Array.isArray(spatialMentions)
    ? spatialMentions
        .map((mention) => ({
          ...mention,
          needle: String(mention?.renderText || mention?.label || "").trim(),
        }))
        .filter((mention) => mention.needle)
        .sort((a, b) => b.needle.length - a.needle.length)
    : [];
  if (!mentions.length) {
    target.appendChild(document.createTextNode(text));
    return;
  }
  let cursor = 0;
  while (cursor < text.length) {
    let best = null;
    for (const mention of mentions) {
      const haystack = text.slice(cursor).toLowerCase();
      const index = haystack.indexOf(mention.needle.toLowerCase());
      if (index < 0) continue;
      const absolute = cursor + index;
      if (!best || absolute < best.index || (absolute === best.index && mention.needle.length > best.needle.length)) {
        best = { mention, index: absolute, needle: mention.needle };
      }
    }
    if (!best) {
      target.appendChild(document.createTextNode(text.slice(cursor)));
      break;
    }
    if (best.index > cursor) {
      target.appendChild(document.createTextNode(text.slice(cursor, best.index)));
    }
    target.appendChild(buildCanvasSpatialMentionPill(best.mention, text.slice(best.index, best.index + best.needle.length)));
    cursor = best.index + best.needle.length;
  }
}

function canvasArtifactPillVariant(kind = "") {
  const value = String(kind || "").trim().toLowerCase();
  if (value === "visual_program" || value === "visual") return "visual";
  if (value === "compute_program" || value === "compute") return "compute";
  if (value.includes("create_program") || value.includes("program")) return "program";
  if (value.includes("atlas") || value.includes("geonode") || value.includes("mini_geonode")) return "atlas";
  if (value.includes("run") || value.includes("execute") || value.includes("launch")) return "run";
  if (value.includes("proof") || value.includes("hash")) return "proof";
  return "feature";
}

function buildCanvasArtifactPill(label, kind = "", title = "", extraClass = "") {
  const pill = document.createElement("span");
  pill.className = `canvas-artifact-pill ${canvasArtifactPillVariant(kind)} ${extraClass}`.trim();
  pill.textContent = label;
  if (title) pill.title = title;
  return pill;
}

function appendCanvasChatTextWithPills(target, text, spatialMentions = []) {
  const source = String(text || "");
  const pillPattern = /\(`(forge_[a-z0-9_]+)`\)|`(forge_[a-z0-9_]+)`|(`?)(compute_program|visual_program)\3|\*\*([^*\n]+?)\*\*/gi;
  let lastIndex = 0;
  let match;
  while ((match = pillPattern.exec(source)) !== null) {
    if (match.index > lastIndex) {
      appendCanvasPlainTextWithSpatialMentions(target, source.slice(lastIndex, match.index), spatialMentions);
    }
    if (match[1] || match[2]) {
      const toolName = String(match[1] || match[2] || "").trim().toLowerCase();
      target.appendChild(buildCanvasArtifactPill(toolName, toolName, `Forge tool (${toolName})`, "toolcall"));
    } else if (match[4]) {
      const kind = String(match[4] || "").trim().toLowerCase();
      const isVisual = kind === "visual_program";
      target.appendChild(
        buildCanvasArtifactPill(
          isVisual ? "Lens" : "Instrument",
          kind,
          `${isVisual ? "Lens" : "Instrument"} (${kind})`
        )
      );
    } else if (match[5]) {
      const strong = document.createElement("strong");
      appendCanvasChatTextWithPills(strong, match[5], spatialMentions);
      target.appendChild(strong);
    }
    lastIndex = match.index + match[0].length;
  }
  if (lastIndex < source.length) {
    appendCanvasPlainTextWithSpatialMentions(target, source.slice(lastIndex), spatialMentions);
  }
}

function canvasPlanetEventLabel(planet) {
  const body = String(
    planet?.name
    || planet?.bodyLabel
    || planet?.body
    || "Mars"
  ).trim();
  return `Planet · ${body.charAt(0).toUpperCase()}${body.slice(1)}`;
}

function buildCanvasPlanetInvocationEvent(planet) {
  const event = createUiEl("div", "canvas-chat-planet-event");
  const icon = createUiEl("span", "canvas-chat-planet-event-icon");
  icon.innerHTML = canvasMessageVisualIcon("planet");
  const label = createUiEl("span", "canvas-chat-planet-event-label", canvasPlanetEventLabel(planet));
  event.append(icon, label);
  return event;
}

function renderCanvasChatTextContent(target, text, message = null) {
  target.innerHTML = "";
  const source = String(text || "");
  const planet = message?.role === "assistant" ? canvasMessagePlanetVisual(message) : null;
  const spatialMentions = Array.isArray(message?.meta?.spatialMentions) ? message.meta.spatialMentions : [];
  const showPlanetEvent = Boolean(
    planet
    && (
      !isCanvasAssistantTyping(message)
      || /\n\s*\n/.test(source)
    )
  );
  if (!showPlanetEvent) {
    target.classList.remove("has-blocks");
    appendCanvasChatTextWithPills(target, source, spatialMentions);
    return;
  }
  target.classList.add("has-blocks");
  const paragraphs = source.split(/\n\s*\n/).filter((part) => part.trim().length > 0);
  if (!paragraphs.length) {
    appendCanvasChatTextWithPills(target, source, spatialMentions);
    return;
  }
  let eventInserted = false;
  paragraphs.forEach((paragraph, index) => {
    const block = createUiEl("p", "canvas-chat-text-paragraph");
    appendCanvasChatTextWithPills(block, paragraph, spatialMentions);
    target.appendChild(block);
    if (!eventInserted && (index === 0 || index < paragraphs.length - 1)) {
      target.appendChild(buildCanvasPlanetInvocationEvent(planet));
      eventInserted = true;
    }
  });
  if (!eventInserted) {
    target.appendChild(buildCanvasPlanetInvocationEvent(planet));
  }
}

function buildCanvasChatPinButton(message) {
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "canvas-chat-pin";
  if (isMessagePinned(message)) btn.classList.add("pinned");
  btn.setAttribute("aria-label", isMessagePinned(message) ? "Unpin chapter" : "Pin as chapter");
  btn.innerHTML = `
    <svg viewBox="0 0 16 16" focusable="false" aria-hidden="true">
      <path d="M4 2h8a1 1 0 0 1 1 1v12l-5-3-5 3V3a1 1 0 0 1 1-1z" />
    </svg>
  `;
  btn.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    toggleCanvasChatPin(message.id);
  });
  return btn;
}

function buildCanvasChatCopyButton(text) {
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "canvas-chat-copy";
  btn.setAttribute("aria-label", "Copy message");
  btn.innerHTML = `
    <svg class="canvas-chat-copy-icon" viewBox="0 0 16 16" focusable="false" aria-hidden="true">
      <rect x="5" y="5" width="9" height="9" rx="1.5" />
      <path d="M11 5V3.5A1.5 1.5 0 0 0 9.5 2h-5A1.5 1.5 0 0 0 3 3.5v6A1.5 1.5 0 0 0 4.5 11H5" />
    </svg>
    <svg class="canvas-chat-copy-check" viewBox="0 0 16 16" focusable="false" aria-hidden="true">
      <path d="m3.5 8.5 3 3 6-7" />
    </svg>
  `;
  let pendingTimer = null;
  btn.addEventListener("click", async (event) => {
    event.preventDefault();
    event.stopPropagation();
    try {
      await navigator.clipboard.writeText(text);
      btn.classList.add("copied");
      btn.setAttribute("aria-label", "Copied");
      if (pendingTimer) clearTimeout(pendingTimer);
      pendingTimer = setTimeout(() => {
        btn.classList.remove("copied");
        btn.setAttribute("aria-label", "Copy message");
        pendingTimer = null;
      }, 1500);
    } catch (err) {
      console.warn("[chat-copy] clipboard write failed", err);
    }
  });
  return btn;
}

let forgeVoiceAudio = null;
let forgeVoiceObjectUrl = "";
let forgeVoiceActiveButton = null;

function forgeVoiceStorageGet(key, fallback = "") {
  try {
    return localStorage.getItem(key) || fallback;
  } catch (_) {
    return fallback;
  }
}

function forgeVoiceStorageSet(key, value) {
  try {
    localStorage.setItem(key, String(value ?? ""));
  } catch (_) {}
}

const FORGE_VOICE_DEFAULT_ID = "cgSgspJ2msm6clMCkdW9";
const FORGE_VOICE_DEFAULT_MODEL = "eleven_multilingual_v2";
const FORGE_VOICE_DEFAULT_VERSION = "jessica-2026-05-09";
const FORGE_VOICE_REPLACED_IDS = new Set([
  "",
  "JBFqnCBsd6RMkjVDRZzb",
  "FFXYdAYPzn8Tw8KiHZqg",
  "WeAAwKYcS06VmXw086yZ",
  "hpp4J3VqNfWAUOO0d1Us",
]);

function migrateForgeVoiceDefaults() {
  if (forgeVoiceStorageGet("forge.voice.defaultVersion", "") === FORGE_VOICE_DEFAULT_VERSION) return;
  const storedVoice = forgeVoiceStorageGet("forge.voice.elevenVoiceId", "").trim();
  const shouldReplaceVoice = FORGE_VOICE_REPLACED_IDS.has(storedVoice);
  if (shouldReplaceVoice) {
    forgeVoiceStorageSet("forge.voice.elevenVoiceId", FORGE_VOICE_DEFAULT_ID);
  }
  const storedModel = forgeVoiceStorageGet("forge.voice.elevenModelId", "").trim();
  if (!storedModel || shouldReplaceVoice || storedModel === "eleven_v3") {
    forgeVoiceStorageSet("forge.voice.elevenModelId", FORGE_VOICE_DEFAULT_MODEL);
  }
  forgeVoiceStorageSet("forge.voice.defaultVersion", FORGE_VOICE_DEFAULT_VERSION);
}

function redactCanvasSecrets(text) {
  return String(text || "")
    .replace(/\bsk_[A-Za-z0-9]{20,}\b/g, "[ELEVENLABS_API_KEY_REDACTED]")
    .replace(/\bAIza[0-9A-Za-z_-]{20,}\b/g, "[GOOGLE_API_KEY_REDACTED]");
}

function canvasTextContainsSecret(text) {
  return /\bsk_[A-Za-z0-9]{20,}\b|\bAIza[0-9A-Za-z_-]{20,}\b/.test(String(text || ""));
}

function installCanvasSecretGuard(input) {
  if (!input) return;
  input.addEventListener("paste", () => {
    setTimeout(() => {
      if (!canvasTextContainsSecret(input.value)) return;
      input.value = redactCanvasSecrets(input.value);
      input.dispatchEvent(new Event("input", { bubbles: true }));
      if (typeof openProviderOverlay === "function") openProviderOverlay({ focus: "voice" });
      if (typeof voiceProviderHint !== "undefined" && voiceProviderHint) {
        voiceProviderHint.textContent = "API key detected in chat and redacted. Paste secrets here instead, then save locally.";
      }
    }, 0);
  });
}

function forgeVoiceFieldValue(id, storageKey, fallback = "") {
  const live = String(document.getElementById(id)?.value || "").trim();
  return live || forgeVoiceStorageGet(storageKey, fallback).trim();
}

function forgeVoiceSettings() {
  migrateForgeVoiceDefaults();
  const monthlyLimit = Number(forgeVoiceFieldValue("voiceMonthlyLimit", "forge.voice.monthlyLimit", "10000"));
  return {
    elevenVoiceId: forgeVoiceFieldValue("voiceElevenVoiceId", "forge.voice.elevenVoiceId", FORGE_VOICE_DEFAULT_ID),
    elevenModelId: forgeVoiceFieldValue("voiceElevenModel", "forge.voice.elevenModelId", FORGE_VOICE_DEFAULT_MODEL),
    orpheusEndpoint: forgeVoiceFieldValue("voiceOrpheusEndpoint", "forge.voice.orpheusEndpoint", ""),
    orpheusVoice: forgeVoiceFieldValue("voiceOrpheusVoice", "forge.voice.orpheusVoice", "tara"),
    monthlyLimit: Number.isFinite(monthlyLimit) ? Math.max(500, monthlyLimit) : 10000,
    autoSpeak: forgeVoiceStorageGet("forge.voice.autoSpeak", "0") === "1",
  };
}

function latestSpeakableAssistantMessage() {
  for (let i = alphaCanvasChatMessages.length - 1; i >= 0; i -= 1) {
    const message = alphaCanvasChatMessages[i];
    if (message?.role === "assistant" && !message?.meta?.attachmentOnly && String(message.text || "").trim()) {
      return message;
    }
  }
  return null;
}

function syncForgeVoiceOutButton() {
  if (!forgeCanvasChatVoiceOutBtn) return;
  const enabled = forgeVoiceSettings().autoSpeak;
  forgeCanvasChatVoiceOutBtn.classList.toggle("active", enabled);
  forgeCanvasChatVoiceOutBtn.setAttribute("aria-pressed", enabled ? "true" : "false");
  forgeCanvasChatVoiceOutBtn.setAttribute("aria-label", enabled ? "Voice output on" : "Voice output off");
  forgeCanvasChatVoiceOutBtn.title = enabled ? "Voice output on" : "Voice output off";
}

function setForgeVoiceAutoSpeak(enabled, options = {}) {
  const next = !!enabled;
  forgeVoiceStorageSet("forge.voice.autoSpeak", next ? "1" : "0");
  if (voiceAutoSpeak) voiceAutoSpeak.checked = next;
  syncForgeVoiceOutButton();
  renderVoiceProviderStatus?.(voiceProviderLastStatus);
  if (!next) {
    stopForgeVoicePlayback();
    return;
  }
  void refreshVoiceProviderStatus({ silent: true });
  if (options.speakLatest) {
    const latest = latestSpeakableAssistantMessage();
    if (latest) setTimeout(() => { void speakForgeCanvasText(latest.text, forgeCanvasChatVoiceOutBtn); }, 120);
  }
}

function stopForgeVoicePlayback() {
  if (forgeVoiceAudio) {
    try {
      forgeVoiceAudio.pause();
      forgeVoiceAudio.src = "";
    } catch (_) {}
    forgeVoiceAudio = null;
  }
  if (forgeVoiceObjectUrl) {
    URL.revokeObjectURL(forgeVoiceObjectUrl);
    forgeVoiceObjectUrl = "";
  }
  if (forgeVoiceActiveButton) {
    forgeVoiceActiveButton.classList.remove("speaking", "loading");
    forgeVoiceActiveButton.setAttribute("aria-label", "Speak message");
    forgeVoiceActiveButton = null;
  }
}

function decodeAudioBase64(base64) {
  const binary = atob(String(base64 || ""));
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

async function speakForgeCanvasText(text, sourceButton = null, options = {}) {
  const cleanText = String(text || "").trim();
  const failVoiceSync = (err = null) => {
    try {
      if (typeof options.onFail === "function") options.onFail(err);
    } catch (_) {
      // Ignore UI sync callback failures.
    }
  };
  const markVoiceReady = (result) => {
    try {
      if (typeof options.onAudioReady === "function") options.onAudioReady(result);
    } catch (_) {
      // Ignore UI sync callback failures.
    }
  };
  if (!cleanText) {
    failVoiceSync();
    return null;
  }
  const invoke = window.__TAURI__?.core?.invoke;
  if (!invoke) {
    console.warn("[voice] Tauri invoke is not available");
    failVoiceSync();
    return null;
  }
  if (sourceButton?.classList.contains("speaking")) {
    stopForgeVoicePlayback();
    failVoiceSync();
    return null;
  }
  stopForgeVoicePlayback();
  if (sourceButton) {
    sourceButton.classList.add("loading");
    sourceButton.setAttribute("aria-label", "Preparing voice");
    forgeVoiceActiveButton = sourceButton;
  }
  const settings = forgeVoiceSettings();
  try {
    const result = await invoke("voice_tts_generate", {
      request: {
        text: cleanText,
        elevenVoiceId: settings.elevenVoiceId,
        elevenModelId: settings.elevenModelId,
        orpheusEndpoint: settings.orpheusEndpoint,
        orpheusVoice: settings.orpheusVoice,
        monthlyLimit: settings.monthlyLimit,
        preferOrpheus: !!options.preferOrpheus,
      },
    });
    const bytes = decodeAudioBase64(result?.audioBase64 || "");
    const blob = new Blob([bytes], { type: result?.contentType || "audio/mpeg" });
    forgeVoiceObjectUrl = URL.createObjectURL(blob);
    forgeVoiceAudio = new Audio(forgeVoiceObjectUrl);
    forgeVoiceAudio.addEventListener("ended", stopForgeVoicePlayback, { once: true });
    forgeVoiceAudio.addEventListener("error", stopForgeVoicePlayback, { once: true });
    if (sourceButton) {
      sourceButton.classList.remove("loading");
      sourceButton.classList.add("speaking");
      sourceButton.setAttribute("aria-label", `Stop voice (${result?.engine || "voice"})`);
    }
    if (typeof voiceProviderHint !== "undefined" && voiceProviderHint && result?.message) {
      voiceProviderHint.textContent = result.message;
    }
    await forgeVoiceAudio.play();
    markVoiceReady(result);
    void refreshVoiceProviderStatus({ silent: true });
    return result;
  } catch (err) {
    if (sourceButton) {
      sourceButton.classList.remove("loading", "speaking");
      sourceButton.classList.add("denied");
      sourceButton.setAttribute("aria-label", "Voice failed");
      setTimeout(() => sourceButton.classList.remove("denied"), 1200);
    }
    if (typeof voiceProviderHint !== "undefined" && voiceProviderHint) {
      voiceProviderHint.textContent = `Voice failed: ${err}`;
    }
    console.warn("[voice] TTS failed", err);
    stopForgeVoicePlayback();
    failVoiceSync(err);
    return null;
  }
}

function buildCanvasChatSpeakButton(text) {
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "canvas-chat-speak";
  btn.setAttribute("aria-label", "Speak message");
  btn.innerHTML = `
    <svg class="canvas-chat-speak-icon" viewBox="0 0 16 16" focusable="false" aria-hidden="true">
      <path d="M2.5 6v4h2.6l3.4 2.5v-9L5.1 6H2.5z" />
      <path d="M11 6.1a3 3 0 0 1 0 3.8" />
      <path d="M13 4.6a5.2 5.2 0 0 1 0 6.8" />
    </svg>
  `;
  btn.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    void speakForgeCanvasText(text, btn);
  });
  return btn;
}

function renderCanvasMessageAttachments(item, message) {
  const attachments = Array.isArray(message?.meta?.attachments) ? message.meta.attachments : [];
  const programs = Array.isArray(message?.meta?.programs) ? message.meta.programs : [];
  const atlasItems = Array.isArray(message?.meta?.atlasItems) ? message.meta.atlasItems : [];
  if (!programs.length && !atlasItems.length) return;
  const wrap = createUiEl("div", "canvas-message-attachments");
  programs.forEach((program) => {
    const name = String(program?.name || "program").trim();
    if (!name) return;
    const lensUrl = String(program?.lensUrl || program?.lens_url || "").trim();
    const chip = createUiEl(lensUrl ? "button" : "span", `canvas-message-attachment program${lensUrl ? " lens" : ""}`);
    if (lensUrl) {
      chip.type = "button";
      chip.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        openMarsLensView(lensUrl);
      });
    }
    chip.textContent = name;
    chip.title = lensUrl ? `Open ${name}` : name;
    wrap.appendChild(chip);
  });
  if (atlasItems.length) {
    // Snapshot of the chat-bar program-group leaning against the user
    // message — same icon + slots as the chat input, read-only here.
    // Click on a cube triggers the in-place formula reveal animation.
    const strip = createUiEl("div", "canvas-message-atlas-strip");
    const icon = createUiEl("span", "canvas-message-atlas-icon");
    icon.innerHTML = '<svg viewBox="0 0 20 20" focusable="false" aria-hidden="true"><path d="m7.5 6.5-3.5 3.5 3.5 3.5"/><path d="m12.5 6.5 3.5 3.5-3.5 3.5"/></svg>';
    strip.appendChild(icon);
    atlasItems.forEach((it) => {
      const tag = String(it?.tag || "").trim();
      if (!tag) return;
      const slot = createUiEl("div", "canvas-message-atlas-slot");
      const cube = createUiEl(
        "span",
        `my-atlas-cube ${atlasNodeColorClass(tag)}`,
      );
      cube.dataset.tag = tag;
      cube.dataset.kind = String(it?.kind || "node");
      if (it?.formula) cube.dataset.formula = String(it.formula);
      if (it?.algorithm) cube.dataset.algorithm = String(it.algorithm);
      cube.title = tag;
      cube.innerHTML = `<span class="my-atlas-cube-face">${escapeAttr(atlasNodeInitials(tag))}</span>`;
      slot.appendChild(cube);
      strip.appendChild(slot);
    });
    wrap.appendChild(strip);
  }
  if (wrap.childNodes.length) item.appendChild(wrap);
}

function canvasMessageVisualAttachments(message) {
  if (message?.role !== "user") return [];
  return Array.isArray(message?.meta?.attachments) ? message.meta.attachments : [];
}

