function inferMarsGeoNodesFromText(text) {
  const normalized = normalizeForLocalIntent(text);
  if (!normalized) return [];
  const matches = [];
  const seen = new Set();
  for (const place of MARS_GEONODE_PLACE_ALIASES) {
    const aliases = [place.label, place.key, place.tag, ...(place.aliases || [])];
    if (!aliases.some((alias) => normalized.includes(normalizeForLocalIntent(alias)))) continue;
    if (seen.has(place.tag)) continue;
    seen.add(place.tag);
    matches.push(place);
  }
  return matches;
}

function matchOriginalSpatialAlias(source, place) {
  const raw = String(source || "");
  const aliases = [place.label, ...(place.aliases || [])]
    .map((value) => String(value || "").trim())
    .filter(Boolean)
    .sort((a, b) => b.length - a.length);
  for (const alias of aliases) {
    const escaped = alias.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const match = raw.match(new RegExp(escaped, "i"));
    if (match?.[0]) return match[0];
  }
  return place.label;
}

async function ensureAssistantSpatialMentions(message) {
  if (!message || message.role !== "assistant") return;
  if (Array.isArray(message.meta?.spatialMentions) && message.meta.spatialMentions.length) return;
  const places = inferMarsGeoNodesFromText(message.text || "");
  if (!places.length) return;
  const invoke = window.__TAURI__?.core?.invoke;
  let atlasTags = new Set();
  if (invoke) {
    try {
      const overview = await invoke("get_forge_atlas_overview", { limit: 120 });
      const tags = overview?.my_atlas?.metric_tags || overview?.my_atlas?.tags || [];
      atlasTags = new Set(
        tags
          .map((item) => String(item?.tag || item?.title || item?.name || "").trim())
          .filter(Boolean),
      );
    } catch (_) {}
  }
  const resolved = [];
  for (const place of places) {
    const coords = MARS_GEONODE_COORDS[place.tag] || null;
    if (invoke && coords && !atlasTags.has(place.tag)) {
      try {
        await invoke("upsert_forge_geonode", {
          request: {
            name: place.label,
            tag: place.tag,
            body: "mars",
            lat: coords.lat,
            lon: coords.lon,
            node_kind: coords.parentTag ? "mini_geo_node" : "geo_node",
            parent_geonode: coords.parentTag || null,
            coordinate_source: "forge_catalog",
            confidence: 0.99,
            aliases: place.aliases || [],
          },
        });
        atlasTags.add(place.tag);
      } catch (_) {}
    }
    resolved.push({
      tag: place.tag,
      key: place.key,
      label: place.label,
      kind: coords?.parentTag ? "minigeonode" : "geonode",
      body: "mars",
      parentTag: coords?.parentTag || "",
      renderText: matchOriginalSpatialAlias(message.text || "", place),
      atlasReady: atlasTags.has(place.tag),
    });
  }
  if (!resolved.length) return;
  message.meta = {
    ...(message.meta || {}),
    spatialMentions: resolved,
  };
  saveAlphaCanvasSessionState();
  alphaCanvasChatVersion += 1;
  alphaLogRenderedVersion = -1;
  scheduleAlphaRender?.();
}

function inferPlanetVisualFromText(text) {
  const normalized = normalizeForLocalIntent(text);
  if (!normalized) return null;
  const geonodes = inferMarsGeoNodesFromText(text);
  const mentionsMars = /\bmars\b/.test(normalized)
    || normalized.includes("planete rouge")
    || normalized.includes("martien")
    || normalized.includes("martienne")
    || geonodes.length > 0;
  if (!mentionsMars) return null;
  const locationKeys = [];
  const tags = [];
  const labels = [];
  const addKey = (key) => {
    if (key && !locationKeys.includes(key)) locationKeys.push(key);
  };
  for (const place of geonodes) {
    addKey(place.parent || place.key);
    addKey(place.key);
    if (place.tag && !tags.includes(place.tag)) tags.push(place.tag);
    if (place.label && !labels.includes(place.label)) labels.push(place.label);
  }
  const lensUrl = planetSphereUrlForBody("mars", {
    locations: locationKeys,
    geonodes: tags,
    embedMode: "inline",
  });
  return {
    tool: "planet_sphere",
    body: "mars",
    name: labels.length ? `Planet · Mars · ${labels.slice(0, 2).join(", ")}` : "Planet · Mars",
    lensUrl,
    geonodes: tags,
    locations: locationKeys,
    labels,
    programKind: "visual_program",
  };
}

function inferSpatialAtlasIntentFromText(text) {
  const normalized = normalizeForLocalIntent(text);
  if (!normalized) return null;
  const terms = [
    "mercury", "mercure", "venus", "earth", "terre", "moon", "lune", "mars",
    "jupiter", "saturn", "saturne", "uranus", "neptune", "pluto", "pluton",
    "europa", "europe", "ganymede", "callisto", "io", "titan", "enceladus",
    "ceres", "vesta", "asteroid", "asteroide", "comet", "comete",
    "solar system", "systeme solaire", "galaxy", "galaxie", "milky way",
    "voie lactee", "nebula", "nebuleuse", "star system", "systeme stellaire",
    "exoplanet", "exoplanete", "crater", "cratere", "mons", "planitia",
    "chasma", "mare", "vallis", "regio",
  ];
  if (!terms.some((term) => normalized.includes(normalizeForLocalIntent(term)))) return null;
  return { scope: "spatial_atlas", knownMarsMatches: inferMarsGeoNodesFromText(text) };
}

function canvasMessagePlanetVisual(message) {
  if (message?.role !== "assistant") return null;
  const planet = message?.meta?.planetVisual || null;
  if (!planet || String(planet?.tool || "").toLowerCase() !== "planet_sphere") return null;
  return planet;
}

function alphaDocForVisualName(name) {
  const wanted = String(name || "").trim().toLowerCase();
  const docs = [alphaDocState, ...alphaExtraCharts];
  return docs.find((doc) => String(doc?.fileName || "").trim().toLowerCase() === wanted)
    || docs.find((doc) => doc?.fileName)
    || null;
}

function alphaDocsForCanvasMessageVisual(message) {
  const docs = [];
  const seen = new Set();
  const addDoc = (doc) => {
    const name = String(doc?.fileName || "").trim();
    if (!name || seen.has(name.toLowerCase())) return;
    seen.add(name.toLowerCase());
    docs.push(doc);
  };
  for (const file of canvasMessageVisualAttachments(message)) {
    addDoc(alphaDocForVisualName(file?.name));
  }
  addDoc(alphaDocState);
  for (const doc of alphaExtraCharts || []) addDoc(doc);
  return docs.filter((doc) => doc?.fileName).slice(0, 4);
}

function canvasMessageVisualIcon(name) {
  const icons = {
    add: '<svg viewBox="0 0 24 24" focusable="false" aria-hidden="true"><path d="M12 5v14" /><path d="M5 12h14" /></svg>',
    programs: '<svg viewBox="0 0 24 24" focusable="false" aria-hidden="true"><path d="m8 6-5 6 5 6" /><path d="m16 6 5 6-5 6" /><path d="m14 4-4 16" /></svg>',
    split: '<svg viewBox="0 0 24 24" focusable="false" aria-hidden="true"><rect x="4" y="5" width="16" height="14" rx="2" /><path d="M12 5v14" /></svg>',
    cube: '<svg viewBox="0 0 24 24" focusable="false" aria-hidden="true"><path d="M12 3 4 7v10l8 4 8-4V7l-8-4z" /><path d="M4 7l8 4 8-4" /><path d="M12 11v10" /></svg>',
    planet: '<svg viewBox="0 0 24 24" focusable="false" aria-hidden="true"><circle cx="12" cy="12" r="8" /><path d="M4 12h16" /><path d="M12 4c2.2 2.4 3.2 5 3.2 8s-1 5.6-3.2 8" /><path d="M12 4c-2.2 2.4-3.2 5-3.2 8s1 5.6 3.2 8" /></svg>',
  };
  return icons[name] || "";
}

function buildCanvasMessageVisualAction(action, title, icon) {
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "canvas-message-visual-action";
  btn.dataset.visualAction = action;
  btn.title = title;
  btn.setAttribute("aria-label", title);
  btn.innerHTML = canvasMessageVisualIcon(icon);
  return btn;
}

function buildCanvasMessageVisualCard(message) {
  const planet = canvasMessagePlanetVisual(message);
  if (planet) return null;
  const files = canvasMessageVisualAttachments(message);
  if (!files.length) return null;
  const docs = alphaDocsForCanvasMessageVisual(message);
  const card = createUiEl("aside", "canvas-message-visual-card");
  const initialMode = message?.meta?.visualMode === "3d" ? "3d" : "2d";
  card.dataset.viewMode = initialMode;
  card.classList.toggle("is-3d", initialMode === "3d");
  if (docs.length > 1) card.classList.add("has-multiple");
  const strip = createUiEl("div", "canvas-message-visual-strip");
  const visualDocs = docs.length ? docs : [{ fileName: String(files[0]?.name || "attached file"), fileSize: Number(files[0]?.size || 0), candles: [] }];
  visualDocs.forEach((doc) => {
    const panel = createUiEl("div", "canvas-message-visual-panel");
    panel.dataset.fileName = String(doc?.fileName || "");
    const canvas = document.createElement("canvas");
    canvas.className = "canvas-message-visual-canvas";
    canvas.dataset.fileName = String(doc?.fileName || "");
    attachCanvasMessageVisualInteractions(canvas);
    panel.appendChild(canvas);
    strip.appendChild(panel);
  });
  card.appendChild(strip);
  const toolbar = createUiEl("div", "canvas-message-visual-toolbar");
  toolbar.appendChild(buildCanvasMessageVisualAction("add-file", "Add another file to this session", "add"));
  toolbar.appendChild(buildCanvasMessageVisualAction("programs", "Choose a program for this file", "programs"));
  toolbar.appendChild(buildCanvasMessageVisualAction("split", "Open split view", "split"));
  const view3dButton = buildCanvasMessageVisualAction(
    "3d",
    initialMode === "3d" ? "Switch this card back to 2D" : "Switch this card to 3D",
    "cube"
  );
  view3dButton.setAttribute("aria-pressed", initialMode === "3d" ? "true" : "false");
  toolbar.appendChild(view3dButton);
  card.appendChild(toolbar);
  return card;
}

function inlineChartIndicatorsForDoc(doc) {
  const candles = Array.isArray(doc?.candles) ? doc.candles : [];
  if (!candles.length) return { ema8: [], ema21: [], ema50: [], vwap: [] };
  if (doc === alphaDocState) return alphaIndicators;
  const closes = candles.map((c) => c.close);
  return {
    ema8: calcEMA(closes, 8),
    ema21: calcEMA(closes, 21),
    ema50: calcEMA(closes, 50),
    vwap: calcVWAP(candles),
  };
}

function drawCanvasMessageCandlesCard(ctx, W, H, doc) {
  const candles = Array.isArray(doc?.candles) ? doc.candles : [];
  ctx.clearRect(0, 0, W, H);
  if (!candles.length) {
    ctx.fillStyle = "rgba(238,238,232,0.48)";
    ctx.font = "12px Geist, Segoe UI, sans-serif";
    ctx.fillText("2D preview loading...", 16, 28);
    return;
  }

  const padTop = 42;
  const padLeft = 8;
  const chartRight = W - 66;
  const chartBottom = H - 28;
  const chartW = Math.max(80, chartRight - padLeft);
  const chartH = Math.max(70, chartBottom - padTop);
  const viewCount = Math.max(10, Math.min(Number(doc.candleViewCount || 200), candles.length));
  const viewEnd = Math.max(viewCount - 1, Math.min(Number(doc.candleViewEnd || candles.length - 1), candles.length - 1));
  const viewStart = viewEnd - viewCount + 1;
  const visible = candles.slice(viewStart, viewEnd + 1);

  let yMin = Infinity;
  let yMax = -Infinity;
  for (const c of visible) {
    if (c.low < yMin) yMin = c.low;
    if (c.high > yMax) yMax = c.high;
  }
  const indicators = inlineChartIndicatorsForDoc(doc);
  for (const key of ["ema8", "ema21", "ema50", "vwap"]) {
    const series = indicators[key] || [];
    for (let i = viewStart; i <= viewEnd && i < series.length; i++) {
      const value = series[i];
      if (!Number.isFinite(value)) continue;
      if (value < yMin) yMin = value;
      if (value > yMax) yMax = value;
    }
  }
  if (!Number.isFinite(yMin) || yMin === yMax) { yMin -= 1; yMax += 1; }
  const yRange = yMax - yMin;
  yMin -= yRange * 0.08;
  yMax += yRange * 0.08;

  const xOf = (i) => padLeft + (i + 0.5) * (chartW / viewCount);
  const yOf = (p) => padTop + (1 - (p - yMin) / (yMax - yMin)) * chartH;
  const candleW = Math.max(1, Math.min(7, (chartW / viewCount) * 0.62));

  ctx.save();
  ctx.strokeStyle = "rgba(255,255,255,0.035)";
  ctx.lineWidth = 1;
  ctx.font = '10px ui-monospace, "SF Mono", Consolas, monospace';
  ctx.textBaseline = "middle";
  ctx.textAlign = "left";
  ctx.fillStyle = "rgba(170,170,164,0.55)";
  for (let i = 0; i <= 4; i++) {
    const price = yMin + (yMax - yMin) * (i / 4);
    const y = yOf(price);
    ctx.beginPath();
    ctx.moveTo(padLeft, y);
    ctx.lineTo(padLeft + chartW, y);
    ctx.stroke();
    ctx.fillText(price.toFixed(3), padLeft + chartW + 8, y);
  }

  ctx.textBaseline = "top";
  ctx.fillStyle = "rgba(140,140,134,0.55)";
  for (let i = 0; i < 3; i++) {
    const t = i / 2;
    const c = visible[Math.round((visible.length - 1) * t)];
    if (!c) continue;
    const d = new Date(c.time);
    const label = viewCount > 100
      ? `${d.getUTCFullYear()}-${pad2(d.getUTCMonth() + 1)}-${pad2(d.getUTCDate())}`
      : `${pad2(d.getUTCMonth() + 1)}-${pad2(d.getUTCDate())} ${pad2(d.getUTCHours())}:00`;
    const x = padLeft + chartW * t;
    ctx.textAlign = i === 0 ? "left" : (i === 2 ? "right" : "center");
    ctx.fillText(label, x, padTop + chartH + 8);
  }

  const drawLine = (series, color, dash = null) => {
    if (!series?.length) return;
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = 1;
    if (dash) ctx.setLineDash(dash);
    ctx.beginPath();
    let first = true;
    for (let i = 0; i < visible.length; i++) {
      const vi = viewStart + i;
      const value = series[vi];
      if (!Number.isFinite(value)) continue;
      if (first) { ctx.moveTo(xOf(i), yOf(value)); first = false; }
      else ctx.lineTo(xOf(i), yOf(value));
    }
    ctx.stroke();
    ctx.restore();
  };
  drawLine(indicators.ema8, "rgba(220,196,118,0.80)");
  drawLine(indicators.ema21, "rgba(118,178,212,0.80)");
  drawLine(indicators.ema50, "rgba(192,148,218,0.58)");
  drawLine(indicators.vwap, "rgba(120,196,128,0.75)", [4, 3]);

  const bullColor = "rgba(96,196,138,1)";
  const bearColor = "rgba(228,108,108,1)";
  for (let i = 0; i < visible.length; i++) {
    const c = visible[i];
    const x = xOf(i);
    const color = c.close >= c.open ? bullColor : bearColor;
    ctx.strokeStyle = color;
    ctx.fillStyle = color;
    ctx.lineWidth = 0.85;
    ctx.beginPath();
    ctx.moveTo(x, yOf(c.high));
    ctx.lineTo(x, yOf(c.low));
    ctx.stroke();
    const yTop = Math.min(yOf(c.open), yOf(c.close));
    const bodyH = Math.max(1, Math.abs(yOf(c.close) - yOf(c.open)));
    ctx.fillRect(x - candleW / 2, yTop, candleW, bodyH);
  }

  ctx.textAlign = "left";
  ctx.textBaseline = "top";
  ctx.fillStyle = "rgba(238,238,232,0.72)";
  ctx.font = '600 12px "Segoe UI", -apple-system, sans-serif';
  ctx.fillText(String(doc.fileName || "attached file").replace(/\.csv$/i, ""), padLeft, 8);
  ctx.font = '10px ui-monospace, "SF Mono", Consolas, monospace';
  ctx.fillStyle = "rgba(140,140,134,0.65)";
  ctx.textAlign = "right";
  ctx.fillText(`${candles.length} bars    ${viewCount} shown`, chartRight, 10);

  const legend = [
    { label: "EMA 8", color: "rgba(220,196,118,0.95)" },
    { label: "EMA 21", color: "rgba(118,178,212,0.95)" },
    { label: "EMA 50", color: "rgba(192,148,218,0.85)" },
    { label: "VWAP", color: "rgba(120,196,128,0.95)" },
  ];
  ctx.textBaseline = "middle";
  let lx = chartRight;
  const ly = 27;
  for (let i = legend.length - 1; i >= 0; i--) {
    const item = legend[i];
    ctx.textAlign = "right";
    ctx.fillStyle = "rgba(170,170,164,0.65)";
    ctx.fillText(item.label, lx, ly);
    const textW = ctx.measureText(item.label).width;
    ctx.fillStyle = item.color;
    ctx.fillRect(lx - textW - 10, ly - 1, 6, 2);
    lx -= textW + 22;
  }

  if (doc.candleHover >= 0 && doc.candleHover < visible.length) {
    const c = visible[doc.candleHover];
    const x = xOf(doc.candleHover);
    ctx.strokeStyle = "rgba(255,255,255,0.14)";
    ctx.setLineDash([2, 4]);
    ctx.beginPath();
    ctx.moveTo(x, padTop);
    ctx.lineTo(x, padTop + chartH);
    ctx.stroke();
    ctx.setLineDash([]);
    const tip = [
      new Date(c.time).toISOString().replace("T", " ").slice(0, 16),
      `O ${c.open.toFixed(3)}  H ${c.high.toFixed(3)}`,
      `L ${c.low.toFixed(3)}  C ${c.close.toFixed(3)}`,
      c.volume ? `V ${formatCount(Math.round(c.volume))}` : null,
    ].filter(Boolean);
    const tipW = 178;
    const tipH = 16 + tip.length * 15;
    let tipX = x + 14;
    if (tipX + tipW > chartRight) tipX = x - tipW - 14;
    const tipY = padTop + 10;
    ctx.fillStyle = "rgba(16,16,15,0.94)";
    ctx.fillRect(tipX, tipY, tipW, tipH);
    ctx.fillStyle = c.close >= c.open ? bullColor : bearColor;
    ctx.fillRect(tipX, tipY, 2, tipH);
    ctx.font = '11px ui-monospace, "SF Mono", Consolas, monospace';
    ctx.textAlign = "left";
    ctx.textBaseline = "top";
    ctx.fillStyle = "rgba(232,232,226,0.96)";
    tip.forEach((line, i) => ctx.fillText(line, tipX + 9, tipY + 8 + i * 15));
  }
  ctx.restore();
}

const canvasMessage3dCameraStates = new WeakMap();
let canvasMessage3dAutoRotateRaf = 0;
const CANVAS_MESSAGE_3D_AUTO_ROTATE_SPEED = (2 * Math.PI) / 420000;
const CANVAS_MESSAGE_3D_AUTO_RESUME_DELAY_MS = 1200;

function canvasMessageIsInline3d(canvas) {
  return canvas?.closest?.(".canvas-message-visual-card")?.dataset?.viewMode === "3d";
}

function canvasMessage3dCameraState(canvas) {
  let state = canvasMessage3dCameraStates.get(canvas);
  if (!state) {
    state = {
      yaw: 0.68,
      pitch: 0.34,
      dist: 1.45,
      drag: null,
      lastFrame: 0,
      lastInteraction: 0,
    };
    canvasMessage3dCameraStates.set(canvas, state);
  }
  return state;
}

function activeCanvasMessage3dCanvases() {
  return Array.from(document.querySelectorAll(".canvas-message-visual-card.is-3d .canvas-message-visual-canvas"))
    .filter((canvas) => canvasMessageIsInline3d(canvas));
}

function syncCanvasMessage3dAutoRotate() {
  const hasActive3d = activeCanvasMessage3dCanvases().length > 0;
  if (hasActive3d && !canvasMessage3dAutoRotateRaf) {
    canvasMessage3dAutoRotateRaf = requestAnimationFrame(canvasMessage3dAutoRotateLoop);
  } else if (!hasActive3d && canvasMessage3dAutoRotateRaf) {
    cancelAnimationFrame(canvasMessage3dAutoRotateRaf);
    canvasMessage3dAutoRotateRaf = 0;
  }
}

function canvasMessage3dAutoRotateLoop(now) {
  canvasMessage3dAutoRotateRaf = 0;
  const canvases = activeCanvasMessage3dCanvases();
  if (!canvases.length) return;
  for (const canvas of canvases) {
    const doc = alphaDocForVisualName(canvas.dataset.fileName);
    if (!doc?.candles?.length) continue;
    const camera = canvasMessage3dCameraState(canvas);
    const elapsed = camera.lastFrame ? Math.min(64, now - camera.lastFrame) : 16;
    camera.lastFrame = now;
    if (!camera.drag && now - camera.lastInteraction > CANVAS_MESSAGE_3D_AUTO_RESUME_DELAY_MS) {
      camera.yaw += elapsed * CANVAS_MESSAGE_3D_AUTO_ROTATE_SPEED;
      drawInlineCandlePreview(canvas, doc);
    }
  }
  canvasMessage3dAutoRotateRaf = requestAnimationFrame(canvasMessage3dAutoRotateLoop);
}

function drawCanvasMessage3dCard(canvas, ctx, W, H, doc) {
  const candles = Array.isArray(doc?.candles) ? doc.candles : [];
  ctx.clearRect(0, 0, W, H);
  if (candles.length < 10) {
    ctx.fillStyle = "rgba(238,238,232,0.48)";
    ctx.font = "12px Geist, Segoe UI, sans-serif";
    ctx.fillText("3D view needs parsed numeric rows.", 16, 28);
    return;
  }
  const viewCount = Math.max(20, Math.min(Number(doc.candleViewCount || 300), candles.length));
  const viewEnd = Math.max(viewCount - 1, Math.min(Number(doc.candleViewEnd || candles.length - 1), candles.length - 1));
  const viewStart = viewEnd - viewCount + 1;
  const visible = candles.slice(viewStart, viewEnd + 1);
  const maxPoints = 900;
  const step = Math.max(1, Math.ceil(visible.length / maxPoints));
  let low = Infinity;
  let high = -Infinity;
  let maxVolume = 0;
  for (const c of visible) {
    if (c.low < low) low = c.low;
    if (c.high > high) high = c.high;
    if ((c.volume || 0) > maxVolume) maxVolume = c.volume || 0;
  }
  if (!Number.isFinite(low) || high === low) { low -= 1; high += 1; }
  const priceRange = high - low || 1;
  const volumeScale = Math.log1p(maxVolume || 1) || 1;
  const cx = W * 0.52;
  const cy = H * 0.54;
  const sx = Math.min(W * 0.58, 520);
  const sy = Math.min(H * 0.58, 260);
  const sz = Math.min(W * 0.24, 170);
  const camera = canvasMessage3dCameraState(canvas);
  const yaw = camera.yaw;
  const pitch = camera.pitch;
  const dist = camera.dist;
  const cosY = Math.cos(yaw);
  const sinY = Math.sin(yaw);
  const cosP = Math.cos(pitch);
  const sinP = Math.sin(pitch);
  const project = (x, y, z) => {
    const px = x - 0.5;
    const py = (y - 0.5) * 0.92;
    const pz = (z - 0.5) * 0.76;
    const x1 = px * cosY - pz * sinY;
    const z1 = px * sinY + pz * cosY;
    const y1 = py * cosP - z1 * sinP;
    const z2 = py * sinP + z1 * cosP;
    const perspective = 1 / Math.max(0.58, dist + z2 * 0.52);
    return {
      x: cx + x1 * sx * perspective,
      y: cy - y1 * sy * perspective,
      depth: z2,
    };
  };

  ctx.save();
  ctx.lineWidth = 1;
  ctx.font = '10px ui-monospace, "SF Mono", Consolas, monospace';
  ctx.fillStyle = "rgba(140,140,134,0.62)";
  ctx.strokeStyle = "rgba(238,238,232,0.13)";
  const origin = project(0, 0, 0);
  const xAxis = project(1, 0, 0);
  const yAxis = project(0, 1, 0);
  const zAxis = project(0, 0, 1);
  ctx.beginPath();
  ctx.moveTo(origin.x, origin.y); ctx.lineTo(xAxis.x, xAxis.y);
  ctx.moveTo(origin.x, origin.y); ctx.lineTo(yAxis.x, yAxis.y);
  ctx.moveTo(origin.x, origin.y); ctx.lineTo(zAxis.x, zAxis.y);
  ctx.stroke();
  ctx.fillText("time", xAxis.x + 6, xAxis.y + 2);
  ctx.fillText("price", yAxis.x + 6, yAxis.y - 8);
  ctx.fillText("volume", zAxis.x + 6, zAxis.y + 2);

  const drawSeries = (series, color, width = 1) => {
    if (!series?.length) return;
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.beginPath();
    let first = true;
    for (let i = 0; i < visible.length; i += step) {
      const vi = viewStart + i;
      const value = series[vi];
      if (!Number.isFinite(value)) continue;
      const c = candles[vi];
      const x = i / Math.max(1, visible.length - 1);
      const y = (value - low) / priceRange;
      const z = Math.log1p(c.volume || 0) / volumeScale;
      const p = project(x, y, z);
      if (first) { ctx.moveTo(p.x, p.y); first = false; }
      else ctx.lineTo(p.x, p.y);
    }
    ctx.stroke();
    ctx.restore();
  };

  const indicators = inlineChartIndicatorsForDoc(doc);
  drawSeries(indicators.ema8, "rgba(220,196,118,0.70)", 1);
  drawSeries(indicators.ema21, "rgba(118,178,212,0.70)", 1);
  drawSeries(indicators.ema50, "rgba(192,148,218,0.55)", 1);
  drawSeries(indicators.vwap, "rgba(120,196,128,0.65)", 1);

  for (let i = 0; i < visible.length; i += step) {
    const c = visible[i];
    const x = i / Math.max(1, visible.length - 1);
    const z = Math.log1p(c.volume || 0) / volumeScale;
    const pLow = project(x, (c.low - low) / priceRange, z);
    const pHigh = project(x, (c.high - low) / priceRange, z);
    const pClose = project(x, (c.close - low) / priceRange, z);
    const color = c.close >= c.open ? "rgba(96,196,138,0.74)" : "rgba(228,108,108,0.72)";
    ctx.strokeStyle = color;
    ctx.fillStyle = color;
    ctx.lineWidth = 0.85;
    ctx.beginPath();
    ctx.moveTo(pLow.x, pLow.y);
    ctx.lineTo(pHigh.x, pHigh.y);
    ctx.stroke();
    ctx.globalAlpha = 0.76;
    ctx.fillRect(pClose.x - 1.4, pClose.y - 1.4, 2.8, 2.8);
    ctx.globalAlpha = 1;
  }

  ctx.textAlign = "left";
  ctx.textBaseline = "top";
  ctx.fillStyle = "rgba(238,238,232,0.72)";
  ctx.font = '600 12px "Segoe UI", -apple-system, sans-serif';
  ctx.fillText(String(doc.fileName || "attached file").replace(/\.csv$/i, ""), 8, 8);
  ctx.font = '10px ui-monospace, "SF Mono", Consolas, monospace';
  ctx.fillStyle = "rgba(140,140,134,0.66)";
  ctx.textAlign = "right";
  ctx.fillText(`3D OHLCV map    ${candles.length} bars    ${viewCount} shown`, W - 66, 10);
  ctx.fillText("EMA 8 · EMA 21 · EMA 50 · VWAP · volume depth", W - 66, 26);
  ctx.restore();
}

function setCandleDocViewCountAtRatio(doc, ratio, targetCount) {
  const candles = Array.isArray(doc?.candles) ? doc.candles : [];
  if (!candles.length) return;
  const viewport = alphaResolveCandleViewport(doc, 10, 2000);
  const oldCount = viewport.viewCount;
  const oldEnd = viewport.viewEnd;
  const oldStart = oldEnd - oldCount + 1;
  const anchorRatio = Math.max(0, Math.min(1, Number(ratio) || 0));
  const anchorIndex = oldStart + anchorRatio * Math.max(1, oldCount - 1);
  const maxFutureSlots = alphaDocMaxFutureSlots(doc);
  const virtualLength = Math.max(candles.length, 1) + maxFutureSlots;
  const newCount = Math.max(10, Math.min(2000, virtualLength, Math.round(Number(targetCount) || oldCount)));
  let newStart = Math.round(anchorIndex - anchorRatio * Math.max(1, newCount - 1));
  let newEnd = newStart + newCount - 1;
  if (newStart < 0) {
    newStart = 0;
    newEnd = newCount - 1;
  }
  const maxEnd = Math.max(0, candles.length - 1) + maxFutureSlots;
  if (newEnd > maxEnd) {
    newEnd = maxEnd;
    newStart = Math.max(0, newEnd - newCount + 1);
  }
  doc.candleViewCount = newCount;
  doc.candleViewEnd = newEnd;
}

function zoomCandleDocAtRatio(doc, ratio, factor) {
  const candles = Array.isArray(doc?.candles) ? doc.candles : [];
  if (!candles.length) return;
  const viewport = alphaResolveCandleViewport(doc, 10, 2000);
  setCandleDocViewCountAtRatio(doc, ratio, viewport.viewCount * factor);
}

function drawInlineCandlePreview(canvas, doc) {
  const ctx = canvas.getContext("2d");
  const W = Math.max(360, canvas.clientWidth || 520);
  const H = Math.max(220, canvas.clientHeight || 300);
  const dpr = window.devicePixelRatio || 1;
  const nextW = Math.floor(W * dpr);
  const nextH = Math.floor(H * dpr);
  if (canvas.width !== nextW || canvas.height !== nextH) {
    canvas.width = nextW;
    canvas.height = nextH;
  }
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  const card = canvas.closest?.(".canvas-message-visual-card");
  if (card?.dataset.viewMode === "3d") {
    drawCanvasMessage3dCard(canvas, ctx, W, H, doc || {});
  } else {
    drawCanvasMessageCandlesCard(ctx, W, H, doc || {});
  }
}

function canvasMessageVisualPlotBounds(canvas) {
  const W = Math.max(360, canvas.clientWidth || 520);
  const H = Math.max(220, canvas.clientHeight || 300);
  return {
    left: 8,
    top: 42,
    right: W - 66,
    bottom: H - 28,
    width: Math.max(80, W - 74),
    height: Math.max(70, H - 70),
  };
}

function attachCanvasMessageVisualInteractions(canvas) {
  let dragging = false;
  let startX = 0;
  let startEnd = 0;
  const docForCanvas = () => alphaDocForVisualName(canvas.dataset.fileName);
  canvas.addEventListener("wheel", (event) => {
    const doc = docForCanvas();
    if (!doc?.candles?.length) return;
    event.preventDefault();
    event.stopPropagation();
    if (canvasMessageIsInline3d(canvas)) {
      const camera = canvasMessage3dCameraState(canvas);
      camera.dist = Math.max(0.86, Math.min(2.8, camera.dist * (event.deltaY > 0 ? 1.08 : 0.92)));
      camera.lastInteraction = performance.now();
      drawInlineCandlePreview(canvas, doc);
      syncCanvasMessage3dAutoRotate();
      return;
    }
    const rect = canvas.getBoundingClientRect();
    const plot = canvasMessageVisualPlotBounds(canvas);
    const ratio = (event.clientX - rect.left - plot.left) / Math.max(1, plot.width);
    zoomCandleDocAtRatio(doc, ratio, event.deltaY > 0 ? 1.25 : 0.8);
    drawInlineCandlePreview(canvas, doc);
  }, { passive: false });
  canvas.addEventListener("mousedown", (event) => {
    const doc = docForCanvas();
    if (!doc?.candles?.length) return;
    if (canvasMessageIsInline3d(canvas)) {
      const camera = canvasMessage3dCameraState(canvas);
      camera.drag = { x: event.clientX, y: event.clientY };
      camera.lastInteraction = performance.now();
      canvas.style.cursor = "grabbing";
      event.preventDefault();
      return;
    }
    dragging = true;
    startX = event.clientX;
    startEnd = Number(doc.candleViewEnd || doc.candles.length - 1);
    canvas.style.cursor = "grabbing";
    event.preventDefault();
  });
  canvas.addEventListener("mousemove", (event) => {
    const doc = docForCanvas();
    if (!doc?.candles?.length) return;
    if (canvasMessageIsInline3d(canvas)) {
      const camera = canvasMessage3dCameraState(canvas);
      if (camera.drag) {
        const dx = event.clientX - camera.drag.x;
        const dy = event.clientY - camera.drag.y;
        camera.drag = { x: event.clientX, y: event.clientY };
        camera.yaw += dx * 0.007;
        camera.pitch = Math.max(-0.92, Math.min(1.12, camera.pitch + dy * 0.006));
        camera.lastInteraction = performance.now();
        canvas.style.cursor = "grabbing";
        drawInlineCandlePreview(canvas, doc);
      } else {
        canvas.style.cursor = "grab";
      }
      syncCanvasMessage3dAutoRotate();
      return;
    }
    const rect = canvas.getBoundingClientRect();
    const plot = canvasMessageVisualPlotBounds(canvas);
    const cellW = plot.width / Math.max(10, Number(doc.candleViewCount || 200));
    if (dragging) {
      const shift = Math.round(-(event.clientX - startX) / Math.max(1, cellW));
      doc.candleViewEnd = Math.max(
        Number(doc.candleViewCount || 200) - 1,
        Math.min(doc.candles.length - 1, startEnd + shift)
      );
    } else {
      const x = event.clientX - rect.left;
      const y = event.clientY - rect.top;
      const xRel = x - plot.left;
      if (xRel < 0 || xRel > plot.width || y < plot.top || y > plot.bottom) {
        doc.candleHover = -1;
        canvas.style.cursor = "default";
      } else {
        doc.candleHover = Math.max(0, Math.min(Number(doc.candleViewCount || 200) - 1, Math.floor(xRel / Math.max(1, cellW))));
        canvas.style.cursor = "crosshair";
      }
    }
    drawInlineCandlePreview(canvas, doc);
  });
  const endDrag = () => {
    const doc = docForCanvas();
    if (canvasMessageIsInline3d(canvas)) {
      const camera = canvasMessage3dCameraState(canvas);
      if (camera.drag) {
        camera.drag = null;
        camera.lastInteraction = performance.now();
      }
      canvas.style.cursor = "grab";
      drawInlineCandlePreview(canvas, doc);
      syncCanvasMessage3dAutoRotate();
      return;
    }
    dragging = false;
    if (doc) doc.candleHover = -1;
    canvas.style.cursor = "default";
    drawInlineCandlePreview(canvas, doc);
  };
  canvas.addEventListener("mouseup", endDrag);
  canvas.addEventListener("mouseleave", endDrag);
}

function drawCanvasChatInlineVisuals() {
  document.querySelectorAll(".canvas-message-visual-canvas").forEach((canvas) => {
    const doc = alphaDocForVisualName(canvas.dataset.fileName);
    drawInlineCandlePreview(canvas, doc);
  });
  syncCanvasMessage3dAutoRotate();
}

function handleCanvasMessageVisualAction(action, source = null) {
  if (action === "add-file") {
    openAlphaFilePicker("append", { jobId: currentAlphaSessionJobId(), skipPlanPreview: true });
    return;
  }
  if (action === "programs") {
    if (typeof openProgramsOverlay === "function") openProgramsOverlay();
    return;
  }
  if (action === "open-planet") {
    const card = source?.closest?.(".canvas-message-visual-card");
    openMarsLensView(card?.dataset?.lensUrl || planetSphereUrlForBody("mars"));
    return;
  }
  if (action === "split") {
    if (hasAlphaVisualCard()) setAlphaSplitView(!alphaSplitViewEnabled);
    return;
  }
  if (action === "3d") {
    if (!alphaDocState?.candles?.length) return;
    if (alpha3dState?.open) closeAlpha3dView();
    const card = source?.closest?.(".canvas-message-visual-card");
    if (!card) return;
    const nextMode = card.dataset.viewMode === "3d" ? "2d" : "3d";
    const messageId = source?.closest?.("[data-message-id]")?.dataset?.messageId || "";
    const message = alphaCanvasChatMessages.find((item) => String(item.id) === String(messageId));
    if (message) {
      message.meta = { ...(message.meta || {}), visualMode: nextMode };
      saveAlphaCanvasSessionState();
    }
    card.dataset.viewMode = nextMode;
    card.classList.toggle("is-3d", nextMode === "3d");
    const btn = card.querySelector('[data-visual-action="3d"]');
    btn?.setAttribute("aria-pressed", nextMode === "3d" ? "true" : "false");
    btn?.setAttribute("title", nextMode === "3d" ? "Switch this card back to 2D" : "Switch this card to 3D");
    requestAnimationFrame(drawCanvasChatInlineVisuals);
    syncCanvasMessage3dAutoRotate();
  }
}

function hasCanvasInlineVisualMessages() {
  if (alphaSplitViewEnabled) return false;
  return alphaCanvasChatMessages.some((message) => (
    canvasMessageVisualAttachments(message).length > 0
    || Boolean(canvasMessagePlanetVisual(message))
  ));
}

function hasCanvasInlinePlanetMessages() {
  if (alphaSplitViewEnabled) return false;
  return alphaCanvasChatMessages.some((message) => Boolean(canvasMessagePlanetVisual(message)));
}

function renderCanvasChatMessages(parent) {
  if (!alphaCanvasChatMessages.length) return;
  const thread = createUiEl("section", "canvas-chat-thread");
  if (hasCanvasInlineVisualMessages()) thread.classList.add("has-inline-visual");
  if (hasCanvasInlinePlanetMessages()) thread.classList.add("has-inline-planet");
  for (const message of alphaCanvasChatMessages.slice(-18)) {
    const item = createUiEl("article", `canvas-chat-message ${message.role}`);
    if (message.meta?.programBuildKind) {
      item.classList.add("program-build-step", `program-build-${message.meta.programBuildKind}`);
    }
    const visualCard = alphaSplitViewEnabled ? null : buildCanvasMessageVisualCard(message);
    if (visualCard) item.classList.add("has-visual-card");
    if (visualCard && canvasMessagePlanetVisual(message)) item.classList.add("has-planet-visual");
    if (visualCard && message.meta?.attachmentOnly) item.classList.add("attachment-only");
    if (message.id != null) item.dataset.messageId = String(message.id);
    if (isMessagePinned(message)) item.classList.add("pinned");
    const name = message.role === "user"
      ? "You"
      : message.role === "tool"
        ? "Forge"
        : (message.meta?.agentLabel || "Codex");
    item.appendChild(buildCanvasChatNameElement(message.role, name));
    const textEl = createUiEl("div", "canvas-chat-text");
    const typing = message.role === "assistant" && isCanvasAssistantTyping(message);
    renderCanvasChatTextContent(
      textEl,
      message.role === "assistant" ? canvasAssistantTypedText(message) : message.text,
      message
    );
    if (message.meta?.programBuildKind) {
      const icon = createUiEl("span", "canvas-program-build-icon");
      icon.innerHTML = canvasProgramBuildIconHtml(message.meta.programBuildKind);
      textEl.prepend(icon);
    }
    if (typing) {
      item.classList.add("typing");
      textEl.appendChild(createUiEl("span", "canvas-chat-caret", ""));
    }
    if (isCanvasSpeakingTarget(message)) {
      item.classList.add("speaking");
    }
    item.appendChild(textEl);
    if (visualCard) item.appendChild(visualCard);
    renderCanvasMessageAttachments(item, message);
    if (message.role !== "tool" && !typing && !message.meta?.attachmentOnly) {
      const actions = createUiEl("div", "canvas-chat-actions");
      if (message.role === "assistant") actions.appendChild(buildCanvasChatSpeakButton(message.text || ""));
      actions.appendChild(buildCanvasChatCopyButton(message.text || ""));
      actions.appendChild(buildCanvasChatPinButton(message));
      item.appendChild(actions);
    }
    const toolLabels = compactCanvasToolLabels(message.meta?.toolEvents);
    if (toolLabels.length) {
      const tools = createUiEl("div", "canvas-chat-tools");
      for (const label of toolLabels) {
        tools.appendChild(createUiEl("span", "canvas-chat-tool", label));
      }
      item.appendChild(tools);
    }
    thread.appendChild(item);
  }
  if (canvasChatBusyInCurrentSession() && forgeCanvasChatPendingAssistants.length) {
    for (const pending of forgeCanvasChatPendingAssistants) {
      const item = createUiEl("article", "canvas-chat-message assistant thinking");
      const nameEl = buildCanvasChatNameElement("assistant", pending.label);
      // Append the rotating "is …" suffix inline with the agent name. The
      // text is updated character-by-character by the rotation timer so it
      // reads as a live typewriter (type → hold → backspace → next).
      const status = createUiEl("span", "canvas-thinking-status", currentCanvasThinkingPhrase());
      const caret = createUiEl("span", "canvas-thinking-caret", "");
      status.appendChild(caret);
      nameEl.appendChild(status);
      item.appendChild(nameEl);
      thread.appendChild(item);
    }
  }
  parent.appendChild(thread);
  thread.addEventListener("click", (event) => {
    const spatialPill = event.target?.closest?.(".canvas-spatial-pill");
    if (spatialPill && thread.contains(spatialPill)) {
      event.preventDefault();
      event.stopPropagation();
      focusPlanetSpatialMention({
        tag: spatialPill.dataset.spatialTag || "",
        body: spatialPill.dataset.spatialBody || "mars",
        key: spatialPill.dataset.spatialKey || "",
        kind: spatialPill.dataset.spatialKind || "geonode",
        parentTag: spatialPill.dataset.spatialParentTag || "",
        label: spatialPill.textContent || spatialPill.title || "",
      });
      return;
    }
    const button = event.target?.closest?.("[data-visual-action]");
    if (!button || !thread.contains(button)) return;
    event.preventDefault();
    event.stopPropagation();
    handleCanvasMessageVisualAction(button.dataset.visualAction || "", button);
  });
  requestAnimationFrame(drawCanvasChatInlineVisuals);
  renderCanvasChapters();
}

function setCanvasChatBusy(busy) {
  alphaCanvasChatBusy = !!busy;
  const visibleBusy = canvasChatBusyInCurrentSession();
  const liveCompute = hasActiveCanvasLiveCompute();
  forgeCanvasChat?.classList.toggle("busy", visibleBusy);
  forgeCanvasChat?.classList.toggle("compute-running", liveCompute);
  if (typeof updateForgeJobsBusyState === "function") updateForgeJobsBusyState();
  if (!alphaCanvasChatBusy) setCanvasChatPendingAssistants([]);
  if (forgeCanvasChatInput) forgeCanvasChatInput.disabled = visibleBusy;
  if (forgeCanvasChatGeminiInput) {
    forgeCanvasChatGeminiInput.disabled = visibleBusy || forgeCanvasChatTargetMode !== "all";
  }
  if (forgeCanvasChatClaudeInput) {
    forgeCanvasChatClaudeInput.disabled = visibleBusy || forgeCanvasChatTargetMode !== "all";
  }
  if (forgeCanvasChatStopBtn) forgeCanvasChatStopBtn.hidden = !(visibleBusy || liveCompute);
  if (forgeCanvasChatSend) forgeCanvasChatSend.hidden = visibleBusy;
  syncCanvasChatSendState();
  syncAlphaDropSurface?.();
}

function autosizeCanvasChatInput() {
  const fields = [forgeCanvasChatInput, forgeCanvasChatGeminiInput, forgeCanvasChatClaudeInput]
    .filter((f) => f && !f.hidden);
  if (!fields.length) return;
  for (const field of fields) field.style.height = "auto";
  // Textarea scrollHeight only reflects the value, never the placeholder. So
  // when the user is idle and the typewriter is filling the placeholder, we
  // briefly swap placeholder→value to measure the real height needed, then
  // restore. This is synchronous: no paint happens between the two
  // assignments, so the user never sees the swap.
  const heights = fields.map((field) => {
    if (field.value) return field.scrollHeight;
    if (!field.placeholder) return field.scrollHeight;
    field.value = field.placeholder;
    const h = field.scrollHeight;
    field.value = "";
    return h;
  });
  const next = Math.min(Math.max(...heights, 22), 220);
  for (const field of fields) field.style.height = `${next}px`;
}

