let canvasChatPlaceholderTimer = null;
let canvasChatPlaceholderRaf = null;
let canvasChatPlaceholderIdx = 0;
let canvasChatPlaceholderCharIdx = 0;
let canvasChatPlaceholderPhase = "typing"; // typing | hold | erasing

// Cadence model: humans don't type at constant speed — short bursts inside
// words, longer pauses around spaces and punctuation. We mirror that here.
function canvasChatTypingDelay(idea, idx) {
  const prev = idx > 1 ? idea[idx - 2] : "";
  const justTyped = idea[idx - 1] || "";
  const base = 18 + Math.random() * 18; // 18–36ms per char baseline
  // Beat after sentence-level punctuation
  if (justTyped === "." || justTyped === ";" || justTyped === ":") {
    return base + 110 + Math.random() * 60;
  }
  if (justTyped === ",") {
    return base + 55 + Math.random() * 40;
  }
  // Tiny beat between words
  if (justTyped === " ") {
    return base + 14 + Math.random() * 22;
  }
  // Lead-in before a capital letter
  const upcoming = idea[idx] || "";
  if (upcoming && upcoming === upcoming.toUpperCase() && /[A-Z]/.test(upcoming) && prev === " ") {
    return base + 12 + Math.random() * 16;
  }
  // Occasional stumble so it isn't perfectly metronomic
  return base + (Math.random() < 0.08 ? 40 + Math.random() * 40 : 0);
}

function canvasChatErasingDelay() {
  // Erasing is much faster than typing — like holding backspace.
  return 5 + Math.random() * 6;
}

/**
 * Returns the currently visible single-provider input. In gemini/claude
 * single mode the codex input is hidden, so the placeholder cycler must
 * write to the visible input — not blindly to forgeCanvasChatInput.
 */
function activeSinglePlaceholderInput() {
  if (forgeCanvasChatTargetMode === "gemini") return forgeCanvasChatGeminiInput;
  if (forgeCanvasChatTargetMode === "claude") return forgeCanvasChatClaudeInput;
  return forgeCanvasChatInput;
}

function canvasChatPlaceholderTick() {
  canvasChatPlaceholderTimer = null;
  canvasChatPlaceholderRaf = null;
  if (forgeCanvasChatTargetMode === "all") {
    canvasChatMultiPlaceholderTick();
    return;
  }
  const target = activeSinglePlaceholderInput();
  if (!target) return;
  // Pause silently if the user is interacting with the visible field.
  if (document.activeElement === target || target.value) {
    return;
  }
  const idea = FORGE_CHAT_PLACEHOLDER_IDEAS[canvasChatPlaceholderIdx];
  let nextDelay = 60;
  if (canvasChatPlaceholderPhase === "typing") {
    canvasChatPlaceholderCharIdx++;
    canvasChatRenderPlaceholder(idea.slice(0, canvasChatPlaceholderCharIdx));
    if (canvasChatPlaceholderCharIdx >= idea.length) {
      canvasChatPlaceholderPhase = "hold";
      nextDelay = 1500;
    } else {
      nextDelay = canvasChatTypingDelay(idea, canvasChatPlaceholderCharIdx);
    }
  } else if (canvasChatPlaceholderPhase === "hold") {
    canvasChatPlaceholderPhase = "erasing";
    nextDelay = 60;
  } else {
    canvasChatPlaceholderCharIdx = Math.max(0, canvasChatPlaceholderCharIdx - 1);
    canvasChatRenderPlaceholder(idea.slice(0, canvasChatPlaceholderCharIdx));
    if (canvasChatPlaceholderCharIdx <= 0) {
      canvasChatPlaceholderPhase = "typing";
      canvasChatPlaceholderIdx = (canvasChatPlaceholderIdx + 1) % FORGE_CHAT_PLACEHOLDER_IDEAS.length;
      nextDelay = 180;
    } else {
      nextDelay = canvasChatErasingDelay();
    }
  }
  canvasChatPlaceholderTimer = setTimeout(canvasChatScheduleFrame, nextDelay);
}

// Sync visual updates with the browser's paint cycle so the placeholder
// repaints exactly once per frame instead of fighting with layout.
function canvasChatScheduleFrame() {
  canvasChatPlaceholderTimer = null;
  if (canvasChatPlaceholderRaf) return;
  canvasChatPlaceholderRaf = requestAnimationFrame(canvasChatPlaceholderTick);
}

function canvasChatRenderPlaceholder(text) {
  const target = activeSinglePlaceholderInput();
  if (!target) return;
  // Clear stale placeholders on the inputs that are not the cycle's
  // current target, so a switch from codex → gemini doesn't leave a
  // half-typed scenario sitting on the codex placeholder.
  for (const input of [forgeCanvasChatInput, forgeCanvasChatGeminiInput, forgeCanvasChatClaudeInput]) {
    if (input && input !== target) input.placeholder = "";
  }
  target.placeholder = text;
  autosizeCanvasChatInput();
}

// Multi-LLM tick: types one scenario across all 3 fields in parallel.
function canvasChatMultiPlaceholderTick() {
  // Pause silently if any of the three fields is being used.
  const fields = [forgeCanvasChatInput, forgeCanvasChatGeminiInput, forgeCanvasChatClaudeInput];
  for (const f of fields) {
    if (!f) continue;
    if (document.activeElement === f || f.value) return;
  }
  const scenario = FORGE_CHAT_PLACEHOLDER_SCENARIOS[
    canvasChatPlaceholderIdx % FORGE_CHAT_PLACEHOLDER_SCENARIOS.length
  ];
  const longest = Math.max(scenario.codex.length, scenario.gemini.length, scenario.claude.length);
  const refIdea = scenario.codex.length >= scenario.gemini.length && scenario.codex.length >= scenario.claude.length
    ? scenario.codex
    : scenario.gemini.length >= scenario.claude.length ? scenario.gemini : scenario.claude;
  let nextDelay = 60;
  const renderAll = () => {
    if (forgeCanvasChatInput) forgeCanvasChatInput.placeholder = scenario.codex.slice(0, canvasChatPlaceholderCharIdx);
    if (forgeCanvasChatGeminiInput) forgeCanvasChatGeminiInput.placeholder = scenario.gemini.slice(0, canvasChatPlaceholderCharIdx);
    if (forgeCanvasChatClaudeInput) forgeCanvasChatClaudeInput.placeholder = scenario.claude.slice(0, canvasChatPlaceholderCharIdx);
    autosizeCanvasChatInput();
  };
  if (canvasChatPlaceholderPhase === "names") {
    // Show "Codex / Gemini / Claude" before the first scenario types in.
    if (forgeCanvasChatInput) forgeCanvasChatInput.placeholder = "Codex";
    if (forgeCanvasChatGeminiInput) forgeCanvasChatGeminiInput.placeholder = "Gemini";
    if (forgeCanvasChatClaudeInput) forgeCanvasChatClaudeInput.placeholder = "Claude";
    autosizeCanvasChatInput();
    canvasChatPlaceholderPhase = "typing";
    canvasChatPlaceholderCharIdx = 0;
    nextDelay = 1500;
  } else if (canvasChatPlaceholderPhase === "typing") {
    canvasChatPlaceholderCharIdx++;
    renderAll();
    if (canvasChatPlaceholderCharIdx >= longest) {
      canvasChatPlaceholderPhase = "hold";
      nextDelay = 1700;
    } else {
      nextDelay = canvasChatTypingDelay(refIdea, Math.min(canvasChatPlaceholderCharIdx, refIdea.length));
    }
  } else if (canvasChatPlaceholderPhase === "hold") {
    canvasChatPlaceholderPhase = "erasing";
    nextDelay = 60;
  } else {
    canvasChatPlaceholderCharIdx = Math.max(0, canvasChatPlaceholderCharIdx - 1);
    renderAll();
    if (canvasChatPlaceholderCharIdx <= 0) {
      // After erasing, briefly show the LLM names again before the next scenario.
      canvasChatPlaceholderPhase = "names";
      canvasChatPlaceholderIdx = (canvasChatPlaceholderIdx + 1) % FORGE_CHAT_PLACEHOLDER_SCENARIOS.length;
      nextDelay = 240;
    } else {
      nextDelay = canvasChatErasingDelay();
    }
  }
  canvasChatPlaceholderTimer = setTimeout(canvasChatScheduleFrame, nextDelay);
}

function startCanvasChatPlaceholderAnimation() {
  if (!forgeCanvasChatInput) return;
  // Don't show prompt suggestions once the user is in conversation.
  if (alphaCanvasChatMessages.length > 0) return;
  if (canvasChatPlaceholderTimer || canvasChatPlaceholderRaf) return;
  // In single mode, only block when the Codex field is in use.
  if (forgeCanvasChatTargetMode !== "all") {
    if (document.activeElement === forgeCanvasChatInput || forgeCanvasChatInput.value) return;
  } else {
    // In multi mode, block if any of the three fields is in use.
    const fields = [forgeCanvasChatInput, forgeCanvasChatGeminiInput, forgeCanvasChatClaudeInput];
    for (const f of fields) {
      if (!f) continue;
      if (document.activeElement === f || f.value) return;
    }
  }
  canvasChatPlaceholderTimer = setTimeout(canvasChatScheduleFrame, 280);
}

function stopCanvasChatPlaceholderAnimation() {
  if (canvasChatPlaceholderTimer) {
    clearTimeout(canvasChatPlaceholderTimer);
    canvasChatPlaceholderTimer = null;
  }
  if (canvasChatPlaceholderRaf) {
    cancelAnimationFrame(canvasChatPlaceholderRaf);
    canvasChatPlaceholderRaf = null;
  }
}

function syncCanvasChatSendState() {
  if (!forgeCanvasChatSend) return;
  const liveCompute = hasActiveCanvasLiveCompute();
  forgeCanvasChat?.classList.toggle("compute-running", liveCompute);
  if (forgeCanvasChatStopBtn) forgeCanvasChatStopBtn.hidden = !(canvasChatBusyInCurrentSession() || liveCompute);
  const hasText = !!currentCanvasChatText();
  const hasAtlasItems = collectChatSlotAtlasItems().length > 0;
  const hasAttachments =
    forgeCanvasChatPendingFiles.length > 0 || forgeCanvasChatPendingPrograms.length > 0;
  if (canvasChatBusyInCurrentSession()) {
    forgeCanvasChatSend.disabled = false;
    forgeCanvasChatSend.classList.add("ready");
    forgeCanvasChatSend.setAttribute("aria-label", "Stop");
    return;
  }
  const ready = hasText || hasAttachments || hasAtlasItems;
  forgeCanvasChatSend.disabled = !ready;
  forgeCanvasChatSend.classList.toggle("ready", ready);
  forgeCanvasChatSend.setAttribute("aria-label", "Send message");
}

function normalizeCanvasAttachmentTarget(target) {
  const value = String(target || "").trim().toLowerCase();
  if (value === "both") return "all";
  return ["codex", "gemini", "claude", "all"].includes(value) ? value : "all";
}

function defaultCanvasAttachmentTarget() {
  return ["codex", "gemini", "claude"].includes(forgeCanvasChatTargetMode)
    ? forgeCanvasChatTargetMode
    : "all";
}

function canvasAttachmentTargetLabel(target) {
  const normalized = normalizeCanvasAttachmentTarget(target);
  if (normalized === "codex") return "Codex";
  if (normalized === "gemini") return "Gemini";
  if (normalized === "claude") return "Claude";
  return "All";
}

function nextCanvasAttachmentTarget(target) {
  const order = ["codex", "gemini", "claude", "all"];
  const idx = order.indexOf(normalizeCanvasAttachmentTarget(target));
  return order[(idx + 1) % order.length];
}

function canvasPendingFileObject(item) {
  return item?.file || item;
}

function canvasPendingFileName(item) {
  return String(canvasPendingFileObject(item)?.name || "").trim();
}

function canvasPendingFileSize(item) {
  return Number(canvasPendingFileObject(item)?.size || 0);
}

function canvasPendingFileTarget(item) {
  return normalizeCanvasAttachmentTarget(item?.target || "all");
}

function canvasPendingProgramTarget(program) {
  return normalizeCanvasAttachmentTarget(program?.target || "all");
}

function canvasAttachmentMatchesRuntime(item, runtime) {
  const target = normalizeCanvasAttachmentTarget(item?.target || "all");
  return target === "all" || target === runtime;
}

function setCanvasChatPendingFileTarget(index, target) {
  const item = forgeCanvasChatPendingFiles[index];
  if (!item) return;
  item.target = normalizeCanvasAttachmentTarget(target);
  renderCanvasChatAttachments();
}

function setCanvasChatPendingProgramTarget(index, target) {
  const item = forgeCanvasChatPendingPrograms[index];
  if (!item) return;
  item.target = normalizeCanvasAttachmentTarget(target);
  renderCanvasChatAttachments();
}

function addCanvasChatPendingProgram(program) {
  if (!program) return;
  const name = String(program.name || program.title || "").trim();
  const hash = String(program.hash || program.programHash || "").trim();
  const lensUrl = String(program.lensUrl || program.lens_url || "").trim();
  const visualMode = String(program.visualMode || program.visual_mode || "").trim();
  if (!name && !hash) return;
  const target = defaultCanvasAttachmentTarget();
  const dup = forgeCanvasChatPendingPrograms.some(
    (p) => ((hash && p.hash === hash) || (!hash && p.name === name)) && canvasPendingProgramTarget(p) === target
  );
  if (dup) return;
  forgeCanvasChatPendingPrograms.push({ name: name || hash, hash, lensUrl, visualMode, target });
  renderCanvasChatAttachments();
  syncCanvasChatSendState();
}

async function loadCanvasChatProgramOptions() {
  const invoke = window.__TAURI__?.core?.invoke;
  if (!invoke) return [];
  try {
    const programs = await invoke("list_forge_programs", { limit: 100 });
    if (Array.isArray(programs) && programs.length) {
      return programs.map((program) => (
        typeof normalizeForgeProgram === "function"
          ? normalizeForgeProgram(program)
          : {
              name: String(program?.title || program?.programHash || "Untitled program"),
              hash: String(program?.programHash || ""),
              desc: String(program?.domain || ""),
            }
      ));
    }
  } catch (err) {
    console.error("list_forge_programs failed", err);
  }
  try {
    const names = await invoke("list_programs");
    return Array.isArray(names) ? names.map((name) => ({ name: String(name), hash: "", desc: "built-in" })) : [];
  } catch (err) {
    console.error("list_programs failed", err);
    return [];
  }
}

function removeCanvasChatPendingProgram(index) {
  if (index < 0 || index >= forgeCanvasChatPendingPrograms.length) return;
  forgeCanvasChatPendingPrograms.splice(index, 1);
  renderCanvasChatAttachments();
  syncCanvasChatSendState();
}

function clearCanvasChatPendingPrograms() {
  if (!forgeCanvasChatPendingPrograms.length) return;
  forgeCanvasChatPendingPrograms.length = 0;
  renderCanvasChatAttachments();
  syncCanvasChatSendState();
}

function formatCanvasChatFileSize(bytes) {
  if (!Number.isFinite(bytes) || bytes <= 0) return "";
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  if (bytes < 1024 * 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  return `${(bytes / (1024 * 1024 * 1024)).toFixed(2)} GB`;
}

function addCanvasChatPendingFiles(fileListLike, options = {}) {
  const incoming = Array.from(fileListLike || []);
  if (!incoming.length) return;
  const target = defaultCanvasAttachmentTarget();
  for (const file of incoming) {
    const dup = forgeCanvasChatPendingFiles.some(
      (item) => {
        const f = canvasPendingFileObject(item);
        return f?.name === file.name
          && f?.size === file.size
          && f?.lastModified === file.lastModified
          && canvasPendingFileTarget(item) === target;
      }
    );
    if (!dup) forgeCanvasChatPendingFiles.push({ file, target });
  }
  try {
    if (!options.skipBoomPreview && typeof window.__forgeBoomPreview3dFiles === "function") {
      void window.__forgeBoomPreview3dFiles(incoming);
    }
  } catch (err) {
    console.warn("[forge] boom 3d preview hook failed:", err);
  }
  renderCanvasChatAttachments();
  syncCanvasChatSendState();
}

function removeCanvasChatPendingFile(index) {
  if (index < 0 || index >= forgeCanvasChatPendingFiles.length) return;
  forgeCanvasChatPendingFiles.splice(index, 1);
  renderCanvasChatAttachments();
  syncCanvasChatSendState();
}

function clearCanvasChatPendingFiles() {
  if (!forgeCanvasChatPendingFiles.length) return;
  forgeCanvasChatPendingFiles.length = 0;
  renderCanvasChatAttachments();
  syncCanvasChatSendState();
}

function renderCanvasChatAttachments() {
  if (!forgeCanvasChatAttachments) return;
  const files = forgeCanvasChatPendingFiles;
  const programs = forgeCanvasChatPendingPrograms;
  if (!files.length && !programs.length) {
    forgeCanvasChatAttachments.hidden = true;
    forgeCanvasChatAttachments.replaceChildren();
    return;
  }
  forgeCanvasChatAttachments.hidden = false;
  const fragment = document.createDocumentFragment();
  const escapeChip = (s) =>
    String(s).replace(/[<>&"']/g, (c) => ({"<":"&lt;",">":"&gt;","&":"&amp;","\"":"&quot;","'":"&#39;"}[c]));
  programs.forEach((program, idx) => {
    const chip = document.createElement("span");
    chip.className = "canvas-chat-chip program";
    const target = canvasPendingProgramTarget(program);
    chip.dataset.target = target;
    chip.title = program.hash
      ? `${program.name} · ${program.hash.slice(0, 12)}… · ${canvasAttachmentTargetLabel(target)}`
      : `${program.name} · ${canvasAttachmentTargetLabel(target)}`;
    chip.innerHTML = `
      <svg class="canvas-chat-chip-icon" viewBox="0 0 16 16" aria-hidden="true">
        <path d="m6 5-3 3 3 3" />
        <path d="m10 5 3 3-3 3" />
      </svg>
      <span class="canvas-chat-chip-name">${escapeChip(program.name)}</span>
      <span class="canvas-chat-chip-size">PROGRAM</span>
    `;
    const targetBtn = document.createElement("button");
    targetBtn.type = "button";
    targetBtn.className = `canvas-chat-chip-target ${target}`;
    targetBtn.textContent = canvasAttachmentTargetLabel(target);
    targetBtn.setAttribute("aria-label", `Assign ${program.name} to ${canvasAttachmentTargetLabel(target)}`);
    targetBtn.title = "Click to assign to Codex, Gemini, Claude, or all";
    targetBtn.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      setCanvasChatPendingProgramTarget(idx, nextCanvasAttachmentTarget(program.target));
    });
    chip.appendChild(targetBtn);
    const remove = document.createElement("button");
    remove.type = "button";
    remove.className = "canvas-chat-chip-remove";
    remove.setAttribute("aria-label", `Remove ${program.name}`);
    remove.innerHTML = `<svg viewBox="0 0 12 12" aria-hidden="true"><path d="m3 3 6 6"/><path d="m9 3-6 6"/></svg>`;
    remove.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      removeCanvasChatPendingProgram(idx);
    });
    chip.appendChild(remove);
    fragment.appendChild(chip);
  });
  files.forEach((item, idx) => {
    const file = canvasPendingFileObject(item);
    if (!file) return;
    const chip = document.createElement("span");
    chip.className = "canvas-chat-chip";
    const target = canvasPendingFileTarget(item);
    chip.dataset.target = target;
    chip.title = `${file.name} · ${canvasAttachmentTargetLabel(target)}`;
    const ext = (file.name.split(".").pop() || "").toLowerCase();
    chip.innerHTML = `
      <svg class="canvas-chat-chip-icon" viewBox="0 0 16 16" aria-hidden="true">
        <path d="M9 2H4a1 1 0 0 0-1 1v10a1 1 0 0 0 1 1h8a1 1 0 0 0 1-1V6Z" />
        <path d="M9 2v4h4" />
      </svg>
      <span class="canvas-chat-chip-name">${file.name.replace(/[<>&"']/g, (c) => ({"<":"&lt;",">":"&gt;","&":"&amp;","\"":"&quot;","'":"&#39;"}[c]))}</span>
      <span class="canvas-chat-chip-size">${ext ? ext.toUpperCase() + " · " : ""}${formatCanvasChatFileSize(file.size)}</span>
    `;
    const targetBtn = document.createElement("button");
    targetBtn.type = "button";
    targetBtn.className = `canvas-chat-chip-target ${target}`;
    targetBtn.textContent = canvasAttachmentTargetLabel(target);
    targetBtn.setAttribute("aria-label", `Assign ${file.name} to ${canvasAttachmentTargetLabel(target)}`);
    targetBtn.title = "Click to assign to Codex, Gemini, Claude, or all";
    targetBtn.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      setCanvasChatPendingFileTarget(idx, nextCanvasAttachmentTarget(item.target));
    });
    chip.appendChild(targetBtn);
    const remove = document.createElement("button");
    remove.type = "button";
    remove.className = "canvas-chat-chip-remove";
    remove.setAttribute("aria-label", `Remove ${file.name}`);
    remove.innerHTML = `<svg viewBox="0 0 12 12" aria-hidden="true"><path d="m3 3 6 6"/><path d="m9 3-6 6"/></svg>`;
    remove.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      removeCanvasChatPendingFile(idx);
    });
    chip.appendChild(remove);
    fragment.appendChild(chip);
  });
  forgeCanvasChatAttachments.replaceChildren(fragment);
}

function canvasAssignedFilesForRuntime(files, runtime) {
  return files.filter((item) => canvasAttachmentMatchesRuntime(item, runtime));
}

function canvasAssignedProgramsForRuntime(programs, runtime) {
  return programs.filter((program) => canvasAttachmentMatchesRuntime(program, runtime));
}

function compactAttachedFileProfile(file) {
  const name = canvasPendingFileName(file) || "attached file";
  const size = Number(canvasPendingFileSize(file) || file?.size || 0);
  const lower = name.toLowerCase();
  const ext = lower.includes(".") ? lower.split(".").pop() : "";
  const type = ext === "csv" ? "csv"
    : ext === "json" ? "json"
    : ext === "pdf" ? "pdf"
    : ext === "txt" ? "text"
    : ext || "unknown";
  const notes = [];
  if (alphaDocState?.fileName && name === alphaDocState.fileName && alphaDocState.candles?.length) {
    notes.push(`2D OHLCV preview loaded: ${alphaDocState.candles.length} bars`);
    notes.push(`visible overlays: EMA 8, EMA 21, EMA 50, VWAP`);
  } else if (type === "csv") {
    notes.push("CSV attached; Forge will profile/parse it locally");
  }
  return `${name} (${type}, ${humanSize(size)})${notes.length ? ` — ${notes.join("; ")}` : ""}`;
}

/**
 * Walks the chat-bar node slots and returns whatever cubes the user has
 * dropped in. Each entry carries the original tag (instrument or node
 * name) and a kind hint so the LLM annotation can describe them.
 */
function collectChatSlotAtlasItems() {
  const root = document.getElementById("forgeCanvasChatNodeSlots");
  if (!root) return [];
  const cubes = root.querySelectorAll(".canvas-chat-nodeslot .my-atlas-cube");
  const items = [];
  for (const cube of cubes) {
    const tag = cube.dataset?.tag || cube.title || cube.textContent?.trim();
    if (!tag) continue;
    const kind = cube.dataset?.kind || "node";
    const formula = cube.dataset?.formula || "";
    const algorithm = cube.dataset?.algorithm || "";
    items.push({ tag: String(tag), kind, formula, algorithm });
  }
  return items;
}

function canvasAttachmentAnnotationForRuntime(runtime, label, files, programs, atlasItems = []) {
  const assignedFiles = canvasAssignedFilesForRuntime(files, runtime);
  const assignedPrograms = canvasAssignedProgramsForRuntime(programs, runtime);
  const parts = [];
  if (assignedFiles.length) {
    parts.push(`Files for ${label}: ${assignedFiles.map(compactAttachedFileProfile).filter(Boolean).join(" | ")}`);
    parts.push("Do not read raw file contents in the LLM. Use Forge session context/tools, compact previews, hashes, manifests, 2D/3D views and local programs if analysis is needed.");
    parts.push("For a newly attached file, answer first in natural language: confirm what file is attached, explain that Forge can create Instruments (compute_program) or Lenses (visual_program) for it, and propose useful Instruments/Lenses to run or create. Do not start or claim a backtest/run unless the user explicitly asked to launch one.");
    parts.push("This is still the same visible chat. Do not restart the conversation or greet again just because a file was attached.");
  }
  if (assignedPrograms.length) {
    parts.push(`Programs for ${label}: ${assignedPrograms.map((p) => p.name).filter(Boolean).join(", ")}`);
  }
  if (Array.isArray(atlasItems) && atlasItems.length) {
    const instruments = atlasItems.filter((it) => it.kind === "program" || it.kind === "instrument");
    const nodes = atlasItems.filter((it) => !(it.kind === "program" || it.kind === "instrument"));
    if (instruments.length) {
      parts.push(`Atlas instruments dropped in chat slots: ${instruments.map((it) => it.tag).join(", ")}`);
    }
    if (nodes.length) {
      parts.push(`Atlas nodes dropped in chat slots: ${nodes.map((it) => it.tag).join(", ")}`);
    }
    parts.push("These atlas items are session attachments — treat them as references the user is asking you to use, combine, evaluate or compose. Look them up via Forge tools (read/run/atlas) instead of guessing their semantics; never assume the user wants them executed unless they say so.");
  }
  if (!parts.length) return "";
  return `[Assigned to ${label} — ${parts.join("; ")}. Ignore items assigned only to the other agent.]`;
}

function compactCanvasPromptText(text, max = 320) {
  const clean = String(text || "").replace(/\s+/g, " ").trim();
  if (!clean) return "";
  if (clean.length <= max) return clean;
  return `${clean.slice(0, Math.max(0, max - 1)).trim()}…`;
}

function canvasMessageIsProgramCritique(text) {
  const normalized = normalizeForLocalIntent(text);
  if (!normalized) return false;
  return normalizedIncludesAny(normalized, [
    "pas assez",
    "plus complet",
    "plus recherche",
    "pas suffisant",
    "trop simple",
    "ca ne va pas",
    "c est pas assez",
    "il faut que le programme",
    "ameliore le programme",
    "retravaille le programme",
    "revise le programme",
    "not enough",
    "more complete",
    "too simple",
    "revise the program",
    "improve the program",
  ]);
}

function compactCanvasConversationContext(currentTurnId = "") {
  const rows = [];
  const visibleMessages = alphaCanvasChatMessages
    .filter((message) => {
      if (!message || message.role === "tool") return false;
      if (String(message.meta?.turnId || "") === currentTurnId) return false;
      return message.role === "user" || message.role === "assistant";
    })
    .slice(-12);
  for (const message of visibleMessages) {
    const label = message.role === "user"
      ? "User"
      : String(message.meta?.agentLabel || "Assistant").trim() || "Assistant";
    const text = compactCanvasPromptText(message.text, message.role === "user" ? 260 : 340);
    if (!text) continue;
    rows.push(`${label}: ${text}`);
  }
  const compactRows = rows.slice(-8);
  if (!compactRows.length) return "";
  return [
    "RECENT_VISIBLE_CHAT_CONTINUITY:",
    ...compactRows,
    "Instruction: continue the same ongoing Forge chat. Do not say hello/bonjour again unless the current user message is itself a greeting.",
  ].join("\n");
}

function compactCanvasFileStateRows() {
  const rows = [];
  const seen = new Set();
  const addFile = (name, size, note = "") => {
    const cleanName = String(name || "").trim();
    if (!cleanName) return;
    const key = cleanName.toLowerCase();
    if (seen.has(key)) return;
    seen.add(key);
    rows.push(`${cleanName}${size ? ` (${humanSize(size)})` : ""}${note ? ` — ${note}` : ""}`);
  };
  for (const file of alphaSessionFiles || []) {
    addFile(file?.name, Number(file?.size || 0), "attached to this Forge session");
  }
  if (alphaDocState?.fileName) {
    const details = [];
    if (alphaDocState.candles?.length) {
      details.push(`${alphaDocState.candles.length} OHLCV bars`);
      details.push("2D view loaded with EMA 8, EMA 21, EMA 50 and VWAP overlays");
    } else if (alphaDocState.previewKind) {
      details.push(`${alphaDocState.previewKind} preview`);
    }
    addFile(alphaDocState.fileName, Number(alphaDocState.fileSize || 0), details.join("; "));
  }
  for (const chart of alphaExtraCharts || []) {
    const note = chart?.candles?.length ? `${chart.candles.length} bars, secondary 2D card` : "secondary visual card";
    addFile(chart?.fileName, Number(chart?.fileSize || 0), note);
  }
  const inputs = typeof selectedForgeInputRefsPayload === "function" ? selectedForgeInputRefsPayload() : [];
  for (const input of inputs.slice(0, 4)) {
    const base = canvasPathBaseName(input?.path || "");
    if (base) addFile(base, 0, `Forge input ref: ${input.role || "data"}`);
  }
  return rows.slice(0, 8);
}

function compactCanvasRunStateRows() {
  const rows = [];
  const job = currentForgeJob?.() || {};
  const manifest = selectedForgeJobManifest || {};
  const jobId = currentAlphaSessionJobId();
  const title = currentProjectLabel?.() || "";
  const status = job?.status || manifest?.status || (jobId ? "active" : "not_started");
  if (jobId || title) {
    rows.push(`session: ${jobId || "pending"} · ${title || "New session"} · status=${status}`);
  }
  const programName =
    manifest.program_name || manifest.programName || manifest.program ||
    manifest.mcp_result?.program_name || job.programName || job.program || "";
  const programHash =
    manifest.program_hash || manifest.programHash || manifest.mcp_result?.program_hash ||
    job.programHash || "";
  if (programName || programHash) {
    rows.push(`compute program/result: ${programName || "program"}${programHash ? ` · hash=${shortHash(programHash)}` : ""}`);
  }
  const mapping = typeof selectedVisualMappingSummary === "function" ? selectedVisualMappingSummary() : null;
  if (mapping?.available) {
    rows.push(`visual program/mapping: ${mapping.kind || "visual_mapping"} · views=${mapping.viewCount || 0} · 3D artifacts=${mapping.artifactCount || 0}${mapping.hash ? ` · hash=${shortHash(mapping.hash)}` : ""}`);
  } else if (alphaDocState?.fileName) {
    rows.push("visual state: default 2D file card is active; 3D can be generated as a visual_program without sending raw rows to the LLM");
  }
  if (alpha3dState?.open || alpha3dState?.mode) {
    rows.push(`3D view: mode=${alpha3dState.mode || "default"} · z=${alpha3dState.zMetric || "auto"} · points=${alpha3dState.pointCount || 0}`);
  }
  const recentToolRows = alphaCanvasChatMessages
    .filter((message) => message?.role === "tool")
    .map((message) => compactCanvasPromptText(message.text, 180))
    .filter((text) => /program|visual|mapping|3d|run|calcul|compute|attach|file/i.test(text))
    .slice(-5);
  for (const line of recentToolRows) rows.push(`recent event: ${line}`);
  return rows.slice(0, 10);
}

function compactCanvasSharedSessionContext() {
  const files = compactCanvasFileStateRows();
  const runs = compactCanvasRunStateRows();
  if (!files.length && !runs.length) return "";
  const lines = [
    "FORGE_SHARED_SESSION_STATE:",
    "This is shared state for whichever LLM is currently selected. Use it for continuity; do not read raw file contents in the LLM.",
  ];
  if (files.length) {
    lines.push("Files/views in current session:");
    for (const file of files) lines.push(`- ${file}`);
  }
  if (runs.length) {
    lines.push("Instruments, Lenses and session events:");
    for (const row of runs) lines.push(`- ${row}`);
  }
  lines.push("When switching LLMs, treat this as the same Forge session and continue from the existing chat, files, views and program results.");
  return lines.join("\n");
}

function canvasPathBaseName(path) {
  return String(path || "").replace(/\\/g, "/").split("/").pop().toLowerCase();
}

function canvasProgramRunInputsForTarget(target, stagedFiles, allInputs) {
  if (!Array.isArray(allInputs) || !allInputs.length) return [];
  const normalizedTarget = normalizeCanvasAttachmentTarget(target);
  if (normalizedTarget === "all") return allInputs;
  const names = stagedFiles
    .filter((item) => canvasAttachmentMatchesRuntime(item, normalizedTarget))
    .map(canvasPendingFileName)
    .filter(Boolean)
    .map((name) => name.toLowerCase());
  if (stagedFiles.length && !names.length) return [];
  if (!names.length) return allInputs;
  const filtered = allInputs.filter((input) => names.includes(canvasPathBaseName(input?.path)));
  return filtered;
}

async function runCanvasAssignedPrograms(stagedPrograms, stagedFiles, activeTargets, turnId, turnSignal, sessionJobId = "") {
  if (!stagedPrograms.length) return;
  const activeRuntimes = new Set((Array.isArray(activeTargets) ? activeTargets : []).map((target) => target.runtime));
  const runnablePrograms = stagedPrograms.filter((program) => {
    const target = canvasPendingProgramTarget(program);
    return target === "all" || activeRuntimes.has(target);
  });
  const skipped = stagedPrograms.length - runnablePrograms.length;
  if (!runnablePrograms.length) {
    appendCanvasChatMessage("tool", "Programs are assigned to an agent that is not active in this turn.", { turnId, sessionJobId });
    return;
  }
  const invokeProgram = window.__TAURI__?.core?.invoke;
  if (!invokeProgram) return;
  const allInputs = (typeof selectedForgeInputRefsPayload === "function") ? selectedForgeInputRefsPayload() : [];
  if (!allInputs.length) {
    appendCanvasChatMessage("tool", "No file references available — programs need session inputs to run.", { turnId, sessionJobId });
    return;
  }
  const runs = runnablePrograms.map(async (program) => {
    const target = canvasPendingProgramTarget(program);
    const targetLabel = canvasAttachmentTargetLabel(target);
    const inputs = canvasProgramRunInputsForTarget(target, stagedFiles, allInputs);
    if (!inputs.length) {
      return {
        ok: false,
        program,
        target,
        targetLabel,
        err: `no file is assigned to ${targetLabel}`,
      };
    }
    try {
      const response = await invokeProgram("run_forge_program", {
        request: {
          programHash: program.hash || null,
          program: program.hash ? null : program.name,
          title: `${program.name || "Forge program"} · ${targetLabel} chat run`,
          inputs,
        },
      });
      const job = response?.data?.job || response?.job || null;
      const jobId = job?.job_id || job?.jobId || "";
      return { ok: true, program, target, targetLabel, jobId };
    } catch (err) {
      return { ok: false, program, target, targetLabel, err };
    }
  });
  const results = await Promise.all(runs);
  if (turnSignal?.aborted) return;
  for (const result of results) {
    if (!result.ok) {
      appendCanvasChatMessage("tool", `Program "${result.program.name}" for ${result.targetLabel} failed to run: ${result.err}`, { turnId, sessionJobId });
      continue;
    }
    if (result.jobId) {
      startCanvasLogFollow?.(result.jobId, turnId, {
        title: result.program.name || "Forge program",
        agentLabel: result.targetLabel,
        runtime: result.target,
      });
      detachCanvasTurnForLiveCompute(turnId);
    }
  }
  await pollForgeJobs?.();
  await refreshSelectedForgeJobManifest?.();
  await refreshSelectedForgeJobLog?.();
  renderForgeJobs?.();
  syncAlphaDropSurface?.();
  scheduleAlphaRender?.();
}

async function sendForgeCanvasChatMessage(event) {
  event?.preventDefault?.();
  const text = redactCanvasSecrets(primaryCanvasChatText());
  const geminiText = forgeCanvasChatTargetMode === "all" ? redactCanvasSecrets(geminiCanvasChatText()) : "";
  const claudeText = forgeCanvasChatTargetMode === "all" ? redactCanvasSecrets(claudeCanvasChatText()) : "";
  const displayText = redactCanvasSecrets(currentCanvasChatText());
  const stagedFiles = forgeCanvasChatPendingFiles.slice();
  const stagedPrograms = forgeCanvasChatPendingPrograms.slice();
  const stagedAtlasItems = collectChatSlotAtlasItems();
  const stagedFileObjects = stagedFiles.map(canvasPendingFileObject).filter(Boolean);
  if (!displayText && !stagedFiles.length && !stagedPrograms.length && !stagedAtlasItems.length) return;
  if (canvasChatBusyInCurrentSession()) return;
  const turnId = `forge-canvas-${Date.now()}-${alphaCanvasChatSeq + 1}`;
  let turnSessionJobId = currentAlphaSessionJobId();
  if (forgeCanvasChatInput) {
    forgeCanvasChatInput.value = "";
  }
  if (forgeCanvasChatGeminiInput) forgeCanvasChatGeminiInput.value = "";
  if (forgeCanvasChatClaudeInput) forgeCanvasChatClaudeInput.value = "";
  autosizeCanvasChatInput();
  syncTradingSlashCommandState();
  if (stagedFiles.length) clearCanvasChatPendingFiles();
  if (stagedPrograms.length) clearCanvasChatPendingPrograms();
  const summaryParts = [];
  if (stagedFiles.length) summaryParts.push(`${stagedFiles.length} file${stagedFiles.length > 1 ? "s" : ""}`);
  if (stagedPrograms.length) summaryParts.push(`${stagedPrograms.length} program${stagedPrograms.length > 1 ? "s" : ""}`);
  if (stagedAtlasItems.length) summaryParts.push(`${stagedAtlasItems.length} atlas item${stagedAtlasItems.length > 1 ? "s" : ""}`);
  const attachedFileNames = stagedFiles.map(canvasPendingFileName).filter(Boolean);
  const attachedProgramNames = stagedPrograms.map((p) => String(p?.name || "").trim()).filter(Boolean);
  const attachmentOnlyText = [
    ...attachedFileNames,
    ...attachedProgramNames.map((name) => `Program: ${name}`),
    ...stagedAtlasItems.map((it) => `${it.kind === "program" || it.kind === "instrument" ? "Instrument" : "Node"}: ${it.tag}`),
  ].join("\n") || `(${summaryParts.join(" + ")} attached)`;
  const userMessageText = displayText || attachmentOnlyText;
  if (isWebExplorerUiActive() && webExplorerLocalMode && /^\s*\/[a-z0-9_-]+/i.test(userMessageText)) {
    webExplorerLocalMode = false;
    syncTradingChatInvolvementControls();
    syncWebExplorerChatModeUi();
  }
  if (isWebExplorerUiActive() && webExplorerLocalMode) {
    syncCanvasChatSendState();
    try {
      await routeWebExplorerLocalCommand(userMessageText);
    } catch (err) {
      console.warn("[webexplorer] local command failed", err);
    }
    scheduleWebExplorerChatFocus();
    syncAlphaDropSurface?.();
    return;
  }
  syncCanvasChatSendState();
  const baseRuntimeTargets = canvasChatRuntimeTargets(text, geminiText, claudeText);
  const runtimeTargets = canvasChatInvolvedRuntimeTargets(baseRuntimeTargets);
  const activeTradingBridge = tradingChatBridge();
  const activeWebBridge = isWebExplorerBridgeActive(activeTradingBridge) ? activeTradingBridge : null;
  const suppressCanvasChatTranscript = !!(activeWebBridge?.isActive?.() && !runtimeTargets.length);
  if (!suppressCanvasChatTranscript) {
    appendCanvasChatMessage("user", userMessageText, {
      turnId,
      sessionJobId: turnSessionJobId || "",
      attachmentOnly: !displayText && stagedFiles.length > 0,
      attachments: stagedFiles.map((f) => ({ name: canvasPendingFileName(f), size: canvasPendingFileSize(f), target: canvasPendingFileTarget(f) })),
      programs: stagedPrograms.map((p) => ({
        name: p.name,
        hash: p.hash,
        lensUrl: p.lensUrl || "",
        visualMode: p.visualMode || "",
        target: canvasPendingProgramTarget(p),
      })),
      atlasItems: stagedAtlasItems.map((it) => ({ tag: it.tag, kind: it.kind, formula: it.formula || "", algorithm: it.algorithm || "" })),
    });
    setAlphaActiveTab("forge");
  }
  if (activeTradingBridge?.isActive?.() && !runtimeTargets.length) {
    const isWebBridge = isWebExplorerBridgeActive(activeTradingBridge);
    const localResult = await activeTradingBridge.routeLocalCommand?.(displayText, {
      turnId,
      sessionJobId: turnSessionJobId || "",
      attachments: stagedFiles.map((f) => ({ name: canvasPendingFileName(f), target: canvasPendingFileTarget(f) })),
      atlasItems: stagedAtlasItems.map((it) => ({ tag: it.tag, kind: it.kind })),
      programs: stagedPrograms.map((p) => ({ name: p.name, target: canvasPendingProgramTarget(p) })),
    });
    if (!isWebBridge) {
      appendCanvasChatMessage("assistant", localResult?.message || "Trading command mode is active. No LLM is currently involved, so Forge handled this locally.", {
        turnId,
        sessionJobId: turnSessionJobId || "",
        agentLabel: "Forge",
        local: true,
        toolEvents: [
          { tool: "trading_command_router", label: localResult?.label || "local trading command" },
        ],
      });
    }
    try { window.__forgeAlphaCanvasBridge?.forceImmediateRender?.(); } catch (_) {}
    syncAlphaDropSurface?.();
    return;
  }
  if (activeTradingBridge?.isActive?.() && /^\s*\/[a-z0-9_-]+/i.test(displayText)) {
    const localResult = await activeTradingBridge.routeLocalCommand?.(displayText, {
      turnId,
      sessionJobId: turnSessionJobId || "",
    });
    try { window.__forgeAlphaCanvasBridge?.forceImmediateRender?.(); } catch (_) {}
    appendCanvasChatMessage("assistant", localResult?.message || "Indicator command applied on the trading chart.", {
      turnId,
      sessionJobId: turnSessionJobId || "",
      agentLabel: "Forge",
      local: true,
      toolEvents: [
        { tool: "trading_indicator_router", label: localResult?.label || "indicator command" },
      ],
    });
    syncAlphaDropSurface?.();
    return;
  }
  const localReply = !stagedFiles.length && !stagedPrograms.length
    ? localCanvasMicroReplyForTurn(text, geminiText, claudeText)
    : "";
  if (localReply) {
    window.setTimeout(() => {
      appendCanvasChatMessage("assistant", localReply, {
        turnId,
        agentLabel: canvasChatTargetLabel(forgeCanvasChatTargetMode),
        local: true,
        toolEvents: [{ tool: "token_usage", label: "0 fresh · local" }],
      });
      syncAlphaDropSurface?.();
    }, localCanvasMicroReplyDelayMs(text));
    syncAlphaDropSurface?.();
    return;
  }
  forgeCanvasChatAbortController = new AbortController();
  const turnSignal = forgeCanvasChatAbortController.signal;
  forgeCanvasChatActiveTurnId = turnId;
  forgeCanvasChatActiveSessionId = turnSessionJobId || "";
  setCanvasChatBusy(true);
  if (stagedFiles.length) {
    try {
      const hasSession = !!currentAlphaSessionJobId() || alphaSessionFiles.length > 0 || !!alphaPendingFile || !!alphaDocState.fileName;
      await alphaHandleFiles(stagedFileObjects, { append: hasSession, jobId: currentAlphaSessionJobId(), skipPlanPreview: true });
      turnSessionJobId = turnSessionJobId || currentAlphaSessionJobId();
      forgeCanvasChatActiveSessionId = turnSessionJobId || forgeCanvasChatActiveSessionId;
      setCanvasChatBusy(true);
      if (turnSignal.aborted) return;
      void refreshSelectedForgeJobManifest?.();
    } catch (err) {
      appendCanvasChatMessage("tool", `Could not attach files: ${err}`, { turnId });
    }
  }
  if (!currentAlphaSessionJobId() && !alphaPendingFile && !alphaSessionFiles.length && !alphaDocState.fileName) {
    try {
      await startAlphaEmptySession();
      turnSessionJobId = currentAlphaSessionJobId();
      forgeCanvasChatActiveSessionId = turnSessionJobId || forgeCanvasChatActiveSessionId;
      setCanvasChatBusy(true);
    } catch (err) {
      appendCanvasChatMessage("assistant", `Could not start the Forge session: ${err}`, { turnId, sessionJobId: turnSessionJobId || "" });
      return;
    }
  }
  turnSessionJobId = turnSessionJobId || currentAlphaSessionJobId();
  forgeCanvasChatActiveSessionId = turnSessionJobId || forgeCanvasChatActiveSessionId;
  await runCanvasAssignedPrograms(stagedPrograms, stagedFiles, runtimeTargets, turnId, turnSignal, turnSessionJobId || "");
  if (turnSignal.aborted) return;
  try {
    const invoke = window.__TAURI__?.core?.invoke;
    if (!invoke) {
      appendCanvasChatMessage(
        "assistant",
        "The canvas chat is ready on the UI side. Open Forge in the Tauri app so I can call the backend broker and talk to the current session."
      );
      return;
    }
    const messageWithAnnotations = (baseText, target) => {
      const currentMessage = redactCanvasSecrets(baseText).trim();
      const annotation = canvasAttachmentAnnotationForRuntime(target.runtime, target.label, stagedFiles, stagedPrograms, stagedAtlasItems);
      const parts = [];
      const isDecisionPoint = lastCanvasAssistantNeedsConfirmation();
      const isProgramCritique = canvasMessageIsProgramCritique(currentMessage);
      const planetVisual = inferPlanetVisualFromText(currentMessage);
      const spatialIntent = inferSpatialAtlasIntentFromText(currentMessage);
      const needsForgeTurnContext = Boolean(annotation || isDecisionPoint || isProgramCritique || planetVisual || spatialIntent);
      const tradingContextPacket = activeTradingBridge?.isActive?.() && activeTradingBridge?.isRuntimeInvolved?.(target.runtime) !== false
        ? String(
          activeTradingBridge?.buildContextEnvelope?.({
            runtime: target.runtime,
            sessionJobId: turnSessionJobId || currentAlphaSessionJobId() || "",
            userMessage: currentMessage,
          })
            || activeTradingBridge?.buildContextDigest?.({ runtime: target.runtime })
            || ""
        ).trim()
        : "";
      if (needsForgeTurnContext) {
        const continuity = compactCanvasConversationContext(turnId);
        if (continuity) parts.push(continuity);
      }
      if (tradingContextPacket) {
        parts.push(tradingContextPacket);
      }
      const webExplorerContextPacket = activeWebBridge?.isActive?.() && activeWebBridge?.isRuntimeInvolved?.(target.runtime) !== false
        ? webExplorerAgentContextPacket()
        : "";
      if (webExplorerContextPacket) {
        parts.push(webExplorerContextPacket);
      }
      if (planetVisual) {
        const labels = Array.isArray(planetVisual.labels) && planetVisual.labels.length
          ? planetVisual.labels.join(", ")
          : "no specific GeoNode mentioned";
        const tags = Array.isArray(planetVisual.geonodes) && planetVisual.geonodes.length
          ? planetVisual.geonodes.join(", ")
          : "none";
        parts.push([
          "CURRENT_TURN_VISUAL_PROGRAM_HINT:",
          "The user message is about Mars or a named Martian location. Treat the inline card as a simple visual_program Lens using tool=planet_sphere body=mars.",
          `Injected Planet Lens URL: ${planetVisual.lensUrl}`,
          `Matched GeoNodes/MiniGeoNodes: ${tags}`,
          `Matched labels: ${labels}`,
          "If the user mentions a specific Martian place that is not in Matched GeoNodes, call forge_atlas_overview first; if absent and you know plausible coordinates, call forge_upsert_geonode with coordinate_source='llm_estimate', confidence, aliases and parent_geonode when it is a sublocation.",
          "This enrichment is not Mars-only: for any planet, moon, asteroid, solar-system place, star system or galaxy object, use forge_upsert_geonode with body and coordinate_system. Use lat/lon for surface anchors and ra/dec/distance for astronomical anchors.",
          "If you answer about a specific matched place, refer to the displayed GeoNode and use Forge Atlas tools for reusable details instead of inventing coordinates.",
        ].join("\n"));
      } else if (spatialIntent) {
        parts.push([
          "CURRENT_TURN_SPATIAL_ATLAS_HINT:",
          "The user message mentions a planet, moon, asteroid, solar-system place, star system or galactic object.",
          "Call forge_atlas_overview first to check whether a matching GeoNode/MiniGeoNode already exists.",
          "If absent and you know plausible coordinates, call forge_upsert_geonode with body, coordinate_system, coordinate_source='llm_estimate', confidence and aliases.",
          "Use lat/lon for planetary or moon surface locations. Use ra/dec and optional distance/distance_unit for astronomical or galactic anchors.",
          "Only surface lat/lon anchors can currently render in the Planet sphere card; ra/dec anchors are still saved to Atlas for future space/galaxy renderers.",
        ].join("\n"));
      }
      if (annotation) {
        const sharedSession = compactCanvasSharedSessionContext();
        if (sharedSession) parts.push(sharedSession);
      }
      if (isProgramCritique) {
        parts.push("CURRENT_TURN_GUARD: The user is critiquing or asking to make the proposed program more complete. Do not create or run a Forge program yet. First revise the design in natural language, explain the richer metrics/modeling plan, and ask for explicit launch confirmation.");
      }
      if (isDecisionPoint) {
        parts.push("CURRENT_TURN_DECISION_POINT: The previous assistant turn asked the user to choose, clarify, or confirm. Interpret the current user message naturally from the visible conversation. If it accepts, confirms, or delegates the choice to you, choose sensible robust defaults for any remaining option and proceed with the next appropriate step. If it rejects, asks for another idea, changes the objective, or adds constraints, do not create/run yet; revise the proposal. Do not ask for another confirmation after a clear acceptance/delegation.");
      }
      if (!parts.length && !annotation) return currentMessage;
      parts.push(currentMessage ? `CURRENT_USER_MESSAGE:\n${currentMessage}` : "CURRENT_USER_ACTION:\nAttached items were sent in the chat.");
      if (annotation) parts.push(annotation);
      return parts.join("\n\n");
    };
    if (turnSignal.aborted) return;
    const targets = runtimeTargets.map((target) => ({
      ...target,
      messageForBroker: messageWithAnnotations(target.text, target),
    }));
    setCanvasChatPendingAssistants(targets);
    const results = await Promise.all(targets.map(async (target) => {
      try {
        const response = await invoke("forge_canvas_assistant_turn", {
          request: {
            message: redactCanvasSecrets(target.messageForBroker),
            jobId: turnSessionJobId || currentAlphaSessionJobId() || null,
            modelRef: target.modelRef,
            reasoningEffort: target.reasoningEffort,
            runtime: target.runtime,
            maxLogLines: 24,
            turnId,
          },
        });
        return { target, response };
      } catch (err) {
        return { target, err };
      }
    }));
    if (canvasTurnDetachedForLiveCompute(turnId)) return;
    if (turnSignal.aborted) return;
    if (forgeCanvasChatActiveTurnId === turnId) setCanvasChatPendingAssistants([]);
    for (const result of results) {
      if (canvasTurnDetachedForLiveCompute(turnId)) return;
      const { target } = result;
      if (result.err) {
        appendCanvasChatMessage("assistant", `Je n'ai pas pu interroger ${target.label}: ${result.err}`, {
          turnId,
          sessionJobId: turnSessionJobId || "",
          agentLabel: target.label,
          toolEvents: [{
            tool: canvasRuntimeToolName(target.runtime),
            status: "unavailable",
          }],
        });
        continue;
      }
      const response = result.response;
      const responseRuntime = canvasResponseRuntime(response, target);
      const responseLabel = canvasChatTargetLabel(responseRuntime);
      if (forgeCanvasChatTargetMode !== "all" && responseRuntime !== target.runtime) {
        const fallbackModel = String(response?.provider?.modelRef || response?.provider?.model_ref || "").trim();
        if (fallbackModel) setCanvasRuntimeModelRef(responseRuntime, fallbackModel);
        setCanvasChatTargetMode(responseRuntime, [responseRuntime]);
      }
      const toolEvents = Array.isArray(response?.toolEvents) ? response.toolEvents.slice() : [];
      if (
        response?.codexBridge?.status &&
        response.codexBridge.status !== "not_attempted" &&
        response.codexBridge.status !== "unavailable"
      ) {
        toolEvents.push({
          tool: canvasRuntimeToolName(responseRuntime),
          transport: response.codexBridge.runtime || responseLabel,
          status: response.codexBridge.status,
        });
      }
      if (response?.codexBridge?.compacted) {
        const generation = Number(response.codexBridge.threadGeneration || 0);
        toolEvents.push({
          tool: "thread_compaction",
          label: generation > 0 ? `Context compacted · gen ${generation}` : "Context compacted",
        });
      }
      const usage = codexBridgeUsageSummary(response?.codexBridge);
      if (usage) {
        toolEvents.push({
          tool: "token_usage",
          label: `${formatCount(usage.fresh)} fresh · ${formatCount(usage.cached)} cached`,
          usage,
        });
      }
      appendCanvasChatMessage("assistant", response?.assistantMessage || `${target.label} a lu le contexte Forge.`, {
        turnId,
        sessionJobId: turnSessionJobId || "",
        agentLabel: responseLabel,
        toolEvents,
        provider: response?.provider || null,
      });
    }
  } catch (err) {
    if (!turnSignal.aborted && !canvasTurnDetachedForLiveCompute(turnId)) {
      appendCanvasChatMessage("assistant", `Could not query the Forge broker: ${err}`, {
        turnId,
        sessionJobId: turnSessionJobId || "",
        agentLabel: forgeCanvasChatTargetMode === "all" ? "Agent" : canvasChatTargetLabel(forgeCanvasChatTargetMode),
      });
    }
  } finally {
    const isCurrentTurn =
      forgeCanvasChatAbortController?.signal === turnSignal || forgeCanvasChatActiveTurnId === turnId;
    if (forgeCanvasChatAbortController?.signal === turnSignal) {
      forgeCanvasChatAbortController = null;
    }
    if (forgeCanvasChatActiveTurnId === turnId) forgeCanvasChatActiveTurnId = "";
    if (forgeCanvasChatActiveTurnId !== turnId && forgeCanvasChatActiveSessionId === turnSessionJobId) {
      forgeCanvasChatActiveSessionId = "";
    }
    if (isCurrentTurn) setCanvasChatBusy(false);
  }
}

function alphaTranscriptIsNearBottom() {
  if (!alphaLogLayer) return true;
  return alphaLogLayer.scrollHeight - alphaLogLayer.scrollTop - alphaLogLayer.clientHeight
    < ALPHA_TRANSCRIPT_BOTTOM_THRESHOLD;
}

function scrollAlphaTranscriptToLive({ smooth = true, force = false } = {}) {
  if (!alphaLogLayer || alphaLogLayer.style.display === "none") return;
  if (force) alphaTranscriptStickToBottom = true;
  // While streaming a long response, calling scrollTo({behavior:"smooth"}) every
  // frame restarts the native smooth animation each tick — that's the friction.
  // Per-frame instant scroll is naturally smooth because content grows by a few
  // chars (a few px) per rAF tick. Smooth is reserved for explicit jumps.
  if (!alphaTranscriptStickToBottom) return;
  if (alphaTranscriptAutoScrollFrame) cancelAnimationFrame(alphaTranscriptAutoScrollFrame);
  alphaTranscriptAutoScrollFrame = requestAnimationFrame(() => {
    alphaTranscriptAutoScrollFrame = 0;
    const target = Math.max(0, alphaLogLayer.scrollHeight - alphaLogLayer.clientHeight);
    const delta = target - alphaLogLayer.scrollTop;
    if (Math.abs(delta) < 2) return;
    alphaTranscriptProgrammaticScrollAt = performance.now();
    // Use native smooth only for explicit jumps (force) over a meaningful gap.
    // Otherwise instant — the typing animation drives the perceived smoothness.
    const useNativeSmooth = smooth && force && delta > 80
      && typeof alphaLogLayer.scrollTo === "function";
    if (useNativeSmooth) {
      alphaLogLayer.scrollTo({ top: target, behavior: "smooth" });
    } else {
      alphaLogLayer.scrollTop = target;
    }
    scheduleAlphaRender();
  });
}

let alphaLogTypingActiveKeys = new Set();

/**
 * Updates only the actively-typing assistant messages in place — no
 * DOM destruction, no flicker on the older messages. Returns true if
 * any message was updated; false if there are no nodes to update.
 *
 * The full structural rebuild path (below) still fires when something
 * other than typing progress changes (new message, pending state, etc).
 * This split is what keeps history truly frozen: once an assistant
 * turn is done typing, its DOM node is left alone until the next
 * structural change.
 */
function updateTypingMessagesInPlace() {
  if (!alphaLogLayer) return false;
  let touched = false;
  for (const message of alphaCanvasChatMessages) {
    if (message.role !== "assistant") continue;
    if (!alphaCanvasTypingStates.has(canvasMessageKey(message))) continue;
    const node = alphaLogLayer.querySelector(
      `.canvas-chat-message[data-message-id="${CSS.escape(String(message.id))}"]`,
    );
    if (!node) continue;
    const textEl = node.querySelector(".canvas-chat-text");
    if (!textEl) continue;
    const caret = textEl.querySelector(".canvas-chat-caret");
    caret?.remove();
    const buildIcon = textEl.querySelector(".canvas-program-build-icon");
    buildIcon?.remove();
    renderCanvasChatTextContent(textEl, canvasAssistantTypedText(message), message);
    if (message.meta?.programBuildKind) {
      const icon = createUiEl("span", "canvas-program-build-icon");
      icon.innerHTML = canvasProgramBuildIconHtml(message.meta.programBuildKind);
      textEl.prepend(icon);
    }
    textEl.appendChild(createUiEl("span", "canvas-chat-caret", ""));
    node.classList.add("typing");
    if (isCanvasSpeakingTarget(message)) {
      node.classList.add("speaking");
    } else {
      node.classList.remove("speaking");
    }
    touched = true;
  }
  return touched;
}

function renderAlphaLogLayer() {
  const structuralKey = [
    alphaLogVersion,
    alphaCanvasChatVersion,
    alphaCanvasPendingVersion,
    selectedForgeJobId,
    selectedForgeJobManifestId,
    alphaVerificationState?.status || "",
    alphaRunState.phase,
    alphaDocState.fileName,
    alphaDocState.fileSize,
    alphaDocState.previewKind,
    (alphaDocState.previewRows || []).length,
    alphaDocState.candles.length,
  ].join(":");
  if (!alphaLogLayer) return;
  // Detect "typing just finished" — a key that was active last frame is
  // no longer active. That transition needs a full rebuild so the caret
  // disappears and the message-actions row (copy/pin/speak) appears.
  const currentTypingKeys = new Set(alphaCanvasTypingStates.keys());
  let typingJustFinished = false;
  for (const k of alphaLogTypingActiveKeys) {
    if (!currentTypingKeys.has(k)) {
      typingJustFinished = true;
      break;
    }
  }
  alphaLogTypingActiveKeys = currentTypingKeys;
  // Fast path: only typing progress changed → update text in place,
  // leave the rest of the DOM (and all completed messages) untouched.
  if (alphaLogRenderedVersion === structuralKey && !typingJustFinished) {
    if (updateTypingMessagesInPlace()) {
      scrollAlphaTranscriptToLive?.({ smooth: false });
    }
    return;
  }
  const selection = window.getSelection();
  if (
    selection &&
    !selection.isCollapsed &&
    (alphaLogLayer.contains(selection.anchorNode) || alphaLogLayer.contains(selection.focusNode))
  ) {
    return;
  }
  alphaLogRenderedVersion = structuralKey;
  alphaLogLayer.innerHTML = "";

  const job = currentForgeJob();
  const manifest = selectedForgeJobManifest || {};
  const durationMs = selectedJobDurationMs(job, manifest);
  const frag = document.createDocumentFragment();

  const transcript = createUiEl("div", "compute-transcript");
  const status = String(job?.status || manifest.status || alphaRunState.phase || "idle").toLowerCase();
  const narrative = computeNarrative(alphaForgeLogs, manifest);
  const visibleGroups = groupedVisibleLogs(alphaForgeLogs);
  const computeStarted = hasAlphaComputeStarted(status, visibleGroups);

  renderCanvasChatMessages(transcript);

  const isFinalStatus = ["completed", "done", "failed", "error", "aborted", "cancelled", "canceled"]
    .includes(status);
  if (isFinalStatus) {
    const footer = createUiEl("div", "transcript-footer");
    const proofButton = createUiEl("button", "compute-proof-icon-action");
    proofButton.type = "button";
    proofButton.dataset.computeAction = "open-proof";
    proofButton.setAttribute("aria-label", "Open verification");
    proofButton.title = "Open verification";
    proofButton.innerHTML = `
      <svg viewBox="0 0 24 24" focusable="false" aria-hidden="true">
        <path d="M12 3.75 18.5 6v5.4c0 4.15-2.55 7.2-6.5 8.85-3.95-1.65-6.5-4.7-6.5-8.85V6L12 3.75Z" />
        <path d="m9 12 2 2 4-4" />
      </svg>
    `;
    footer.appendChild(proofButton);
    transcript.appendChild(footer);
  }

  frag.appendChild(transcript);
  alphaLogLayer.appendChild(frag);
  const shouldFollowLive = status === "running" || alphaRunning || alphaCanvasChatMessages.length > 0;
  if (shouldFollowLive) {
    scrollAlphaTranscriptToLive({ smooth: true });
  } else {
    alphaLogLayer.scrollTop = 0;
  }
}

function getAlphaChartStaticBounds() {
  const W = alphaCanvas.clientWidth;
  const H = alphaCanvas.clientHeight;
  const layout = alphaChartLayoutPreset();
  const marginX = layout.outerMarginX;
  const hasChatOverlay = alphaCanvasChatMessages.length > 0;
  const hasVisualCard = hasAlphaVisualCard();
  const tradingSurface = isTradingPanelActive();
  if (tradingSurface) {
    if (alphaSplitViewEnabled && W >= 980) {
      const leftGutter = Math.max(350, Math.floor(W * 0.405));
      const right = Math.max(20, Math.floor(W * 0.022));
      const top = hasChatOverlay
        ? Math.max(16, Math.floor(H * 0.024))
        : Math.max(layout.topOffset, Math.floor(H * 0.028));
      const bottomReserve = Math.max(110, Math.floor(H * 0.12));
      return {
        x: leftGutter,
        y: top,
        w: Math.max(320, W - leftGutter - right),
        h: Math.max(320, H - top - bottomReserve),
      };
    }
    const top = hasChatOverlay
      ? Math.max(14, Math.floor(H * 0.018))
      : Math.max(layout.topOffset, Math.floor(H * 0.022));
    const bottomReserve = hasChatOverlay
      ? Math.max(150, Math.floor(H * 0.20))
      : Math.max(108, Math.floor(H * 0.115));
    return {
      x: marginX,
      y: top,
      w: Math.max(280, W - marginX * 2),
      h: Math.max(320, H - top - bottomReserve),
    };
  }
  if (alphaSplitViewEnabled && hasChatOverlay && hasVisualCard && W >= 880) {
    const x = Math.max(360, Math.floor(W * 0.38));
    const right = Math.max(24, Math.floor(W * 0.025));
    const y = Math.max(42, Math.floor(H * 0.06));
    return {
      x,
      y,
      w: Math.max(340, W - x - right),
      h: Math.min(Math.max(340, H - y - 118), Math.max(360, Math.floor(H * 0.72))),
    };
  }
  if (hasChatOverlay && hasVisualCard && W >= 760) {
    const top = Math.max(48, Math.floor(H * 0.06));
    const right = Math.max(24, Math.floor(W * 0.025));
    const bottomReserve = Math.max(148, Math.floor(H * 0.19));
    const w = Math.min(Math.max(760, Math.floor(W * 0.76)), W - marginX - right);
    const h = Math.min(Math.max(420, Math.floor(H * 0.68)), H - top - bottomReserve);
    return {
      x: Math.max(marginX, Math.floor((W - w) * 0.5)),
      y: top,
      w,
      h,
    };
  }
  const top = Math.max(layout.topOffset, Math.floor(H * 0.07));
  const bottomReserve = Math.max(136, Math.floor(H * 0.16));
  return {
    x: marginX,
    y: top,
    w: Math.max(280, W - marginX * 2),
    h: Math.min(Math.max(420, Math.floor(H * 0.74)), H - top - bottomReserve),
  };
}

function getAlphaChartBounds() {
  const b = getAlphaChartStaticBounds();
  const hasVisualCard = hasAlphaVisualCard();
  if (!hasVisualCard) {
    b.y -= alphaTranscriptScrollOffset();
  }
  return b;
}

function getAlphaChartPlotBounds() {
  return alphaChartPlotRect(getAlphaChartBounds());
}

function alphaTradingSplitChartDocs() {
  if (!isTradingPanelActive() || alphaExtraChartLayout !== "split") return [];
  const secondary = Array.isArray(alphaExtraCharts)
    ? alphaExtraCharts.filter((chart) => Array.isArray(chart?.candles) && chart.candles.length).slice(0, 3)
    : [];
  return secondary.length ? [alphaDocState, ...secondary] : [];
}

function alphaTradingSplitChartBounds(fullBounds, count = 2) {
  const chartCount = Math.max(1, Math.min(4, Number(count) || 1));
  const gap = 14;
  if (chartCount === 1) return [fullBounds];
  const columns = chartCount === 2 && fullBounds.w < 760 ? 1 : Math.min(2, chartCount);
  const rows = Math.ceil(chartCount / columns);
  const cellW = Math.max(180, Math.floor((fullBounds.w - gap * (columns - 1)) / columns));
  const cellH = Math.max(150, Math.floor((fullBounds.h - gap * (rows - 1)) / rows));
  const out = [];
  for (let index = 0; index < chartCount; index += 1) {
    const col = index % columns;
    const row = Math.floor(index / columns);
    const x = fullBounds.x + col * (cellW + gap);
    const y = fullBounds.y + row * (cellH + gap);
    out.push({
      x,
      y,
      w: col === columns - 1 ? Math.max(180, fullBounds.x + fullBounds.w - x) : cellW,
      h: row === rows - 1 ? Math.max(150, fullBounds.y + fullBounds.h - y) : cellH,
    });
  }
  return out;
}

function alphaTradingSplitChartBrokerLabel(doc) {
  return String(
    doc?.brokerLabel
    || alphaTradingHeaderState.brokerLabel
    || tradingBrokerDisplayName(activeTradingBroker)
    || "Broker",
  ).trim() || "Broker";
}

function alphaTradingSplitChartBrokerLogoKind(doc) {
  return String(doc?.brokerLogoKind || alphaTradingHeaderState.brokerLogoKind || "").trim().toLowerCase();
}

function alphaTradingSplitChartInstrumentLabel(doc) {
  return String(
    doc?.instrumentLabel
    || doc?.tradingInstrument
    || doc?.instrument
    || doc?.displayName
    || alphaTradingHeaderState.instrumentLabel
    || "Instrument",
  ).trim() || "Instrument";
}

function alphaTradingSplitChartGranularity(doc) {
  return String(
    doc?.tradingGranularity
    || alphaDocState?.tradingGranularity
    || "H4",
  ).trim().toUpperCase();
}

function alphaTradingSplitTopbarRoot() {
  const topbar = document.querySelector("#alphaSection .canvas-topbar") || document.querySelector(".canvas-topbar");
  if (!topbar) return null;
  let root = topbar.querySelector(".trading-split-topbar-mirror");
  if (!root) {
    root = document.createElement("div");
    root.className = "trading-split-topbar-mirror";
    root.hidden = true;
    topbar.appendChild(root);
  }
  return root;
}

function alphaTradingSplitTopbarCell(doc, bounds, index = 0) {
  const cell = document.createElement("div");
  cell.className = "trading-split-topbar-cell";
  cell.style.left = `${Math.round(bounds.x)}px`;
  cell.style.width = `${Math.max(120, Math.round(bounds.w))}px`;
  cell.dataset.tradingSplitIndex = String(index);

  const main = document.createElement("div");
  main.className = "trading-split-topbar-main";

  const brokerButton = document.createElement("button");
  brokerButton.type = "button";
  brokerButton.className = "trading-split-topbar-broker-button";
  brokerButton.dataset.tradingSplitAction = "broker";
  brokerButton.dataset.tradingSplitIndex = String(index);
  brokerButton.title = "Broker";
  const mark = document.createElement("span");
  mark.className = `trading-split-topbar-broker-mark${alphaTradingSplitChartBrokerLogoKind(doc) ? " is-branded" : ""}`;
  mark.setAttribute("aria-hidden", "true");
  brokerButton.appendChild(mark);
  const broker = document.createElement("span");
  broker.className = "trading-split-topbar-broker";
  broker.textContent = alphaTradingSplitChartBrokerLabel(doc);
  brokerButton.appendChild(broker);
  main.appendChild(brokerButton);

  const slash = document.createElement("span");
  slash.className = "trading-split-topbar-slash";
  slash.textContent = "/";
  main.appendChild(slash);

  const assetButton = document.createElement("button");
  assetButton.type = "button";
  assetButton.className = "trading-split-topbar-asset";
  assetButton.dataset.tradingSplitAction = "asset";
  assetButton.dataset.tradingSplitIndex = String(index);
  assetButton.dataset.tradingInstrument = String(doc?.tradingInstrument || doc?.instrument || "");
  assetButton.title = "Asset";
  const asset = document.createElement("span");
  asset.className = "trading-split-topbar-asset-label";
  asset.textContent = alphaTradingSplitChartInstrumentLabel(doc);
  assetButton.appendChild(asset);
  main.appendChild(assetButton);

  const compare = document.createElement("button");
  compare.type = "button";
  compare.className = "trading-split-topbar-action";
  compare.dataset.tradingSplitAction = "compare";
  compare.dataset.tradingSplitIndex = String(index);
  compare.textContent = alphaTradingHeaderState.compareLabel || "compare_";
  main.appendChild(compare);

  const add = document.createElement("button");
  add.type = "button";
  add.className = "trading-split-topbar-action add";
  add.dataset.tradingSplitAction = "add";
  add.dataset.tradingSplitIndex = String(index);
  add.textContent = alphaTradingHeaderState.addLabel || "add_";
  main.appendChild(add);
  cell.appendChild(main);

  const granularity = alphaTradingSplitChartGranularity(doc);
  const frames = document.createElement("div");
  frames.className = "trading-split-topbar-timeframes";
  for (const item of ALPHA_TRADING_SPLIT_TIMEFRAMES) {
    const frame = document.createElement("button");
    frame.type = "button";
    frame.className = "trading-split-topbar-timeframe";
    frame.dataset.tradingSplitAction = "timeframe";
    frame.dataset.tradingSplitIndex = String(index);
    frame.dataset.tradingGranularity = item.value;
    if (item.value === granularity || item.label === granularity || (granularity === "W1" && item.value === "W")) {
      frame.classList.add("is-active");
    }
    frame.textContent = item.label;
    frames.appendChild(frame);
  }
  cell.appendChild(frames);
  return cell;
}

function syncAlphaTradingSplitTopbar(fullBounds = null, docsOverride = null) {
  const root = alphaTradingSplitTopbarRoot();
  if (!root) return;
  const docs = Array.isArray(docsOverride) ? docsOverride : alphaTradingSplitChartDocs();
  const active = isTradingPanelActive()
    && alphaExtraChartLayout === "split"
    && docs.length > 1
    && fullBounds
    && Number(fullBounds.w) > 0;
  if (!active) {
    alphaTradingSplitTopbarKey = "";
    root.hidden = true;
    root.replaceChildren();
    alphaCanvasWrap?.classList.remove("has-trading-split-topbar");
    return;
  }
  const bounds = alphaTradingSplitChartBounds(fullBounds, docs.length);
  const topY = bounds[0]?.y ?? fullBounds.y;
  const cells = docs
    .map((doc, index) => ({ doc, index, bounds: bounds[index] || fullBounds }))
    .filter((entry) => entry.index > 0 && Math.abs((entry.bounds?.y ?? topY) - topY) < 2);
  if (!cells.length) {
    alphaTradingSplitTopbarKey = "";
    root.hidden = true;
    root.replaceChildren();
    alphaCanvasWrap?.classList.remove("has-trading-split-topbar");
    return;
  }
  const key = JSON.stringify(cells.map((entry) => ({
    x: Math.round(entry.bounds.x),
    w: Math.round(entry.bounds.w),
    broker: alphaTradingSplitChartBrokerLabel(entry.doc),
    logo: alphaTradingSplitChartBrokerLogoKind(entry.doc),
    instrument: alphaTradingSplitChartInstrumentLabel(entry.doc),
    granularity: alphaTradingSplitChartGranularity(entry.doc),
    compare: alphaTradingHeaderState.compareLabel || "compare_",
    add: alphaTradingHeaderState.addLabel || "add_",
  })));
  if (alphaTradingSplitTopbarKey !== key) {
    alphaTradingSplitTopbarKey = key;
    root.replaceChildren(...cells.map((entry) => alphaTradingSplitTopbarCell(entry.doc, entry.bounds, entry.index)));
  }
  root.hidden = false;
  alphaCanvasWrap?.classList.add("has-trading-split-topbar");
}

function alphaTradingChartBoundsAtCanvasPoint(x, y) {
  const docs = alphaTradingSplitChartDocs();
  const fullBounds = getAlphaChartBounds();
  if (docs.length < 2) return fullBounds;
  const bounds = alphaTradingSplitChartBounds(fullBounds, docs.length);
  return bounds.find((part) =>
    x >= part.x && x <= (part.x + part.w) && y >= part.y && y <= (part.y + part.h)
  ) || fullBounds;
}

function drawAlphaTradingSplitCharts(time, fullBounds) {
  const docs = alphaTradingSplitChartDocs();
  if (docs.length < 2) return false;
  const bounds = alphaTradingSplitChartBounds(fullBounds, docs.length);
  for (let index = 0; index < docs.length; index += 1) {
    const doc = docs[index];
    const cardBounds = bounds[index] || fullBounds;
    const viewportSnapshot = doc === alphaDocState ? null : { ...alphaTradingViewport };
    if (viewportSnapshot) {
      alphaTradingViewport.initialized = false;
      alphaTradingViewportEnsure(doc, { forceFit: true });
    } else {
      alphaTradingViewportEnsure(doc);
    }
    drawAlphaCandles(time, cardBounds, false, doc, {
      showIndicators: true,
      showSignals: false,
    });
    if (viewportSnapshot) Object.assign(alphaTradingViewport, viewportSnapshot);
  }
  alphaCtx.save();
  alphaCtx.strokeStyle = "rgba(255,255,255,0.05)";
  alphaCtx.lineWidth = 1;
  const splitXs = [...new Set(bounds.filter((part) => part.x > fullBounds.x).map((part) => Math.round(part.x - 7)))];
  for (const x of splitXs) {
    alphaCtx.beginPath();
    alphaCtx.moveTo(x, fullBounds.y);
    alphaCtx.lineTo(x, fullBounds.y + fullBounds.h);
    alphaCtx.stroke();
  }
  const splitYs = [...new Set(bounds.filter((part) => part.y > fullBounds.y).map((part) => Math.round(part.y - 7)))];
  for (const y of splitYs) {
    alphaCtx.beginPath();
    alphaCtx.moveTo(fullBounds.x, y);
    alphaCtx.lineTo(fullBounds.x + fullBounds.w, y);
    alphaCtx.stroke();
  }
  alphaCtx.restore();
  return true;
}

function getAlphaChartInteractionZones(bounds = getAlphaChartBounds()) {
  const card = bounds;
  const tradingSurface = isTradingPanelActive();
  const priceAxisWidth = tradingSurface
    ? Math.max(64, Math.min(92, Math.round(card.w * 0.075)))
    : Math.max(20, Math.round(card.w * 0.07));
  const priceAxisOnLeft = tradingSurface && alphaTradingScalePrefs.priceAxisSide === "left";
  const pricePanelActive = tradingSurface && (
    alphaTradingDockPanelModeUsesPriceRail(alphaTradingDockPanel.mode)
    || alphaTradingDockPanelModeUsesPriceRail(alphaTradingDockPanel.visualMode)
    || alphaTradingDockPanelModeUsesPriceRail(alphaTradingDockPanel.previousMode)
  );
  const timePanelActive = tradingSurface && (
    alphaTradingDockPanelModeUsesTimeRail(alphaTradingDockPanel.mode)
    || alphaTradingDockPanelModeUsesTimeRail(alphaTradingDockPanel.visualMode)
    || alphaTradingDockPanelModeUsesTimeRail(alphaTradingDockPanel.previousMode)
  );
  const priceExpandedWidth = Math.max(ALPHA_TRADING_DOCK_PRICE_PANEL_MIN_WIDTH, Math.min(320, Math.round(card.w * 0.24)));
  const priceReserveWidth = tradingSurface
    ? (pricePanelActive
      ? Math.round(priceAxisWidth + (priceExpandedWidth - priceAxisWidth) * alphaTradingDockPanel.openProgress)
      : priceAxisWidth)
    : priceAxisWidth;
  const timeAxisHeight = tradingSurface ? 22 : 0;
  const timeVisualMode = alphaTradingDockPanel.visualMode === "none" ? "time-axis" : alphaTradingDockPanel.visualMode;
  const timePreviousMode = alphaTradingDockPanel.previousMode === "none" ? timeVisualMode : alphaTradingDockPanel.previousMode;
  const timeExpandedHeight = alphaTradingDockTimePanelExpandedHeight(card.h, timeVisualMode);
  const timePreviousHeight = alphaTradingDockTimePanelExpandedHeight(card.h, timePreviousMode);
  const timeContentHeight = Math.round(timePreviousHeight + (timeExpandedHeight - timePreviousHeight) * alphaTradingDockPanel.contentProgress);
  const timePanelHeight = tradingSurface
    ? (timePanelActive
      ? Math.round(timeContentHeight * alphaTradingDockPanel.openProgress)
      : 0)
    : 0;
  const topReserve = tradingSurface
    ? (timePanelHeight + timeAxisHeight)
    : 0;
  const plot = tradingSurface
    ? {
      left: priceAxisOnLeft ? (card.x + priceReserveWidth + 2) : (card.x + 2),
      top: card.y + Math.max(alphaChartLayoutPreset().headerHeight, topReserve),
      right: priceAxisOnLeft ? (card.x + card.w - 2) : (card.x + card.w - priceReserveWidth),
      bottom: card.y + card.h - alphaChartLayoutPreset().bottomAxisHeight,
      width: Math.max(50, (priceAxisOnLeft ? (card.x + card.w - 2) : (card.x + card.w - priceReserveWidth)) - (priceAxisOnLeft ? (card.x + priceReserveWidth + 2) : (card.x + 2))),
      height: Math.max(50, card.y + card.h - alphaChartLayoutPreset().bottomAxisHeight - (card.y + Math.max(alphaChartLayoutPreset().headerHeight, topReserve))),
    }
    : alphaChartPlotRect(card);
  const priceAxis = tradingSurface
    ? {
      left: priceAxisOnLeft
        ? (pricePanelActive ? (card.x + priceReserveWidth - priceAxisWidth) : card.x)
        : (pricePanelActive ? (card.x + card.w - priceReserveWidth) : (card.x + card.w - priceAxisWidth)),
      right: priceAxisOnLeft
        ? (pricePanelActive ? (card.x + priceReserveWidth) : (card.x + priceAxisWidth))
        : (pricePanelActive ? (card.x + card.w - priceReserveWidth + priceAxisWidth) : (card.x + card.w)),
      top: Math.max(0, card.y - 4),
      bottom: plot.bottom,
    }
    : {
      left: plot.right,
      right: card.x + card.w,
      top: plot.top,
      bottom: plot.bottom,
    };
  const timeAxis = tradingSurface
    ? {
      left: plot.left,
      right: plot.right,
      top: plot.top - timeAxisHeight,
      bottom: plot.top,
    }
    : {
      left: card.x,
      right: plot.right,
      top: card.y,
      bottom: plot.top,
    };
  const pricePanel = tradingSurface && pricePanelActive
    ? (priceAxisOnLeft
      ? {
        left: card.x,
        right: priceAxis.left,
        top: card.y + 6,
        bottom: plot.bottom,
      }
      : {
        left: priceAxis.right,
        right: card.x + card.w,
        top: card.y + 6,
        bottom: plot.bottom,
      })
    : null;
  const timePanel = tradingSurface && timePanelActive
    ? {
      left: plot.left,
      right: plot.right,
      top: card.y,
      bottom: timeAxis.top,
    }
    : null;
  return { card, plot, priceAxis, timeAxis, pricePanel, timePanel };
}

function scheduleAlphaRender(options = {}) {
  if (options.force) alphaRenderFailed = false;
  if (alphaRenderFailed) return;
  if (alphaRenderQueued) return;
  alphaRenderQueued = true;
  requestAnimationFrame(renderAlpha);
}

function renderAlpha(time) {
  alphaRenderQueued = false;
  try {
    if (!alphaSection.hidden) {
      if ((alphaWidth === 0 || alphaHeight === 0) && !resizeAlphaCanvas()) {
        scheduleAlphaResizeRecovery(90);
        return;
      }
      const interactionActive = alphaDragging || alphaPriceScaleDragging || alphaTimeScaleDragging;
      alphaTradingDockPanelTick(time);
      updateAlphaTokenSavings();
      drawAlphaUnified(time);
      if (!interactionActive) renderAlphaProofPanel();
    }
  } catch (err) {
    alphaRunState.phase = "error";
    if (!alphaRenderFailed) {
      alphaRenderFailed = true;
      alphaForgeLogs.push(`ALPHA UI ERROR: ${err}`);
      trimArrayInPlace(alphaForgeLogs, ALPHA_MAX_FORGE_LOGS);
      alphaLogVersion += 1;
      console.error("Alpha render failed", err);
    }
    return;
  }
  if (alphaRunning || alphaDragging || alphaTradingDockPanelAnimating()) {
    scheduleAlphaRender();
  }
}

function snapshotAlphaCanvasState() {
  return {
    activeTab: alphaActiveTab,
    doc: JSON.parse(JSON.stringify(alphaDocState)),
    extraCharts: JSON.parse(JSON.stringify(alphaExtraCharts)),
    tradingViewport: JSON.parse(JSON.stringify(alphaTradingViewport)),
    tradingTimePrefs: JSON.parse(JSON.stringify(alphaTradingTimePrefs)),
    tradingScalePrefs: JSON.parse(JSON.stringify(alphaTradingScalePrefs)),
    tradingAxisMetricPrefs: JSON.parse(JSON.stringify(alphaTradingAxisMetricPrefs)),
    tradingMetricSpacePrefs: JSON.parse(JSON.stringify(alphaTradingMetricSpacePrefs)),
    tradingCrosshair: JSON.parse(JSON.stringify(alphaTradingCrosshair)),
    is3dOpen: !!alpha3dState?.open,
    rightPanelOpen: !!alphaProofPanelOpen,
    rightPanelMode: alphaRightPanelMode,
  };
}

function restoreAlphaCanvasState(snapshot) {
  if (!snapshot || typeof snapshot !== "object") return;
  const doc = snapshot.doc || {};
  alphaDocState.candles = Array.isArray(doc.candles) ? doc.candles : [];
  alphaDocState.logicalBars = alphaBuildLogicalBars(alphaDocState.candles);
  alphaDocState.candleViewCount = Number(doc.candleViewCount) || Math.min(200, alphaDocState.candles.length || 200);
  alphaDocState.candleViewEnd = Number(doc.candleViewEnd);
  if (!Number.isFinite(alphaDocState.candleViewEnd)) {
    alphaDocState.candleViewEnd = Math.max(0, alphaDocState.candles.length - 1);
  }
  alphaDocState.candleHover = Number.isFinite(Number(doc.candleHover)) ? Number(doc.candleHover) : -1;
  alphaDocState.chartDisplayMode = alphaNormalizeChartDisplayMode(doc.chartDisplayMode);
  alphaDocState.priceZoom = alphaClampPriceZoom(doc.priceZoom);
  alphaDocState.pricePan = Number.isFinite(Number(doc.pricePan)) ? Number(doc.pricePan) : 0;
  alphaDocState.fileName = String(doc.fileName || "");
  alphaDocState.fileSize = Number(doc.fileSize) || 0;
  alphaDocState.previewKind = String(doc.previewKind || "");
  alphaDocState.previewRows = Array.isArray(doc.previewRows) ? doc.previewRows : [];
  alphaDocState.tradingInstrument = String(doc.tradingInstrument || "");
  alphaDocState.tradingGranularity = String(doc.tradingGranularity || "").toUpperCase();
  alphaExtraCharts = Array.isArray(snapshot.extraCharts) ? snapshot.extraCharts : [];
  const tradingViewport = snapshot.tradingViewport || {};
  alphaTradingViewport.visibleBars = Math.max(20, Math.min(2000, Number(tradingViewport.visibleBars) || alphaTradingViewport.visibleBars));
  alphaTradingViewport.timeEndMs = Number.isFinite(Number(tradingViewport.timeEndMs)) ? Number(tradingViewport.timeEndMs) : alphaTradingViewport.timeEndMs;
  alphaTradingViewport.timeStepMs = Math.max(1000, Number(tradingViewport.timeStepMs) || alphaTradingViewport.timeStepMs);
  alphaTradingViewport.priceMin = Number.isFinite(Number(tradingViewport.priceMin)) ? Number(tradingViewport.priceMin) : alphaTradingViewport.priceMin;
  alphaTradingViewport.priceMax = Number.isFinite(Number(tradingViewport.priceMax)) ? Number(tradingViewport.priceMax) : alphaTradingViewport.priceMax;
  alphaTradingViewport.initialized = !!tradingViewport.initialized;
  if (alphaDocState.candles.length) recomputeIndicators(alphaDocState.candles);
  if (snapshot.activeTab === "forge" || snapshot.activeTab === "results") {
    setAlphaActiveTab(snapshot.activeTab);
  } else {
    scheduleAlphaRender();
  }
  syncAlphaDropSurface();
  if (typeof snapshot.rightPanelMode === "string") {
    setAlphaRightPanelMode(snapshot.rightPanelMode, { skipRender: true });
  }
  if (typeof snapshot.rightPanelOpen === "boolean") {
    setAlphaProofPanelOpen(snapshot.rightPanelOpen);
  }
}

function alphaNormalizeCanvasCandles(entries) {
  if (!Array.isArray(entries)) return [];
  return entries.map((item) => ({
    time: new Date(Number(item?.time) || Date.parse(item?.time || "") || Date.now()).toISOString(),
    open: Number(item?.open) || 0,
    high: Number(item?.high) || 0,
    low: Number(item?.low) || 0,
    close: Number(item?.close) || 0,
    volume: Number(item?.volume || 0),
  }));
}

function alphaBuildLogicalBars(candles) {
  if (!Array.isArray(candles)) return [];
  return candles
    .map((candle, index) => ({
      index,
      timeMs: alphaCoerceTimeMs(candle?.time, Date.now()),
      candle,
    }))
    .filter((entry) => Number.isFinite(entry.timeMs));
}

function setAlphaCanvasDocument(payload = {}) {
  const candles = alphaNormalizeCanvasCandles(payload.candles);
  const nextFileName = String(payload.fileName || "");
  const tradingSurface = isTradingPanelActive();
  const preserveViewport = payload.preserveViewport === true
    || (
      payload.preserveViewport !== false
      && tradingSurface
      && !!nextFileName
      && nextFileName === alphaDocState.fileName
      && Array.isArray(alphaDocState.candles)
      && alphaDocState.candles.length > 0
    );
  const previousCount = Number(alphaDocState.candleViewCount) || 200;
  const previousEnd = Number(alphaDocState.candleViewEnd);
  const previousZoom = alphaDocPriceZoom(alphaDocState);
  const previousPan = Number(alphaDocState.pricePan || 0);
  const previousTradingInstrument = String(alphaDocState.tradingInstrument || "").trim();
  const previousTradingGranularity = String(alphaDocState.tradingGranularity || "").trim().toUpperCase();
  const nextTradingInstrument = String(payload.tradingInstrument || "").trim();
  const nextTradingGranularity = String(payload.tradingGranularity || "").trim().toUpperCase();
  const previousExtraCharts = alphaExtraCharts;
  const previousExtraChartLayout = alphaExtraChartLayout;
  const preserveExtraCharts = tradingSurface
    && previousExtraChartLayout === "split"
    && Array.isArray(previousExtraCharts)
    && previousExtraCharts.length > 0
    && previousTradingInstrument === nextTradingInstrument
    && previousTradingGranularity === nextTradingGranularity;
  alphaExtraCharts = preserveExtraCharts ? previousExtraCharts : [];
  alphaExtraChartLayout = preserveExtraCharts ? previousExtraChartLayout : "overlay";
  alphaDocState.candles = candles;
  alphaDocState.logicalBars = alphaBuildLogicalBars(candles);
  alphaDocState.chartDisplayMode = alphaNormalizeChartDisplayMode(payload.chartDisplayMode || alphaDocState.chartDisplayMode);
  if (preserveViewport) {
    const futureSlots = alphaDocMaxFutureSlots({ candles, candleViewCount: previousCount });
    const maxVirtualLen = Math.max(candles.length, 1) + futureSlots;
    alphaDocState.candleViewCount = Math.max(5, Math.min(2000, maxVirtualLen, previousCount));
    const maxEnd = Math.max(0, candles.length - 1) + futureSlots;
    const fallbackEnd = Math.max(0, candles.length - 1);
    alphaDocState.candleViewEnd = Number.isFinite(previousEnd)
      ? Math.max(alphaDocState.candleViewCount - 1, Math.min(maxEnd, previousEnd))
      : fallbackEnd;
    alphaDocState.priceZoom = previousZoom;
    alphaDocState.pricePan = previousPan;
  } else {
    alphaDocState.candleViewCount = Math.max(5, Math.min(200, candles.length || 200));
    alphaDocState.candleViewEnd = Math.max(0, candles.length - 1);
    alphaDocState.priceZoom = 1;
    alphaDocState.pricePan = 0;
  }
  alphaDocState.candleHover = -1;
  alphaDocState.fileName = nextFileName;
  alphaDocState.fileSize = Number(payload.fileSize) || 0;
  alphaDocState.previewKind = String(payload.previewKind || (candles.length ? "CSV" : ""));
  alphaDocState.previewRows = Array.isArray(payload.previewRows) ? payload.previewRows : [];
  alphaDocState.tradingInstrument = nextTradingInstrument;
  alphaDocState.tradingGranularity = nextTradingGranularity;
  if (candles.length) {
    recomputeIndicators(candles);
  }
  if (tradingSurface) {
    alphaTradingViewportEnsure(alphaDocState, { forceFit: !preserveViewport });
    if (preserveViewport && alphaTradingScalePrefs.autoFit) {
      alphaTradingAutoFitVisiblePriceRange(alphaDocState);
    }
  }
  syncAlphaDropSurface();
  if (alpha3dState.open && tradingSurface) {
    alpha3dState.pressureKey = "";
    void refreshAlpha3dPressureModel(true);
  }
  alphaCanvasWrap?.classList.toggle("is-trading-add-split", alphaExtraChartLayout === "split" && alphaExtraCharts.length > 0);
  scheduleAlphaRender();
}

function setAlphaCanvasExtraCharts(entries = []) {
  alphaExtraChartLayout = Array.isArray(entries) && entries.some((entry) => String(entry?.layout || "").trim().toLowerCase() === "split")
    ? "split"
    : "overlay";
  alphaExtraCharts = Array.isArray(entries)
    ? entries.map((entry) => ({
      candles: alphaNormalizeCanvasCandles(entry?.candles),
      candleViewCount: Math.min(200, Array.isArray(entry?.candles) ? entry.candles.length : 0),
      candleViewEnd: Math.max(0, (Array.isArray(entry?.candles) ? entry.candles.length : 0) - 1),
      candleHover: -1,
      priceZoom: 1,
      pricePan: 0,
      fileName: String(entry?.fileName || ""),
      fileSize: Number(entry?.fileSize || 0),
      instrument: String(entry?.instrument || ""),
      instrumentLabel: String(entry?.instrumentLabel || entry?.instrument || ""),
      tradingInstrument: String(entry?.tradingInstrument || entry?.instrument || ""),
      tradingGranularity: String(entry?.tradingGranularity || alphaDocState.tradingGranularity || "").trim().toUpperCase(),
      brokerLabel: String(entry?.brokerLabel || alphaTradingHeaderState.brokerLabel || tradingBrokerDisplayName(activeTradingBroker)),
      brokerLogoKind: String(entry?.brokerLogoKind || alphaTradingHeaderState.brokerLogoKind || "").trim().toLowerCase(),
      displayName: String(entry?.displayName || ""),
      layout: String(entry?.layout || alphaExtraChartLayout || "overlay"),
      comparison: true,
    }))
    : [];
  alphaCanvasWrap?.classList.toggle("is-trading-add-split", alphaExtraChartLayout === "split" && alphaExtraCharts.length > 0);
  scheduleAlphaRender();
}

function setAlphaTradingAlerts(payload = {}) {
  alphaTradingAlertState.alerts = Array.isArray(payload?.alerts)
    ? payload.alerts.map((entry) => ({
      id: String(entry?.id || ""),
      instrument: String(entry?.instrument || ""),
      granularity: String(entry?.granularity || ""),
      operator: String(entry?.operator || "crossing"),
      targetValue: Number(entry?.targetValue),
      message: String(entry?.message || ""),
      active: entry?.active !== false,
      triggeredCount: Math.max(0, Number(entry?.triggeredCount) || 0),
      lastTriggeredAtMs: Number.isFinite(Number(entry?.lastTriggeredAtMs)) ? Number(entry.lastTriggeredAtMs) : null,
    })).filter((entry) => entry.id && Number.isFinite(entry.targetValue))
    : [];
  scheduleAlphaRender();
}

function setAlphaTradingIndicators(payload = {}) {
  alphaTradingIndicatorState.active = Array.isArray(payload?.indicators)
    ? payload.indicators
      .map((entry) => ({
        id: String(entry?.id || "").trim().toLowerCase(),
        label: String(entry?.label || entry?.id || ""),
        command: String(entry?.command || ""),
        visible: entry?.visible !== false,
        settings: entry?.settings && typeof entry.settings === "object" ? { ...entry.settings } : {},
      }))
      .filter((entry) => entry.id)
    : [];
  scheduleAlphaRender({ force: true });
}

function setAlphaTradingHeader(payload = {}) {
  alphaTradingHeaderState = {
    active: !!payload?.active,
    brokerLabel: String(payload?.brokerLabel || tradingBrokerDisplayName(activeTradingBroker)),
    brokerLogoKind: String(payload?.brokerLogoKind || "").trim().toLowerCase(),
    instrumentLabel: String(payload?.instrumentLabel || currentProjectLabel()),
    compareLabel: String(payload?.compareLabel || "Compare"),
    compareActive: !!payload?.compareActive,
  };
  updateWorkspaceBreadcrumb();
  if (alpha3dState.open && alphaTradingHeaderState.active) {
    alpha3dState.pressureKey = "";
    void refreshAlpha3dPressureModel(true);
  }
}

function forceAlphaCanvasImmediateRender() {
  alphaRenderFailed = false;
  resizeAlphaCanvas();
  scheduleAlphaRender({ force: true });
  requestAnimationFrame(() => {
    alphaRenderFailed = false;
    resizeAlphaCanvas();
    scheduleAlphaRender({ force: true });
  });
  scheduleAlphaResizeRecovery(80);
}

