const forgeAtlasSlashEntityRegistry = (() => {
  const byToken = new Map();
  const byId = new Map();

  function slug(value = "") {
    return String(value || "")
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "_")
      .replace(/^_+|_+$/g, "")
      .replace(/_+/g, "_");
  }

  function inferKindFamily(raw = {}) {
    const parts = [
      raw.kind,
      raw.family,
      raw.node_kind,
      raw.geonode_level,
      raw.dtype,
      raw.domain,
      raw.op,
      raw.class,
      raw.specialization,
      raw.category,
    ].map((value) => String(value || "").toLowerCase());
    const text = parts.join(" ");
    if (/\bcandle\b/.test(text)) return { kind: "metric", family: "candle" };
    if (/\bcreate\b/.test(text)) return { kind: "program", family: "create" };
    if (/\bstrategy\b/.test(text)) return { kind: "program", family: "strategy" };
    if (/\bprogram\b/.test(text)) return { kind: "program", family: "program" };
    if (/\bindicator\b/.test(text)) return { kind: "metric", family: "indicator" };
    if (/mini_geo_node|minigeonode|mini geo|sub_region/.test(text) || raw.parent_geonode) {
      return { kind: "metric", family: "minigeo" };
    }
    if (/geo_node|geonode|geo_anchor|geo_path|geo_region|geo_heatmap|geojson|\blat\b|\blon\b/.test(text)) {
      return { kind: "metric", family: "geo" };
    }
    return { kind: "metric", family: "metric" };
  }

  function defaultToken(raw = {}, normalized = inferKindFamily(raw)) {
    const explicit = String(raw.token || raw.command || "").trim().toLowerCase();
    if (explicit.startsWith("/")) return explicit;
    const baseSlug = slug(
      raw.slug
      || raw.id
      || raw.tag
      || raw.program_hash
      || raw.programHash
      || raw.hash
      || raw.name
      || raw.title
      || raw.label
      || raw.formula
    );
    if (!baseSlug) return "";
    if (normalized.kind === "program") {
      return `/${normalized.family === "strategy" ? "strategy_" : "program_"}${baseSlug}`;
    }
    if (normalized.family === "geo") return `/geo_${baseSlug}`;
    if (normalized.family === "minigeo") return `/minigeo_${baseSlug}`;
    return `/${baseSlug}`;
  }

  function normalize(raw = {}) {
    const normalized = inferKindFamily(raw);
    const token = defaultToken(raw, normalized);
    const id = slug(raw.id || raw.tag || raw.program_hash || raw.programHash || raw.hash || raw.name || raw.title || raw.label || token);
    if (!id || !token) return null;
    return {
      id,
      token,
      slug: slug(raw.slug || raw.tag || raw.name || raw.title || raw.label || id),
      label: String(raw.label || raw.title || raw.name || raw.tag || token).trim() || token,
      summary: String(raw.summary || raw.description || raw.algorithm || raw.goal || raw.intent || "").trim(),
      kind: normalized.kind,
      family: normalized.family,
      source: String(raw.source || "atlas").trim().toLowerCase() || "atlas",
      command: token,
      settings: raw.settings && typeof raw.settings === "object" ? JSON.parse(JSON.stringify(raw.settings)) : {},
      favorites: raw.favorites === true,
      meta: {
        tag: raw.tag || "",
        formula: raw.formula || raw.equation || raw.expression || raw.math || "",
        algorithm: raw.algorithm || "",
        programHash: raw.program_hash || raw.programHash || raw.hash || "",
        parentGeonode: raw.parent_geonode || "",
      },
    };
  }

  function register(raw = {}) {
    const entity = normalize(raw);
    if (!entity) return null;
    const existingById = byId.get(entity.id);
    const existingByToken = byToken.get(entity.token);
    const next = {
      ...(existingById || {}),
      ...(existingByToken || {}),
      ...entity,
      settings: {
        ...((existingById && existingById.settings) || (existingByToken && existingByToken.settings) || {}),
        ...(entity.settings || {}),
      },
      meta: {
        ...((existingById && existingById.meta) || (existingByToken && existingByToken.meta) || {}),
        ...(entity.meta || {}),
      },
    };
    byId.set(next.id, next);
    byToken.set(next.token, next);
    return next;
  }

  function registerBatch(list = []) {
    return Array.isArray(list) ? list.map((entry) => register(entry)).filter(Boolean) : [];
  }

  function resolve(value = "") {
    const normalized = String(value || "").trim().toLowerCase();
    if (!normalized) return null;
    return byToken.get(normalized) || byId.get(slug(normalized)) || null;
  }

  function list(filters = {}) {
    const kind = String(filters.kind || "").trim().toLowerCase();
    const family = String(filters.family || "").trim().toLowerCase();
    const source = String(filters.source || "").trim().toLowerCase();
    return Array.from(byId.values()).filter((entity) => {
      if (kind && entity.kind !== kind) return false;
      if (family && entity.family !== family) return false;
      if (source && entity.source !== source) return false;
      return true;
    });
  }

  function fromAtlasItem(item = {}, extra = {}) {
    return register({
      ...item,
      ...extra,
      kind: extra.kind || item.kind,
      family: extra.family || item.family,
      label: extra.label || item.label || item.title || item.name || item.tag,
      summary: extra.summary || item.summary || item.algorithm || item.description || item.goal || "",
      source: extra.source || "atlas",
    });
  }

  return {
    slug,
    normalize,
    register,
    registerBatch,
    resolve,
    list,
    fromAtlasItem,
  };
})();

window.__forgeAtlasSlashRegistry = forgeAtlasSlashEntityRegistry;
window.__forgeAtlasRegisterSlashEntity = (payload) => forgeAtlasSlashEntityRegistry.register(payload);
window.__forgeAtlasRegisterSlashEntities = (payload) => forgeAtlasSlashEntityRegistry.registerBatch(payload);
window.__forgeAtlasResolveSlashEntity = (value) => forgeAtlasSlashEntityRegistry.resolve(value);
window.__forgeAtlasListSlashEntities = (filters) => forgeAtlasSlashEntityRegistry.list(filters);
window.__forgeAtlasEntityFromItem = (item, extra) => forgeAtlasSlashEntityRegistry.fromAtlasItem(item, extra);

function buildPickerCubeRow(tag, label, kind, extra = {}) {
  const row = document.createElement("li");
  row.className = "program-picker-row";
  row.setAttribute("role", "option");
  row.dataset.tag = tag;
  row.dataset.kind = kind;
  row.tabIndex = 0;
  row.title = label || tag;
  const entity = forgeAtlasSlashEntityRegistry.fromAtlasItem({
    tag,
    label,
    kind,
    formula: extra.formula || "",
    algorithm: extra.algorithm || "",
    program_hash: extra.programHash || "",
  });
  if (entity?.token) row.dataset.slashToken = entity.token;
  const formula = String(extra.formula || "");
  const algorithm = String(extra.algorithm || "");
  const dataAttrs = [
    `data-tag="${escapeAttr(tag)}"`,
    `data-kind="${escapeAttr(kind)}"`,
    formula ? `data-formula="${escapeAttr(formula)}"` : "",
    algorithm ? `data-algorithm="${escapeAttr(algorithm)}"` : "",
  ].filter(Boolean).join(" ");
  row.innerHTML = `<span class="my-atlas-cube ${atlasNodeColorClass(tag)}" draggable="false" title="${escapeAttr(label || tag)}" ${dataAttrs}><span class="my-atlas-cube-face">${escapeAttr(atlasNodeInitials(tag))}</span></span><span class="program-picker-row-label">${escapeAttr(label || tag)}</span>`;
  return row;
}

function buildAtlasCubeElement(tag, label, kind, extra = {}) {
  const cube = document.createElement("span");
  cube.className = `my-atlas-cube ${atlasNodeColorClass(tag)}`.trim();
  cube.setAttribute("draggable", "false");
  cube.setAttribute("title", label || tag);
  cube.dataset.tag = tag;
  cube.dataset.kind = kind || "node";
  const entity = forgeAtlasSlashEntityRegistry.fromAtlasItem({
    tag,
    label,
    kind,
    formula: extra.formula || "",
    algorithm: extra.algorithm || "",
  });
  if (entity?.token) cube.dataset.slashToken = entity.token;
  if (extra.formula) cube.dataset.formula = String(extra.formula);
  if (extra.algorithm) cube.dataset.algorithm = String(extra.algorithm);
  cube.innerHTML = `<span class="my-atlas-cube-face">${escapeAttr(atlasNodeInitials(tag))}</span>`;
  return cube;
}

function ensureCanvasChatNodeSlot() {
  const slotsRoot = document.getElementById("forgeCanvasChatNodeSlots");
  if (!slotsRoot) return null;
  const empty = Array.from(slotsRoot.querySelectorAll(".canvas-chat-nodeslot"))
    .find((slot) => !slot.querySelector(".my-atlas-cube"));
  if (empty) return empty;
  const next = document.createElement("div");
  next.className = "canvas-chat-nodeslot";
  next.dataset.slot = String(slotsRoot.querySelectorAll(".canvas-chat-nodeslot").length);
  slotsRoot.appendChild(next);
  syncCanvasChatRemoveBtnState();
  return next;
}

function injectAtlasItemIntoChatSlot(item) {
  const tag = String(item?.tag || "").trim();
  if (!tag) return null;
  forgeAtlasSlashEntityRegistry.fromAtlasItem(item);
  const slot = ensureCanvasChatNodeSlot();
  if (!slot) return null;
  slot.querySelector(".my-atlas-cube")?.remove();
  const cube = buildAtlasCubeElement(tag, String(item?.label || tag), String(item?.kind || "node"), {
    formula: item?.formula || item?.label || tag,
    algorithm: item?.algorithm || (item?.body ? `geo_anchor:${item.body}` : ""),
  });
  slot.appendChild(cube);
  playForgeUiSound("slot-in");
  syncCanvasChatSendState();
  return cube;
}

function isGeoNodeAtlasItem(item) {
  const parts = [
    item?.kind,
    item?.node_kind,
    item?.geonode_level,
    item?.dtype,
    item?.domain,
    item?.op,
    item?.tag,
    item?.title,
    item?.formula,
    item?.algorithm,
    item?.geo_ref,
    item?.geonode_tag,
  ].map((value) => String(value || "").toLowerCase());
  return parts.some((value) => (
    value.includes("mini_geo_node")
    || value.includes("minigeonode")
    || value.includes("geo_node")
    || value.includes("geonode")
    || value.includes("geo_anchor")
    || value.includes("geo_path")
    || value.includes("geo_region")
    || value.includes("geo_heatmap")
    || value.includes("geojson")
    || value.includes("lat")
    || value.includes("lon")
  ));
}

function isMiniGeoNodeAtlasItem(item) {
  const parts = [
    item?.node_kind,
    item?.geonode_level,
    item?.class,
  ].map((value) => String(value || "").toLowerCase());
  return parts.some((value) => (
    value.includes("mini_geo_node")
    || value.includes("minigeonode")
    || value === "mini"
    || value === "sub_region"
  )) || Boolean(item?.parent_geonode);
}

async function openCanvasChatProgramPicker() {
  if (!forgeCanvasChatProgramPicker || !forgeCanvasChatProgramPickerList) return;
  forgeCanvasChatProgramPickerList.innerHTML = "";
  if (forgeCanvasChatPickerNodesList) forgeCanvasChatPickerNodesList.innerHTML = "";
  if (forgeCanvasChatPickerGeoNodesList) forgeCanvasChatPickerGeoNodesList.innerHTML = "";
  if (forgeCanvasChatProgramPickerEmpty) forgeCanvasChatProgramPickerEmpty.hidden = true;
  if (forgeCanvasChatPickerInstrumentsSection) forgeCanvasChatPickerInstrumentsSection.hidden = true;
  if (forgeCanvasChatPickerNodesSection) forgeCanvasChatPickerNodesSection.hidden = true;
  if (forgeCanvasChatPickerGeoNodesSection) forgeCanvasChatPickerGeoNodesSection.hidden = true;
  forgeCanvasChatProgramPicker.hidden = false;
  forgeCanvasChatPrograms?.setAttribute("aria-expanded", "true");

  // Fetch atlas overview (instruments + node tags). Programs come from
  // list_forge_programs; nodes come from get_forge_atlas_overview.
  const invoke = window.__TAURI__?.core?.invoke;
  const [programs, atlasOverview] = await Promise.all([
    loadCanvasChatProgramOptions(),
    invoke ? invoke("get_forge_atlas_overview", { limit: 60 }).catch(() => null) : null,
  ]);

  let hasAny = false;

  if (Array.isArray(programs) && programs.length) {
    hasAny = true;
    if (forgeCanvasChatPickerInstrumentsSection) forgeCanvasChatPickerInstrumentsSection.hidden = false;
    for (const program of programs) {
      const tag = program.name || program.hash || "instrument";
      const row = buildPickerCubeRow(tag, program.name || program.hash || "Untitled", "program", {
        formula: program.formula || program.spec_summary || "",
        algorithm: program.algorithm || program.intent || program.goal || "",
        programHash: program.hash || "",
      });
      row.dataset.programHash = program.hash || "";
      forgeCanvasChatProgramPickerList.appendChild(row);
    }
  }

  const tags = atlasOverview?.my_atlas?.metric_tags || atlasOverview?.my_atlas?.tags || [];
  const uniqueTags = [];
  const tagMeta = new Map();
  const geoTags = [];
  const normalTags = [];
  const seen = new Set();
  for (const item of tags) {
    const t = item?.tag || item?.title || item?.name;
    if (typeof t !== "string" || !t.trim()) continue;
    if (seen.has(t)) continue;
    seen.add(t);
    uniqueTags.push(t);
    tagMeta.set(t, {
      formula: item?.formula || item?.equation || item?.expression || item?.math || "",
      algorithm: item?.algorithm || item?.description || item?.goal || "",
      nodeKind: item?.node_kind || item?.geonode_level || "",
    });
    (isGeoNodeAtlasItem(item) ? geoTags : normalTags).push(t);
    if (uniqueTags.length >= 24) break;
  }
  if (normalTags.length && forgeCanvasChatPickerNodesList) {
    hasAny = true;
    if (forgeCanvasChatPickerNodesSection) forgeCanvasChatPickerNodesSection.hidden = false;
    for (const tag of normalTags) {
      const meta = tagMeta.get(tag) || {};
      const row = buildPickerCubeRow(tag, tag, "node", { formula: meta.formula, algorithm: meta.algorithm });
      forgeCanvasChatPickerNodesList.appendChild(row);
    }
  }
  if (geoTags.length && forgeCanvasChatPickerGeoNodesList) {
    hasAny = true;
    if (forgeCanvasChatPickerGeoNodesSection) forgeCanvasChatPickerGeoNodesSection.hidden = false;
    for (const tag of geoTags) {
      const meta = tagMeta.get(tag) || {};
      const isMini = /mini|sub_region/i.test(String(meta.nodeKind || ""));
      const row = buildPickerCubeRow(tag, tag, isMini ? "minigeonode" : "geonode", { formula: meta.formula, algorithm: meta.algorithm });
      forgeCanvasChatPickerGeoNodesList.appendChild(row);
    }
  }

  if (!hasAny && forgeCanvasChatProgramPickerEmpty) {
    forgeCanvasChatProgramPickerEmpty.hidden = false;
  }
}

// Hover behaviour: open after a small dwell on the icon, close after a
// small grace period when the cursor leaves both the icon and the popup.
const canvasChatPickerHoverHost = document.querySelector(".canvas-chat-program-group");
function scheduleOpenPicker() {
  if (canvasChatPickerHoverTimer) clearTimeout(canvasChatPickerHoverTimer);
  canvasChatPickerHoverTimer = setTimeout(() => {
    void openCanvasChatProgramPicker();
  }, 140);
}
function scheduleClosePicker() {
  if (canvasChatPickerHoverTimer) clearTimeout(canvasChatPickerHoverTimer);
  canvasChatPickerHoverTimer = setTimeout(() => {
    if (!forgeCanvasChatProgramPicker || forgeCanvasChatProgramPicker.hidden) return;
    if (forgeCanvasChatProgramPicker.matches(":hover")) return;
    if (forgeCanvasChatPrograms?.matches(":hover")) return;
    closeCanvasChatProgramPicker();
  }, 220);
}
forgeCanvasChatPrograms?.addEventListener("mouseenter", scheduleOpenPicker);
forgeCanvasChatPrograms?.addEventListener("focus", scheduleOpenPicker);
forgeCanvasChatProgramPicker?.addEventListener("mouseenter", () => {
  if (canvasChatPickerHoverTimer) clearTimeout(canvasChatPickerHoverTimer);
});
canvasChatPickerHoverHost?.addEventListener("mouseleave", scheduleClosePicker);
forgeCanvasChatProgramPicker?.addEventListener("mouseleave", scheduleClosePicker);

// Click-toggle is preserved for accessibility / touch.
forgeCanvasChatPrograms?.addEventListener("click", (event) => {
  event.preventDefault();
  event.stopPropagation();
  if (forgeCanvasChatProgramPicker?.hidden === false) {
    closeCanvasChatProgramPicker();
  } else {
    void openCanvasChatProgramPicker();
  }
});

forgeCanvasChatProgramPicker?.addEventListener("click", (event) => {
  const row = event.target?.closest?.(".program-picker-row[data-slash-token]");
  if (!row) return;
  const token = String(row.dataset.slashToken || "").trim();
  if (!token) return;
  event.preventDefault();
  event.stopPropagation();
  insertCanvasChatToken(token);
  closeCanvasChatProgramPicker();
});

const forgeCanvasChatRemoveSlotBtn = document.getElementById("forgeCanvasChatRemoveSlot");
const CHAT_NODE_SLOT_MIN = 1;

function syncCanvasChatRemoveBtnState() {
  if (!forgeCanvasChatRemoveSlotBtn) return;
  const slotsRoot = document.getElementById("forgeCanvasChatNodeSlots");
  const count = slotsRoot?.querySelectorAll(".canvas-chat-nodeslot").length ?? 0;
  forgeCanvasChatRemoveSlotBtn.disabled = count <= CHAT_NODE_SLOT_MIN;
}

// "+" button — appends an extra empty node slot to the chat tray.
forgeCanvasChatAddSlotBtn?.addEventListener("click", (event) => {
  event.preventDefault();
  event.stopPropagation();
  const slotsRoot = document.getElementById("forgeCanvasChatNodeSlots");
  if (!slotsRoot) return;
  const next = document.createElement("div");
  const idx = slotsRoot.querySelectorAll(".canvas-chat-nodeslot").length;
  next.className = "canvas-chat-nodeslot";
  next.dataset.slot = String(idx);
  slotsRoot.appendChild(next);
  syncCanvasChatRemoveBtnState();
});

// "−" button — removes the rightmost slot. Prefers an empty slot first
// so a populated cube isn't lost by accident; falls back to the last
// slot if all are populated. Keeps at least CHAT_NODE_SLOT_MIN slot.
forgeCanvasChatRemoveSlotBtn?.addEventListener("click", (event) => {
  event.preventDefault();
  event.stopPropagation();
  const slotsRoot = document.getElementById("forgeCanvasChatNodeSlots");
  if (!slotsRoot) return;
  const slots = Array.from(slotsRoot.querySelectorAll(".canvas-chat-nodeslot"));
  if (slots.length <= CHAT_NODE_SLOT_MIN) return;
  // Walk from the right; first empty slot wins, otherwise drop the last one.
  let target = null;
  for (let i = slots.length - 1; i >= CHAT_NODE_SLOT_MIN; i--) {
    if (!slots[i].querySelector(".my-atlas-cube")) {
      target = slots[i];
      break;
    }
  }
  if (!target) target = slots[slots.length - 1];
  target.remove();
  syncCanvasChatRemoveBtnState();
});

syncCanvasChatRemoveBtnState();

document.addEventListener("click", (event) => {
  if (!forgeCanvasChatProgramPicker || forgeCanvasChatProgramPicker.hidden) return;
  if (forgeCanvasChatProgramPicker.contains(event.target)) return;
  if (forgeCanvasChatPrograms?.contains(event.target)) return;
  closeCanvasChatProgramPicker();
});
document.addEventListener("click", (event) => {
  const cube = event.target?.closest?.(".my-atlas-cube[data-slash-token]");
  if (!cube) return;
  if (event.target?.closest?.(".canvas-chat-nodeslot")) return;
  const token = String(cube.dataset.slashToken || "").trim();
  if (!token) return;
  insertCanvasChatToken(token);
});
window.addEventListener("keydown", (event) => {
  if (event.key === "Escape" && forgeCanvasChatProgramPicker && !forgeCanvasChatProgramPicker.hidden) {
    closeCanvasChatProgramPicker();
  }
});
forgeCanvasChatFileInput?.addEventListener("change", (event) => {
  addCanvasChatPendingFiles(event.target.files);
  event.target.value = "";
});

window.addEventListener("forge:banger-stage-files", (event) => {
  const files = event?.detail?.files;
  if (!files?.length) return;
  addCanvasChatPendingFiles(files, { skipBoomPreview: true });
});

function stopCanvasChatActivity() {
  const turnId = forgeCanvasChatActiveTurnId;
  const liveJobId = activeCanvasLiveComputeJobId();
  const jobId = liveJobId || currentAlphaSessionJobId();
  const live = liveJobId ? alphaCanvasLiveComputes.get(liveJobId) : null;
  if (forgeCanvasChatAbortController) {
    try { forgeCanvasChatAbortController.abort(); } catch (_) {}
    forgeCanvasChatAbortController = null;
  }
  forgeCanvasChatActiveTurnId = "";
  if (live) {
    live.stopRequested = true;
    live.status = "cancelling";
    live.updatedAt = Date.now();
    renderCanvasLiveComputeCard();
    syncCanvasChatSendState();
  } else {
    appendCanvasChatMessage("tool", "Stopped by user.", {});
  }
  setCanvasChatBusy(false);
  const invoke = window.__TAURI__?.core?.invoke;
  if (invoke) {
    void invoke("cancel_forge_canvas_activity", {
      request: {
        turnId: turnId || null,
        jobId: jobId || null,
        reason: "Stopped from Forge canvas chat",
      },
    }).catch((err) => {
      appendCanvasChatMessage("tool", `Stop request reached the UI, but backend cancel failed: ${err}`, {});
    });
  }
  window.dispatchEvent(new CustomEvent("forge:cancel-current"));
}

forgeCanvasChatStopBtn?.addEventListener("click", (event) => {
  event.preventDefault();
  event.stopPropagation();
  if (!alphaCanvasChatBusy && !hasActiveCanvasLiveCompute()) return;
  stopCanvasChatActivity();
});

function activeCanvasDictationInput() {
  if (forgeCanvasChatTargetMode === "all" && document.activeElement === forgeCanvasChatGeminiInput) {
    return forgeCanvasChatGeminiInput;
  }
  if (forgeCanvasChatTargetMode === "all" && document.activeElement === forgeCanvasChatClaudeInput) {
    return forgeCanvasChatClaudeInput;
  }
  return forgeCanvasChatInput;
}

function insertCanvasDictationText(text) {
  const clean = String(text || "").trim();
  const targetInput = activeCanvasDictationInput();
  if (!clean || !targetInput) return;
  const start = Number.isFinite(targetInput.selectionStart) ? targetInput.selectionStart : targetInput.value.length;
  const end = Number.isFinite(targetInput.selectionEnd) ? targetInput.selectionEnd : start;
  const before = targetInput.value.slice(0, start);
  const after = targetInput.value.slice(end);
  const prefix = before && !/\s$/.test(before) ? " " : "";
  const suffix = after && !/^\s/.test(after) ? " " : "";
  targetInput.value = `${before}${prefix}${clean}${suffix}${after}`;
  const nextCaret = before.length + prefix.length + clean.length + suffix.length;
  targetInput.focus();
  targetInput.setSelectionRange?.(nextCaret, nextCaret);
  autosizeCanvasChatInput();
  syncCanvasChatSendState();
  syncTradingSlashCommandState();
}

function insertCanvasChatToken(text) {
  const clean = String(text || "").trim();
  const targetInput = primaryCanvasComposerInput?.() || forgeCanvasChatInput;
  if (!clean || !targetInput) return;
  const start = Number.isFinite(targetInput.selectionStart) ? targetInput.selectionStart : targetInput.value.length;
  const end = Number.isFinite(targetInput.selectionEnd) ? targetInput.selectionEnd : start;
  const before = targetInput.value.slice(0, start);
  const after = targetInput.value.slice(end);
  const prefix = before && !/\s$/.test(before) ? " " : "";
  const suffix = after && !/^\s/.test(after) ? " " : "";
  targetInput.value = `${before}${prefix}${clean}${suffix}${after}`;
  const nextCaret = before.length + prefix.length + clean.length;
  targetInput.focus();
  targetInput.setSelectionRange?.(nextCaret, nextCaret);
  autosizeCanvasChatInput();
  syncCanvasChatSendState();
  syncTradingSlashCommandState();
}

function setCanvasChatCommand(text) {
  const clean = String(text || "").trim();
  const targetInput = primaryCanvasComposerInput?.() || forgeCanvasChatInput;
  if (!clean || !targetInput) return;
  targetInput.value = clean;
  targetInput.focus();
  const caret = targetInput.value.length;
  targetInput.setSelectionRange?.(caret, caret);
  autosizeCanvasChatInput();
  syncCanvasChatSendState();
  syncTradingSlashCommandState();
}
if (typeof window !== "undefined") {
  window.__forgeTradingInjectChatToken = insertCanvasChatToken;
  window.__forgeTradingSetChatCommand = setCanvasChatCommand;
}

function canvasSlashCommandToneClass(value = "") {
  const token = String(value || "").trim().split(/\s+/)[0]?.toLowerCase() || "";
  if (!token.startsWith("/")) return "";
  const entity = window.__forgeAtlasResolveSlashEntity?.(token) || null;
  if (token === "/create_" || entity?.family === "create") return "is-slash-create";
  if (entity?.kind === "program") return "is-slash-program";
  if (entity?.kind === "metric") return "is-slash-metric";
  return "is-slash-command";
}

function syncTradingSlashCommandState() {
  const fields = [forgeCanvasChatInput, forgeCanvasChatGeminiInput, forgeCanvasChatClaudeInput].filter(Boolean);
  const activeField = primaryCanvasComposerInput?.() || forgeCanvasChatInput || null;
  const activeValue = String(activeField?.value || "");
  const activeToken = activeValue.trim().split(/\s+/)[0]?.toLowerCase() || "";
  const activeEntity = window.__forgeAtlasResolveSlashEntity?.(activeToken) || null;
  for (const field of fields) {
    const className = canvasSlashCommandToneClass(field.value || "");
    field.classList.remove("is-slash-command", "is-slash-metric", "is-slash-program", "is-slash-create");
    if (className) field.classList.add(className);
  }
  window.dispatchEvent(new CustomEvent("forge:trading-slash-preview", {
    detail: {
      token: activeToken,
      entity: activeEntity,
      text: activeValue,
    },
  }));
}

function setCanvasDictationState(state = "idle") {
  const nodes = [forgeCanvasChatDictationBar, forgeCanvasChatMicBtn].filter(Boolean);
  for (const node of nodes) {
    node.classList.remove("recording", "transcribing", "denied");
    if (state && state !== "idle") node.classList.add(state);
  }
  if (forgeCanvasChatMicBtn) {
    const label = state === "recording"
      ? "Stop ElevenLabs dictation"
      : state === "transcribing"
        ? "Transcribing with ElevenLabs"
        : "Voice input";
    forgeCanvasChatMicBtn.setAttribute("aria-label", label);
  }
  if (forgeCanvasChatDictationBar) {
    const label = state === "recording"
      ? "Release Ctrl Alt to transcribe"
      : state === "transcribing"
        ? "Transcribing with ElevenLabs"
        : "Hold Ctrl Alt to dictate with ElevenLabs";
    forgeCanvasChatDictationBar.setAttribute("aria-label", label);
  }
}

function markCanvasDictationDenied() {
  setCanvasDictationState("denied");
  setTimeout(() => {
    if (!forgeCanvasDictationRecording && !forgeCanvasDictationStarting) setCanvasDictationState("idle");
  }, 1200);
}

function pickCanvasDictationMimeType() {
  const candidates = [
    "audio/webm;codecs=opus",
    "audio/webm",
    "audio/mp4",
    "audio/ogg;codecs=opus",
  ];
  if (!window.MediaRecorder?.isTypeSupported) return "";
  return candidates.find((type) => MediaRecorder.isTypeSupported(type)) || "";
}

function blobToBase64(blob) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const text = String(reader.result || "");
      resolve(text.includes(",") ? text.split(",").pop() : text);
    };
    reader.onerror = () => reject(reader.error || new Error("Failed to read audio blob"));
    reader.readAsDataURL(blob);
  });
}

async function transcribeCanvasDictationBlob(blob) {
  const invoke = window.__TAURI__?.core?.invoke;
  if (!invoke) throw new Error("Tauri invoke is not available");
  const audioBase64 = await blobToBase64(blob);
  return invoke("voice_stt_transcribe", {
    request: {
      audioBase64,
      mimeType: blob.type || "audio/webm",
      modelId: "scribe_v2",
      languageCode: null,
    },
  });
}

function playForgeUiSound(kind) {
  const sounds = {
    "dictation-on": { src: "assets/sounds/wooden-click.mp3", volume: 0.11, rate: 1.05 },
    "dictation-off": { src: "assets/sounds/dictation-release.ogg", volume: 0.18, rate: 1 },
    "slot-in": { src: "assets/sounds/wooden-click.mp3", volume: 0.16, rate: 0.62 },
    "slot-swap": { src: "assets/sounds/wooden-click.mp3", volume: 0.12, rate: 0.74 },
    "program-complete": { src: "assets/sounds/program-complete.mp3", volume: 0.20, rate: 1 },
    "alert-soft": { src: "assets/sounds/wooden-click.mp3", volume: 0.18, rate: 0.88 },
    "alert-bell": { src: "assets/sounds/program-complete.mp3", volume: 0.28, rate: 1.04 },
    "alert-pulse": { src: "assets/sounds/wooden-click.mp3", volume: 0.15, rate: 1.2 },
  };
  const spec = sounds[kind];
  if (!spec?.src || typeof Audio === "undefined") return;
  try {
    if (!forgeUiAudioCache.has(kind)) {
      const base = new Audio(spec.src);
      base.preload = "auto";
      base.volume = spec.volume;
      base.playbackRate = spec.rate;
      forgeUiAudioCache.set(kind, base);
    }
    const sound = forgeUiAudioCache.get(kind).cloneNode(true);
    sound.volume = spec.volume;
    sound.playbackRate = spec.rate;
    sound.play().catch(() => {});
  } catch (err) {
    console.warn("[ui-audio] failed to play micro sound", err);
  }
}

async function startCanvasElevenDictation() {
  if (forgeCanvasDictationRecording || forgeCanvasDictationStarting) return true;
  if (!navigator.mediaDevices?.getUserMedia || !window.MediaRecorder) {
    return false;
  }
  forgeCanvasDictationStarting = true;
  try {
    const stream = await navigator.mediaDevices.getUserMedia({
      audio: {
        echoCancellation: true,
        noiseSuppression: true,
        autoGainControl: true,
      },
    });
    const mimeType = pickCanvasDictationMimeType();
    const options = mimeType ? { mimeType } : undefined;
    const recorder = new MediaRecorder(stream, options);
    forgeCanvasDictationChunks = [];
    forgeCanvasDictationStream = stream;
    forgeCanvasDictationRecorder = recorder;
    recorder.ondataavailable = (event) => {
      if (event.data && event.data.size > 0) forgeCanvasDictationChunks.push(event.data);
    };
    recorder.onstop = async () => {
      const chunks = forgeCanvasDictationChunks.slice();
      const type = recorder.mimeType || mimeType || "audio/webm";
      forgeCanvasDictationChunks = [];
      forgeCanvasDictationRecorder = null;
      forgeCanvasDictationRecording = false;
      forgeCanvasDictationStream?.getTracks?.().forEach((track) => track.stop());
      forgeCanvasDictationStream = null;
      if (!chunks.length) {
        setCanvasDictationState("idle");
        return;
      }
      setCanvasDictationState("transcribing");
      try {
        const result = await transcribeCanvasDictationBlob(new Blob(chunks, { type }));
        insertCanvasDictationText(result?.text || "");
        if (typeof voiceProviderHint !== "undefined" && voiceProviderHint && result?.message) {
          voiceProviderHint.textContent = result.message;
        }
      } catch (err) {
        console.warn("[voice] ElevenLabs dictation failed", err);
        if (typeof voiceProviderHint !== "undefined" && voiceProviderHint) {
          voiceProviderHint.textContent = `Dictation failed: ${err}`;
        }
        markCanvasDictationDenied();
        return;
      }
      if (!forgeCanvasDictationRecording && !forgeCanvasDictationStarting) setCanvasDictationState("idle");
    };
    recorder.start(250);
    forgeCanvasDictationRecording = true;
    setCanvasDictationState("recording");
    playForgeUiSound("dictation-on");
    return true;
  } catch (err) {
    console.warn("[voice] ElevenLabs dictation start failed", err);
    markCanvasDictationDenied();
    return false;
  } finally {
    forgeCanvasDictationStarting = false;
  }
}

function stopCanvasElevenDictation() {
  if (!forgeCanvasDictationRecorder || !forgeCanvasDictationRecording) return false;
  try {
    playForgeUiSound("dictation-off");
    forgeCanvasDictationRecorder.stop();
  } catch (err) {
    console.warn("[voice] ElevenLabs dictation stop failed", err);
    forgeCanvasDictationStream?.getTracks?.().forEach((track) => track.stop());
    forgeCanvasDictationStream = null;
    forgeCanvasDictationRecording = false;
    setCanvasDictationState("idle");
  }
  return true;
}

async function toggleCanvasElevenDictation() {
  if (forgeCanvasDictationRecording) {
    stopCanvasElevenDictation();
    return true;
  }
  const started = await startCanvasElevenDictation();
  if (!started) markCanvasDictationDenied();
  return started;
}

function ensureCanvasChatRecognition() {
  if (forgeCanvasChatRecognition) return forgeCanvasChatRecognition;
  const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (!SR) return null;
  const recognition = new SR();
  recognition.continuous = false;
  recognition.interimResults = true;
  recognition.lang = (navigator.language || "en-US");
  recognition.onresult = (event) => {
    let finalText = "";
    let interim = "";
    for (let i = event.resultIndex; i < event.results.length; i++) {
      const r = event.results[i];
      if (r.isFinal) finalText += r[0].transcript;
      else interim += r[0].transcript;
    }
    const targetInput = forgeCanvasChatTargetMode === "all" && document.activeElement === forgeCanvasChatGeminiInput
      ? forgeCanvasChatGeminiInput
      : forgeCanvasChatTargetMode === "all" && document.activeElement === forgeCanvasChatClaudeInput
        ? forgeCanvasChatClaudeInput
        : forgeCanvasChatInput;
    if (targetInput && (finalText || interim)) {
      const base = (targetInput.value || "").trimEnd();
      const append = (finalText || interim).trim();
      targetInput.value = base ? `${base} ${append}` : append;
      autosizeCanvasChatInput();
      syncCanvasChatSendState();
    }
  };
  recognition.onend = () => {
    forgeCanvasChatRecognizing = false;
    forgeCanvasChatMicBtn?.classList.remove("recording");
    forgeCanvasChatMicBtn?.setAttribute("aria-label", "Voice input");
  };
  recognition.onerror = (event) => {
    forgeCanvasChatRecognizing = false;
    forgeCanvasChatMicBtn?.classList.remove("recording");
    forgeCanvasChatMicBtn?.classList.add("denied");
    setTimeout(() => forgeCanvasChatMicBtn?.classList.remove("denied"), 1200);
    console.warn("[voice] error", event.error);
  };
  forgeCanvasChatRecognition = recognition;
  return recognition;
}

forgeCanvasChatMicBtn?.addEventListener("click", (event) => {
  event.preventDefault();
  void toggleCanvasElevenDictation();
});

forgeCanvasChatDictationBar?.addEventListener("click", (event) => {
  event.preventDefault();
  void toggleCanvasElevenDictation();
});

window.addEventListener("keydown", (event) => {
  if (event.repeat || forgeCanvasDictationHotkeyDown) return;
  if (event.ctrlKey && event.altKey && !event.metaKey && !event.shiftKey && (event.key === "Control" || event.key === "Alt")) {
    forgeCanvasDictationHotkeyDown = true;
    event.preventDefault();
    void startCanvasElevenDictation();
  }
});

window.addEventListener("keyup", (event) => {
  if (!forgeCanvasDictationHotkeyDown) return;
  if (event.key === "Control" || event.key === "Alt") {
    forgeCanvasDictationHotkeyDown = false;
    event.preventDefault();
    stopCanvasElevenDictation();
  }
});

function startCanvasBrowserDictationFallback() {
  const recognition = ensureCanvasChatRecognition();
  if (!recognition) {
    if (forgeCanvasChatMicBtn) {
      forgeCanvasChatMicBtn.classList.add("denied");
      setTimeout(() => forgeCanvasChatMicBtn.classList.remove("denied"), 1200);
    }
    console.warn("[voice] SpeechRecognition API not available");
    return;
  }
  if (forgeCanvasChatRecognizing) {
    try { recognition.stop(); } catch (_) {}
    return;
  }
  try {
    recognition.start();
    forgeCanvasChatRecognizing = true;
    forgeCanvasChatMicBtn.classList.add("recording");
    forgeCanvasChatMicBtn.setAttribute("aria-label", "Stop voice input");
  } catch (err) {
    forgeCanvasChatMicBtn?.classList.add("denied");
    setTimeout(() => forgeCanvasChatMicBtn?.classList.remove("denied"), 1200);
    console.warn("[voice] start failed", err);
  }
}

