const alphaProgramPicker      = document.getElementById("alphaProgramPicker");
const alphaProgramPickerList  = document.getElementById("alphaProgramPickerList");
const alphaProgramPickerEmpty = document.getElementById("alphaProgramPickerEmpty");

function closeProgramPicker() {
  if (!alphaProgramPicker) return;
  alphaProgramPicker.hidden = true;
  alphaAddProgramBtn?.setAttribute("aria-expanded", "false");
}

function appendMarsLensPickerRow() {
  if (!alphaProgramPickerList) return;
  const row = document.createElement("li");
  row.className = "program-picker-row mars-special-lens";
  row.setAttribute("role", "menuitem");
  row.tabIndex = 0;
  row.title = "Open the Planet renderer on Mars";
  row.innerHTML = `
    <svg viewBox="0 0 24 24" aria-hidden="true">
      <circle cx="12" cy="12" r="7.5"></circle>
      <path d="M5.7 10.2c2.2.9 4.5.9 6.6.2 2.1-.7 3.8-.6 5.8.5"></path>
      <path d="M8.2 15.5c1.9-.6 3.9-.5 5.6.1 1.4.5 2.6.6 4 .2"></path>
    </svg>
  `;
  const label = document.createElement("span");
  label.className = "program-picker-row-label";
  label.textContent = "Planet · Mars";
  row.appendChild(label);
  const select = () => {
    if (typeof openMarsLensView === "function") openMarsLensView();
    closeProgramPicker();
  };
  row.addEventListener("click", select);
  row.addEventListener("keydown", (event) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      select();
    }
  });
  alphaProgramPickerList.appendChild(row);
}

async function openProgramPicker() {
  if (!alphaProgramPicker || !alphaProgramPickerList) return;
  alphaProgramPickerList.innerHTML = "";
  if (alphaProgramPickerEmpty) alphaProgramPickerEmpty.hidden = true;
  alphaProgramPicker.hidden = false;
  alphaAddProgramBtn?.setAttribute("aria-expanded", "true");

  const programs = await loadCanvasChatProgramOptions();
  const hasPlanetToolProgram = Array.isArray(programs) && programs.some((program) => (
    String(program?.lensUrl || "").includes("assets/lenses/mars-globe/")
    || (Array.isArray(program?.views) && program.views.some((view) => /planet_sphere/i.test(JSON.stringify(view || {}))))
  ));
  if (!hasPlanetToolProgram) appendMarsLensPickerRow();
  if (!Array.isArray(programs) || programs.length === 0) {
    return;
  }

  for (const program of programs) {
    const row = document.createElement("li");
    row.className = "program-picker-row";
    row.setAttribute("role", "menuitem");
    row.tabIndex = 0;
    if (program.desc) row.title = program.desc;
    row.innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m8 6-5 6 5 6"/><path d="m16 6 5 6-5 6"/><path d="m14 4-4 16"/></svg>';
    const label = document.createElement("span");
    label.textContent = program.name || program.hash || "Untitled program";
    row.appendChild(label);
    const select = () => {
      window.dispatchEvent(new CustomEvent("forge:attach-program", { detail: program }));
      closeProgramPicker();
    };
    row.addEventListener("click", select);
    row.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        select();
      }
    });
    alphaProgramPickerList.appendChild(row);
  }
}

