function alphaSelectedLogText() {
  const selection = window.getSelection();
  if (!selection || selection.isCollapsed) return "";
  if (!alphaLogLayer.contains(selection.anchorNode) && !alphaLogLayer.contains(selection.focusNode)) return "";
  return selection.toString();
}

function selectAllAlphaLogs() {
  if (!alphaLogLayer) return;
  const range = document.createRange();
  range.selectNodeContents(alphaLogLayer);
  const selection = window.getSelection();
  selection.removeAllRanges();
  selection.addRange(range);
}

async function copyAlphaLogsFromMenu() {
  const selected = alphaSelectedLogText();
  const text = selected.trim() ? selected : alphaForgeLogs.join("\n");
  if (!text) return;
  await navigator.clipboard.writeText(text);
}

function hideAlphaLogMenu() {
  if (alphaLogMenu) alphaLogMenu.hidden = true;
}

function showAlphaLogMenu(x, y) {
  if (!alphaLogMenu) return;
  alphaLogMenu.hidden = false;
  const rect = alphaLogMenu.getBoundingClientRect();
  const left = Math.min(x, window.innerWidth - rect.width - 8);
  const top = Math.min(y, window.innerHeight - rect.height - 8);
  alphaLogMenu.style.left = `${Math.max(8, left)}px`;
  alphaLogMenu.style.top = `${Math.max(8, top)}px`;
}

function hideAlphaChartMenu() {
  if (alphaChartMenu) alphaChartMenu.hidden = true;
  setAlphaTradingDockPanelMode("none");
}

let alphaChartMenuMode = "chart";

function setAlphaTradingDockPanelMode(mode = "none") {
  const nextMode = mode || "none";
  const prevTarget = alphaTradingDockPanel.mode;
  const currentVisual = alphaTradingDockPanel.visualMode === "none"
    ? (prevTarget === "none" ? "none" : prevTarget)
    : alphaTradingDockPanel.visualMode;
  alphaTradingDockPanel.mode = nextMode;
  if (nextMode === "none") {
    alphaTradingDockPanel.previousMode = currentVisual;
  } else if (currentVisual !== nextMode) {
    alphaTradingDockPanel.previousMode = currentVisual;
    alphaTradingDockPanel.visualMode = nextMode;
    alphaTradingDockPanel.contentProgress = 0;
  } else {
    alphaTradingDockPanel.visualMode = nextMode;
    alphaTradingDockPanel.previousMode = "none";
  }
  alphaTradingDockPanel.itemRects = [];
  alphaTradingDockPanel.panelRect = null;
  alphaTradingDockPanel.scrollMax = 0;
  if (nextMode !== prevTarget) alphaTradingDockPanel.scrollOffset = 0;
  if (alphaChartMenu) alphaChartMenu.hidden = true;
}

function alphaTradingDockPanelOpen(mode) {
  return isTradingPanelActive() && alphaTradingDockPanel.mode === mode;
}

function alphaTradingDockPanelAnimating() {
  return alphaTradingDockPanel.openProgress > 0.001
    || alphaTradingDockPanel.mode !== "none"
    || alphaTradingDockPanel.contentProgress < 0.999;
}

function alphaTradingDockPanelTick(now = performance.now()) {
  const dt = Math.max(0.001, Math.min(64, now - (alphaTradingDockPanel.lastTickAt || now)));
  alphaTradingDockPanel.lastTickAt = now;
  const openTarget = alphaTradingDockPanel.mode === "none" ? 0 : 1;
  const openEase = 1 - Math.exp(-dt / 120);
  const contentEase = 1 - Math.exp(-dt / 92);
  alphaTradingDockPanel.openProgress += (openTarget - alphaTradingDockPanel.openProgress) * openEase;
  alphaTradingDockPanel.contentProgress += (1 - alphaTradingDockPanel.contentProgress) * contentEase;
  if (Math.abs(alphaTradingDockPanel.openProgress - openTarget) < 0.002) {
    alphaTradingDockPanel.openProgress = openTarget;
  }
  if (Math.abs(alphaTradingDockPanel.contentProgress - 1) < 0.002) {
    alphaTradingDockPanel.contentProgress = 1;
    alphaTradingDockPanel.previousMode = "none";
  }
  if (alphaTradingDockPanel.mode === "none" && alphaTradingDockPanel.openProgress <= 0.002) {
    alphaTradingDockPanel.openProgress = 0;
    alphaTradingDockPanel.visualMode = "none";
    alphaTradingDockPanel.previousMode = "none";
    alphaTradingDockPanel.contentProgress = 1;
  }
}

function alphaTradingDockPanelModeUsesPriceRail(mode) {
  return mode === "price-axis" || mode === "price-ymetric-list" || mode === "settings-both";
}

function alphaTradingDockPanelModeUsesTimeRail(mode) {
  return mode === "time-axis" || mode === "time-zone-list" || mode === "time-xmetric-list" || mode === "settings-both";
}

function alphaTradingDockTimePanelExpandedHeight(cardH, mode) {
  if (mode === "time-zone-list") {
    return Math.max(ALPHA_TRADING_DOCK_TIMEZONE_PANEL_MIN_HEIGHT, Math.min(360, Math.round(cardH * 0.40)));
  }
  if (mode === "time-xmetric-list") {
    return Math.max(136, Math.min(220, Math.round(cardH * 0.24)));
  }
  return Math.max(ALPHA_TRADING_DOCK_TIME_PANEL_MIN_HEIGHT, Math.min(72, Math.round(cardH * 0.10)));
}

function alphaTradingBuildPanelItems(mode = alphaTradingDockPanel.mode) {
  if (mode === "price-axis") {
    const sideLabel = alphaTradingScalePrefs.priceAxisSide === "right"
      ? "Move scale to the left"
      : "Move scale to the right";
    const modeCheck = (name) => alphaTradingScalePrefs.scaleMode === name;
    return [
      { kind: "scale-action", value: "reset-price-scale", label: "Reset price scale", reset: true },
      { kind: "price-action", value: "open-y-metric-list", label: `Y axis: ${alphaTradingYAxisMetricLabel()}`, arrow: true },
      { kind: "scale-action", value: "auto-fit", label: "Auto fit", checked: alphaTradingScalePrefs.autoFit },
      { kind: "scale-action", value: "lock-price-bar-ratio", label: "Lock price / bar ratio", checked: alphaTradingScalePrefs.lockPriceBarRatio },
      { kind: "scale-action", value: "chart-only-scale", label: "Chart-only price scale", checked: alphaTradingScalePrefs.chartOnlyPriceScale },
      { kind: "scale-action", value: "invert-price-scale", label: "Invert scale", checked: alphaTradingScalePrefs.invertPriceScale },
      { kind: "scale-mode", value: "normal", label: "Normal", checked: modeCheck("normal") },
      { kind: "scale-mode", value: "percent", label: "Percent", checked: modeCheck("percent") },
      { kind: "scale-mode", value: "indexed", label: "Indexed to 100", checked: modeCheck("indexed") },
      { kind: "scale-mode", value: "logarithmic", label: "Logarithmic", checked: modeCheck("logarithmic") },
      { kind: "scale-action", value: "toggle-price-axis-side", label: sideLabel },
      { kind: "scale-action", value: "toggle-labels", label: "Labels", checked: alphaTradingScalePrefs.showPriceLabels },
      { kind: "scale-action", value: "toggle-lines", label: "Lines", checked: alphaTradingScalePrefs.showGridLines },
      { kind: "scale-action", value: "toggle-plus-button", label: "Plus button", checked: alphaTradingScalePrefs.showPlusButton },
    ];
  }
  if (mode === "time-axis") {
    return [
      { kind: "time-action", value: "reset-time-scale", label: "Reset time scale", reset: true },
      { kind: "time-action", value: "open-time-zone-list", label: `Time zone: ${alphaTradingTimeZoneLabel()}`, arrow: true },
      { kind: "time-action", value: "open-x-metric-list", label: `X axis: ${alphaTradingXAxisMetricLabel()}`, arrow: true },
      { kind: "time-action", value: "toggle-session-breaks", label: "Session breaks", checked: alphaTradingTimePrefs.showSessionBreaks },
      { kind: "time-action", value: "toggle-signal-markers", label: "Forge signal markers", checked: alphaTradingTimePrefs.showSignalMarkers },
    ];
  }
  if (mode === "time-xmetric-list") {
    return [
      { kind: "time-action", value: "back-to-time-axis", label: "X axis", back: true },
      { kind: "x-metric", value: "time", label: "Time", checked: alphaTradingAxisMetricPrefs.xMode === "time" },
      { kind: "x-metric", value: "volatility", label: "Cumulative volatility", checked: alphaTradingAxisMetricPrefs.xMode === "volatility" },
      { kind: "x-metric", value: "signal-density", label: "Forge signal density", checked: alphaTradingAxisMetricPrefs.xMode === "signal-density" },
      { kind: "x-metric", value: "regime", label: "Regime progression", checked: alphaTradingAxisMetricPrefs.xMode === "regime" },
    ];
  }
  if (mode === "price-ymetric-list") {
    return [
      { kind: "price-action", value: "back-to-price-axis", label: "Y axis", back: true },
      { kind: "y-metric", value: "price", label: "Price", checked: alphaTradingAxisMetricPrefs.yMode === "price" },
      { kind: "y-metric", value: "fair-gap", label: "Fair value gap", checked: alphaTradingAxisMetricPrefs.yMode === "fair-gap" },
      { kind: "y-metric", value: "conviction", label: "Conviction score", checked: alphaTradingAxisMetricPrefs.yMode === "conviction" },
      { kind: "y-metric", value: "anomaly", label: "Anomaly score", checked: alphaTradingAxisMetricPrefs.yMode === "anomaly" },
    ];
  }
  if (mode === "time-zone-list") {
    return [
      { kind: "time-action", value: "back-to-time-axis", label: "Time zone", back: true },
      ...ALPHA_TRADING_TIME_ZONES.map((entry) => ({
        kind: "time-zone",
        value: entry.id,
        label: entry.label,
        checked: alphaTradingTimePrefs.timeZone === entry.id,
      })),
    ];
  }
  return [];
}

function alphaTradingApplyTimeAction(action) {
  if (action === "reset-time-scale") {
    alphaTradingTimeScaleReset(alphaDocState);
    setAlphaTradingDockPanelMode("time-axis");
  } else if (action === "open-time-zone-list") {
    setAlphaTradingDockPanelMode("time-zone-list");
  } else if (action === "open-x-metric-list") {
    setAlphaTradingDockPanelMode("time-xmetric-list");
  } else if (action === "back-to-time-axis") {
    setAlphaTradingDockPanelMode("time-axis");
  } else if (action === "toggle-session-breaks") {
    alphaTradingTimePrefs.showSessionBreaks = !alphaTradingTimePrefs.showSessionBreaks;
    setAlphaTradingDockPanelMode("time-axis");
  } else if (action === "toggle-signal-markers") {
    alphaTradingTimePrefs.showSignalMarkers = !alphaTradingTimePrefs.showSignalMarkers;
    setAlphaTradingDockPanelMode("time-axis");
  }
  scheduleAlphaRender();
}

function alphaTradingApplyTimeZone(timeZoneId) {
  alphaTradingTimePrefs.timeZone = timeZoneId;
  setAlphaTradingDockPanelMode("time-zone-list");
  scheduleAlphaRender();
}

function alphaTradingApplyMetricSpace(mode = "classic") {
  alphaTradingMetricSpacePrefs.mode = mode || "classic";
  setAlphaTradingDockPanelMode("time-xmetric-list");
  scheduleAlphaRender();
}

function alphaTradingApplyXAxisMetric(mode = "time") {
  alphaTradingAxisMetricPrefs.xMode = mode || "time";
  setAlphaTradingDockPanelMode("time-xmetric-list");
  scheduleAlphaRender();
}

function alphaTradingApplyPriceAction(action = "") {
  if (action === "open-y-metric-list") {
    setAlphaTradingDockPanelMode("price-ymetric-list");
  } else if (action === "back-to-price-axis") {
    setAlphaTradingDockPanelMode("price-axis");
  }
  scheduleAlphaRender();
}

function alphaTradingApplyYAxisMetric(mode = "price") {
  alphaTradingAxisMetricPrefs.yMode = mode || "price";
  setAlphaTradingDockPanelMode("price-ymetric-list");
  scheduleAlphaRender();
}

function alphaTradingAddHorizontalLevel(value, label = "") {
  const price = Number(value);
  if (!Number.isFinite(price)) return;
  alphaTradingOverlayState.horizontalLevels.push({
    value: price,
    label: String(label || alphaFormatTradingPrice(price)),
  });
}

function alphaTradingApplyPlusAction(action = "") {
  const price = Number(alphaTradingPlusButtonState.price);
  const priceText = alphaTradingPlusButtonState.priceText || alphaFormatTradingPrice(price);
  const symbol = alphaTradingPlusButtonState.symbol || alphaTradingCurrentSymbol(alphaDocState);
  if (!Number.isFinite(price)) return;
  if (action === "draw-horizontal-line") {
    alphaTradingAddHorizontalLevel(price, priceText);
  } else if (action === "alert-price") {
    appendAlphaForge(`[trading] alert added on ${symbol} at ${priceText}`);
  } else if (action === "alert-vwap") {
    appendAlphaForge(`[trading] VWAP alert added on ${symbol} near ${priceText}`);
  } else if (action === "buy-limit") {
    appendAlphaForge(`[trading] draft order: buy 1 ${symbol} @ ${priceText} limit`);
  } else if (action === "sell-stop") {
    appendAlphaForge(`[trading] draft order: sell 1 ${symbol} @ ${priceText} stop`);
  } else if (action === "add-order") {
    appendAlphaForge(`[trading] draft order ticket opened for ${symbol} @ ${priceText}`);
  }
  hideAlphaChartMenu();
  scheduleAlphaRender();
}

function alphaTradingToggleSettingsPanels() {
  setAlphaTradingDockPanelMode(alphaTradingDockPanel.mode === "settings-both" ? "none" : "settings-both");
  scheduleAlphaRender();
}

function alphaTradingApplyScaleAction(scaleAction, scaleMode = "") {
  if (scaleMode) {
    if (scaleMode === "normal") {
      alphaTradingScalePrefs.scaleMode = "normal";
    } else {
      alphaTradingScalePrefs.scaleMode = alphaTradingScalePrefs.scaleMode === scaleMode
        ? "normal"
        : scaleMode;
    }
  } else if (scaleAction === "reset-price-scale" || scaleAction === "auto-fit") {
    alphaTradingScalePrefs.autoFit = true;
    alphaTradingScaleAutoFit(alphaDocState);
  } else if (scaleAction === "lock-price-bar-ratio") {
    alphaTradingScalePrefs.lockPriceBarRatio = !alphaTradingScalePrefs.lockPriceBarRatio;
  } else if (scaleAction === "chart-only-scale") {
    alphaTradingScalePrefs.chartOnlyPriceScale = !alphaTradingScalePrefs.chartOnlyPriceScale;
  } else if (scaleAction === "invert-price-scale") {
    alphaTradingScalePrefs.invertPriceScale = !alphaTradingScalePrefs.invertPriceScale;
  } else if (scaleAction === "toggle-price-axis-side") {
    alphaTradingScalePrefs.priceAxisSide = alphaTradingScalePrefs.priceAxisSide === "right" ? "left" : "right";
  } else if (scaleAction === "toggle-labels") {
    alphaTradingScalePrefs.showPriceLabels = !alphaTradingScalePrefs.showPriceLabels;
  } else if (scaleAction === "toggle-lines") {
    alphaTradingScalePrefs.showGridLines = !alphaTradingScalePrefs.showGridLines;
  } else if (scaleAction === "toggle-plus-button") {
    alphaTradingScalePrefs.showPlusButton = !alphaTradingScalePrefs.showPlusButton;
  }
  setAlphaTradingDockPanelMode("price-axis");
  scheduleAlphaRender();
}

function alphaTradingHandleDockPanelClick(x, y) {
  if (!alphaTradingDockPanel.panelRect) return false;
  const panel = alphaTradingDockPanel.panelRect;
  if (x < panel.left || x > panel.right || y < panel.top || y > panel.bottom) return false;
  const hit = alphaTradingDockPanel.itemRects.find((item) => x >= item.left && x <= item.right && y >= item.top && y <= item.bottom);
  if (!hit) return true;
  if (hit.kind === "time-zone") {
    alphaTradingApplyTimeZone(hit.value);
    return true;
  }
  if (hit.kind === "x-metric") {
    alphaTradingApplyXAxisMetric(hit.value);
    return true;
  }
  if (hit.kind === "y-metric") {
    alphaTradingApplyYAxisMetric(hit.value);
    return true;
  }
  if (hit.kind === "price-action") {
    alphaTradingApplyPriceAction(hit.value);
    return true;
  }
  if (hit.kind === "time-action") {
    alphaTradingApplyTimeAction(hit.value);
    return true;
  }
  if (hit.kind === "scale-mode") {
    alphaTradingApplyScaleAction("", hit.value);
    return true;
  }
  if (hit.kind === "scale-action") {
    alphaTradingApplyScaleAction(hit.value);
    return true;
  }
  return true;
}

function alphaTradingScaleAutoFit(doc = alphaDocState) {
  alphaTradingViewport.initialized = false;
  alphaTradingViewportEnsure(doc, { forceFit: true });
}

function alphaTradingTimeScaleReset(doc = alphaDocState) {
  const { candles, lastTime, count } = alphaTradingViewportCandleMeta(doc);
  alphaTradingViewport.visibleBars = alphaTradingClampVisibleBars(
    Math.max(40, Math.min(600, Number(doc?.candleViewCount || 200) || 200)),
    count,
  );
  alphaTradingViewport.timeStepMs = Math.max(1000, alphaInferCandleStepMs(candles));
  alphaTradingViewport.timeEndMs = Number.isFinite(lastTime)
    ? lastTime + alphaTradingViewportFutureSlots(alphaTradingViewport.visibleBars) * alphaTradingViewport.timeStepMs
    : Date.now();
  alphaTradingViewport.initialized = true;
}

function renderAlphaChartMenu(mode = "chart") {
  if (!alphaChartMenu) return;
  alphaChartMenuMode = mode;
  if (mode === "price-plus") {
    const priceText = alphaTradingPlusButtonState.priceText || alphaFormatTradingPrice(alphaTradingPlusButtonState.price);
    const symbol = alphaTradingPlusButtonState.symbol || alphaTradingCurrentSymbol(alphaDocState);
    alphaChartMenu.classList.add("trading-scale-menu");
    alphaChartMenu.innerHTML = `
      <button type="button" class="chart-menu-item" data-plus-action="alert-price">
        <span class="chart-menu-check"></span>
        <span class="chart-menu-label">Ajouter une alerte sur ${symbol} à ${priceText}</span>
      </button>
      <button type="button" class="chart-menu-item" data-plus-action="alert-vwap">
        <span class="chart-menu-check"></span>
        <span class="chart-menu-label">Ajouter une alerte sur VWAP à ${priceText}</span>
      </button>
      <button type="button" class="chart-menu-item" data-plus-action="buy-limit">
        <span class="chart-menu-check"></span>
        <span class="chart-menu-label">Acheter 1 ${symbol} @ ${priceText} limite</span>
      </button>
      <button type="button" class="chart-menu-item" data-plus-action="sell-stop">
        <span class="chart-menu-check"></span>
        <span class="chart-menu-label">Vendre 1 ${symbol} @ ${priceText} stop</span>
      </button>
      <button type="button" class="chart-menu-item" data-plus-action="add-order">
        <span class="chart-menu-check"></span>
        <span class="chart-menu-label">Ajouter un ordre sur ${symbol} à ${priceText}</span>
      </button>
      <button type="button" class="chart-menu-item" data-plus-action="draw-horizontal-line">
        <span class="chart-menu-check"></span>
        <span class="chart-menu-label">Tracer une ligne horizontale à ${priceText}</span>
      </button>
    `;
    return;
  }
  if (mode === "price-axis") {
    const sideLabel = alphaTradingScalePrefs.priceAxisSide === "right"
      ? "Move scale to the left"
      : "Move scale to the right";
    const check = (on) => on ? "true" : "false";
    const modeCheck = (name) => alphaTradingScalePrefs.scaleMode === name;
    alphaChartMenu.classList.add("trading-scale-menu");
    alphaChartMenu.innerHTML = `
      <button type="button" class="chart-menu-item" data-scale-action="reset-price-scale">
        <span class="chart-menu-check">${check(false) === "true" ? "✓" : ""}</span>
        <span class="chart-menu-label">Reset price scale</span>
      </button>
      <button type="button" class="chart-menu-item" data-scale-action="auto-fit">
        <span class="chart-menu-check">${alphaTradingScalePrefs.autoFit ? "✓" : ""}</span>
        <span class="chart-menu-label">Auto fit</span>
      </button>
      <button type="button" class="chart-menu-item" data-scale-action="lock-price-bar-ratio">
        <span class="chart-menu-check">${alphaTradingScalePrefs.lockPriceBarRatio ? "✓" : ""}</span>
        <span class="chart-menu-label">Lock price / bar ratio</span>
      </button>
      <button type="button" class="chart-menu-item" data-scale-action="chart-only-scale">
        <span class="chart-menu-check">${alphaTradingScalePrefs.chartOnlyPriceScale ? "✓" : ""}</span>
        <span class="chart-menu-label">Chart-only price scale</span>
      </button>
      <button type="button" class="chart-menu-item" data-scale-action="invert-price-scale">
        <span class="chart-menu-check">${alphaTradingScalePrefs.invertPriceScale ? "✓" : ""}</span>
        <span class="chart-menu-label">Invert scale</span>
      </button>
      <button type="button" class="chart-menu-item" data-scale-mode="normal">
        <span class="chart-menu-check">${modeCheck("normal") ? "✓" : ""}</span>
        <span class="chart-menu-label">Normal</span>
      </button>
      <button type="button" class="chart-menu-item" data-scale-mode="percent">
        <span class="chart-menu-check">${modeCheck("percent") ? "✓" : ""}</span>
        <span class="chart-menu-label">Percent</span>
      </button>
      <button type="button" class="chart-menu-item" data-scale-mode="indexed">
        <span class="chart-menu-check">${modeCheck("indexed") ? "✓" : ""}</span>
        <span class="chart-menu-label">Indexed to 100</span>
      </button>
      <button type="button" class="chart-menu-item" data-scale-mode="logarithmic">
        <span class="chart-menu-check">${modeCheck("logarithmic") ? "✓" : ""}</span>
        <span class="chart-menu-label">Logarithmic</span>
      </button>
      <button type="button" class="chart-menu-item" data-scale-action="toggle-price-axis-side">
        <span class="chart-menu-check"></span>
        <span class="chart-menu-label">${sideLabel}</span>
      </button>
      <button type="button" class="chart-menu-item" data-scale-action="toggle-labels">
        <span class="chart-menu-check">${alphaTradingScalePrefs.showPriceLabels ? "✓" : ""}</span>
        <span class="chart-menu-label">Labels</span>
      </button>
      <button type="button" class="chart-menu-item" data-scale-action="toggle-lines">
        <span class="chart-menu-check">${alphaTradingScalePrefs.showGridLines ? "✓" : ""}</span>
        <span class="chart-menu-label">Lines</span>
      </button>
      <button type="button" class="chart-menu-item" data-scale-action="toggle-plus-button">
        <span class="chart-menu-check">${alphaTradingScalePrefs.showPlusButton ? "✓" : ""}</span>
        <span class="chart-menu-label">Plus button</span>
      </button>
    `;
    return;
  }
  if (mode === "time-axis") {
    alphaChartMenu.classList.add("trading-scale-menu");
    alphaChartMenu.innerHTML = `
      <button type="button" class="chart-menu-item" data-time-action="reset-time-scale">
        <span class="chart-menu-check"></span>
        <span class="chart-menu-label">Reset time scale</span>
      </button>
      <button type="button" class="chart-menu-item chart-menu-item-arrow" data-time-action="open-time-zone-list">
        <span class="chart-menu-check"></span>
        <span class="chart-menu-label">Time zone: ${alphaTradingTimeZoneLabel()}</span>
      </button>
      <button type="button" class="chart-menu-item" data-time-action="toggle-session-breaks">
        <span class="chart-menu-check">${alphaTradingTimePrefs.showSessionBreaks ? "✓" : ""}</span>
        <span class="chart-menu-label">Session breaks</span>
      </button>
    `;
    return;
  }
  if (mode === "time-zone-list") {
    alphaChartMenu.classList.add("trading-scale-menu", "trading-timezone-menu");
    alphaChartMenu.innerHTML = `
      <button type="button" class="chart-menu-item chart-menu-item-back" data-time-action="back-to-time-axis">
        <span class="chart-menu-check"></span>
        <span class="chart-menu-label">Time zone</span>
      </button>
      ${ALPHA_TRADING_TIME_ZONES.map((entry) => `
        <button type="button" class="chart-menu-item" data-time-zone-id="${entry.id}">
          <span class="chart-menu-check">${alphaTradingTimePrefs.timeZone === entry.id ? "✓" : ""}</span>
          <span class="chart-menu-label">${entry.label}</span>
        </button>
      `).join("")}
    `;
    return;
  }
  alphaChartMenu.classList.remove("trading-scale-menu", "trading-timezone-menu");
  alphaChartMenu.innerHTML = `
    <button type="button" data-action="reset-chart">Reinitialiser le graphique</button>
  `;
}

function showAlphaChartMenu(x, y, mode = "chart") {
  if (mode === "price-axis" || mode === "time-axis" || mode === "time-zone-list" || mode === "time-xmetric-list" || mode === "price-ymetric-list" || mode === "settings-both") {
    setAlphaTradingDockPanelMode(mode);
    scheduleAlphaRender();
    return;
  }
  if (!alphaChartMenu) return;
  renderAlphaChartMenu(mode);
  alphaChartMenu.hidden = false;
  const rect = alphaChartMenu.getBoundingClientRect();
  const left = Math.min(x, window.innerWidth - rect.width - 8);
  const top = Math.min(y, window.innerHeight - rect.height - 8);
  alphaChartMenu.style.left = `${Math.max(8, left)}px`;
  alphaChartMenu.style.top = `${Math.max(8, top)}px`;
}

function alphaTradingDockPanelFallbackBounds(zones = getAlphaChartInteractionZones()) {
  if (alphaTradingDockPanel.panelRect) return alphaTradingDockPanel.panelRect;
  if (!zones) return null;
  if (alphaTradingDockPanel.mode === "settings-both") {
    const parts = [zones.timePanel, zones.pricePanel].filter(Boolean);
    if (!parts.length) return null;
    return {
      left: Math.min(...parts.map((part) => part.left)),
      top: Math.min(...parts.map((part) => part.top)),
      right: Math.max(...parts.map((part) => part.right)),
      bottom: Math.max(...parts.map((part) => part.bottom)),
    };
  }
  return alphaTradingDockPanel.mode === "price-axis" ? zones.pricePanel : zones.timePanel;
}

function drawAlphaTradingDockPanel(zones) {
  const mode = alphaTradingDockPanel.visualMode;
  if (!isTradingPanelActive() || mode === "none" || alphaTradingDockPanel.openProgress <= 0.001) return;
  const basePanel = mode === "price-axis" ? zones.pricePanel : zones.timePanel;
  if (mode !== "settings-both" && !basePanel) return;

  const openT = alphaTradingDockPanel.openProgress;
  const contentT = alphaTradingDockPanel.contentProgress;
  const prevMode = alphaTradingDockPanel.previousMode;
  alphaTradingDockPanel.itemRects = [];
  alphaTradingDockPanel.panelRect = null;

  function registerPanelRect(left, top, right, bottom) {
    if (!alphaTradingDockPanel.panelRect) {
      alphaTradingDockPanel.panelRect = { left, top, right, bottom };
      return;
    }
    alphaTradingDockPanel.panelRect.left = Math.min(alphaTradingDockPanel.panelRect.left, left);
    alphaTradingDockPanel.panelRect.top = Math.min(alphaTradingDockPanel.panelRect.top, top);
    alphaTradingDockPanel.panelRect.right = Math.max(alphaTradingDockPanel.panelRect.right, right);
    alphaTradingDockPanel.panelRect.bottom = Math.max(alphaTradingDockPanel.panelRect.bottom, bottom);
  }

  function panelWidth(panel) {
    return Math.max(80, panel.right - panel.left);
  }

  function drawResetIcon(cx, cy, radius, alphaScale) {
    alphaCtx.save();
    alphaCtx.strokeStyle = `rgba(214,234,232,${0.90 * alphaScale})`;
    alphaCtx.lineWidth = 1.45;
    alphaCtx.lineCap = "round";
    alphaCtx.lineJoin = "round";
    alphaCtx.beginPath();
    alphaCtx.arc(cx, cy, radius, Math.PI * 0.30, Math.PI * 1.92);
    alphaCtx.stroke();
    alphaCtx.beginPath();
    alphaCtx.moveTo(cx + radius * 0.42, cy - radius * 1.02);
    alphaCtx.lineTo(cx + radius * 1.16, cy - radius * 0.96);
    alphaCtx.lineTo(cx + radius * 0.82, cy - radius * 0.28);
    alphaCtx.stroke();
    alphaCtx.restore();
  }

  function drawItemText(item, x, y, w, h, alphaScale) {
    const markColumnX = x;
    const labelColumnX = x + 20;
    alphaCtx.font = item.reset
      ? '700 13px Geist, "Segoe UI", sans-serif'
      : '600 13px Geist, "Segoe UI", sans-serif';
    alphaCtx.textBaseline = "middle";
    alphaCtx.textAlign = "left";
    if (item.reset) {
      drawResetIcon(markColumnX + 12, y + h * 0.5, 9, alphaScale);
      alphaCtx.fillStyle = `rgba(244,244,238,${0.96 * alphaScale})`;
      alphaCtx.fillText(item.label, labelColumnX + 8, y + h * 0.5);
      return;
    }
    if (item.checked) {
      alphaCtx.fillStyle = `rgba(166,232,222,${0.90 * alphaScale})`;
      alphaCtx.fillText("✓", markColumnX, y + h * 0.5);
    }
    alphaCtx.fillStyle = `rgba(244,244,238,${0.95 * alphaScale})`;
    alphaCtx.fillText(item.label, labelColumnX, y + h * 0.5);
    if (item.arrow) {
      alphaCtx.textAlign = "right";
      alphaCtx.fillText("›", x + w, y + h * 0.5);
      alphaCtx.textAlign = "left";
    } else if (item.back) {
      alphaCtx.fillStyle = `rgba(190,223,220,${0.90 * alphaScale})`;
      alphaCtx.font = '700 20px Geist, "Segoe UI", sans-serif';
      alphaCtx.fillText("‹", markColumnX - 2, y + h * 0.5);
      alphaCtx.font = '700 13px Geist, "Segoe UI", sans-serif';
      alphaCtx.fillStyle = `rgba(244,244,238,${0.95 * alphaScale})`;
      alphaCtx.fillText(item.label, labelColumnX, y + h * 0.5);
    }
  }

  function drawVerticalList(panel, listMode, alphaScale, translateX = 0, translateY = 0, interactive = false) {
    if (!panel) return;
    const pW = panelWidth(panel);
    if (listMode === "time-zone-list") {
      const groups = alphaTradingTimeZoneGroups();
      const outerLeft = panel.left + 18 + translateX;
      const outerTop = panel.top + 10 + translateY;
      const outerRight = panel.right - 18;
      const colGap = 28;
      const colCount = Math.max(1, groups.length);
      const colW = Math.max(150, Math.floor((Math.max(1, outerRight - outerLeft) - colGap * (colCount - 1)) / colCount));
      const headerH = 30;
      const titleGap = 20;
      const rowH = 24;
      const backTop = outerTop;
      const backLeft = outerLeft;
      const backW = Math.min(220, Math.max(150, colW));
      drawItemText({ kind: "time-action", value: "back-to-time-axis", label: "Time zone", back: true }, backLeft, backTop, backW, headerH, alphaScale);
      registerPanelRect(backLeft - 2, backTop - 2, backLeft + backW + 2, backTop + headerH + 2);
      if (interactive) {
        alphaTradingDockPanel.itemRects.push({
          left: backLeft - 2,
          right: backLeft + backW + 2,
          top: backTop - 2,
          bottom: backTop + headerH + 2,
          kind: "time-action",
          value: "back-to-time-axis",
        });
      }
      const columnsTop = outerTop + headerH + 14;
      alphaTradingDockPanel.scrollMax = 0;
      alphaTradingDockPanel.scrollOffset = 0;
      for (let gi = 0; gi < groups.length; gi += 1) {
        const group = groups[gi];
        const colLeft = outerLeft + gi * (colW + colGap);
        alphaCtx.save();
        alphaCtx.globalAlpha = alphaScale;
        alphaCtx.font = '700 11px "SF Mono", Consolas, monospace';
        alphaCtx.textBaseline = "top";
        alphaCtx.textAlign = "left";
        alphaCtx.fillStyle = "rgba(176,226,220,0.72)";
        alphaCtx.fillText(group.label, colLeft, columnsTop);
        alphaCtx.strokeStyle = "rgba(255,255,255,0.08)";
        alphaCtx.lineWidth = 1;
        alphaCtx.beginPath();
        alphaCtx.moveTo(colLeft, columnsTop + 16);
        alphaCtx.lineTo(colLeft + colW, columnsTop + 16);
        alphaCtx.stroke();
        alphaCtx.restore();
        for (let ei = 0; ei < group.entries.length; ei += 1) {
          const entry = group.entries[ei];
          const rowY = columnsTop + titleGap + ei * rowH;
          drawItemText({
            kind: "time-zone",
            value: entry.id,
            label: entry.label,
            checked: alphaTradingTimePrefs.timeZone === entry.id,
          }, colLeft, rowY, colW, rowH, alphaScale);
          registerPanelRect(colLeft - 2, rowY - 2, colLeft + colW + 2, rowY + rowH + 2);
          if (interactive) {
            alphaTradingDockPanel.itemRects.push({
              left: colLeft - 2,
              right: colLeft + colW + 2,
              top: rowY - 2,
              bottom: rowY + rowH + 2,
              kind: "time-zone",
              value: entry.id,
            });
          }
        }
      }
      return;
    }
    const listItems = alphaTradingBuildPanelItems(listMode);
    const railLeft = panel.left + 18 + translateX;
    const railTop = panel.top + 14 + translateY;
    const railWidth = Math.max(162, pW - 34);
    const rowH = 26;
    const gap = 5;
    const startY = railTop;
    const visibleHeight = Math.max(40, panel.bottom - startY - 8);
    alphaCtx.save();
    alphaCtx.beginPath();
    alphaCtx.rect(panel.left, startY - 2, pW, visibleHeight + 4);
    alphaCtx.clip();
    for (let index = 0; index < listItems.length; index += 1) {
      const item = listItems[index];
      const rowY = startY + index * (rowH + gap);
      const rowX = railLeft;
      const rowW = railWidth;
      alphaCtx.strokeStyle = item.reset
        ? `rgba(176,226,220,${0.24 * alphaScale})`
        : `rgba(255,255,255,${0.07 * alphaScale})`;
      alphaCtx.lineWidth = 1;
      alphaCtx.beginPath();
      alphaCtx.moveTo(rowX, rowY + rowH + 1);
      alphaCtx.lineTo(rowX + rowW, rowY + rowH + 1);
      alphaCtx.stroke();
      drawItemText(item, rowX, rowY, rowW, rowH, alphaScale);
      registerPanelRect(rowX - 2, rowY - 2, rowX + rowW + 2, rowY + rowH + 2);
      if (interactive) {
        alphaTradingDockPanel.itemRects.push({
          left: rowX - 2,
          right: rowX + rowW + 2,
          top: rowY - 2,
          bottom: rowY + rowH + 2,
          kind: item.kind,
          value: item.value,
        });
      }
    }
    alphaCtx.restore();
  }

  function drawHorizontalStrip(panel, stripMode, alphaScale, translateY = 0, interactive = false) {
    if (!panel) return;
    const stripItems = alphaTradingBuildPanelItems(stripMode);
    const stripLeft = panel.left + 12;
    const stripTop = panel.top + 8 + translateY;
    let cursorX = stripLeft;
    const rowH = 24;
    for (const item of stripItems) {
      alphaCtx.font = item.reset
        ? '700 13px Geist, "Segoe UI", sans-serif'
        : '600 13px Geist, "Segoe UI", sans-serif';
      const chipW = item.reset
        ? Math.max(118, Math.min(220, alphaCtx.measureText(item.label).width + 34))
        : Math.max(112, Math.min(240, alphaCtx.measureText(item.label).width + 20 + (item.arrow ? 12 : 0) + (item.checked ? 18 : 0)));
      const chipX = cursorX;
      const chipY = stripTop;
      drawItemText(item, chipX, chipY, chipW, rowH, alphaScale);
      registerPanelRect(chipX - 2, chipY - 2, chipX + chipW + 2, chipY + rowH + 2);
      if (interactive) {
        alphaTradingDockPanel.itemRects.push({
          left: chipX - 2,
          right: chipX + chipW + 2,
          top: chipY - 2,
          bottom: chipY + rowH + 2,
          kind: item.kind,
          value: item.value,
        });
      }
      if (item !== stripItems[stripItems.length - 1]) {
        alphaCtx.strokeStyle = `rgba(255,255,255,${0.08 * alphaScale})`;
        alphaCtx.lineWidth = 1;
        alphaCtx.beginPath();
        alphaCtx.moveTo(chipX + chipW + 10, chipY + 4);
        alphaCtx.lineTo(chipX + chipW + 10, chipY + rowH - 4);
        alphaCtx.stroke();
      }
      cursorX += chipW + 24;
    }
  }

  function drawPanelSeam(panel, seamMode, alphaScale = 1) {
    if (!panel) return;
    alphaCtx.save();
    alphaCtx.strokeStyle = seamMode === "price"
      ? `rgba(172,231,223,${0.14 * alphaScale})`
      : `rgba(172,231,223,${0.10 * alphaScale})`;
    alphaCtx.lineWidth = 1;
    alphaCtx.beginPath();
    if (seamMode === "price") {
      const seamX = alphaTradingScalePrefs.priceAxisSide === "right" ? panel.left + 0.5 : panel.right - 0.5;
      alphaCtx.moveTo(seamX, panel.top + 10);
      alphaCtx.lineTo(seamX, panel.bottom - 10);
    } else {
      const seamY = panel.bottom - 0.5;
      alphaCtx.moveTo(panel.left + 12, seamY);
      alphaCtx.lineTo(panel.right - 12, seamY);
    }
    alphaCtx.stroke();
    alphaCtx.restore();
  }

  if (mode === "settings-both") {
    if (zones.timePanel) {
      drawPanelSeam(zones.timePanel, "time", openT);
      drawHorizontalStrip(zones.timePanel, "time-axis", openT * contentT, 8 * (1 - contentT), true);
    }
    if (zones.pricePanel) {
      drawPanelSeam(zones.pricePanel, "price", openT);
      drawVerticalList(zones.pricePanel, "price-axis", openT * contentT, 8 * (1 - contentT), 0, true);
    }
    if (!alphaTradingDockPanel.panelRect) {
      alphaTradingDockPanel.panelRect = alphaTradingDockPanelFallbackBounds(zones);
    }
    return;
  }

  drawPanelSeam(basePanel, mode === "price-axis" || mode === "price-ymetric-list" ? "price" : "time");

  const sameRailTransition = (
    (alphaTradingDockPanelModeUsesPriceRail(prevMode) && alphaTradingDockPanelModeUsesPriceRail(mode))
    || (alphaTradingDockPanelModeUsesTimeRail(prevMode) && alphaTradingDockPanelModeUsesTimeRail(mode))
  );
  if (sameRailTransition && prevMode !== "none" && prevMode !== mode && contentT < 0.999) {
    if (prevMode === "time-axis") drawHorizontalStrip(basePanel, prevMode, 1 - contentT, -8 * contentT, false);
    else if (prevMode === "time-zone-list" || prevMode === "time-xmetric-list") drawVerticalList(basePanel, prevMode, 1 - contentT, 0, -10 * contentT, false);
    else if (prevMode === "price-axis" || prevMode === "price-ymetric-list") drawVerticalList(basePanel, prevMode, 1 - contentT, 8 * contentT, 0, false);
  }

  if (mode === "time-axis") {
    drawHorizontalStrip(basePanel, mode, openT * contentT, 8 * (1 - contentT), true);
  } else if (mode === "time-zone-list" || mode === "time-xmetric-list") {
    drawVerticalList(basePanel, mode, openT * contentT, 0, 10 * (1 - contentT), true);
  } else {
    drawVerticalList(basePanel, mode, openT * contentT, 8 * (1 - contentT), 0, true);
  }

  if (!alphaTradingDockPanel.panelRect) {
    alphaTradingDockPanel.panelRect = {
      left: basePanel.left,
      top: basePanel.top,
      right: basePanel.right,
      bottom: basePanel.bottom,
    };
  }
}

alphaLogLayer.addEventListener("contextmenu", (event) => {
  event.preventDefault();
  showAlphaLogMenu(event.clientX, event.clientY);
});

alphaLogLayer.addEventListener("scroll", () => {
  // Programmatic scrolls bump alphaTranscriptProgrammaticScrollAt — give them a
  // short window so we don't mistake our own scroll for a user gesture.
  if (performance.now() - alphaTranscriptProgrammaticScrollAt > 80) {
    alphaTranscriptStickToBottom = alphaTranscriptIsNearBottom();
  }
  scheduleAlphaRender();
  if (alpha3dState?.open) scheduleAlpha3dRender();
}, { passive: true });

alphaLogLayer.addEventListener("click", (event) => {
  const button = event.target?.closest?.("[data-compute-action]");
  if (!button) return;
  event.preventDefault();
  void handleComputeTranscriptAction(button.dataset.computeAction);
});

alphaProofPanel?.addEventListener("click", (event) => {
  const modeButton = event.target?.closest?.("[data-right-panel-mode]");
  if (modeButton) {
    event.preventDefault();
    setAlphaRightPanelMode(modeButton.dataset.rightPanelMode || "proof");
    return;
  }
  const languageButton = event.target?.closest?.("[data-console-language]");
  if (languageButton) {
    event.preventDefault();
    const nextLanguage = String(languageButton.dataset.consoleLanguage || "rust").toLowerCase();
    alphaConsoleState.language = nextLanguage === "kasm" ? "kasm" : nextLanguage === "pine" ? "pine" : "rust";
    alphaConsoleRenderedKey = "";
    renderAlphaConsolePanel();
    return;
  }
  const consoleButton = event.target?.closest?.("[data-console-action]");
  if (consoleButton) {
    event.preventDefault();
    if (consoleButton.dataset.consoleAction === "console-template") {
      const draft = currentAlphaConsoleDraft();
      const template = alphaConsolePlaceholder(alphaConsoleState.language);
      setCurrentAlphaConsoleDraft(draft.trim() ? `${draft.replace(/\s+$/u, "")}\n\n${template}` : template);
    } else if (consoleButton.dataset.consoleAction === "console-insert-context") {
      const draft = currentAlphaConsoleDraft();
      const contextBlock = alphaConsoleContextInsertion(alphaConsoleState.language);
      setCurrentAlphaConsoleDraft(draft.trim() ? `${draft.replace(/\s+$/u, "")}\n\n${contextBlock}` : contextBlock);
    } else if (consoleButton.dataset.consoleAction === "console-prepare") {
      prepareAlphaConsoleRun();
    } else if (consoleButton.dataset.consoleAction === "console-run") {
      void runAlphaConsole();
      return;
    } else if (consoleButton.dataset.consoleAction === "console-clear") {
      setCurrentAlphaConsoleDraft("");
      alphaConsoleState.output = "";
      alphaConsoleState.outputKind = "idle";
      alphaConsoleState.lastPreparedHash = "";
    }
    renderAlphaConsolePanel();
    return;
  }
  const webExplorerProofButton = event.target?.closest?.("[data-webexplorer-proof-action]");
  if (webExplorerProofButton) {
    event.preventDefault();
    const action = String(webExplorerProofButton.dataset.webexplorerProofAction || "");
    if (action === "refresh") {
      invalidateWebExplorerProofPanel();
      void refreshWebExplorerRendererProbe(true);
      void refreshWebExplorerMemorySnapshot();
    } else if (action === "copy-digest") {
      const digest = webExplorerProofDigest();
      void navigator.clipboard?.writeText?.(digest).catch(() => {});
    }
    return;
  }
  const button = event.target?.closest?.("[data-compute-action]");
  if (!button) return;
  event.preventDefault();
  void handleComputeTranscriptAction(button.dataset.computeAction);
});

alphaProofPanel?.addEventListener("input", (event) => {
  const field = event.target?.dataset?.consoleField;
  if (field === "script") {
    setCurrentAlphaConsoleDraft(event.target.value || "");
    return;
  }
});

alphaLogMenu.addEventListener("click", async (event) => {
  const action = event.target?.dataset?.action;
  if (action === "copy") {
    await copyAlphaLogsFromMenu();
    hideAlphaLogMenu();
  } else if (action === "select-all") {
    selectAllAlphaLogs();
    hideAlphaLogMenu();
  }
});

alphaChartMenu?.addEventListener("click", (event) => {
  const plusAction = event.target?.closest?.("[data-plus-action]")?.dataset?.plusAction;
  if (plusAction) {
    alphaTradingApplyPlusAction(plusAction);
    return;
  }
  const timeZoneId = event.target?.closest?.("[data-time-zone-id]")?.dataset?.timeZoneId;
  if (timeZoneId) {
    alphaTradingApplyTimeZone(timeZoneId);
    return;
  }
  const timeAction = event.target?.closest?.("[data-time-action]")?.dataset?.timeAction;
  if (timeAction) {
    alphaTradingApplyTimeAction(timeAction);
    return;
  }
  const scaleAction = event.target?.closest?.("[data-scale-action]")?.dataset?.scaleAction;
  const scaleMode = event.target?.closest?.("[data-scale-mode]")?.dataset?.scaleMode;
  if (scaleAction || scaleMode) {
    alphaTradingApplyScaleAction(scaleAction || "", scaleMode || "");
    return;
  }
  const action = event.target?.dataset?.action;
  if (action !== "reset-chart") return;
  resetAlphaChartViewport(alphaDocState);
  hideAlphaChartMenu();
  scheduleAlphaRender();
});

