// ── Wheel zoom ────────────────────────────────────────────────────
alphaCanvas.addEventListener("wheel", (e) => {
  const rect = alphaCanvas.getBoundingClientRect();
  const x = e.clientX - rect.left;
  const y = e.clientY - rect.top;
  const zones = getAlphaChartInteractionZones();
  const dockPanel = alphaTradingDockPanelFallbackBounds(zones);
  const inDockPanel = !!dockPanel
    && x >= dockPanel.left && x <= dockPanel.right
    && y >= dockPanel.top && y <= dockPanel.bottom;
  if (alphaTradingDockPanel.mode === "time-zone-list" && inDockPanel && alphaTradingDockPanel.scrollMax > 0) {
    e.preventDefault();
    alphaTradingDockPanel.scrollOffset = Math.max(
      0,
      Math.min(alphaTradingDockPanel.scrollMax, alphaTradingDockPanel.scrollOffset + e.deltaY),
    );
    scheduleAlphaRender();
    return;
  }
  const inPlot = x >= zones.plot.left && x <= zones.plot.right && y >= zones.plot.top && y <= zones.plot.bottom;
  const inTimeAxis = x >= zones.timeAxis.left && x <= zones.timeAxis.right && y >= zones.timeAxis.top && y <= zones.timeAxis.bottom;
  if (!inPlot && !inTimeAxis) return;
  e.preventDefault();
  const tradingSurface = isTradingPanelActive();
  const isLikelyTrackpadPan = tradingSurface
    && !e.ctrlKey
    && !e.metaKey
    && !e.altKey
    && (
      Math.abs(e.deltaX) > 0.1
      || (Math.abs(e.deltaY) > 0.1 && Math.abs(e.deltaY) < 24)
    );
  if (isLikelyTrackpadPan) {
    const viewport = alphaTradingResolveViewport(alphaDocState);
    const dominantDelta = Math.abs(e.deltaX) > Math.abs(e.deltaY) ? e.deltaX : e.deltaY;
    const pixelsPerBar = Math.max(6, Math.min(48, zones.plot.width / Math.max(8, viewport.visibleBars)));
    const shiftBars = dominantDelta / pixelsPerBar;
    alphaTradingViewport.timeEndMs += shiftBars * viewport.stepMs;
    if (alphaTradingScalePrefs.autoFit) alphaTradingAutoFitVisiblePriceRange(alphaDocState);
    scheduleAlphaRender();
    return;
  }
  const anchorRatio = tradingSurface
    ? (x - zones.timeAxis.left) / Math.max(1, zones.timeAxis.right - zones.timeAxis.left)
    : (x - zones.plot.left) / Math.max(1, zones.plot.width);
  const smoothFactor = Math.exp((tradingSurface ? -1 : 1) * e.deltaY * 0.0016);
  const f = Math.max(0.92, Math.min(1.09, smoothFactor));
  if (tradingSurface) {
    alphaTradingZoomTimeAtRatio(anchorRatio, f, alphaDocState);
    if (alphaTradingScalePrefs.autoFit) alphaTradingAutoFitVisiblePriceRange(alphaDocState);
  }
  else {
    if (!alphaDocState.candles.length) return;
    zoomCandleDocAtRatio(alphaDocState, anchorRatio, f);
  }
  scheduleAlphaRender();
}, { passive: false });

// ── Drag pan + hover ──────────────────────────────────────────────
let alphaDragStartX = 0, alphaDragStartEnd = 0, alphaDragging = false;
let alphaDragStartY = 0;
let alphaDragStartPricePan = 0;
let alphaDragStartTimeEndMs = 0;
let alphaDragStartPriceMin = 0;
let alphaDragStartPriceMax = 1;
let alphaChartPointerMoved = false;
let alphaTradingSelectionActive = false;
let alphaTradingSelectionStartX = 0;
let alphaTradingSelectionStartY = 0;
let alphaTradingSelectionEndX = 0;
let alphaTradingSelectionEndY = 0;
let alphaPriceScaleDragging = false;
let alphaPriceScaleStartY = 0;
let alphaPriceZoomStart = 1;
let alphaPriceScaleStartMin = 0;
let alphaPriceScaleStartMax = 1;
let alphaTimeScaleDragging = false;
let alphaTimeScaleStartX = 0;
let alphaTimeScaleStartCount = 200;
let alphaTimeScaleAnchorRatio = 0.5;

function alphaPriceScaleHandleHit(zones, x, y) {
  const handleWidth = Math.max(14, Math.min(22, zones.priceAxis.right - zones.priceAxis.left));
  return x >= (zones.priceAxis.right - handleWidth)
    && x <= zones.priceAxis.right
    && y >= zones.priceAxis.top
    && y <= zones.priceAxis.bottom;
}

function alphaTimeScaleHandleHit(zones, x, y) {
  const handleHeight = Math.max(10, Math.min(16, zones.timeAxis.bottom - zones.timeAxis.top));
  return x >= zones.timeAxis.left
    && x <= zones.timeAxis.right
    && y >= zones.timeAxis.top
    && y <= (zones.timeAxis.top + handleHeight);
}

function alphaTradingCandleTimeAnchor(granularity = "", timeMs = Date.now()) {
  const tf = String(granularity || "").trim().toUpperCase();
  const date = new Date(Number(timeMs) || Date.now());
  if (tf === "D" || tf === "W") {
    const yyyy = date.getFullYear();
    const mm = String(date.getMonth() + 1).padStart(2, "0");
    const dd = String(date.getDate()).padStart(2, "0");
    return `${yyyy}-${mm}-${dd}`;
  }
  const hour24 = date.getHours();
  const minutes = date.getMinutes();
  const suffix = hour24 >= 12 ? "pm" : "am";
  const hour12 = hour24 % 12 || 12;
  return minutes ? `${hour12}${String(minutes).padStart(2, "0")}${suffix}` : `${hour12}${suffix}`;
}

function alphaTradingCandleSlashToken(granularity = "", timeMs = Date.now()) {
  const tf = String(granularity || "").trim().toLowerCase() || "h4";
  return `/candle${tf}-${alphaTradingCandleTimeAnchor(granularity, timeMs)}`;
}

function alphaTradingResolveVisibleCandleHit(clientX, clientY, doc = alphaDocState) {
  if (!isTradingPanelActive()) return null;
  const rect = alphaCanvas.getBoundingClientRect();
  const zones = getAlphaChartInteractionZones();
  const plot = zones.plot;
  const x = clientX - rect.left;
  const y = clientY - rect.top;
  if (!(x >= plot.left && x <= plot.right && y >= plot.top && y <= plot.bottom)) return null;
  const viewport = alphaTradingResolveViewport(doc);
  const logicalWindow = alphaTradingResolveLogicalWindow(doc, viewport);
  if (!Array.isArray(logicalWindow.visible) || !logicalWindow.visible.length) return null;
  const slotWidth = plot.width / Math.max(1, logicalWindow.visibleBars);
  const logicalIndex = Math.max(0, Math.min(logicalWindow.visibleBars - 1, Math.floor((x - plot.left) / Math.max(1, slotWidth))));
  const entry = logicalWindow.visible.find((item) => item.logicalIndex === logicalIndex) || null;
  if (!entry?.candle || !Number.isFinite(entry.timeMs)) return null;
  return {
    entry,
    candle: entry.candle,
    timeMs: entry.timeMs,
    instrument: String(doc?.tradingInstrument || alphaTradingHeaderState.instrumentLabel || "").trim(),
    granularity: String(doc?.tradingGranularity || "").trim().toUpperCase(),
  };
}

function alphaTradingRegisterSelectedCandle(hit) {
  if (!hit?.candle || !hit?.granularity) return null;
  const registry = window.__forgeAtlasSlashRegistry;
  if (!registry?.register) return null;
  const token = alphaTradingCandleSlashToken(hit.granularity, hit.timeMs);
  return registry.register({
    id: `candle_${String(hit.instrument || "instrument").toLowerCase()}_${String(hit.granularity).toLowerCase()}_${Number(hit.timeMs)}`,
    token,
    label: `${hit.instrument || "Instrument"} ${hit.granularity} ${alphaTradingCandleTimeAnchor(hit.granularity, hit.timeMs)}`,
    summary: "Selected trading candle reference.",
    kind: "metric",
    family: "candle",
    source: "trading",
    meta: {
      instrument: hit.instrument || "",
      granularity: hit.granularity,
      timeMs: Number(hit.timeMs),
      isoTime: new Date(Number(hit.timeMs)).toISOString(),
      open: Number(hit.candle.open),
      high: Number(hit.candle.high),
      low: Number(hit.candle.low),
      close: Number(hit.candle.close),
      volume: Number(hit.candle.volume || 0),
    },
  });
}

function alphaTradingCandleSelectionKey(hit = {}) {
  return [
    String(hit.instrument || "").trim().toLowerCase(),
    String(hit.granularity || "").trim().toLowerCase(),
    Number(hit.timeMs) || 0,
  ].join("|");
}

function alphaTradingSetSelectedCandles(hits = []) {
  alphaTradingSelectedCandlesState.keys = new Set(
    (Array.isArray(hits) ? hits : [])
      .map((hit) => alphaTradingCandleSelectionKey(hit))
      .filter(Boolean),
  );
  alphaTradingSelectedCandlesState.updatedAt = Date.now();
}

function alphaTradingIsSelectedCandle(hit = {}) {
  return alphaTradingSelectedCandlesState.keys.has(alphaTradingCandleSelectionKey(hit));
}

function alphaTradingOverlayToken(indicator = {}, plot = {}) {
  const id = String(indicator?.id || "").trim().toLowerCase();
  const settings = indicator?.settings || {};
  const label = String(plot?.label || "").trim().toLowerCase();
  if (id === "vwap") return "/vwap";
  if (id === "ema") return `/ema${Number(settings.length || 20)}`;
  if (id === "sma") return `/sma${Number(settings.length || 50)}`;
  if (id === "wma") return `/wma${Number(settings.length || 21)}`;
  if (id === "hma") return `/hma${Number(settings.length || 55)}`;
  if (id === "vwma") return `/vwma${Number(settings.length || 20)}`;
  if (id === "bollinger") {
    if (label.includes("upper")) return "/bollinger-upperband";
    if (label.includes("lower")) return "/bollinger-lowerband";
    return "/bollinger-basis";
  }
  if (id === "donchian") {
    if (label.includes("upper")) return "/donchian-upperband";
    if (label.includes("lower")) return "/donchian-lowerband";
    return "/donchian";
  }
  if (id === "keltner") {
    if (label.includes("upper")) return "/keltner-upperband";
    if (label.includes("lower")) return "/keltner-lowerband";
    return "/keltner-basis";
  }
  if (id === "supertrend") return label.includes("bear") ? "/supertrend-bear" : "/supertrend-bull";
  if (id === "ichimoku") {
    if (label.includes("tenkan")) return "/ichimoku-tenkan";
    if (label.includes("kijun")) return "/ichimoku-kijun";
    if (label.includes("span a")) return "/ichimoku-spana";
    if (label.includes("span b")) return "/ichimoku-spanb";
    return "/ichimoku";
  }
  if (id === "psar") return "/psar";
  return indicator?.command || `/${id}`;
}

function alphaTradingRegisterOverlayMetric(indicator = {}, plot = {}) {
  const registry = window.__forgeAtlasSlashRegistry;
  const token = alphaTradingOverlayToken(indicator, plot);
  if (!registry?.register || !token) return { token };
  return registry.register({
    id: `${String(indicator?.id || "indicator").toLowerCase()}_${String(plot?.label || token).toLowerCase().replace(/[^a-z0-9]+/g, "_")}`,
    token,
    label: String(plot?.label || indicator?.label || token).trim() || token,
    summary: "Selected indicator metric reference from the trading chart.",
    kind: "metric",
    family: "indicator",
    source: "trading",
    meta: {
      indicatorId: String(indicator?.id || "").trim().toLowerCase(),
      plotLabel: String(plot?.label || "").trim(),
      settings: indicator?.settings || {},
    },
  });
}

function alphaTradingVisibleOverlayHits(clientX, clientY, doc = alphaDocState) {
  if (!isTradingPanelActive()) return [];
  const rect = alphaCanvas.getBoundingClientRect();
  const zones = getAlphaChartInteractionZones();
  const plotZone = zones.plot;
  const x = clientX - rect.left;
  const y = clientY - rect.top;
  if (!(x >= plotZone.left && x <= plotZone.right && y >= plotZone.top && y <= plotZone.bottom)) return [];
  const viewport = alphaTradingResolveViewport(doc);
  const logicalWindow = alphaTradingResolveLogicalWindow(doc, viewport);
  if (!logicalWindow.visible.length) return [];
  const chartW = plotZone.width;
  const chartH = plotZone.height;
  const padLeft = plotZone.left;
  const padTop = plotZone.top;
  const slotWidth = chartW / Math.max(1, logicalWindow.visibleBars);
  const logicalIndex = Math.max(0, Math.min(logicalWindow.visibleBars - 1, Math.floor((x - plotZone.left) / Math.max(1, slotWidth))));
  const visibleEntry = logicalWindow.visible.find((item) => item.logicalIndex === logicalIndex) || null;
  if (!visibleEntry) return [];
  const referencePrice = alphaTradingScaleReferencePrice(doc, viewport);
  const scaleMin = alphaTradingProjectPrice(viewport.priceMin, alphaTradingScalePrefs.scaleMode, referencePrice);
  const scaleMax = alphaTradingProjectPrice(viewport.priceMax, alphaTradingScalePrefs.scaleMode, referencePrice);
  const scaleSpan = Math.max(0.0001, scaleMax - scaleMin);
  const yOf = (price) => {
    const scaled = alphaTradingProjectPrice(price, alphaTradingScalePrefs.scaleMode, referencePrice);
    const ratio = alphaTradingScalePrefs.invertPriceScale
      ? ((scaled - scaleMin) / scaleSpan)
      : (1 - (scaled - scaleMin) / scaleSpan);
    return padTop + ratio * chartH;
  };
  const hits = [];
  for (const indicator of Array.isArray(alphaTradingIndicatorState.active) ? alphaTradingIndicatorState.active : []) {
    if (indicator?.visible === false) continue;
    for (const plot of alphaTradingOverlaySeries(doc.candles || [], indicator)) {
      if (plot?.kind === "cloud") continue;
      const rawValue = Array.isArray(plot?.series) ? plot.series[visibleEntry.index] : undefined;
      const value = rawValue == null ? NaN : Number(rawValue);
      if (!Number.isFinite(value)) continue;
      const plotY = yOf(value);
      if (Math.abs(plotY - y) > 8) continue;
      hits.push({
        token: alphaTradingRegisterOverlayMetric(indicator, plot)?.token || alphaTradingOverlayToken(indicator, plot),
        indicator,
        plot,
      });
    }
  }
  return hits;
}

function alphaTradingSelectionBounds() {
  return {
    left: Math.min(alphaTradingSelectionStartX, alphaTradingSelectionEndX),
    right: Math.max(alphaTradingSelectionStartX, alphaTradingSelectionEndX),
    top: Math.min(alphaTradingSelectionStartY, alphaTradingSelectionEndY),
    bottom: Math.max(alphaTradingSelectionStartY, alphaTradingSelectionEndY),
  };
}

function alphaTradingCommitSelection(doc = alphaDocState) {
  if (!alphaTradingSelectionActive) return;
  const bounds = alphaTradingSelectionBounds();
  const rect = alphaCanvas.getBoundingClientRect();
  const zones = getAlphaChartInteractionZones();
  const plotZone = zones.plot;
  const left = Math.max(plotZone.left, bounds.left);
  const right = Math.min(plotZone.right, bounds.right);
  const top = Math.max(plotZone.top, bounds.top);
  const bottom = Math.min(plotZone.bottom, bounds.bottom);
  const tokens = [];
  const viewport = alphaTradingResolveViewport(doc);
  const logicalWindow = alphaTradingResolveLogicalWindow(doc, viewport);
  const slotWidth = plotZone.width / Math.max(1, logicalWindow.visibleBars);
  const referencePrice = alphaTradingScaleReferencePrice(doc, viewport);
  const scaleMin = alphaTradingProjectPrice(viewport.priceMin, alphaTradingScalePrefs.scaleMode, referencePrice);
  const scaleMax = alphaTradingProjectPrice(viewport.priceMax, alphaTradingScalePrefs.scaleMode, referencePrice);
  const scaleSpan = Math.max(0.0001, scaleMax - scaleMin);
  const selectedCandleHits = [];
  const yOf = (price) => {
    const scaled = alphaTradingProjectPrice(price, alphaTradingScalePrefs.scaleMode, referencePrice);
    const ratio = alphaTradingScalePrefs.invertPriceScale
      ? ((scaled - scaleMin) / scaleSpan)
      : (1 - (scaled - scaleMin) / scaleSpan);
    return plotZone.top + ratio * plotZone.height;
  };
  for (const entry of logicalWindow.visible) {
    const xStart = plotZone.left + entry.logicalIndex * slotWidth;
    const xEnd = xStart + slotWidth;
    if (xEnd < left || xStart > right) continue;
    const entity = alphaTradingRegisterSelectedCandle({
      candle: entry.candle,
      timeMs: entry.timeMs,
      instrument: String(doc?.tradingInstrument || alphaTradingHeaderState.instrumentLabel || "").trim(),
      granularity: String(doc?.tradingGranularity || "").trim().toUpperCase(),
    });
    selectedCandleHits.push({
      candle: entry.candle,
      timeMs: entry.timeMs,
      instrument: String(doc?.tradingInstrument || alphaTradingHeaderState.instrumentLabel || "").trim(),
      granularity: String(doc?.tradingGranularity || "").trim().toUpperCase(),
    });
    if (entity?.token) tokens.push(entity.token);
  }
  for (const indicator of Array.isArray(alphaTradingIndicatorState.active) ? alphaTradingIndicatorState.active : []) {
    if (indicator?.visible === false) continue;
    for (const plot of alphaTradingOverlaySeries(doc.candles || [], indicator)) {
      if (plot?.kind === "cloud") continue;
      let matched = false;
      for (const entry of logicalWindow.visible) {
        const x = plotZone.left + entry.logicalIndex * slotWidth + slotWidth * 0.5;
        if ((x + slotWidth * 0.5) < left || (x - slotWidth * 0.5) > right) continue;
        const rawValue = Array.isArray(plot?.series) ? plot.series[entry.index] : undefined;
        const value = rawValue == null ? NaN : Number(rawValue);
        if (!Number.isFinite(value)) continue;
        const y = yOf(value);
        if (y < top || y > bottom) continue;
        matched = true;
        break;
      }
      if (matched) {
        const entity = alphaTradingRegisterOverlayMetric(indicator, plot);
        tokens.push(entity?.token || alphaTradingOverlayToken(indicator, plot));
      }
    }
  }
  const unique = Array.from(new Set(tokens.filter(Boolean)));
  alphaTradingSetSelectedCandles(selectedCandleHits);
  if (unique.length) {
    window.__forgeTradingInjectChatToken?.(unique.join(" "));
    syncTradingSlashCommandState();
  }
  alphaTradingSelectionActive = false;
}

alphaCanvas.addEventListener("contextmenu", (e) => {
  if (!isTradingPanelActive()) return;
  const rect = alphaCanvas.getBoundingClientRect();
  const x = e.clientX - rect.left;
  const y = e.clientY - rect.top;
  const zones = getAlphaChartInteractionZones();
  const inCard = x >= zones.card.x && x <= (zones.card.x + zones.card.w) && y >= zones.card.y && y <= (zones.card.y + zones.card.h);
  const inPriceAxis = x >= zones.priceAxis.left && x <= zones.priceAxis.right && y >= zones.priceAxis.top && y <= zones.priceAxis.bottom;
  const inTimeAxis = x >= zones.timeAxis.left && x <= zones.timeAxis.right && y >= zones.timeAxis.top && y <= zones.timeAxis.bottom;
  const dockPanel = alphaTradingDockPanelFallbackBounds(zones);
  const inDockPanel = !!dockPanel
    && x >= dockPanel.left && x <= dockPanel.right
    && y >= dockPanel.top && y <= dockPanel.bottom;
  if (!inCard) return;
  e.preventDefault();
  if (inDockPanel) return;
  showAlphaChartMenu(
    e.clientX,
    e.clientY,
    inPriceAxis ? "price-axis" : (inTimeAxis ? "time-axis" : "chart"),
  );
});

alphaCanvas.addEventListener("mousedown", (e) => {
  const rect = alphaCanvas.getBoundingClientRect();
  const x = e.clientX - rect.left;
  const y = e.clientY - rect.top;
  const zones = getAlphaChartInteractionZones();
  const tradingSurface = isTradingPanelActive();
  const hitSettingsButton = tradingSurface
    && alphaTradingSettingsButtonState.active
    && x >= alphaTradingSettingsButtonState.left
    && x <= alphaTradingSettingsButtonState.right
    && y >= alphaTradingSettingsButtonState.top
    && y <= alphaTradingSettingsButtonState.bottom;
  const hitSelectionButton = tradingSurface
    && alphaTradingSelectionButtonState.active
    && x >= alphaTradingSelectionButtonState.left
    && x <= alphaTradingSelectionButtonState.right
    && y >= alphaTradingSelectionButtonState.top
    && y <= alphaTradingSelectionButtonState.bottom;
  const hitPlusButton = tradingSurface
    && alphaTradingPlusButtonState.active
    && ((x - alphaTradingPlusButtonState.cx) ** 2 + (y - alphaTradingPlusButtonState.cy) ** 2)
      <= (alphaTradingPlusButtonState.radius ** 2);
  if (hitSettingsButton) {
    e.preventDefault();
    alphaTradingToggleSettingsPanels();
    return;
  }
  if (hitSelectionButton) {
    e.preventDefault();
    alphaTradingSelectionToolState.enabled = !alphaTradingSelectionToolState.enabled;
    alphaCanvas.style.cursor = alphaTradingSelectionToolState.enabled ? "crosshair" : "default";
    scheduleAlphaRender();
    return;
  }
  if (hitPlusButton) {
    e.preventDefault();
    showAlphaChartMenu(e.clientX, e.clientY, "price-plus");
    return;
  }
  const dockPanel = alphaTradingDockPanelFallbackBounds(zones);
  const inDockPanel = !!dockPanel
    && x >= dockPanel.left && x <= dockPanel.right
    && y >= dockPanel.top && y <= dockPanel.bottom;
  if (tradingSurface && inDockPanel) {
    if (e.button === 0) {
      e.preventDefault();
      alphaTradingHandleDockPanelClick(x, y);
    }
    return;
  }
  hideAlphaChartMenu();
  if (e.button !== 0) return;
  e.preventDefault();
  const inPlot = x >= zones.plot.left && x <= zones.plot.right && y >= zones.plot.top && y <= zones.plot.bottom;
  const inCard = x >= zones.card.x && x <= (zones.card.x + zones.card.w) && y >= zones.card.y && y <= (zones.card.y + zones.card.h);
  const inTimeAxis = x >= zones.timeAxis.left && x <= zones.timeAxis.right && y >= zones.timeAxis.top && y <= zones.timeAxis.bottom;
  const inPriceAxis = x >= zones.priceAxis.left && x <= zones.priceAxis.right && y >= zones.priceAxis.top && y <= zones.priceAxis.bottom;
  const inPriceScaleHandle = tradingSurface && alphaPriceScaleHandleHit(zones, x, y);
  const inTimeScaleHandle = tradingSurface && alphaTimeScaleHandleHit(zones, x, y);
  if (inPriceScaleHandle) {
    alphaTradingScalePrefs.autoFit = false;
    alphaPriceScaleDragging = true;
    alphaPriceScaleStartY = e.clientY;
    if (tradingSurface) {
      const viewport = alphaTradingResolveViewport(alphaDocState);
      alphaPriceScaleStartMin = viewport.priceMin;
      alphaPriceScaleStartMax = viewport.priceMax;
    } else {
      alphaPriceZoomStart = alphaDocPriceZoom(alphaDocState);
    }
    alphaCanvas.style.cursor = "ns-resize";
    scheduleAlphaRender();
    return;
  }
  if (inTimeScaleHandle) {
    alphaTradingScalePrefs.autoFit = false;
    alphaTimeScaleDragging = true;
    alphaTimeScaleStartX = e.clientX;
    alphaTimeScaleStartCount = tradingSurface
      ? alphaTradingResolveViewport(alphaDocState).visibleBars
      : alphaResolveCandleViewport(alphaDocState, 5, 2000).viewCount;
    alphaTimeScaleAnchorRatio = (x - zones.timeAxis.left) / Math.max(1, zones.timeAxis.right - zones.timeAxis.left);
    alphaCanvas.style.cursor = "ew-resize";
    scheduleAlphaRender();
    return;
  }
  if (!tradingSurface && !alphaDocState.candles.length) return;
  if (!inPlot) return;
  if (tradingSurface && alphaTradingSelectionToolState.enabled) {
    alphaTradingSelectionActive = true;
    alphaTradingSelectionStartX = x;
    alphaTradingSelectionStartY = y;
    alphaTradingSelectionEndX = x;
    alphaTradingSelectionEndY = y;
    alphaChartPointerMoved = false;
    alphaCanvas.style.cursor = "crosshair";
    scheduleAlphaRender();
    return;
  }
  alphaDragging = true;
  alphaChartPointerMoved = false;
  alphaDragStartX = e.clientX;
  alphaDragStartY = e.clientY;
  if (tradingSurface) {
    const viewport = alphaTradingResolveViewport(alphaDocState);
    alphaDragStartTimeEndMs = viewport.timeEndMs;
    alphaDragStartPriceMin = viewport.priceMin;
    alphaDragStartPriceMax = viewport.priceMax;
  } else {
    alphaDragStartEnd = alphaDocState.candleViewEnd;
    alphaDragStartPricePan = Number(alphaDocState.pricePan || 0);
  }
  alphaCanvas.style.cursor = "grabbing";
  scheduleAlphaRender();
});

function handleAlphaChartMouseMove(e) {
  const rect    = alphaCanvas.getBoundingClientRect();
  const insideCanvas = e.clientX >= rect.left && e.clientX <= rect.right && e.clientY >= rect.top && e.clientY <= rect.bottom;
  if (!insideCanvas && !alphaDragging && !alphaPriceScaleDragging && !alphaTimeScaleDragging) return;
  const tradingSurface = isTradingPanelActive();
  const chartMenuOverlayActive = tradingSurface && (
    alphaCanvasWrap?.classList.contains("dropdown-scrim-active")
    || alphaCanvasWrap?.classList.contains("is-trading-header-menu-open")
  );
  if (chartMenuOverlayActive && !alphaDragging && !alphaPriceScaleDragging && !alphaTimeScaleDragging) {
    const changed = alphaTradingCrosshair.active || alphaDocState.candleHover >= 0 || alphaCanvas.style.cursor !== "default";
    alphaTradingCrosshair.active = false;
    alphaDocState.candleHover = -1;
    alphaCanvas.style.cursor = "default";
    if (changed) scheduleAlphaRender();
    return;
  }
  const zones   = getAlphaChartInteractionZones();
  const plot    = zones.plot;
  if (!tradingSurface && !alphaDocState.candles.length) return;
  const viewport = tradingSurface
    ? alphaTradingResolveViewport(alphaDocState)
    : alphaResolveCandleViewport(alphaDocState, 5, 2000);
  const logicalWindow = tradingSurface ? alphaTradingResolveLogicalWindow(alphaDocState, viewport) : null;
  const chartW  = plot.width;
  const cellW   = chartW / (tradingSurface ? viewport.visibleBars : viewport.viewCount);
  const x = e.clientX - rect.left;
  const y = e.clientY - rect.top;
  const inPlot = x >= plot.left && x <= plot.right && y >= plot.top && y <= plot.bottom;
  const inCard = x >= zones.card.x && x <= (zones.card.x + zones.card.w) && y >= zones.card.y && y <= (zones.card.y + zones.card.h);
  const inTimeAxis = x >= zones.timeAxis.left && x <= zones.timeAxis.right && y >= zones.timeAxis.top && y <= zones.timeAxis.bottom;
  const inPriceAxis = x >= zones.priceAxis.left && x <= zones.priceAxis.right && y >= zones.priceAxis.top && y <= zones.priceAxis.bottom;
  const hitSettingsButton = tradingSurface
    && alphaTradingSettingsButtonState.active
    && x >= alphaTradingSettingsButtonState.left
    && x <= alphaTradingSettingsButtonState.right
    && y >= alphaTradingSettingsButtonState.top
    && y <= alphaTradingSettingsButtonState.bottom;
  const hitPlusButton = tradingSurface
    && alphaTradingPlusButtonState.active
    && ((x - alphaTradingPlusButtonState.cx) ** 2 + (y - alphaTradingPlusButtonState.cy) ** 2)
      <= (alphaTradingPlusButtonState.radius ** 2);
  const dockPanel = alphaTradingDockPanelFallbackBounds(zones);
  const inDockPanel = !!dockPanel
    && x >= dockPanel.left && x <= dockPanel.right
    && y >= dockPanel.top && y <= dockPanel.bottom;
  const inPriceScaleHandle = tradingSurface && alphaPriceScaleHandleHit(zones, x, y);
  const inTimeScaleHandle = tradingSurface && alphaTimeScaleHandleHit(zones, x, y);
  if (alphaTradingSelectionActive) {
    if (Math.abs(x - alphaTradingSelectionStartX) > 2 || Math.abs(y - alphaTradingSelectionStartY) > 2) alphaChartPointerMoved = true;
    alphaTradingSelectionEndX = x;
    alphaTradingSelectionEndY = y;
    alphaCanvas.style.cursor = "crosshair";
  } else if (alphaPriceScaleDragging) {
    if (Math.abs(e.clientY - alphaPriceScaleStartY) > 2) alphaChartPointerMoved = true;
    const delta = alphaPriceScaleStartY - e.clientY;
    if (tradingSurface) {
      const referencePrice = alphaTradingScaleReferencePrice(alphaDocState, viewport);
      const startMinScaled = alphaTradingProjectPrice(alphaPriceScaleStartMin, alphaTradingScalePrefs.scaleMode, referencePrice);
      const startMaxScaled = alphaTradingProjectPrice(alphaPriceScaleStartMax, alphaTradingScalePrefs.scaleMode, referencePrice);
      const centerScaled = (startMinScaled + startMaxScaled) * 0.5;
      const startSpanScaled = Math.max(0.0001, startMaxScaled - startMinScaled);
      const spanScaled = Math.max(0.0001, startSpanScaled / Math.pow(1.004, delta));
      const nextMin = alphaTradingUnprojectPrice(centerScaled - spanScaled * 0.5, alphaTradingScalePrefs.scaleMode, referencePrice);
      const nextMax = alphaTradingUnprojectPrice(centerScaled + spanScaled * 0.5, alphaTradingScalePrefs.scaleMode, referencePrice);
      const range = alphaTradingViewportClampPriceRange(nextMin, nextMax);
      alphaTradingViewport.priceMin = range.min;
      alphaTradingViewport.priceMax = range.max;
    } else {
      alphaDocState.priceZoom = alphaClampPriceZoom(alphaPriceZoomStart * Math.pow(1.005, delta));
    }
    alphaCanvas.style.cursor = "ns-resize";
  } else if (alphaTimeScaleDragging) {
    if (Math.abs(e.clientX - alphaTimeScaleStartX) > 2) alphaChartPointerMoved = true;
    const delta = e.clientX - alphaTimeScaleStartX;
    const targetCount = alphaTimeScaleStartCount * Math.exp(-delta * 0.003);
    if (tradingSurface) {
      alphaTradingZoomTimeAtRatio(
        alphaTimeScaleAnchorRatio,
        targetCount / Math.max(1, alphaTimeScaleStartCount),
        alphaDocState,
      );
      if (alphaTradingScalePrefs.autoFit) alphaTradingAutoFitVisiblePriceRange(alphaDocState);
    } else {
      setCandleDocViewCountAtRatio(alphaDocState, alphaTimeScaleAnchorRatio, targetCount);
    }
    alphaCanvas.style.cursor = "ew-resize";
  } else if (alphaDragging) {
    if (Math.abs(e.clientX - alphaDragStartX) > 2 || Math.abs(e.clientY - alphaDragStartY) > 2) alphaChartPointerMoved = true;
    if (tradingSurface) {
      const horizontalShiftBars = (e.clientX - alphaDragStartX) / Math.max(1, cellW);
      alphaTradingViewport.timeEndMs = alphaDragStartTimeEndMs - horizontalShiftBars * viewport.stepMs;
      if (alphaTradingScalePrefs.autoFit) {
        alphaTradingAutoFitVisiblePriceRange(alphaDocState);
      } else {
        const pricePerPixel = viewport.priceSpan / Math.max(60, plot.height);
        const verticalShift = (e.clientY - alphaDragStartY) * pricePerPixel;
        const range = alphaTradingViewportClampPriceRange(
          alphaDragStartPriceMin + verticalShift,
          alphaDragStartPriceMax + verticalShift,
        );
        alphaTradingViewport.priceMin = range.min;
        alphaTradingViewport.priceMax = range.max;
      }
    } else {
      const shift = Math.round(-(e.clientX - alphaDragStartX) / cellW);
      const priceWindow = alphaDocAutoPriceWindow(alphaDocState);
      const pricePerPixel = priceWindow.span / Math.max(60, plot.height);
      const verticalShift = (alphaDragStartY - e.clientY) * pricePerPixel;
      alphaDocState.candleViewEnd = Math.max(viewport.viewCount - 1, Math.min(viewport.lastIndex + viewport.futureSlots, alphaDragStartEnd + shift));
      alphaDocState.pricePan = alphaClampPricePan(alphaDocState, alphaDragStartPricePan + verticalShift);
    }
  } else if (tradingSurface && inDockPanel) {
    alphaTradingCrosshair.active = false;
    alphaDocState.candleHover = -1;
    alphaCanvas.style.cursor = "default";
  } else {
    const xRel = x - plot.left;
    if (tradingSurface && inPlot) {
      const referencePrice = alphaTradingScaleReferencePrice(alphaDocState, viewport);
      const scaleMin = alphaTradingProjectPrice(viewport.priceMin, alphaTradingScalePrefs.scaleMode, referencePrice);
      const scaleMax = alphaTradingProjectPrice(viewport.priceMax, alphaTradingScalePrefs.scaleMode, referencePrice);
      const scaleSpan = Math.max(0.0001, scaleMax - scaleMin);
      const pointerRatio = Math.max(0, Math.min(1, (y - plot.top) / Math.max(1, plot.height)));
      const scaleRatio = alphaTradingScalePrefs.invertPriceScale ? pointerRatio : (1 - pointerRatio);
      const scaleValue = scaleMin + scaleRatio * scaleSpan;
      const logicalSlot = Math.max(0, Math.min(viewport.visibleBars - 1, Math.floor((x - plot.left) / Math.max(1, cellW))));
      const slotAnchorX = plot.left + logicalSlot * Math.max(1, cellW);
      alphaTradingCrosshair.active = true;
      alphaTradingCrosshair.x = Math.max(plot.left, Math.min(plot.right, slotAnchorX));
      alphaTradingCrosshair.y = Math.max(plot.top, Math.min(plot.bottom, y));
      alphaTradingCrosshair.timeMs = logicalWindow
        ? logicalWindow.timeAtSlot(logicalSlot)
        : (
          viewport.timeStartMs
          + Math.max(0, Math.min(1, (x - plot.left) / Math.max(1, plot.width)))
            * Math.max(0, viewport.visibleBars - 1) * viewport.stepMs
        );
      alphaTradingCrosshair.price = alphaTradingUnprojectPrice(scaleValue, alphaTradingScalePrefs.scaleMode, referencePrice);
      alphaDocState.candleHover = -1;
      if (hitSettingsButton || hitPlusButton) alphaCanvas.style.cursor = "pointer";
      else if (inPriceScaleHandle) alphaCanvas.style.cursor = "ns-resize";
      else if (inTimeScaleHandle) alphaCanvas.style.cursor = "ew-resize";
      else alphaCanvas.style.cursor = ALPHA_TRADING_CURSOR;
    } else if (inPlot) {
      alphaDocState.candleHover = Math.max(0, Math.min(viewport.viewCount - 1, Math.floor(xRel / cellW)));
      alphaCanvas.style.cursor  = hitPlusButton ? "pointer" : (tradingSurface ? ALPHA_TRADING_CURSOR : "grab");
    } else {
      alphaTradingCrosshair.active = false;
      alphaDocState.candleHover = -1;
      if (tradingSurface && (hitSettingsButton || hitPlusButton)) alphaCanvas.style.cursor = "pointer";
      else if (tradingSurface && inPriceScaleHandle) alphaCanvas.style.cursor = "ns-resize";
      else if (tradingSurface && inTimeScaleHandle) alphaCanvas.style.cursor = "ew-resize";
      else alphaCanvas.style.cursor = "default";
    }
  }
  scheduleAlphaRender();
}

alphaCanvas.addEventListener("mousemove", handleAlphaChartMouseMove);
window.addEventListener("mousemove", handleAlphaChartMouseMove);
function finishAlphaChartDrag() {
  const changed = alphaDragging || alphaPriceScaleDragging || alphaTimeScaleDragging || alphaTradingSelectionActive || alphaDocState.candleHover >= 0;
  if (alphaTradingSelectionActive) alphaTradingCommitSelection(alphaDocState);
  alphaDragging = false;
  alphaPriceScaleDragging = false;
  alphaTimeScaleDragging = false;
  setTimeout(() => { alphaChartPointerMoved = false; }, 0);
  if (!isTradingPanelActive()) alphaTradingCrosshair.active = false;
  alphaDocState.candleHover = -1;
  alphaCanvas.style.cursor = "default";
  if (changed) scheduleAlphaRender();
}
alphaCanvas.addEventListener("mouseup", finishAlphaChartDrag);
window.addEventListener("mouseup", finishAlphaChartDrag);
alphaCanvas.addEventListener("click", (event) => {
  if (!isTradingPanelActive() || alphaChartPointerMoved) {
    alphaChartPointerMoved = false;
    return;
  }
  const overlayHits = alphaTradingVisibleOverlayHits(event.clientX, event.clientY, alphaDocState);
  if (overlayHits.length) {
    window.__forgeTradingInjectChatToken?.(overlayHits[0].token);
    syncTradingSlashCommandState();
    return;
  }
  const hit = alphaTradingResolveVisibleCandleHit(event.clientX, event.clientY, alphaDocState);
  const entity = alphaTradingRegisterSelectedCandle(hit);
  const token = String(entity?.token || "").trim();
  if (!token) return;
  alphaTradingSetSelectedCandles(hit ? [hit] : []);
  window.__forgeTradingInjectChatToken?.(token);
  syncTradingSlashCommandState();
});
alphaCanvas.addEventListener("mouseleave", () => {
  if (alphaDragging || alphaPriceScaleDragging || alphaTimeScaleDragging) return;
  alphaTradingCrosshair.active = false;
  alphaDocState.candleHover = -1;
  alphaCanvas.style.cursor = "default";
  scheduleAlphaRender();
});

// ── Route Tauri events to alpha when active ───────────────────────
// (additional listeners; existing listeners always feed forge logs)
if (window.__TAURI__) {
  window.__TAURI__.event.listen("forge-log",    (e) => {
    if (activeSection === "alpha") appendAlphaForge(String(e.payload));
  });
  window.__TAURI__.event.listen("forge-result", (e) => {
    if (activeSection === "alpha") appendAlphaResult(String(e.payload));
  });
  window.__TAURI__.event.listen("forge-canvas-assistant-event", (e) => {
    try {
      handleForgeCanvasAssistantEvent(e.payload);
    } catch (err) {
      console.error("forge-canvas-assistant-event listener failed", err);
    }
  });
  window.__TAURI__.event.listen("forge-provider-terminal", (e) => {
    try {
      handleCodexProviderTerminalEvent(e.payload);
      handleGeminiProviderTerminalEvent(e.payload);
      handleClaudeProviderTerminalEvent(e.payload);
    } catch (err) {
      console.error("forge-provider-terminal listener failed", err);
    }
  });

  // Φ.ν.7g — Canaux dédiés à la section α Alpha. Émis par le backend
  // start_alpha_synthesis (main.rs::emit_alpha_log + emit_alpha_signal).
  // Ne pollue PAS les logs DNA grâce aux canaux séparés.
  //
  // Format alpha-signal : "LONG @ 1717084800000 @ 2.847" ou
  // "SHORT @ ... @ ...". Parsé ici en {type, time, price, idx} pour
  // markers chart (triangles glow ▲ ▼).
  window.__TAURI__.event.listen("alpha-log", (e) => {
    try {
      appendAlphaForge(String(e.payload));
    } catch (err) {
      console.error("alpha-log listener failed", err);
    }
  });
  window.__TAURI__.event.listen("alpha-signal", (e) => {
    try {
      const s = String(e.payload);
      const m = s.match(/^(LONG|SHORT)\s+@\s+(\d+)\s+@\s+([0-9.+-]+)$/);
      if (!m) return;
      const type = m[1].toLowerCase();
      const timeMs = Number(m[2]);
      const price = Number(m[3]);
      if (!Number.isFinite(timeMs) || !Number.isFinite(price)) return;
      const candles = alphaDocState.candles;
      let idx = -1;
      for (let i = 0; i < candles.length; i += 1) {
        if (candles[i].time === timeMs) { idx = i; break; }
      }
      if (idx < 0) return;
      pushAlphaSignal({ type, time: timeMs, price, barIndex: idx });
      scheduleAlphaRender();
    } catch (err) {
      console.error("alpha-signal listener failed", err);
    }
  });
  window.__TAURI__.event.listen("alpha-signal-reset", () => {
    try {
      alphaSignals.length = 0;
      scheduleAlphaRender();
    } catch (err) {
      console.error("alpha-signal-reset listener failed", err);
    }
  });
  window.__TAURI__.event.listen("webexplorer-dom-committed", (event) => {
    try {
      if (!isWebExplorerUiActive()) return;
      const payload = event?.payload || {};
      webExplorerProofStats.domCommitCount += 1;
      webExplorerProofStats.lastDomCommit = {
        url: String(payload?.url || ""),
        capturedAtMs: Number(payload?.capturedAtMs || 0),
        receivedAtMs: Date.now(),
        nodeCount: Number(payload?.nodeCount || 0),
        captureElapsedMs: Number(payload?.captureElapsedMs || 0),
        rustCommitElapsedUs: Number(payload?.rustCommitElapsedUs || 0),
        receiveLagMs: Number(payload?.receiveLagMs || 0),
        scannedNodeCount: Number(payload?.scannedNodeCount || 0),
        maxNodes: Number(payload?.maxNodes || 0),
        source: String(payload?.source || "dom"),
      };
      webExplorerProofStats.lastAutoExportEnabled = !!payload?.exportEnabled;
      invalidateWebExplorerProofPanel();
      if (webExplorerDomCommitRefreshTimer) {
        window.clearTimeout(webExplorerDomCommitRefreshTimer);
      }
      webExplorerDomCommitRefreshTimer = window.setTimeout(() => {
        webExplorerDomCommitRefreshTimer = 0;
        if (!isWebExplorerUiActive()) return;
        void refreshWebExplorerMemorySnapshot();
      }, 650);
    } catch (err) {
      console.error("webexplorer-dom-committed listener failed", err);
    }
  });
}

// ── Start alpha RAF loop ──────────────────────────────────────────
void loadWorkspaceBreadcrumb();
if (!isWebExplorerSurface && window.__TAURI__?.core?.invoke) {
  void pollForgeJobs();
  setInterval(() => {
    if (activeSection === "alpha" || selectedForgeJobId) void pollForgeJobs();
  }, 1000);
  window.addEventListener("load", () => {
    window.setTimeout(emitForgeTerminalStatus, 2500);
    window.setInterval(emitForgeTerminalStatus, 10000);
  }, { once: true });
}
if (!isWebExplorerSurface) {
  scheduleAlphaRender();
}

// No eager Alpha preview at startup: wait for a real file to keep the UI responsive.

// ── Library overlay ───────────────────────────────────────────────

const navLibraryBtn  = document.getElementById("navLibraryBtn");
const libraryOverlay = document.getElementById("libraryOverlay");
const libraryGrid    = document.getElementById("libraryGrid");
const libraryEmpty   = document.getElementById("libraryEmpty");
const libraryClose   = document.getElementById("libraryClose");
const librarySearch  = document.getElementById("librarySearch");
const libraryCount   = document.getElementById("libraryCount");

let libraryFilter    = "all";
let librarySearchVal = "";

function detectLibFileType(label) {
  const l = label.toLowerCase();
  if (l.includes(".json")) return "json";
  if (l.includes(".pdf"))  return "pdf";
  if (l.includes(".txt"))  return "txt";
  if (l.includes(".csv") || l.includes("csv")) return "csv";
  return "generic";
}

function isTradingFile(label) {
  return /natgas|ohlc|ohlcv|h1|h4|m15|m30|daily|weekly|forex|stock|btc|eth|usd|eur|gbp|trade|candle|bar|equity|spx|nq\b/i.test(label);
}

function seededRand(seed) {
  let h = 0;
  for (let i = 0; i < seed.length; i++) h = (Math.imul(31, h) + seed.charCodeAt(i)) | 0;
  return () => { h ^= h << 13; h ^= h >> 17; h ^= h << 5; return (h >>> 0) / 4294967296; };
}

// Cache jobId → parsed candles array (null = tried but failed)
const libChartCache = new Map();

function drawLibCandleChart(canvas, candles) {
  const ctx = canvas.getContext("2d");
  const W   = canvas.offsetWidth  || 186;
  const H   = canvas.offsetHeight || 78;
  const dpr = window.devicePixelRatio || 1;
  canvas.width  = W * dpr;
  canvas.height = H * dpr;
  ctx.scale(dpr, dpr);

  // Show last N candles that fit
  const bodyW = 4, gap = 1;
  const N     = Math.min(candles.length, Math.floor(W / (bodyW + gap)));
  const slice = candles.slice(-N);

  const padV  = 5;
  const minP  = Math.min(...slice.map(c => c.low));
  const maxP  = Math.max(...slice.map(c => c.high));
  const range = maxP - minP || 1;
  const toY   = p => padV + (1 - (p - minP) / range) * (H - 2 * padV);

  slice.forEach((c, i) => {
    const cx    = i * (bodyW + gap) + gap + bodyW / 2;
    const isUp  = c.close >= c.open;
    const col   = isUp ? "#4ade80" : "#f87171";
    const bodyT = toY(Math.max(c.open, c.close));
    const bodyB = toY(Math.min(c.open, c.close));
    const bodyH = Math.max(bodyB - bodyT, 1);

    // Wick
    ctx.beginPath();
    ctx.strokeStyle = col;
    ctx.lineWidth = 1;
    ctx.moveTo(cx, toY(c.high));
    ctx.lineTo(cx, toY(c.low));
    ctx.stroke();

    // Body
    ctx.fillStyle = col;
    ctx.fillRect(cx - bodyW / 2, bodyT, bodyW, bodyH);
  });
}

async function loadAndDrawLibChart(canvas, jobId) {
  // Serve from cache
  const cached = libChartCache.get(jobId);
  if (cached) { drawLibCandleChart(canvas, cached); return; }
  if (cached === null) return; // known failure

  if (!window.__TAURI__?.core?.invoke) { libChartCache.set(jobId, null); return; }
  try {
    const payload = await window.__TAURI__.core.invoke("read_forge_job_file", { jobId });
    const text    = payload?.text ? String(payload.text) : "";
    const candles = text ? tryParseCandleCsv(text) : null;
    libChartCache.set(jobId, candles || null);
    if (candles && canvas.isConnected) drawLibCandleChart(canvas, candles);
  } catch (_) {
    libChartCache.set(jobId, null);
  }
}

function libPreviewHTML(type, label, jobId) {
  if (type === "csv" && isTradingFile(label)) {
    return `<canvas class="lib-preview-canvas" data-jobchart="${jobId}"></canvas>`;
  }
  if (type === "csv") {
    const row = (hdr) => `<div class="lib-preview-row">
      <div class="lib-preview-cell narrow${hdr ? " hdr" : ""}"></div>
      <div class="lib-preview-cell wide${hdr ? " hdr" : ""}"></div>
      <div class="lib-preview-cell${hdr ? " hdr" : ""}"></div>
      <div class="lib-preview-cell narrow${hdr ? " hdr" : ""}"></div>
    </div>`;
    return `<div class="lib-preview-table">${row(true)}${row(false)}${row(false)}${row(false)}</div>`;
  }
  if (type === "json") {
    const r = seededRand(jobId);
    const n = Math.floor(r() * 50000);
    return `<div class="lib-preview-json">{<br>
      <span class="jk">"version"</span>: <span class="js">"forge-v7"</span>,<br>
      <span class="jk">"tokens"</span>: <span class="jv">${n}</span>,<br>
      <span class="jk">"status"</span>: <span class="js">"ok"</span><br>
    }</div>`;
  }
  if (type === "pdf") {
    const widths = [92, 100, 76, 62, 88, 96, 54, 80];
    return `<div class="lib-preview-pdf">${widths.map(w =>
      `<div class="lib-preview-pdf-line" style="width:${w}%"></div>`).join("")}</div>`;
  }
  const r = seededRand(jobId);
  const dotLine = () => "· ".repeat(Math.floor(r() * 14 + 8)).trim();
  return `<div class="lib-preview-txt">${dotLine()}<br>${dotLine()}<br>${dotLine()}<br>${dotLine()}</div>`;
}

function libStatusClass(status) {
  const s = String(status || "").toLowerCase();
  if (s === "completed" || s === "done") return "done";
  if (s === "running") return "running";
  if (s === "failed"  || s === "error") return "error";
  if (s === "archived") return "archived";
  return "pending";
}

function libFormatDate(ms) {
  if (!ms) return "";
  const d = new Date(Number(ms));
  if (isNaN(d.getTime())) return "";
  return d.toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" });
}

// createLibCard defined after context-menu section below

function libDateBucket(ms) {
  if (!ms) return "Older";
  const now   = Date.now();
  const d     = new Date(Number(ms));
  const today = new Date(); today.setHours(0, 0, 0, 0);
  const yest  = new Date(today); yest.setDate(yest.getDate() - 1);
  const week  = new Date(today); week.setDate(week.getDate() - 7);
  const month = new Date(today); month.setDate(1);
  if (d >= today) return "Today";
  if (d >= yest)  return "Yesterday";
  if (d >= week)  return "This week";
  if (d >= month) return "This month";
  return d.toLocaleDateString(undefined, { month: "long", year: "numeric" });
}

function groupByDate(jobs) {
  const buckets = new Map();
  jobs.forEach(job => {
    const ms  = job.lastModifiedMs || job.last_modified_ms || job.createdMs || job.created_ms || 0;
    const key = libDateBucket(ms);
    if (!buckets.has(key)) buckets.set(key, []);
    buckets.get(key).push(job);
  });
  return Array.from(buckets.entries()).map(([label, items]) => ({ label, items }));
}

function renderLibraryGrid() {
  if (!libraryGrid) return;
  const q = librarySearchVal.trim().toLowerCase();

  const jobMs = j => j.lastModifiedMs || j.last_modified_ms || j.createdMs || j.created_ms || 0;

  const filtered = forgeJobs
    .filter(job => {
      if (String(job.status || "").toLowerCase() === "archived") return false;
      const label = forgeJobLabel(job).toLowerCase();
      const type  = detectLibFileType(label);
      if (libraryFilter !== "all" && type !== libraryFilter) return false;
      if (q && !label.includes(q)) return false;
      return true;
    })
    .sort((a, b) => jobMs(b) - jobMs(a));

  if (libraryCount) libraryCount.textContent = String(filtered.length);

  const isEmpty = filtered.length === 0;
  libraryGrid.style.display = isEmpty ? "none" : "";
  if (libraryEmpty) libraryEmpty.style.display = isEmpty ? "" : "none";
  if (isEmpty) return;

  const pinned   = filtered.filter(j => !!(j.pinned || j.is_pinned));
  const unpinned = filtered.filter(j =>  !(j.pinned || j.is_pinned));

  libraryGrid.innerHTML = "";
  let cardIdx = 0;

  const appendGroup = (jobs, sectionLabel, sectionClass) => {
    if (jobs.length === 0) return;

    // Section header (Pinned / recent)
    const hdr = document.createElement("div");
    hdr.className = "lib-section-hdr" + (sectionClass ? ` ${sectionClass}` : "");
    if (sectionClass === "is-pinned") {
      hdr.innerHTML = `<svg class="lib-section-pin" width="10" height="10" viewBox="0 0 24 24" fill="currentColor"><path d="M12 2l3 7h7l-6 4.5 2 7.5-6-4.5L6 21l2-7.5L2 9h7z"/></svg>${sectionLabel}`;
    } else {
      hdr.textContent = sectionLabel;
    }
    libraryGrid.appendChild(hdr);

    // Date groups within the section
    groupByDate(jobs).forEach(({ label: dateLabel, items }) => {
      const sep = document.createElement("div");
      sep.className = "lib-date-sep";
      sep.textContent = dateLabel;
      libraryGrid.appendChild(sep);

      items.forEach(job => {
        const card = createLibCard(job);
        card.style.animationDelay = `${cardIdx * 18}ms`;
        cardIdx++;
        libraryGrid.appendChild(card);
      });
    });
  };

  appendGroup(pinned,   "Pinned", "is-pinned");

  // Gap between pinned + regular
  if (pinned.length > 0 && unpinned.length > 0) {
    const gap = document.createElement("div");
    gap.className = "lib-section-gap";
    libraryGrid.appendChild(gap);
  }

  appendGroup(unpinned, "Files", "");

  requestAnimationFrame(() => {
    libraryGrid.querySelectorAll("canvas[data-jobchart]").forEach(c => {
      void loadAndDrawLibChart(c, c.dataset.jobchart);
    });
  });
}

