let oandaProviderTerminalPersistedPostState = null;
let oandaProviderTerminalStoredSecrets = { accountId: "", apiKey: "", baseUrl: "" };
let oandaProviderTerminalMaskedCarry = { accountId: false, apiKey: false, baseUrl: false };
let oandaProviderTerminalScrollbarDrag = null;
const providerTerminalFilterCarry = { codex: "", gemini: "", claude: "" };
const providerTerminalInstances = new Map();
const providerTerminalLiveHydration = { codex: false, gemini: false, claude: false };
let activeProviderWorkbench = localStorage.getItem("forge.provider.workbench.active") || "codex";

function storedOpenAiModelRef() {
  try {
    return localStorage.getItem("forge.openai.subscription.model") || "";
  } catch (_) {
    return "";
  }
}

function normalizeOpenAiModelRef(model) {
  const raw = String(model || "").trim();
  const direct = raw.replace(/^openai-codex\//, "").replace(/^openai\//, "");
  const allowed = new Set(["gpt-5.3-codex", "gpt-5.5", "gpt-5.4"]);
  return allowed.has(direct) ? direct : "gpt-5.3-codex";
}

function setStoredOpenAiModelRef(model) {
  try {
    localStorage.setItem("forge.openai.subscription.model", normalizeOpenAiModelRef(model));
  } catch (_) {
    // Local storage can be disabled in file previews.
  }
}

function selectedOpenAiModelRef() {
  return normalizeOpenAiModelRef(openAiProviderModel?.value || storedOpenAiModelRef());
}

function storedRuntimeModelRef(storageKey) {
  try {
    return localStorage.getItem(storageKey) || "";
  } catch (_) {
    return "";
  }
}

function normalizeCliModelRef(model, fallback, aliases = {}) {
  const raw = String(model || "").trim();
  if (!raw) return fallback;
  const key = raw
    .toLowerCase()
    .replace(/[’']/g, "")
    .replace(/[^a-z0-9.]+/g, " ")
    .trim()
    .replace(/\s+/g, " ");
  if (aliases[key]) return aliases[key];
  const direct = raw.replace(/\s+/g, "-");
  if (
    direct.length > 90 ||
    !direct
      .split("")
      .every((ch) => /[A-Za-z0-9._/-]/.test(ch))
  ) {
    return fallback;
  }
  return direct;
}

function normalizeGeminiModelRef(model) {
  return normalizeCliModelRef(model, "gemini-2.5-pro", {
    "gemini 3": "gemini-3-pro",
    "gemini 3 pro": "gemini-3-pro",
    "3": "gemini-3-pro",
    "3 pro": "gemini-3-pro",
    "gemini 2.5": "gemini-2.5-pro",
    "gemini 2.5 pro": "gemini-2.5-pro",
    "2.5": "gemini-2.5-pro",
    "2.5 pro": "gemini-2.5-pro",
    "2.5 flash": "gemini-2.5-flash",
  });
}

function normalizeClaudeModelRef(model) {
  return normalizeCliModelRef(model, "claude-code-default", {
    "default": "claude-code-default",
    "claude default": "claude-code-default",
    "claude code default": "claude-code-default",
    "opus": "opus",
    "claude opus": "opus",
    "sonnet": "sonnet",
    "claude sonnet": "sonnet",
    "haiku": "haiku",
    "claude haiku": "haiku",
  });
}

function setStoredRuntimeModelRef(storageKey, model, normalizer) {
  try {
    localStorage.setItem(storageKey, normalizer(model));
  } catch (_) {}
}

function hydrateProviderModelPickers() {
  const stored = normalizeOpenAiModelRef(storedOpenAiModelRef());
  if (openAiProviderModel) openAiProviderModel.value = stored;
  if (stored !== storedOpenAiModelRef()) setStoredOpenAiModelRef(stored);
  if (openAiProviderModelLabel) openAiProviderModelLabel.textContent = selectedOpenAiModelRef();
  const gemini = normalizeGeminiModelRef(storedRuntimeModelRef("forge.gemini.model"));
  if (geminiProviderModel) geminiProviderModel.value = gemini;
  if (gemini !== storedRuntimeModelRef("forge.gemini.model")) {
    setStoredRuntimeModelRef("forge.gemini.model", gemini, normalizeGeminiModelRef);
  }
  if (geminiProviderModelLabel) geminiProviderModelLabel.textContent = selectedGeminiModelRef();
  const claude = normalizeClaudeModelRef(storedRuntimeModelRef("forge.claude.model"));
  if (claudeProviderModel) claudeProviderModel.value = claude;
  if (claude !== storedRuntimeModelRef("forge.claude.model")) {
    setStoredRuntimeModelRef("forge.claude.model", claude, normalizeClaudeModelRef);
  }
  if (claudeProviderModelLabel) claudeProviderModelLabel.textContent = selectedClaudeModelRef();
  if (providerLauncherCodexMeta) providerLauncherCodexMeta.textContent = selectedOpenAiModelRef();
  if (providerLauncherGeminiMeta) providerLauncherGeminiMeta.textContent = selectedGeminiModelRef();
  if (providerLauncherClaudeMeta) providerLauncherClaudeMeta.textContent = selectedClaudeModelRef();
  renderCliProviderTerminalShell("codex");
  renderCliProviderTerminalShell("gemini");
  renderCliProviderTerminalShell("claude");
  hydrateVoiceProviderSettings();
  syncCanvasChatModelLabel();
  renderProviderWorkbench();
}

function hydrateOpenAiModelPicker() {
  hydrateProviderModelPickers();
}

function hydrateVoiceProviderSettings() {
  const settings = forgeVoiceSettings();
  if (voiceElevenVoiceId) voiceElevenVoiceId.value = settings.elevenVoiceId;
  if (voiceElevenModel) voiceElevenModel.value = settings.elevenModelId;
  if (voiceMonthlyLimit) voiceMonthlyLimit.value = String(settings.monthlyLimit);
  if (voiceOrpheusEndpoint) voiceOrpheusEndpoint.value = settings.orpheusEndpoint;
  if (voiceOrpheusVoice) voiceOrpheusVoice.value = settings.orpheusVoice;
  if (voiceAutoSpeak) voiceAutoSpeak.checked = settings.autoSpeak;
  syncForgeVoiceOutButton();
}

function saveVoiceProviderSettingsFromUi() {
  if (voiceElevenVoiceId) forgeVoiceStorageSet("forge.voice.elevenVoiceId", voiceElevenVoiceId.value.trim() || FORGE_VOICE_DEFAULT_ID);
  if (voiceElevenModel) forgeVoiceStorageSet("forge.voice.elevenModelId", voiceElevenModel.value || FORGE_VOICE_DEFAULT_MODEL);
  if (voiceMonthlyLimit) forgeVoiceStorageSet("forge.voice.monthlyLimit", String(Math.max(500, Number(voiceMonthlyLimit.value || 10000) || 10000)));
  if (voiceOrpheusEndpoint) forgeVoiceStorageSet("forge.voice.orpheusEndpoint", voiceOrpheusEndpoint.value.trim());
  if (voiceOrpheusVoice) forgeVoiceStorageSet("forge.voice.orpheusVoice", voiceOrpheusVoice.value.trim() || "tara");
  if (voiceAutoSpeak) forgeVoiceStorageSet("forge.voice.autoSpeak", voiceAutoSpeak.checked ? "1" : "0");
  hydrateVoiceProviderSettings();
  syncForgeVoiceOutButton();
}

function formatVoiceBytes(bytes) {
  const n = Number(bytes || 0);
  if (!Number.isFinite(n) || n <= 0) return "0 B";
  if (n >= 1024 * 1024) return `${(n / (1024 * 1024)).toFixed(1)} MB`;
  if (n >= 1024) return `${(n / 1024).toFixed(1)} KB`;
  return `${Math.round(n)} B`;
}

function renderVoiceProviderStatus(status, options = {}) {
  const busy = !!options.busy;
  const configured = !!status?.elevenConfigured;
  voiceProviderLastStatus = status || voiceProviderLastStatus;
  const settings = forgeVoiceSettings();
  if (voiceProviderStatus) {
    voiceProviderStatus.textContent = busy ? "Checking" : configured ? "Ready" : settings.orpheusEndpoint ? "Fallback only" : "Setup";
    voiceProviderStatus.classList.toggle("connected", (configured || !!settings.orpheusEndpoint) && !busy);
    voiceProviderStatus.classList.toggle("needs-auth", !configured && !settings.orpheusEndpoint && !busy);
  }
  if (voiceProviderEngine) {
    voiceProviderEngine.textContent = configured ? "ElevenLabs -> Orpheus" : settings.orpheusEndpoint ? "Orpheus only" : "not configured";
  }
  if (voiceProviderUsage) {
    const used = Number(status?.usageChars || 0);
    voiceProviderUsage.textContent = `${used.toLocaleString()} / ${settings.monthlyLimit.toLocaleString()} chars`;
  }
  if (voiceProviderCache) {
    voiceProviderCache.textContent = `${Number(status?.cacheFiles || 0).toLocaleString()} files · ${formatVoiceBytes(status?.cacheBytes)}`;
  }
  if (voiceElevenApiKey && status) {
    voiceElevenApiKey.placeholder = configured ? "Saved locally" : "sk_...";
  }
  if (voiceProviderHint && status) {
    voiceProviderHint.textContent = status.message || "Forge voice output is ready.";
  }
}

async function refreshVoiceProviderStatus(options = {}) {
  const invoke = window.__TAURI__?.core?.invoke;
  if (!options.silent) renderVoiceProviderStatus(voiceProviderLastStatus, { busy: true });
  if (!invoke) {
    renderVoiceProviderStatus({
      elevenConfigured: false,
      usageChars: 0,
      cacheFiles: 0,
      cacheBytes: 0,
      message: "Open Forge as a Tauri app to use ElevenLabs/Orpheus voice output.",
    });
    return null;
  }
  try {
    const status = await invoke("voice_tts_status");
    renderVoiceProviderStatus(status);
    return status;
  } catch (err) {
    renderVoiceProviderStatus({
      elevenConfigured: false,
      usageChars: 0,
      cacheFiles: 0,
      cacheBytes: 0,
      message: `Voice status failed: ${err}`,
    });
    return null;
  }
}

async function saveElevenLabsApiKey() {
  const invoke = window.__TAURI__?.core?.invoke;
  const apiKey = String(voiceElevenApiKey?.value || "").trim();
  if (!apiKey) {
    if (voiceProviderHint) voiceProviderHint.textContent = "Paste an ElevenLabs API key before saving.";
    return;
  }
  if (!invoke) {
    if (voiceProviderHint) voiceProviderHint.textContent = "Open Forge as a Tauri app to save the ElevenLabs key.";
    return;
  }
  const oldText = voiceElevenSaveKey?.textContent;
  if (voiceElevenSaveKey) {
    voiceElevenSaveKey.disabled = true;
    voiceElevenSaveKey.textContent = "Saving";
  }
  try {
    const result = await invoke("elevenlabs_api_key_save", { request: { apiKey } });
    if (voiceElevenApiKey) {
      voiceElevenApiKey.value = "";
      voiceElevenApiKey.placeholder = "Saved locally";
    }
    if (voiceProviderHint) voiceProviderHint.textContent = result?.message || "ElevenLabs API key saved locally.";
    await refreshVoiceProviderStatus({ silent: true });
  } catch (err) {
    if (voiceProviderHint) voiceProviderHint.textContent = `ElevenLabs key save failed: ${err}`;
  } finally {
    if (voiceElevenSaveKey) {
      voiceElevenSaveKey.disabled = false;
      voiceElevenSaveKey.textContent = oldText || "Save key";
    }
  }
}

async function clearElevenLabsApiKey() {
  const invoke = window.__TAURI__?.core?.invoke;
  if (!invoke) {
    if (voiceProviderHint) voiceProviderHint.textContent = "Open Forge as a Tauri app to clear the ElevenLabs key.";
    return;
  }
  const oldText = voiceElevenClearKey?.textContent;
  if (voiceElevenClearKey) {
    voiceElevenClearKey.disabled = true;
    voiceElevenClearKey.textContent = "Clearing";
  }
  try {
    const result = await invoke("elevenlabs_api_key_clear");
    if (voiceElevenApiKey) {
      voiceElevenApiKey.value = "";
      voiceElevenApiKey.placeholder = result?.configured ? "Environment key active" : "sk_...";
    }
    if (voiceProviderHint) voiceProviderHint.textContent = result?.message || "ElevenLabs API key cleared.";
    await refreshVoiceProviderStatus({ silent: true });
  } catch (err) {
    if (voiceProviderHint) voiceProviderHint.textContent = `ElevenLabs key clear failed: ${err}`;
  } finally {
    if (voiceElevenClearKey) {
      voiceElevenClearKey.disabled = false;
      voiceElevenClearKey.textContent = oldText || "Clear";
    }
  }
}

function setTopbarProviderMode(on) {
  canvasTopbar?.classList.toggle("topbar-provider-mode", !!on);
}

function renderOpenAiProviderStatus(status, options = {}) {
  const busy = !!options.busy;
  const connected = !!status?.connected;
  openAiProviderLastStatus = status || openAiProviderLastStatus;
  if (openAiProviderStatus) {
    openAiProviderStatus.textContent = busy ? "Checking" : connected ? "Connected" : "Not connected";
    openAiProviderStatus.classList.toggle("connected", connected && !busy);
  }
  if (providerConnectionChip) {
    providerConnectionChip.textContent = connected ? "online" : busy ? "checking" : "offline";
  }
  if (openAiProviderAccount) {
    openAiProviderAccount.textContent = connected ? (status?.accountLabel || "Connected") : "Not connected";
  }
  if (openAiProviderSource) {
    openAiProviderSource.textContent = connected ? (status?.authSource || "OpenAI subscription") : "none";
  }
  if (openAiProviderModelLabel) {
    openAiProviderModelLabel.textContent = selectedOpenAiModelRef();
  }
  if (openAiProviderConnect) {
    openAiProviderConnect.textContent = connected ? "Open sign-in again" : "Connect subscription";
  }
  if (openAiProviderHint) {
    if (busy) {
      openAiProviderHint.textContent = "Checking local OAuth status.";
    } else if (connected) {
      const refreshed = status?.lastRefresh ? ` Last refresh: ${status.lastRefresh}.` : "";
      openAiProviderHint.textContent = `${status?.message || "OpenAI subscription auth is ready."}${refreshed}`;
    } else {
      openAiProviderHint.textContent = status?.message || "No local OpenAI subscription auth found.";
    }
  }
}

function oandaProviderBaseUrlLabel(status = oandaProviderLastStatus) {
  const raw = String(status?.baseUrl || "https://api-fxpractice.oanda.com").trim();
  if (!raw) return "api-fxpractice.oanda.com";
  try {
    return new URL(raw).host || raw;
  } catch (_) {
    return raw.replace(/^https?:\/\//i, "") || "api-fxpractice.oanda.com";
  }
}

function oandaProviderLauncherState(status, options = {}) {
  if (options.busy) return "checking";
  return status?.connected ? "ready" : "auth";
}

function setOandaProviderTerminalBusy(busy) {
  oandaProviderTerminalBusy = !!busy;
  if (oandaProviderTerminalInput) oandaProviderTerminalInput.disabled = !!busy;
  if (oandaProviderTerminalSend) oandaProviderTerminalSend.disabled = !!busy;
  if (oandaProviderTerminalReset) oandaProviderTerminalReset.disabled = !!busy;
}

function setOandaProviderTerminalStateLabel(label) {
  if (oandaProviderTerminalState) oandaProviderTerminalState.textContent = label;
}

function setOandaProviderTerminalInputMode(options = {}) {
  if (!oandaProviderTerminalInput) return;
  const secret = !!options.secret;
  oandaProviderTerminalInput.type = secret ? "password" : "text";
  oandaProviderTerminalInput.placeholder = options.placeholder || "";
  oandaProviderTerminalInput.disabled = !!options.disabled;
}

function syncOandaProviderTerminalOutput() {
  if (!oandaProviderTerminalOutput) return;
  oandaProviderTerminalOutput.innerHTML = `${oandaProviderTerminalBaseHtml}${oandaProviderTerminalLogHtml}`;
  oandaProviderTerminalOutput.scrollTop = oandaProviderTerminalOutput.scrollHeight;
  window.requestAnimationFrame(syncOandaProviderTerminalScrollbar);
}

function syncOandaProviderTerminalScrollbar() {
  if (!oandaProviderTerminalOutput || !oandaProviderTerminalScrollbar || !oandaProviderTerminalScrollbarThumb) return;
  const viewportHeight = oandaProviderTerminalOutput.clientHeight;
  const contentHeight = oandaProviderTerminalOutput.scrollHeight;
  const scrollRange = Math.max(contentHeight - viewportHeight, 0);
  if (scrollRange <= 1 || viewportHeight <= 0) {
    oandaProviderTerminalScrollbar.classList.add("is-hidden");
    oandaProviderTerminalScrollbarThumb.style.height = "0px";
    oandaProviderTerminalScrollbarThumb.style.transform = "translateY(0px)";
    return;
  }
  const railHeight = oandaProviderTerminalScrollbar.clientHeight;
  if (railHeight <= 0) {
    oandaProviderTerminalScrollbar.classList.add("is-hidden");
    return;
  }
  const thumbHeight = Math.max(32, Math.round((viewportHeight / contentHeight) * railHeight));
  const trackTravel = Math.max(railHeight - thumbHeight, 0);
  const progress = Math.min(Math.max(oandaProviderTerminalOutput.scrollTop / scrollRange, 0), 1);
  oandaProviderTerminalScrollbar.classList.remove("is-hidden");
  oandaProviderTerminalScrollbarThumb.style.height = `${thumbHeight}px`;
  oandaProviderTerminalScrollbarThumb.style.transform = `translateY(${Math.round(trackTravel * progress)}px)`;
}

function escapeOandaTerminalHtml(value) {
  return String(value || "").replace(/[&<>"']/g, (char) => (
    { "&": "&amp;", "<": "&lt;", ">": "&gt;", "\"": "&quot;", "'": "&#39;" }[char] || char
  ));
}

function renderOandaTerminalText(text) {
  return escapeOandaTerminalHtml(text).replace(/\n/g, "<br>");
}

function setOandaProviderTerminalOutput(html) {
  oandaProviderTerminalBaseHtml = String(html || "");
  oandaProviderTerminalLogHtml = "";
  syncOandaProviderTerminalOutput();
}

function appendOandaProviderTerminalOutput(text, tone = "") {
  const className = tone ? ` oanda-terminal-logline-${tone}` : "";
  oandaProviderTerminalLogHtml += `<div class="oanda-terminal-logline${className}">${renderOandaTerminalText(text)}</div>`;
  syncOandaProviderTerminalOutput();
}

function maskOandaAccountId(value) {
  const raw = String(value || "").trim();
  if (!raw) return "***";
  const tail = raw.slice(-4);
  return `***${tail}`;
}

function maskOandaApiKey(value) {
  const raw = String(value || "").trim();
  if (!raw) return "***";
  if (raw.length <= 8) return `${raw.slice(0, 2)}***`;
  return `${raw.slice(0, 4)}...${raw.slice(-4)}`;
}

function waitOandaTerminal(ms) {
  return new Promise((resolve) => window.setTimeout(resolve, ms));
}

function isOandaDigitOneHotkey(event) {
  return event?.key === "1" || event?.code === "Digit1" || event?.code === "Numpad1";
}

function isOandaDigitTwoHotkey(event) {
  return event?.key === "2" || event?.code === "Digit2" || event?.code === "Numpad2";
}

function oandaProviderTerminalStatusText() {
  if (oandaProviderTerminalBusy) return oandaProviderTerminalPhase === "encrypting" ? "Encrypting" : "Checking";
  if (oandaProviderTerminalPhase === "post") return "Ready";
  if (oandaProviderTerminalPhase === "editing") return "Setup";
  return "OANDA";
}

function resetOandaProviderDraft() {
  oandaProviderTerminalDraft = {
    accountId: "",
    apiKey: "",
    baseUrl: "",
  };
  resetOandaProviderTerminalMaskedCarry();
}

function oandaProviderTerminalIntroLines() {
  return [
    "███████  ██████  ██████   ██████  ███████",
    "██      ██    ██ ██   ██ ██       ██",
    "█████   ██    ██ ██████  ██   ███ █████",
    "██      ██    ██ ██   ██ ██    ██ ██",
    "██       ██████  ██   ██  ██████  ███████",
  ];
}

function oandaProviderTerminalFieldOrder() {
  return ["accountId", "apiKey", "baseUrl"];
}

function oandaProviderTerminalFieldMeta(field) {
  if (field === "apiKey") {
    return {
      label: "OANDA_API_KEY",
      placeholder: "Paste your OANDA API key then press Enter",
      secret: true,
    };
  }
  if (field === "baseUrl") {
    return {
      label: "OANDA_BASE_URL",
      placeholder: "Paste your OANDA base URL then press Enter",
      secret: false,
    };
  }
  return {
    label: "OANDA_ACCOUNT_ID",
    placeholder: "Paste your OANDA account id then press Enter",
    secret: false,
  };
}

function resetOandaProviderTerminalFieldFx() {
  oandaProviderTerminalFieldFx = { accountId: null, apiKey: null, baseUrl: null };
}

function resetOandaProviderTerminalFieldVisibility(visible = true) {
  oandaProviderTerminalFieldVisible = {
    accountId: visible,
    apiKey: visible,
    baseUrl: visible,
  };
}

function resetOandaProviderTerminalMaskedCarry() {
  oandaProviderTerminalMaskedCarry = {
    accountId: false,
    apiKey: false,
    baseUrl: false,
  };
}

function resetOandaProviderTerminalLogs() {
  oandaProviderTerminalLogs = [];
}

function readPersistedOandaProviderTerminalPostState() {
  try {
    const raw = localStorage.getItem(OANDA_TERMINAL_POST_STATE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (!parsed || parsed.phase !== "post") return null;
    const logs = Array.isArray(parsed.logs)
      ? parsed.logs
          .map((entry, index) => {
            const text = String(entry?.text || "").trim();
            if (!text) return null;
            return {
              id: `oanda-log-restored-${index}-${Math.random().toString(16).slice(2, 8)}`,
              text,
              tone: String(entry?.tone || ""),
              spinner: false,
              erasing: false,
            };
          })
          .filter(Boolean)
      : [];
    return {
      phase: "post",
      status: parsed.status && typeof parsed.status === "object" ? parsed.status : null,
      logs,
    };
  } catch (_) {
    return null;
  }
}

function persistOandaProviderTerminalPostState() {
  if (oandaProviderTerminalPhase !== "post") return;
  const payload = {
    phase: "post",
    status: oandaProviderLastStatus || null,
    logs: oandaProviderTerminalLogs.map((entry) => ({
      text: String(entry?.text || ""),
      tone: String(entry?.tone || ""),
    })),
  };
  oandaProviderTerminalPersistedPostState = {
    phase: "post",
    status: payload.status,
    logs: oandaProviderTerminalLogs.map((entry) => ({ ...entry })),
  };
  try {
    localStorage.setItem(OANDA_TERMINAL_POST_STATE_KEY, JSON.stringify(payload));
  } catch (_) {}
}

function clearPersistedOandaProviderTerminalPostState() {
  oandaProviderTerminalPersistedPostState = null;
  try {
    localStorage.removeItem(OANDA_TERMINAL_POST_STATE_KEY);
  } catch (_) {}
}

function restoreOandaProviderTerminalPostState() {
  const persisted = oandaProviderTerminalPersistedPostState || readPersistedOandaProviderTerminalPostState();
  oandaProviderTerminalPersistedPostState = persisted;
  const fallbackStatus = oandaProviderLastStatus || persisted?.status || null;
  if (fallbackStatus && (!oandaProviderLastStatus || !oandaProviderLastStatus.connected)) {
    oandaProviderLastStatus = fallbackStatus;
  }
  resetOandaProviderTerminalFieldFx();
  resetOandaProviderTerminalFieldVisibility(false);
  resetOandaProviderTerminalMaskedCarry();
  oandaProviderTerminalPhase = "post";
  oandaProviderTerminalActiveField = "post";
  resetOandaProviderDraft();
  if (persisted?.logs?.length) {
    oandaProviderTerminalLogs = persisted.logs.map((entry, index) => ({
      id: `oanda-log-restored-${index}-${Math.random().toString(16).slice(2, 8)}`,
      text: String(entry?.text || ""),
      tone: String(entry?.tone || ""),
      spinner: false,
      erasing: false,
    }));
  } else {
    oandaProviderTerminalLogs = [
      {
        id: `oanda-log-restored-validation-${Math.random().toString(16).slice(2, 8)}`,
        text: "OANDA API validation succeeded.",
        tone: "success",
        spinner: false,
        erasing: false,
      },
      {
        id: `oanda-log-restored-encryption-${Math.random().toString(16).slice(2, 8)}`,
        text: "Encryption confirmed. Local OANDA store updated.",
        tone: "success",
        spinner: false,
        erasing: false,
      },
      {
        id: `oanda-log-restored-ready-${Math.random().toString(16).slice(2, 8)}`,
        text: "Everything is ready.",
        tone: "success",
        spinner: false,
        erasing: false,
      },
    ];
  }
  trimOandaProviderTerminalLogs();
}

oandaProviderTerminalPersistedPostState = readPersistedOandaProviderTerminalPostState();

function trimOandaProviderTerminalLogs(limit = 6) {
  if (oandaProviderTerminalLogs.length > limit) {
    oandaProviderTerminalLogs = oandaProviderTerminalLogs.slice(-limit);
  }
}

function oandaProviderTerminalAllFieldsReady() {
  return oandaProviderTerminalFieldOrder().every((field) => String(oandaProviderTerminalDraft[field] || "").trim());
}

function oandaProviderTerminalMaskedValue(field) {
  const source = String(oandaProviderTerminalStoredSecrets[field] || "");
  if (!source) return "";
  return "*".repeat(Math.max(8, Math.min(14, source.length)));
}

function primeOandaProviderTerminalMaskedDraft() {
  oandaProviderTerminalFieldOrder().forEach((field) => {
    const hasStored = !!String(oandaProviderTerminalStoredSecrets[field] || "").trim();
    const shouldMask = hasStored || !!oandaProviderLastStatus?.connected;
    oandaProviderTerminalDraft[field] = shouldMask
      ? (hasStored ? oandaProviderTerminalMaskedValue(field) : "***********")
      : "";
    oandaProviderTerminalMaskedCarry[field] = shouldMask;
  });
}

function resolvedOandaProviderTerminalValue(field) {
  if (oandaProviderTerminalMaskedCarry[field] && String(oandaProviderTerminalStoredSecrets[field] || "").trim()) {
    return String(oandaProviderTerminalStoredSecrets[field] || "").trim();
  }
  if (oandaProviderTerminalMaskedCarry[field]) {
    return OANDA_KEEP_STORED_SENTINEL;
  }
  return String(oandaProviderTerminalDraft[field] || "").trim();
}

function oandaProviderTerminalNextField(field) {
  const order = oandaProviderTerminalFieldOrder();
  const index = order.indexOf(field);
  if (index < 0 || index === order.length - 1) return "validate";
  return order[index + 1];
}

function oandaProviderTerminalEditableEl(field) {
  return oandaProviderTerminalOutput?.querySelector?.(`[data-oanda-input="${field}"]`) || null;
}

function normalizedOandaEditableText(value) {
  return String(value || "").replace(/\u00A0/g, " ").replace(/\r/g, "").replace(/\n+/g, " ");
}

function setOandaProviderFieldValue(field, value) {
  oandaProviderTerminalDraft[field] = normalizedOandaEditableText(value || "");
  const input = oandaProviderTerminalEditableEl(field);
  if (input && input.value !== oandaProviderTerminalDraft[field]) {
    input.value = oandaProviderTerminalDraft[field];
  }
}

function focusOandaProviderTerminalField(field) {
  oandaProviderTerminalActiveField = field;
  if (field === "validate" || field === "post") {
    if (oandaProviderTerminalOutput) {
      oandaProviderTerminalOutput.tabIndex = 0;
      oandaProviderTerminalOutput.focus();
    }
    return;
  }
  window.requestAnimationFrame(() => {
    const editable = oandaProviderTerminalEditableEl(field);
    editable?.focus?.();
    try {
      const length = editable?.value?.length ?? 0;
      editable?.setSelectionRange?.(length, length);
    } catch (_) {
      // no-op
    }
  });
}

function createOandaTerminalLog(text, options = {}) {
  const entry = {
    id: `oanda-log-${Date.now()}-${Math.random().toString(16).slice(2, 8)}`,
    text: String(text || ""),
    tone: options.tone || "",
    spinner: !!options.spinner,
    erasing: false,
  };
  oandaProviderTerminalLogs.push(entry);
  trimOandaProviderTerminalLogs();
  renderOandaProviderTerminal();
  return entry.id;
}

async function eraseOandaTerminalLog(id) {
  const entry = oandaProviderTerminalLogs.find((item) => item.id === id);
  if (!entry) return;
  entry.erasing = true;
  renderOandaProviderTerminal();
  await waitOandaTerminal(420);
  oandaProviderTerminalLogs = oandaProviderTerminalLogs.filter((item) => item.id !== id);
  renderOandaProviderTerminal();
}

async function typeOandaTerminalLog(text, tone = "") {
  const entry = {
    id: `oanda-log-${Date.now()}-${Math.random().toString(16).slice(2, 8)}`,
    text: "",
    tone,
    spinner: false,
    erasing: false,
  };
  const source = String(text || "");
  oandaProviderTerminalLogs.push(entry);
  trimOandaProviderTerminalLogs();
  for (let index = 0; index <= source.length; index += 1) {
    entry.text = source.slice(0, index);
    renderOandaProviderTerminal();
    await waitOandaTerminal(index === source.length ? 30 : 28);
  }
}

function syncOandaProviderDraftFromInput() {
  if (oandaProviderTerminalPhase !== "editing") return;
  const editable = oandaProviderTerminalEditableEl(oandaProviderTerminalActiveField);
  if (!editable) return;
  oandaProviderTerminalDraft[oandaProviderTerminalActiveField] = normalizedOandaEditableText(editable.value || "");
}

function oandaProviderTerminalFieldDisplay(field) {
  const effect = oandaProviderTerminalFieldFx[field];
  if (effect?.text != null) return escapeOandaTerminalHtml(effect.text);
  const raw = String(oandaProviderTerminalDraft[field] || "");
  return escapeOandaTerminalHtml(raw);
}

function renderOandaProviderTerminalFields() {
  return oandaProviderTerminalFieldOrder()
    .filter((field) => oandaProviderTerminalFieldVisible[field])
    .map((field) => {
      const isActive = oandaProviderTerminalPhase === "editing" && oandaProviderTerminalActiveField === field;
      const effect = oandaProviderTerminalFieldFx[field];
      const classes = [
        "oanda-terminal-field-entry",
        isActive ? "is-active" : "",
        effect?.state === "encrypting" ? "is-encrypting" : "",
        effect?.state === "clearing" ? "is-clearing" : "",
      ].filter(Boolean).join(" ");
      const meta = oandaProviderTerminalFieldMeta(field);
      const editable = oandaProviderTerminalPhase === "editing" && !effect;
      return `
        <div class="oanda-terminal-field">
          <div class="oanda-terminal-field-label">
            <span class="oanda-terminal-field-glyph">{ }</span>
            <span>${escapeOandaTerminalHtml(meta.label)}</span>
          </div>
          <div class="${classes}" data-oanda-field="${field}">
            <span class="oanda-terminal-entry-prompt">&gt;</span>
            ${editable
              ? `<input class="oanda-terminal-entry-input" data-oanda-input="${field}" type="text" value="${escapeOandaTerminalHtml(String(oandaProviderTerminalDraft[field] || ""))}" placeholder="${escapeOandaTerminalHtml(meta.label)}" autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false">`
              : `<span class="oanda-terminal-entry-text">${oandaProviderTerminalFieldDisplay(field)}</span>`}
          </div>
        </div>
      `;
    })
    .join("");
}

function renderOandaProviderTerminalLogs() {
  if (!oandaProviderTerminalLogs.length) return "";
  return oandaProviderTerminalLogs.map((entry) => {
    const className = [
      "oanda-terminal-logline",
      entry.tone ? `oanda-terminal-logline-${entry.tone}` : "",
      entry.erasing ? "is-erasing" : "",
    ].filter(Boolean).join(" ");
    const icon = entry.spinner ? '<span class="oanda-terminal-pixel-hourglass" aria-hidden="true"></span>' : "";
    return `<div class="${className}" data-log-id="${entry.id}">${icon}<span>${renderOandaTerminalText(entry.text)}</span></div>`;
  }).join("");
}

function renderOandaProviderTerminalChoices() {
  if (oandaProviderTerminalPhase !== "post") return "";
  return `
    <div class="oanda-terminal-choiceblock">
      <div class="oanda-terminal-choicegap"></div>
      <div class="oanda-terminal-choices">
        <div class="oanda-terminal-choice-row"><span class="oanda-terminal-option">[1]</span><span>Modify credentials</span></div>
        <div class="oanda-terminal-choice-row"><span class="oanda-terminal-option">[2]</span><span>Delete credentials</span></div>
      </div>
    </div>
  `;
}

function buildOandaProviderTerminalShell(connected) {
  const statusRef = oandaProviderLastStatus || oandaProviderTerminalPersistedPostState?.status || null;
  const wordmark = oandaProviderTerminalIntroLines().map((line) => (
    `<div class="oanda-terminal-wordmark-line">${escapeOandaTerminalHtml(line)}</div>`
  )).join("");
  const statusLine = connected
    ? `<div class="oanda-terminal-statusline"><span class="oanda-terminal-label">status</span><span class="oanda-terminal-keyword">encrypted</span> via ${escapeOandaTerminalHtml(statusRef?.authSource || "OANDA")}</div>
       <div class="oanda-terminal-statusline"><span class="oanda-terminal-label">account</span>${escapeOandaTerminalHtml(statusRef?.accountIdHint || "configured")}</div>
       <div class="oanda-terminal-statusline"><span class="oanda-terminal-label">base url</span>${escapeOandaTerminalHtml(statusRef?.baseUrl || "https://api-fxtrade.oanda.com")}</div>`
    : `<div class="oanda-terminal-statusline"><span class="oanda-terminal-label">status</span><span class="oanda-terminal-keyword-alt">awaiting local OANDA credentials</span></div>`;
  const fieldsHtml = oandaProviderTerminalPhase === "post" && !Object.values(oandaProviderTerminalFieldVisible).some(Boolean)
    ? ""
    : `<div class="oanda-terminal-form">${renderOandaProviderTerminalFields()}</div>`;
  const validateHtml = oandaProviderTerminalPhase === "post"
    ? ""
    : `<div class="oanda-terminal-step">
         Press <span class="oanda-terminal-keyword-alt oanda-terminal-step-trigger" data-oanda-action="validate">1</span> to <span class="oanda-terminal-keyword">validate</span> and finish local setup.
         ${oandaProviderTerminalAllFieldsReady() ? "" : '<span class="oanda-terminal-step-muted">Finish every field first.</span>'}
       </div>`;
  return `
    <div class="oanda-terminal-shellcopy">
      <div class="oanda-terminal-hero">
        <div class="oanda-terminal-mark" aria-hidden="true">
          <span class="oanda-terminal-mark-block is-a"></span>
          <span class="oanda-terminal-mark-block is-a"></span>
          <span class="oanda-terminal-mark-block is-a"></span>
          <span class="oanda-terminal-mark-block"></span>
          <span class="oanda-terminal-mark-block"></span>
          <span class="oanda-terminal-mark-block is-a"></span>
          <span class="oanda-terminal-mark-block is-b"></span>
          <span class="oanda-terminal-mark-block"></span>
          <span class="oanda-terminal-mark-block is-a"></span>
          <span class="oanda-terminal-mark-block is-b"></span>
          <span class="oanda-terminal-mark-block is-b"></span>
          <span class="oanda-terminal-mark-block"></span>
          <span class="oanda-terminal-mark-block is-a"></span>
          <span class="oanda-terminal-mark-block is-a"></span>
          <span class="oanda-terminal-mark-block is-a"></span>
          <span class="oanda-terminal-mark-block is-a"></span>
          <span class="oanda-terminal-mark-block is-a"></span>
          <span class="oanda-terminal-mark-block"></span>
          <span class="oanda-terminal-mark-block is-b"></span>
          <span class="oanda-terminal-mark-block is-b"></span>
          <span class="oanda-terminal-mark-block"></span>
          <span class="oanda-terminal-mark-block is-a"></span>
          <span class="oanda-terminal-mark-block is-a"></span>
          <span class="oanda-terminal-mark-block is-a"></span>
          <span class="oanda-terminal-mark-block"></span>
        </div>
        <div class="oanda-terminal-hero-copy">
          <div class="oanda-terminal-bannerline"><span class="oanda-terminal-keyword">FORGE</span> PROVIDER TERMINAL</div>
          <div class="oanda-terminal-wordmark">${wordmark}</div>
          <div class="oanda-terminal-kicker"><span class="oanda-terminal-keyword">OANDA</span> credential bridge for <span class="oanda-terminal-keyword-alt">Trading</span></div>
          <div class="oanda-terminal-intro">
            <span class="oanda-terminal-keyword">Validate</span> broker access, keep credentials only on your machine
            with <span class="oanda-terminal-keyword-alt">encrypted key storage</span> in the <span class="oanda-terminal-keyword-alt">OS secure store</span>,
            and enable <span class="oanda-terminal-keyword">live routing</span>.
          </div>
        </div>
      </div>
      <div class="oanda-terminal-panel">
        ${statusLine}
        ${fieldsHtml}
        ${validateHtml}
        <div class="oanda-terminal-logfeed">${renderOandaProviderTerminalLogs()}</div>
        ${renderOandaProviderTerminalChoices()}
      </div>
    </div>
  `;
}

function startOandaProviderTerminal(options = {}) {
  const connected = !!oandaProviderLastStatus?.connected || !!oandaProviderTerminalPersistedPostState?.status?.connected;
  if (connected) {
    restoreOandaProviderTerminalPostState();
  } else {
    if (!options.preserveDraft) resetOandaProviderDraft();
    resetOandaProviderTerminalLogs();
    resetOandaProviderTerminalFieldFx();
    resetOandaProviderTerminalFieldVisibility(true);
    oandaProviderTerminalPhase = "editing";
    oandaProviderTerminalActiveField = "accountId";
  }
  renderOandaProviderTerminal();
  focusOandaProviderTerminalField(connected ? "post" : "accountId");
}

function renderOandaProviderStatus(status, options = {}) {
  const busy = !!options.busy;
  oandaProviderLastStatus = status || oandaProviderLastStatus;
  if (oandaProviderLastStatus?.connected) {
    if (oandaProviderTerminalPhase === "post" || oandaProviderTerminalPersistedPostState) {
      persistOandaProviderTerminalPostState();
    }
  } else if (!busy) {
    clearPersistedOandaProviderTerminalPostState();
  }
  if (providerLauncherOandaMeta) providerLauncherOandaMeta.textContent = oandaProviderBaseUrlLabel(status);
  renderProviderWorkbenchLauncher("oanda", oandaProviderLauncherState(status, { busy }), { muted: false });
  if (activeProviderWorkbench === "oanda") {
    if (oandaProviderLastStatus?.connected && !oandaProviderTerminalBusy) {
      restoreOandaProviderTerminalPostState();
      renderOandaProviderTerminal();
      focusOandaProviderTerminalField("post");
    } else if (!oandaProviderLastStatus?.connected && oandaProviderTerminalPhase === "post" && !oandaProviderTerminalBusy) {
      startOandaProviderTerminal({ preserveDraft: false });
    } else if (!oandaProviderTerminalBaseHtml) {
      startOandaProviderTerminal({ preserveDraft: true });
    }
  }
  renderProviderWorkbench();
}

async function refreshOandaProviderStatus(options = {}) {
  const invoke = window.__TAURI__?.core?.invoke;
  if (!options.silent) {
    renderOandaProviderStatus(oandaProviderLastStatus || {
      connected: false,
      installed: true,
      authSource: "none",
      baseUrl: "https://api-fxpractice.oanda.com",
      accountIdHint: "not set",
      message: "Checking OANDA credential status.",
    }, { busy: true });
  }
  if (!invoke) {
    const fallback = {
      connected: false,
      installed: true,
      authSource: "none",
      baseUrl: "https://api-fxpractice.oanda.com",
      accountIdHint: "not set",
      message: "Open Forge as a Tauri app to validate and save OANDA credentials.",
    };
    renderOandaProviderStatus(fallback);
    return fallback;
  }
  try {
    const status = await invoke("trading_oanda_provider_status");
    renderOandaProviderStatus(status);
    return status;
  } catch (err) {
    const fallback = {
      connected: false,
      installed: true,
      authSource: "error",
      baseUrl: "https://api-fxpractice.oanda.com",
      accountIdHint: "not set",
      message: `OANDA status failed: ${err}`,
    };
    renderOandaProviderStatus(fallback);
    return fallback;
  }
}

async function saveOandaProviderCredentialsFromTerminal() {
  const invoke = window.__TAURI__?.core?.invoke;
  if (!invoke) {
    void typeOandaTerminalLog("Open Forge as a Tauri app to validate and save OANDA credentials.", "error");
    return;
  }
  if (!oandaProviderTerminalAllFieldsReady()) {
    const missingField = oandaProviderTerminalFieldOrder().find((field) => !String(oandaProviderTerminalDraft[field] || "").trim()) || "accountId";
    await typeOandaTerminalLog(`Missing ${oandaProviderTerminalFieldMeta(missingField).label}.`, "error");
    focusOandaProviderTerminalField(missingField);
    return;
  }
  setOandaProviderTerminalBusy(true);
  oandaProviderTerminalPhase = "validating";
  renderOandaProviderTerminal();
  const spinnerId = createOandaTerminalLog("Checking OANDA API connectivity...", { tone: "pending", spinner: true });
  try {
    const request = {
      accountId: resolvedOandaProviderTerminalValue("accountId"),
      apiKey: resolvedOandaProviderTerminalValue("apiKey"),
      baseUrl: resolvedOandaProviderTerminalValue("baseUrl"),
    };
    const validation = await invoke("trading_oanda_provider_validate_credentials", {
      request,
    });
    await eraseOandaTerminalLog(spinnerId);
    await typeOandaTerminalLog(validation?.message || "OANDA API validation succeeded.", "success");
    await waitOandaTerminal(320);
    oandaProviderTerminalPhase = "encrypting";
    renderOandaProviderTerminal();
    await typeOandaTerminalLog("Encrypting local credentials with Windows DPAPI...", "accent");
    const sources = {
      accountId: request.accountId,
      apiKey: request.apiKey,
      baseUrl: request.baseUrl,
    };
    const randomSource = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
    for (let step = 0; step <= 12; step += 1) {
      oandaProviderTerminalFieldOrder().forEach((field) => {
        const length = Math.max(6, String(sources[field] || "").length || 6);
        const starCount = step >= 8 ? Math.min(6, step - 6) : 0;
        const randomCount = Math.max(length - starCount, 0);
        const randomPart = Array.from({ length: randomCount }, () => randomSource[Math.floor(Math.random() * randomSource.length)]).join("");
        const stars = "*".repeat(starCount);
        oandaProviderTerminalFieldFx[field] = {
          state: "encrypting",
          text: step >= 12 ? "******" : `${randomPart}${stars}`,
        };
      });
      renderOandaProviderTerminal();
      await waitOandaTerminal(132);
    }
    oandaProviderTerminalFieldOrder().forEach((field) => {
      oandaProviderTerminalFieldFx[field] = { state: "clearing", text: "******" };
    });
    renderOandaProviderTerminal();
    await waitOandaTerminal(420);
    resetOandaProviderTerminalFieldFx();
    resetOandaProviderTerminalFieldVisibility(false);
    renderOandaProviderTerminal();
    const status = await invoke("trading_oanda_provider_encrypt_credentials", {
      request,
    });
    oandaProviderTerminalStoredSecrets = {
      accountId: request.accountId,
      apiKey: request.apiKey,
      baseUrl: request.baseUrl,
    };
    renderOandaProviderStatus(status);
    await typeOandaTerminalLog("Encryption confirmed. Local OANDA store updated.", "success");
    await waitOandaTerminal(220);
    await typeOandaTerminalLog("Everything is ready.", "success");
    oandaProviderTerminalPhase = "post";
    resetOandaProviderDraft();
    persistOandaProviderTerminalPostState();
    focusOandaProviderTerminalField("post");
  } catch (err) {
    await eraseOandaTerminalLog(spinnerId);
    oandaProviderTerminalPhase = "editing";
    resetOandaProviderTerminalFieldFx();
    resetOandaProviderTerminalFieldVisibility(true);
    await typeOandaTerminalLog(`Validation failed: ${err}`, "error");
    focusOandaProviderTerminalField("accountId");
  } finally {
    setOandaProviderTerminalBusy(false);
    renderOandaProviderTerminal();
    focusOandaProviderTerminalField(oandaProviderTerminalPhase === "post" ? "post" : oandaProviderTerminalActiveField);
  }
}

async function clearOandaProviderCredentialsFromTerminal() {
  const invoke = window.__TAURI__?.core?.invoke;
  if (!invoke) {
    void typeOandaTerminalLog("Open Forge as a Tauri app to clear OANDA credentials.", "error");
    return;
  }
  setOandaProviderTerminalBusy(true);
  oandaProviderTerminalPhase = "encrypting";
  renderOandaProviderTerminal();
  const spinnerId = createOandaTerminalLog("Removing encrypted local credentials...", { tone: "pending", spinner: true });
  try {
    const status = await invoke("trading_oanda_clear_credentials");
    await eraseOandaTerminalLog(spinnerId);
    renderOandaProviderStatus(status);
    oandaProviderTerminalStoredSecrets = { accountId: "", apiKey: "", baseUrl: "" };
    clearPersistedOandaProviderTerminalPostState();
    resetOandaProviderDraft();
    resetOandaProviderTerminalFieldFx();
    resetOandaProviderTerminalFieldVisibility(true);
    oandaProviderTerminalPhase = "editing";
    await typeOandaTerminalLog(status?.message || "OANDA credentials cleared.", "success");
    focusOandaProviderTerminalField("accountId");
  } catch (err) {
    await eraseOandaTerminalLog(spinnerId);
    await typeOandaTerminalLog(`Clear failed: ${err}`, "error");
  } finally {
    setOandaProviderTerminalBusy(false);
    renderOandaProviderTerminal();
    focusOandaProviderTerminalField(oandaProviderTerminalPhase === "post" ? "post" : oandaProviderTerminalActiveField);
  }
}

function printOandaProviderStatusToTerminal() {
  const status = oandaProviderLastStatus;
  void typeOandaTerminalLog(`status: ${status?.connected ? "ready" : "not configured"}`, "accent");
  void typeOandaTerminalLog(`source: ${status?.authSource || "none"}`, "muted");
  void typeOandaTerminalLog(`account: ${status?.accountIdHint || "not set"}`, "muted");
  void typeOandaTerminalLog(`base url: ${status?.baseUrl || "https://api-fxpractice.oanda.com"}`, "muted");
  if (status?.message) void typeOandaTerminalLog(status.message, "muted");
}

function renderOandaProviderTerminal() {
  const connected = !!oandaProviderLastStatus?.connected || !!oandaProviderTerminalPersistedPostState?.status?.connected;
  oandaProviderTerminalBaseHtml = buildOandaProviderTerminalShell(connected);
  oandaProviderTerminalLogHtml = "";
  syncOandaProviderTerminalOutput();
  if (oandaProviderTerminalOutput) oandaProviderTerminalOutput.tabIndex = 0;
  setOandaProviderTerminalStateLabel(oandaProviderTerminalStatusText());
  if (oandaProviderTerminalBusy) {
    setOandaProviderTerminalInputMode({ placeholder: "Forge is checking the OANDA connection...", secret: false, disabled: true });
    return;
  }
  if (oandaProviderTerminalPhase === "post") {
    setOandaProviderTerminalInputMode({ placeholder: "Type 1 to modify or 2 to delete", secret: false, disabled: false });
    return;
  }
  if (oandaProviderTerminalActiveField === "validate") {
    setOandaProviderTerminalInputMode({ placeholder: "Type 1 then press Enter to validate", secret: false, disabled: false });
    return;
  }
  const meta = oandaProviderTerminalFieldMeta(oandaProviderTerminalActiveField);
  setOandaProviderTerminalInputMode({ placeholder: meta.placeholder, secret: meta.secret, disabled: false });
}

async function submitOandaProviderTerminalInput(forcedValue = null) {
  if (oandaProviderTerminalBusy) return;
  const raw = forcedValue == null ? String(oandaProviderTerminalInput?.value || "") : String(forcedValue);
  const value = raw.trim();
  if (oandaProviderTerminalPhase === "post") {
    if (value === "1") {
      if (
        oandaProviderTerminalFieldOrder().some((field) => String(oandaProviderTerminalStoredSecrets[field] || "").trim())
        || !!oandaProviderLastStatus?.connected
      ) {
        primeOandaProviderTerminalMaskedDraft();
      } else {
        resetOandaProviderDraft();
      }
      resetOandaProviderTerminalFieldFx();
      resetOandaProviderTerminalFieldVisibility(true);
      oandaProviderTerminalPhase = "editing";
      renderOandaProviderTerminal();
      focusOandaProviderTerminalField("accountId");
      return;
    }
    if (value === "2") {
      if (oandaProviderTerminalInput) oandaProviderTerminalInput.value = "";
      await clearOandaProviderCredentialsFromTerminal();
      return;
    }
    if (value) await typeOandaTerminalLog("Type 1 to modify or 2 to delete the local credentials.", "error");
    focusOandaProviderTerminalField("post");
    return;
  }
  if (oandaProviderTerminalActiveField === "validate") {
    if (value === "1") {
      if (oandaProviderTerminalInput) oandaProviderTerminalInput.value = "";
      await saveOandaProviderCredentialsFromTerminal();
      return;
    }
    if (value) await typeOandaTerminalLog("Press 1 to launch the live validation.", "error");
    focusOandaProviderTerminalField("validate");
    return;
  }
  if (oandaProviderTerminalPhase === "editing" && value === "1" && oandaProviderTerminalAllFieldsReady()) {
    if (oandaProviderTerminalInput) oandaProviderTerminalInput.value = "";
    oandaProviderTerminalActiveField = "validate";
    await saveOandaProviderCredentialsFromTerminal();
    return;
  }
  if (!oandaProviderTerminalFieldOrder().includes(oandaProviderTerminalActiveField)) {
    focusOandaProviderTerminalField("accountId");
    return;
  }
  oandaProviderTerminalDraft[oandaProviderTerminalActiveField] = raw;
  if (!value) {
    await typeOandaTerminalLog(`Missing ${oandaProviderTerminalFieldMeta(oandaProviderTerminalActiveField).label}.`, "error");
    focusOandaProviderTerminalField(oandaProviderTerminalActiveField);
    return;
  }
  const nextField = oandaProviderTerminalNextField(oandaProviderTerminalActiveField);
  renderOandaProviderTerminal();
  focusOandaProviderTerminalField(nextField);
}

function providerWorkbenchStatus(kind) {
  if (kind === "codex") return codexProviderLastStatus || openAiProviderLastStatus;
  if (kind === "claude") return claudeProviderLastStatus;
  if (kind === "oanda") return oandaProviderLastStatus;
  return geminiProviderLastStatus;
}

function providerWorkbenchDisplayName(kind) {
  if (kind === "codex") return "Codex";
  if (kind === "claude") return "Claude";
  if (kind === "oanda") return "OANDA";
  return "Gemini";
}

function providerStatusTextBlob(status) {
  return `${String(status?.authSource || "")}\n${String(status?.message || "")}`.toLowerCase();
}

function providerStatusNeedsNode(status) {
  return /node\.js|npm/i.test(String(status?.message || ""));
}

function providerStatusNeedsRepair(status) {
  return /found but not executable|found on disk, but forge could not execute|permissions|access denied|acces refuse/i
    .test(providerStatusTextBlob(status));
}

function providerCliEffectiveInstalled(status) {
  return !!status?.installed || !!status?.connected || providerStatusNeedsRepair(status);
}

function providerCliFriendlySource(kind, status) {
  const connected = !!status?.connected;
  const installed = providerCliEffectiveInstalled(status);
  const source = providerStatusTextBlob(status);
  if (connected) {
    if (kind === "gemini") {
      if (source.includes("api key")) return "saved local key";
      if (source.includes("oauth") || source.includes("google")) return "Google login";
      return "Gemini ready";
    }
    if (kind === "claude") {
      if (source.includes("oauth") || source.includes("claude.ai")) return "Claude.ai login";
      if (source.includes("credential")) return "saved local login";
      return "Claude ready";
    }
    return "OpenAI login";
  }
  if (providerStatusNeedsRepair(status)) return "automatic repair";
  if (installed) return "local setup";
  return "automatic setup";
}

function providerCliFriendlyHint(kind, status, options = {}) {
  const busy = !!options.busy;
  const connected = !!status?.connected;
  const installed = providerCliEffectiveInstalled(status);
  const selectedModel = options.selectedModel || providerWorkbenchModel(kind);
  const display = providerWorkbenchDisplayName(kind);
  const modelText = selectedModel ? ` Selected model: ${selectedModel}.` : "";
  if (busy) return `Checking ${display} in Forge.${modelText}`;
  if (connected) return `${display} is ready in Forge.${modelText}`;
  if (providerStatusNeedsRepair(status)) {
    return `${display} is being repaired automatically in Forge.${modelText}`;
  }
  if (providerStatusNeedsNode(status)) {
    return `Node.js is required before Forge can finish the automatic ${display} setup.${modelText}`;
  }
  if (installed) {
    return `${display} is preparing its local connection in Forge.${modelText}`;
  }
  return `${display} is preparing. Forge will install and connect it automatically when the environment is ready.${modelText}`;
}

const providerAutoHealLastAttempt = new Map();
let providerAutoHealTimer = null;

function isTradingBrokerProvider(kind) {
  return kind === "oanda";
}

function tradingBrokerDisplayName(kind) {
  if (kind === "oanda") return "OANDA";
  return String(kind || "Broker").toUpperCase();
}

function setActiveTradingBroker(kind = "oanda") {
  const next = isTradingBrokerProvider(kind) ? kind : "oanda";
  activeTradingBroker = next;
  try { localStorage.setItem("forge.trading.broker", next); } catch (_) {}
  if (alphaTradingHeaderState.active) {
    alphaTradingHeaderState.brokerLabel = tradingBrokerDisplayName(next);
    updateWorkspaceBreadcrumb();
  }
  if (typeof window !== "undefined") {
    window.dispatchEvent(new CustomEvent("forge:trading-broker-change", {
      detail: {
        broker: next,
        label: tradingBrokerDisplayName(next),
      },
    }));
  }
}

function providerWorkbenchModel(kind) {
  if (kind === "codex") return selectedOpenAiModelRef();
  if (kind === "claude") return selectedClaudeModelRef();
  if (kind === "oanda") return oandaProviderBaseUrlLabel();
  return selectedGeminiModelRef();
}

function providerLauncherDom(kind) {
  if (kind === "codex") {
    return {
      button: providerLauncherCodex,
      dot: providerLauncherCodexDot,
      state: providerLauncherCodexState,
      meta: providerLauncherCodexMeta,
    };
  }
  if (kind === "claude") {
    return {
      button: providerLauncherClaude,
      dot: providerLauncherClaudeDot,
      state: providerLauncherClaudeState,
      meta: providerLauncherClaudeMeta,
    };
  }
  if (kind === "oanda") {
    return {
      button: providerLauncherOanda,
      dot: providerLauncherOandaDot,
      state: providerLauncherOandaState,
      meta: providerLauncherOandaMeta,
    };
  }
  return {
    button: providerLauncherGemini,
    dot: providerLauncherGeminiDot,
    state: providerLauncherGeminiState,
    meta: providerLauncherGeminiMeta,
  };
}

function providerWorkbenchLogoClass(kind) {
  if (kind === "codex") return "provider-logo-openai";
  if (kind === "claude") return "provider-logo-claude";
  if (kind === "oanda") return "provider-logo-oanda";
  return "provider-logo-gemini";
}

function providerWorkbenchStateText(status) {
  const connected = !!status?.connected;
  const installed = providerCliEffectiveInstalled(status);
  if (connected) return "ready";
  if (installed) return "auth";
  return "missing";
}

function stripAnsiTerminalCodes(value) {
  return String(value || "").replace(/\x1B\[[0-?]*[ -/]*[@-~]/g, "");
}

function shouldSuppressProviderTerminalLine(provider, line) {
  const plain = stripAnsiTerminalCodes(line).trim();
  if (!plain) return false;
  if (provider === "codex") {
    if (/Skipped loading \d+ skill\(s\) due to invalid SKILL\.md files\./i.test(plain)) return true;
    if (/SKILL\.md:\s+missing YAML frontmatter delimited by ---/i.test(plain)) return true;
    if (/cloudflare-api MCP server is not logged in/i.test(plain)) return true;
    if (/MCP client .*xcodebuildmcp.* failed to start/i.test(plain)) return true;
    if (/MCP startup incomplete \(failed: .*cloudflare-api.*xcodebuildmcp.*\)/i.test(plain)) return true;
    if (/Starting MCP servers \(\d+\/\d+\): xcodebuildmcp/i.test(plain)) return true;
  }
  return false;
}

function filterProviderTerminalDisplayText(provider, text, options = {}) {
  const normalized = String(text || "").replace(/\r\n/g, "\n");
  providerTerminalFilterCarry[provider] = "";
  return normalized;
}

function providerTerminalRawOutput(provider) {
  if (provider === "codex") return codexProviderTerminalOutputCache || "";
  if (provider === "claude") return claudeProviderTerminalOutputCache || "";
  return geminiProviderTerminalOutputCache || "";
}

function providerTerminalStoryProfile(provider) {
  if (provider === "codex") {
    return {
      name: "Codex",
      runtime: "OpenAI Codex CLI",
      metaLabel: "model",
      sourceLabel: "subscription",
      eyebrow: "OPENAI SUBSCRIPTION BRIDGE",
      kicker: "Codex CLI bridge for local Forge sessions",
      intro: "Reuse local ChatGPT / Codex subscription auth, open the runtime directly inside Forge, and keep session routing on this machine.",
    };
  }
  if (provider === "claude") {
    return {
      name: "Claude",
      runtime: "Claude Code CLI",
      metaLabel: "model",
      sourceLabel: "auth",
      eyebrow: "ANTHROPIC CLI BRIDGE",
      kicker: "Claude Code login bridge for local Forge sessions",
      intro: "Open Claude Code inside Forge, finish Claude.ai authentication locally, and keep the linked workspace flow inside the embedded terminal.",
    };
  }
  return {
    name: "Gemini",
    runtime: "Gemini CLI",
    metaLabel: "model",
    sourceLabel: "auth",
    eyebrow: "GOOGLE CLI BRIDGE",
    kicker: "Gemini CLI bridge for local Forge sessions",
    intro: "Launch Gemini directly inside Forge, reuse local CLI auth or the saved local API key, and keep installation plus login in one terminal surface.",
  };
}

function providerTerminalPixelGlyphs() {
  return {
    A: [" ███ ", "██ ██", "█████", "██ ██", "██ ██"],
    C: [" ████", "██   ", "██   ", "██   ", " ████"],
    D: ["████ ", "██ ██", "██ ██", "██ ██", "████ "],
    E: ["█████", "██   ", "████ ", "██   ", "█████"],
    G: [" ████ ", "██    ", "██ ███", "██   ██", " █████ "],
    I: ["█████", "  ██ ", "  ██ ", "  ██ ", "█████"],
    L: ["██   ", "██   ", "██   ", "██   ", "█████"],
    M: ["██   ██", "███ ███", "██ █ ██", "██   ██", "██   ██"],
    N: ["██   ██", "███  ██", "██ ██ ██", "██  ███", "██   ██"],
    O: [" ████ ", "██  ██", "██  ██", "██  ██", " ████ "],
    U: ["██  ██", "██  ██", "██  ██", "██  ██", " ████ "],
    X: ["██  ██", " ██ ██", "  ███ ", " ██ ██", "██  ██"],
  };
}

function providerTerminalPixelWordmark(name) {
  const glyphs = providerTerminalPixelGlyphs();
  const letters = String(name || "").toUpperCase().split("");
  const rows = ["", "", "", "", ""];
  letters.forEach((letter, index) => {
    const glyph = glyphs[letter] || ["?????", "?????", "?????", "?????", "?????"];
    for (let row = 0; row < rows.length; row += 1) {
      rows[row] += glyph[row];
      if (index < letters.length - 1) rows[row] += "  ";
    }
  });
  return rows;
}

function providerTerminalStoryStatus(provider) {
  if (provider === "codex") {
    return {
      ...(codexProviderLastStatus || openAiProviderLastStatus || {}),
      accountLabel: openAiProviderLastStatus?.accountLabel || codexProviderLastStatus?.accountLabel || "",
      modelRef: selectedOpenAiModelRef(),
    };
  }
  if (provider === "claude") {
    return {
      ...(claudeProviderLastStatus || {}),
      modelRef: selectedClaudeModelRef(),
    };
  }
  return {
    ...(geminiProviderLastStatus || {}),
    modelRef: selectedGeminiModelRef(),
  };
}

function providerTerminalStoryState(provider) {
  const status = providerTerminalStoryStatus(provider);
  const connected = !!status?.connected;
  const installed = providerCliEffectiveInstalled(status);
  const running = providerTerminalIsRunning(provider);
  const opening = providerTerminalIsOpening(provider);
  const needsNode = providerStatusNeedsNode(status);
  let stateText = "missing";
  let tone = "error";
  if (opening) {
    stateText = "opening";
    tone = "accent";
  } else if (running) {
    stateText = "live";
    tone = "success";
  } else if (connected) {
    stateText = "ready";
    tone = "success";
  } else if (installed) {
    stateText = "auth";
    tone = "accent";
  } else if (needsNode) {
    stateText = "needs node";
    tone = "error";
  }
  return {
    profile: providerTerminalStoryProfile(provider),
    status,
    connected,
    installed,
    running,
    opening,
    needsNode,
    stateText,
    tone,
  };
}

function providerTerminalStoryPreviewTone(line) {
  const plain = stripAnsiTerminalCodes(line).trim();
  if (!plain) return "muted";
  if (/\b(error|failed|missing|not installed|not visible|denied|unavailable)\b/i.test(plain)) return "error";
  if (/\b(ready|connected|logged in|succeeded|saved|opened|attached|available)\b/i.test(plain)) return "success";
  if (/\b(install|opening|preparing|checking|waiting|auth|connect|launch)\b/i.test(plain)) return "accent";
  if (/\[forge\]/i.test(plain)) return "accent";
  return "muted";
}

function providerTerminalStoryPreviewLines(provider) {
  const { profile, status, connected, installed, running, opening, needsNode } = providerTerminalStoryState(provider);
  const raw = providerTerminalRawOutput(provider);
  const lines = String(raw || "")
    .replace(/\r/g, "")
    .split("\n")
    .map((line) => stripAnsiTerminalCodes(line).trimEnd())
    .filter((line) => line.trim() && line.trim() !== "Ready.")
    .slice(-6)
    .map((line) => ({
      text: line,
      tone: providerTerminalStoryPreviewTone(line),
    }));
  if (lines.length) return lines;
  if (running || opening) {
    return [
      { text: `Preparing the live ${profile.runtime} session inside Forge.`, tone: "accent" },
      { text: "The embedded terminal will take over as soon as the runtime is attached.", tone: "muted" },
    ];
  }
  if (connected) {
    return [
      { text: `${profile.runtime} is ready to open in Forge.`, tone: "success" },
      { text: providerCliFriendlyHint(provider, status, { selectedModel: status?.modelRef || providerWorkbenchModel(provider) }), tone: "muted" },
    ];
  }
  if (providerStatusNeedsRepair(status)) {
    return [
      { text: `${profile.runtime} is being repaired automatically in Forge.`, tone: "accent" },
      { text: "Forge will reinstall or reconnect the local runtime as needed.", tone: "muted" },
    ];
  }
  if (installed) {
    return [
      { text: `${profile.runtime} is preparing its local connection.`, tone: "accent" },
      { text: "Forge will keep the embedded terminal aligned until the runtime is ready.", tone: "muted" },
    ];
  }
  if (needsNode) {
    return [
      { text: "Node.js is required before Forge can install this CLI automatically.", tone: "error" },
      { text: "Install Node.js once, then Forge can finish the automatic setup.", tone: "muted" },
    ];
  }
  return [
    { text: `${profile.runtime} is preparing in Forge.`, tone: "accent" },
    { text: "Forge can install and reconnect this runtime automatically inside the embedded terminal.", tone: "muted" },
  ];
}

function providerTerminalStoryActionText(provider) {
  const { profile, connected, installed, running, opening, needsNode } = providerTerminalStoryState(provider);
  if (opening || running) return `Forge is routing the live ${profile.name} session into the embedded terminal.`;
  if (connected) return `Press Open above to launch ${profile.name} inside Forge.`;
  if (installed) return `Forge is completing the ${profile.name} connection automatically.`;
  if (needsNode) return "Install Node.js first, then reopen this terminal to let Forge install the CLI.";
  return "Forge can bootstrap this runtime automatically from the embedded terminal.";
}

function buildProviderStoryMark() {
  const pattern = [
    "a", "a", "a", "", "",
    "a", "b", "", "a", "b",
    "b", "", "a", "a", "a",
    "a", "a", "", "b", "b",
    "", "a", "a", "a", "",
  ];
  return pattern
    .map((tone) => `<span class="provider-story-mark-block${tone ? ` is-${tone}` : ""}"></span>`)
    .join("");
}

function buildCliProviderTerminalShell(provider) {
  const { profile, status, connected, stateText, tone, running, opening } = providerTerminalStoryState(provider);
  const wordmark = providerTerminalPixelWordmark(profile.name).map((line) => (
    `<div class="provider-story-wordmark-line">${escapeOandaTerminalHtml(line)}</div>`
  )).join("");
  const accountLabel = provider === "codex"
    ? String(status?.accountLabel || "Not connected")
    : provider === "gemini"
      ? String(status?.configured ? "Local API key saved" : "CLI login")
      : "Claude.ai local login";
  const sourceLabel = providerCliFriendlySource(provider, status);
  const metaValue = String(status?.modelRef || providerWorkbenchModel(provider));
  const previewLines = providerTerminalStoryPreviewLines(provider);
  const previewHtml = previewLines
    .map((entry) => `
      <div class="provider-story-logline provider-story-logline-${escapeOandaTerminalHtml(entry.tone || "muted")}">
        <span>${renderOandaTerminalText(entry.text)}</span>
      </div>
    `)
    .join("");
  const statusToneClass = tone === "success"
    ? "provider-story-keyword"
    : tone === "accent"
      ? "provider-story-keyword-alt"
      : "provider-story-keyword-error";
  return `
    <div class="provider-story-shellcopy">
      <div class="provider-story-hero">
        <div class="provider-story-mark" aria-hidden="true">${buildProviderStoryMark()}</div>
        <div class="provider-story-hero-copy">
          <div class="provider-story-bannerline"><span class="provider-story-keyword">FORGE</span> PROVIDER TERMINAL</div>
          <div class="provider-story-wordmark">${wordmark}</div>
          <div class="provider-story-kicker"><span class="provider-story-keyword">${escapeOandaTerminalHtml(profile.eyebrow)}</span></div>
          <div class="provider-story-intro">${escapeOandaTerminalHtml(profile.intro)}</div>
        </div>
      </div>
      <div class="provider-story-panel">
        <div class="provider-story-statusline"><span class="provider-story-label">status</span><span class="${statusToneClass}">${escapeOandaTerminalHtml(stateText)}</span></div>
        <div class="provider-story-statusline"><span class="provider-story-label">runtime</span>${escapeOandaTerminalHtml(profile.runtime)}</div>
        <div class="provider-story-statusline"><span class="provider-story-label">${escapeOandaTerminalHtml(profile.sourceLabel)}</span>${escapeOandaTerminalHtml(sourceLabel)}</div>
        <div class="provider-story-statusline"><span class="provider-story-label">${escapeOandaTerminalHtml(profile.metaLabel)}</span>${escapeOandaTerminalHtml(metaValue)}</div>
        <div class="provider-story-statusline"><span class="provider-story-label">account</span>${escapeOandaTerminalHtml(accountLabel)}</div>
        <div class="provider-story-step">${escapeOandaTerminalHtml(providerTerminalStoryActionText(provider))}</div>
        <div class="provider-story-logfeed">${previewHtml}</div>
        ${(running || opening) ? `
          <div class="provider-story-liveframe">
            <div class="provider-story-livehead">
              <span class="provider-story-label">live</span>
              <span class="provider-story-livecaption">${escapeOandaTerminalHtml(profile.runtime)}</span>
            </div>
            <div class="provider-story-livebox">
              <div class="provider-story-live-slot" data-provider-live-slot="${escapeOandaTerminalHtml(provider)}"></div>
            </div>
          </div>
        ` : ""}
      </div>
    </div>
  `;
}

function attachProviderTerminalViewport(provider) {
  const dom = providerTerminalDom(provider);
  const viewport = dom?.viewport;
  if (!viewport) return;
  const screen = dom.shell?.querySelector?.(".provider-terminal-screen");
  if (screen && viewport.parentElement !== screen) {
    screen.insertBefore(viewport, screen.firstChild || null);
  }
  syncProviderTerminalViewportPlacement(provider);
}

function syncProviderTerminalViewportPlacement(provider) {
  const dom = providerTerminalDom(provider);
  const viewport = dom?.viewport;
  const screen = dom?.shell?.querySelector?.(".provider-terminal-screen");
  const slot = dom?.output?.querySelector?.(`[data-provider-live-slot="${provider}"]`) || null;
  if (!viewport || !screen) return;
  if (!slot) {
    viewport.style.position = "";
    viewport.style.left = "";
    viewport.style.top = "";
    viewport.style.width = "";
    viewport.style.height = "";
    return;
  }
  const screenRect = screen.getBoundingClientRect();
  const slotRect = slot.getBoundingClientRect();
  const left = Math.max(0, slotRect.left - screenRect.left);
  const top = Math.max(0, slotRect.top - screenRect.top);
  const width = Math.max(0, slotRect.width);
  const height = Math.max(0, slotRect.height);
  viewport.style.position = "absolute";
  viewport.style.left = `${left}px`;
  viewport.style.top = `${top}px`;
  viewport.style.width = `${width}px`;
  viewport.style.height = `${height}px`;
  requestAnimationFrame(() => {
    const runtime = providerTerminalInstances.get(provider);
    try {
      runtime?.fitAddon?.fit();
      void resizeProviderTerminalToFit(provider);
    } catch (_) {}
  });
}

function renderCliProviderTerminalShell(provider) {
  const dom = providerTerminalDom(provider);
  if (!dom?.output) return;
  dom.output.innerHTML = buildCliProviderTerminalShell(provider);
  attachProviderTerminalViewport(provider);
  dom.output.scrollTop = 0;
}

function providerTerminalReplaySeed(provider, text) {
  const normalized = String(text || "").replace(/\r\n/g, "\n");
  if (!normalized) return "";
  const maxChars = 24000;
  const tail = normalized.length > maxChars ? normalized.slice(-maxChars) : normalized;
  const anchor = provider === "codex"
    ? "OpenAI Codex"
    : provider === "gemini"
      ? "Gemini CLI"
      : "Claude";
  const anchorIndex = tail.indexOf(anchor);
  if (anchorIndex >= 0) {
    const windowStart = Math.max(0, anchorIndex - 256);
    const escStart = tail.lastIndexOf("\u001b", anchorIndex);
    const start = escStart >= windowStart ? escStart : windowStart;
    return tail.slice(start);
  }
  return tail;
}

function providerTerminalIsRunning(kind) {
  if (kind === "codex") return !!codexProviderTerminalRunning;
  if (kind === "claude") return !!claudeProviderTerminalRunning;
  if (kind === "oanda") return false;
  return !!geminiProviderTerminalRunning;
}

function providerTerminalIsOpening(kind) {
  if (kind === "codex") return !!codexProviderTerminalOpening;
  if (kind === "claude") return !!claudeProviderTerminalOpening;
  if (kind === "oanda") return false;
  return !!geminiProviderTerminalOpening;
}

function setProviderTerminalOpening(kind, opening) {
  if (kind === "codex") codexProviderTerminalOpening = !!opening;
  else if (kind === "claude") claudeProviderTerminalOpening = !!opening;
  else if (kind === "oanda") return;
  else geminiProviderTerminalOpening = !!opening;
}

function providerWorkbenchCanOpen(kind) {
  if (kind === "oanda") return true;
  const status = providerWorkbenchStatus(kind);
  const connected = !!status?.connected;
  const installed = providerCliEffectiveInstalled(status);
  return installed;
}

function providerShouldAutoHeal(kind, status) {
  if (!["codex", "gemini", "claude"].includes(kind)) return false;
  if (!window.__TAURI__?.core?.invoke) return false;
  if (!status) return true;
  if (providerTerminalIsRunning(kind) || providerTerminalIsOpening(kind)) return false;
  if (!!status.connected) return false;
  if (providerStatusNeedsNode(status)) return false;
  return providerCliEffectiveInstalled(status) || !status?.installed;
}

async function maybeAutoHealProvider(kind, status, options = {}) {
  if (options.autoHeal === false || options.busy) return;
  if (!providerShouldAutoHeal(kind, status)) return;
  const now = Date.now();
  const last = providerAutoHealLastAttempt.get(kind) || 0;
  if (now - last < 15000) return;
  providerAutoHealLastAttempt.set(kind, now);
  try {
    if (kind === "codex") await connectCodexProvider({ background: true });
    else if (kind === "claude") await connectClaudeProvider({ background: true });
    else await connectGeminiProvider({ background: true });
  } catch (_) {}
}

function startProviderAutoHealRobot() {
  if (providerAutoHealTimer || !window.__TAURI__?.core?.invoke) return;
  providerAutoHealTimer = setInterval(() => {
    void refreshProviderWorkbenchStatuses({ silent: true, autoHeal: true });
  }, 30000);
}

async function maybeAutoLaunchProviderWorkbench(kind) {
  if (!providerWorkbenchCanOpen(kind)) return;
  if (providerTerminalIsRunning(kind) || providerTerminalIsOpening(kind)) return;
  if (kind === "codex") await connectCodexProvider();
  else if (kind === "claude") await connectClaudeProvider();
  else if (kind === "oanda") {
    if (!oandaProviderTerminalBaseHtml || oandaProviderTerminalPhase === "boot") startOandaProviderTerminal({ preserveDraft: true });
    renderOandaProviderTerminal();
  }
  else await connectGeminiProvider();
}

function syncActiveProviderTerminalShell(kind) {
  const active = ["codex", "gemini", "claude", "oanda"].includes(kind) ? kind : "codex";
  [
    ["codex", codexProviderTerminal],
    ["gemini", geminiProviderTerminal],
    ["claude", claudeProviderTerminal],
    ["oanda", oandaProviderTerminal],
  ].forEach(([name, shell]) => {
    if (!shell) return;
    const on = name === active;
    shell.hidden = !on;
    shell.classList.toggle("is-active", on);
    shell.setAttribute("aria-hidden", on ? "false" : "true");
  });
}

function setActiveProviderWorkbench(kind, options = {}) {
  const normalized = ["codex", "gemini", "claude", "oanda"].includes(kind) ? kind : "codex";
  activeProviderWorkbench = normalized;
  try { localStorage.setItem("forge.provider.workbench.active", normalized); } catch (_) {}
  if (isTradingBrokerProvider(normalized)) setActiveTradingBroker(normalized);
  [["codex", providerLauncherCodex], ["gemini", providerLauncherGemini], ["claude", providerLauncherClaude], ["oanda", providerLauncherOanda]].forEach(([name, button]) => {
    const on = name === normalized;
    button?.classList.toggle("active", on);
    button?.setAttribute("aria-selected", on ? "true" : "false");
  });
  syncActiveProviderTerminalShell(normalized);
  if (options.ensureTerminal !== false && normalized !== "oanda") {
    ensureProviderTerminalEmulator(normalized);
  }
  if (normalized === "oanda" && (!oandaProviderTerminalBaseHtml || oandaProviderTerminalPhase === "boot")) {
    startOandaProviderTerminal({ preserveDraft: true });
  }
  renderProviderWorkbench();
  if (options.focusTerminal) {
    requestAnimationFrame(() => {
      const runtime = providerTerminalInstances.get(normalized);
      try {
        runtime?.fitAddon?.fit();
        runtime?.term?.focus();
        void resizeProviderTerminalToFit(normalized);
      } catch (_) {}
    });
    setTimeout(() => {
      const runtime = providerTerminalInstances.get(normalized);
      try {
        runtime?.fitAddon?.fit();
        void resizeProviderTerminalToFit(normalized);
      } catch (_) {}
    }, 60);
  }
}

function renderProviderWorkbench() {
  const kind = activeProviderWorkbench;
  const status = providerWorkbenchStatus(kind);
  if (kind === "oanda") {
    const connected = !!status?.connected;
    const stateText = oandaProviderLauncherState(status);
    const workbenchState = {
      kind,
      label: "OANDA",
      meta: oandaProviderBaseUrlLabel(status),
      stateText,
      logo: "provider-logo-oanda",
      hint: status?.message || "Validate OANDA credentials, then Forge stores them only on this machine in the OS secure store.",
      launchText: connected ? "Replace" : "Restart",
      launchDisabled: false,
    };
    if (!forgeUiShouldRender("provider:workbench", workbenchState)) return;
    if (providerWorkbenchActiveLabel) providerWorkbenchActiveLabel.textContent = "OANDA";
    if (providerWorkbenchActiveMeta) providerWorkbenchActiveMeta.textContent = oandaProviderBaseUrlLabel(status);
    if (providerWorkbenchActiveState) providerWorkbenchActiveState.textContent = stateText;
    if (providerWorkbenchActiveDot) providerWorkbenchActiveDot.dataset.state = stateText;
    if (providerWorkbenchActiveLogo) {
      providerWorkbenchActiveLogo.classList.remove("provider-logo-openai", "provider-logo-gemini", "provider-logo-claude", "provider-logo-oanda");
      providerWorkbenchActiveLogo.classList.add("provider-logo-oanda");
    }
    if (providerWorkbenchHint) {
      providerWorkbenchHint.textContent = status?.message || "Validate OANDA credentials, then Forge stores them only on this machine in the OS secure store.";
    }
    if (providerWorkbenchLaunch) {
      providerWorkbenchLaunch.textContent = connected ? "Replace" : "Restart";
      providerWorkbenchLaunch.disabled = false;
    }
    return;
  }
  const connected = !!status?.connected;
  const installed = providerCliEffectiveInstalled(status);
  const needsNode = providerStatusNeedsNode(status);
  const stateText = providerWorkbenchStateText(status);
  const launchText = connected
    ? "Open"
    : installed
      ? "Repair"
      : needsNode
        ? "Needs Node"
        : "Install";
  const launchDisabled = kind === "codex" ? !installed : false;
  const workbenchState = {
    kind,
    label: providerWorkbenchDisplayName(kind),
    meta: providerWorkbenchModel(kind),
    stateText,
    logo: providerWorkbenchLogoClass(kind),
    hint: providerCliFriendlyHint(kind, status, { selectedModel: providerWorkbenchModel(kind) }),
    launchText,
    launchDisabled,
  };
  if (!forgeUiShouldRender("provider:workbench", workbenchState)) return;
  if (providerWorkbenchActiveLabel) providerWorkbenchActiveLabel.textContent = providerWorkbenchDisplayName(kind);
  if (providerWorkbenchActiveMeta) providerWorkbenchActiveMeta.textContent = providerWorkbenchModel(kind);
  if (providerWorkbenchActiveState) providerWorkbenchActiveState.textContent = stateText;
  if (providerWorkbenchActiveDot) providerWorkbenchActiveDot.dataset.state = stateText;
  if (providerWorkbenchActiveLogo) {
    providerWorkbenchActiveLogo.classList.remove("provider-logo-openai", "provider-logo-gemini", "provider-logo-claude", "provider-logo-oanda");
    providerWorkbenchActiveLogo.classList.add(providerWorkbenchLogoClass(kind));
  }
  if (providerWorkbenchHint) {
    providerWorkbenchHint.textContent = providerCliFriendlyHint(kind, status, { selectedModel: providerWorkbenchModel(kind) });
  }
  if (providerWorkbenchLaunch) {
    providerWorkbenchLaunch.textContent = launchText;
    providerWorkbenchLaunch.disabled = launchDisabled;
  }
}

function renderProviderWorkbenchLauncher(kind, stateText, options = {}) {
  const dom = providerLauncherDom(kind);
  const launcherState = {
    kind,
    meta: providerWorkbenchModel(kind),
    stateText,
    muted: !!options.muted,
  };
  if (!forgeUiShouldRender(`provider:launcher:${kind}`, launcherState)) return;
  if (dom.meta) dom.meta.textContent = providerWorkbenchModel(kind);
  if (dom.state) dom.state.textContent = stateText;
  if (dom.dot) dom.dot.dataset.state = stateText;
  dom.button?.classList.toggle("muted", !!options.muted);
}

function mountProviderWorkbenchTerminals() {
  if (!providerTerminalDeck) return;
  if (geminiProviderTerminal && geminiProviderTerminal.parentElement !== providerTerminalDeck) {
    providerTerminalDeck.appendChild(geminiProviderTerminal);
  }
  if (claudeProviderTerminal && claudeProviderTerminal.parentElement !== providerTerminalDeck) {
    providerTerminalDeck.appendChild(claudeProviderTerminal);
  }
}

function providerTerminalDom(provider) {
  if (provider === "codex") {
    return {
      shell: codexProviderTerminal,
      viewport: codexProviderTerminalViewport,
      output: codexProviderTerminalOutput,
    };
  }
  return provider === "claude"
    ? {
        shell: claudeProviderTerminal,
        viewport: claudeProviderTerminalViewport,
        output: claudeProviderTerminalOutput,
      }
    : {
        shell: geminiProviderTerminal,
        viewport: geminiProviderTerminalViewport,
        output: geminiProviderTerminalOutput,
      };
}

function providerTerminalInvokeName(provider, action) {
  return `${provider}_terminal_${action}`;
}

function providerTerminalXtermGlobals() {
  const TerminalCtor = window.Terminal || window.XTerm?.Terminal || null;
  const FitAddonCtor = window.FitAddon?.FitAddon || null;
  return { TerminalCtor, FitAddonCtor };
}

function setProviderTerminalLiveMode(provider, live) {
  const dom = providerTerminalDom(provider);
  dom.shell?.classList.toggle("terminal-live", !!live);
}

function resetProviderTerminalEmulator(provider, text = "") {
  const runtime = providerTerminalInstances.get(provider);
  if (!runtime?.term) return;
  runtime.term.reset();
  runtime.term.clear();
  providerTerminalLiveHydration[provider] = false;
  if (text) runtime.term.write(providerTerminalReplaySeed(provider, text));
  requestAnimationFrame(() => {
    try {
      runtime.fitAddon?.fit();
      void resizeProviderTerminalToFit(provider);
    } catch (_) {}
  });
}

function writeProviderTerminalEmulator(provider, text = "") {
  const runtime = providerTerminalInstances.get(provider);
  if (!runtime?.term || !text) return;
  providerTerminalLiveHydration[provider] = true;
  runtime.term.write(text);
}

async function resizeProviderTerminalToFit(provider) {
  const runtime = providerTerminalInstances.get(provider);
  const invoke = window.__TAURI__?.core?.invoke;
  if (!runtime?.term || !invoke) return;
  const cols = Math.max(20, Number(runtime.term.cols || 0));
  const rows = Math.max(6, Number(runtime.term.rows || 0));
  try {
    await invoke(providerTerminalInvokeName(provider, "resize"), { cols, rows });
  } catch (_) {}
}

function ensureProviderTerminalEmulator(provider) {
  if (providerTerminalInstances.has(provider)) return providerTerminalInstances.get(provider);
  const { TerminalCtor, FitAddonCtor } = providerTerminalXtermGlobals();
  const dom = providerTerminalDom(provider);
  if (!TerminalCtor || !FitAddonCtor || !dom.viewport) return null;
  const term = new TerminalCtor({
    allowTransparency: false,
    convertEol: false,
    customGlyphs: true,
    drawBoldTextInBrightColors: true,
    minimumContrastRatio: 1,
    rescaleOverlappingGlyphs: true,
    cursorBlink: true,
    cursorStyle: "bar",
    cursorWidth: 1,
    fontFamily: '"Cascadia Mono", Consolas, "SF Mono", monospace',
    fontSize: 12,
    fontWeight: 400,
    fontWeightBold: 600,
    lineHeight: 1.06,
    letterSpacing: 0,
    theme: {
      background: "#000000",
      foreground: "#f3f3ef",
      cursor: "#f3f3ee",
      cursorAccent: "#111111",
      selectionBackground: "rgba(255,255,255,0.16)",
      black: "#000000",
      red: "#ff8b99",
      green: "#8ee88c",
      yellow: "#f5d67b",
      blue: "#7f9dff",
      magenta: "#c59bff",
      cyan: "#86d7ff",
      white: "#d7d7d2",
      brightBlack: "#6f6f6a",
      brightRed: "#ffadb6",
      brightGreen: "#aff3a7",
      brightYellow: "#ffe7a8",
      brightBlue: "#a8bcff",
      brightMagenta: "#d7b8ff",
      brightCyan: "#aae7ff",
      brightWhite: "#ffffff",
    },
    scrollback: 0,
  });
  const fitAddon = new FitAddonCtor();
  term.loadAddon(fitAddon);
  term.open(dom.viewport);
  requestAnimationFrame(() => {
    try {
      fitAddon.fit();
      void resizeProviderTerminalToFit(provider);
    } catch (_) {}
  });
  setTimeout(() => {
    try {
      fitAddon.fit();
      void resizeProviderTerminalToFit(provider);
    } catch (_) {}
  }, 60);
  term.onData((data) => {
    const invoke = window.__TAURI__?.core?.invoke;
    if (!invoke) return;
    void invoke(providerTerminalInvokeName(provider, "send_input"), { input: data }).catch(() => {});
  });
  const observer = new ResizeObserver(() => {
    try {
      fitAddon.fit();
      syncProviderTerminalViewportPlacement(provider);
      void resizeProviderTerminalToFit(provider);
    } catch (_) {}
  });
  observer.observe(dom.viewport);
  dom.output?.addEventListener?.("scroll", () => {
    try {
      syncProviderTerminalViewportPlacement(provider);
    } catch (_) {}
  });
  dom.viewport.addEventListener("mousedown", () => {
    try { term.focus(); } catch (_) {}
  });
  const runtime = { term, fitAddon, observer };
  providerTerminalInstances.set(provider, runtime);
  return runtime;
}

function setCodexProviderTerminalVisible(visible) {
  if (!codexProviderTerminal) return;
  if (visible) {
    setActiveProviderWorkbench("codex", { focusTerminal: true, autoLaunch: false });
  } else {
    codexProviderTerminal.hidden = true;
  }
}

function setCodexProviderTerminalOutput(text) {
  providerTerminalFilterCarry.codex = "";
  codexProviderTerminalOutputCache = filterProviderTerminalDisplayText("codex", text, { flush: true }) || "Ready.";
  renderCliProviderTerminalShell("codex");
  return codexProviderTerminalOutputCache;
}

function appendCodexProviderTerminalOutput(text) {
  const filtered = filterProviderTerminalDisplayText("codex", text);
  if (!filtered) return "";
  codexProviderTerminalOutputCache = `${codexProviderTerminalOutputCache || ""}${filtered}` || "Ready.";
  renderCliProviderTerminalShell("codex");
  return filtered;
}

function renderCodexProviderTerminal(snapshot = {}, options = {}) {
  const resetLiveTerminal = !!options.resetLiveTerminal;
  const running = !!snapshot.running;
  codexProviderTerminalRunning = running;
  const phase = String(snapshot.phase || (running ? "running" : "idle")).trim();
  const message = String(snapshot.message || "").trim();
  const label = message ? `${phase} · ${message}` : phase;
  if (codexProviderTerminalState) codexProviderTerminalState.textContent = label;
  let filteredSnapshotOutput = "";
  if (typeof snapshot.output === "string") {
    filteredSnapshotOutput = setCodexProviderTerminalOutput(snapshot.output);
    const canReplaySnapshot = resetLiveTerminal
      && ensureProviderTerminalEmulator("codex")
      && (!running || !providerTerminalLiveHydration.codex);
    if (canReplaySnapshot) {
      resetProviderTerminalEmulator("codex", filteredSnapshotOutput);
    }
  }
  if (codexProviderTerminalInput) {
    codexProviderTerminalInput.disabled = !snapshot.readyForInput;
    codexProviderTerminalInput.placeholder = snapshot.readyForInput
      ? "Type a command or answer for Codex CLI"
      : running
        ? "Codex is preparing…"
        : "Open Codex in Forge";
  }
  if (codexProviderTerminalSend) codexProviderTerminalSend.disabled = !snapshot.readyForInput;
  if (codexProviderTerminalStop) codexProviderTerminalStop.disabled = !running;
  renderCliProviderTerminalShell("codex");
  setProviderTerminalLiveMode("codex", running);
}

function handleCodexProviderTerminalEvent(payload) {
  const provider = String(payload?.provider || "");
  if (provider !== "codex") return;
  if (typeof payload?.outputDelta === "string" && payload.outputDelta) {
    providerTerminalLiveHydration.codex = true;
    const filteredDelta = appendCodexProviderTerminalOutput(payload.outputDelta);
    if (filteredDelta && activeProviderWorkbench === "codex" && ensureProviderTerminalEmulator("codex")) {
      writeProviderTerminalEmulator("codex", filteredDelta);
    }
  }
  const snapshot = { ...payload };
  delete snapshot.outputDelta;
  renderCodexProviderTerminal(snapshot);
  if (activeProviderWorkbench === "codex") {
    setCodexProviderTerminalVisible(true);
  }
  if (!payload?.running) {
    setTimeout(() => { void refreshProviderWorkbenchStatuses({ silent: true }); }, 900);
  }
}

async function refreshCodexProviderTerminalSnapshot() {
  const invoke = window.__TAURI__?.core?.invoke;
  if (!invoke) return null;
  try {
    const snapshot = await invoke("codex_terminal_snapshot");
    const meaningful = snapshot && (snapshot.running || String(snapshot.phase || "") !== "idle" || String(snapshot.output || "").trim() !== "Ready.");
    if (meaningful && activeProviderWorkbench === "codex") {
      setCodexProviderTerminalVisible(true);
      renderCodexProviderTerminal(snapshot, { resetLiveTerminal: true });
    }
    return snapshot;
  } catch (_) {
    return null;
  }
}

async function startCodexProviderTerminal() {
  const invoke = window.__TAURI__?.core?.invoke;
  if (!invoke) {
    renderCodexProviderStatus({
      connected: false,
      installed: false,
      authSource: "none",
      message: "Open Forge as a Tauri app to launch Codex inside Forge.",
    });
    return;
  }
  setProviderTerminalOpening("codex", true);
  setCodexProviderTerminalVisible(true);
  resetProviderTerminalEmulator("codex");
  renderCodexProviderTerminal({
    running: true,
    readyForInput: false,
    phase: "opening",
    message: "Preparing Codex CLI",
    output: codexProviderTerminalOutputCache,
  });
  try {
    const snapshot = await invoke("codex_terminal_start");
    renderCodexProviderTerminal(snapshot || {}, { resetLiveTerminal: false });
  } finally {
    setProviderTerminalOpening("codex", false);
  }
}

async function sendCodexProviderTerminalInput() {
  const invoke = window.__TAURI__?.core?.invoke;
  const input = String(codexProviderTerminalInput?.value || "").trim();
  if (!invoke || !input) return;
  codexProviderTerminalInput.value = "";
  if (!providerTerminalInstances.get("codex")) {
    appendCodexProviderTerminalOutput(`\n> ${input}\n`);
  }
  try {
    await invoke("codex_terminal_send_input", { input: `${input}\r` });
  } catch (err) {
    appendCodexProviderTerminalOutput(`\n[forge] input failed: ${err}\n`);
    void refreshCodexProviderTerminalSnapshot();
  }
}

async function stopCodexProviderTerminal() {
  const invoke = window.__TAURI__?.core?.invoke;
  if (!invoke) return;
  try {
    const snapshot = await invoke("codex_terminal_stop");
    renderCodexProviderTerminal(snapshot || {}, { resetLiveTerminal: true });
  } catch (err) {
    appendCodexProviderTerminalOutput(`\n[forge] stop failed: ${err}\n`);
  }
}

