function openProviderOverlay(options = {}) {
  if (!providerOverlay) return;
  if (libraryOverlay && !libraryOverlay.hidden) closeLibraryOverlay();
  if (mcpOverlay && !mcpOverlay.hidden) closeMcpOverlay();
  if (typeof programsOverlay !== "undefined" && programsOverlay && !programsOverlay.hidden) closeProgramsOverlay();
  if (docsOverlay && !docsOverlay.hidden) closeDocsOverlay();
  const selectedProvider = options?.provider || activeProviderWorkbench || "codex";
  providerOverlay.hidden = false;
  mountProviderWorkbenchTerminals();
  hydrateProviderModelPickers();
  if (!oandaProviderTerminalBaseHtml || oandaProviderTerminalPhase === "boot") startOandaProviderTerminal({ preserveDraft: true });
  setTopbarProviderMode(true);
  void refreshProviderWorkbenchStatuses().then(() => maybeAutoLaunchProviderWorkbench(selectedProvider));
  setActiveProviderWorkbench(selectedProvider);
  if (options?.focus === "voice") {
    setTimeout(() => {
      const card = document.getElementById("providerVoiceCard");
      card?.scrollIntoView?.({ block: "center", behavior: "smooth" });
      card?.classList.add("provider-card-focus");
      setTimeout(() => card?.classList.remove("provider-card-focus"), 1600);
      voiceElevenApiKey?.focus?.();
    }, 80);
  }
}

function closeProviderOverlay() {
  if (providerOverlay) providerOverlay.hidden = true;
  setTopbarProviderMode(false);
}

if (providerClose) providerClose.addEventListener("click", closeProviderOverlay);
if (providerOverlay) providerOverlay.addEventListener("mousedown", (event) => {
  if (providerOverlay.hidden) return;
  const target = event.target;
  if (!(target instanceof Node)) return;
  if (providerWorkbench?.contains(target)) return;
  closeProviderOverlay();
});
if (providerLauncherCodex) providerLauncherCodex.addEventListener("click", () => {
  setActiveProviderWorkbench("codex", { focusTerminal: true });
  void maybeAutoLaunchProviderWorkbench("codex");
});
if (providerLauncherGemini) providerLauncherGemini.addEventListener("click", () => {
  setActiveProviderWorkbench("gemini", { focusTerminal: true });
  void maybeAutoLaunchProviderWorkbench("gemini");
});
if (providerLauncherClaude) providerLauncherClaude.addEventListener("click", () => {
  setActiveProviderWorkbench("claude", { focusTerminal: true });
  void maybeAutoLaunchProviderWorkbench("claude");
});
if (providerLauncherOanda) providerLauncherOanda.addEventListener("click", () => {
  setActiveProviderWorkbench("oanda", { focusTerminal: true, ensureTerminal: false });
  void maybeAutoLaunchProviderWorkbench("oanda");
});
if (providerWorkbenchLaunch) providerWorkbenchLaunch.addEventListener("click", () => {
  if (activeProviderWorkbench === "codex") void connectCodexProvider();
  else if (activeProviderWorkbench === "claude") void connectClaudeProvider();
  else if (activeProviderWorkbench === "oanda") startOandaProviderTerminal();
  else void connectGeminiProvider();
});
if (providerWorkbenchRefresh) providerWorkbenchRefresh.addEventListener("click", () => {
  void refreshProviderWorkbenchStatuses();
});
startProviderAutoHealRobot();
if (openAiProviderRefresh) openAiProviderRefresh.addEventListener("click", () => {
  void refreshOpenAiProviderStatus();
  void refreshCliProviderStatuses();
  void refreshOandaProviderStatus();
  void refreshVoiceProviderStatus();
});
if (oandaProviderTerminalSend) oandaProviderTerminalSend.addEventListener("click", () => {
  void submitOandaProviderTerminalInput();
});
if (oandaProviderTerminalReset) oandaProviderTerminalReset.addEventListener("click", () => {
  startOandaProviderTerminal();
  focusOandaProviderTerminalField(oandaProviderTerminalPhase === "post" ? "post" : oandaProviderTerminalActiveField);
});
if (oandaProviderTerminalOutput) oandaProviderTerminalOutput.addEventListener("click", (event) => {
  const actionEl = event.target instanceof Element ? event.target.closest("[data-oanda-action]") : null;
  const action = actionEl?.getAttribute?.("data-oanda-action");
  if (action === "validate" && !oandaProviderTerminalBusy) {
    void submitOandaProviderTerminalInput("1");
    return;
  }
  const fieldButton = event.target instanceof Element ? event.target.closest("[data-oanda-field]") : null;
  if (!fieldButton) return;
  const field = fieldButton.getAttribute("data-oanda-field");
  if (!field || oandaProviderTerminalBusy || oandaProviderTerminalPhase !== "editing") return;
  focusOandaProviderTerminalField(field);
});
if (oandaProviderTerminalOutput) oandaProviderTerminalOutput.addEventListener("scroll", () => {
  syncOandaProviderTerminalScrollbar();
});
if (oandaProviderTerminalOutput) oandaProviderTerminalOutput.addEventListener("input", (event) => {
  const editable = event.target instanceof Element ? event.target.closest("[data-oanda-input]") : null;
  if (!editable) return;
  const field = editable.getAttribute("data-oanda-input");
  if (!field) return;
  oandaProviderTerminalActiveField = field;
  oandaProviderTerminalMaskedCarry[field] = false;
  setOandaProviderFieldValue(field, editable.value || "");
});
if (oandaProviderTerminalOutput) oandaProviderTerminalOutput.addEventListener("focusin", (event) => {
  const editable = event.target instanceof Element ? event.target.closest("[data-oanda-input]") : null;
  if (!editable) return;
  const field = editable.getAttribute("data-oanda-input");
  if (!field) return;
  oandaProviderTerminalActiveField = field;
});
if (oandaProviderTerminalOutput) oandaProviderTerminalOutput.addEventListener("contextmenu", (event) => {
  const editable = event.target instanceof Element ? event.target.closest("[data-oanda-input]") : null;
  if (!editable) return;
  const field = editable.getAttribute("data-oanda-input");
  if (field === "apiKey" || field === "accountId" || field === "baseUrl") return;
  event.preventDefault();
});
if (oandaProviderTerminalOutput) oandaProviderTerminalOutput.addEventListener("keydown", (event) => {
  if (oandaProviderTerminalBusy) return;
  const isValidateHotkey = isOandaDigitOneHotkey(event);
  const editable = event.target instanceof Element ? event.target.closest("[data-oanda-input]") : null;
  if (editable) {
    const field = editable.getAttribute("data-oanda-input");
    if (!field) return;
    if (
      oandaProviderTerminalMaskedCarry[field]
      && !event.ctrlKey
      && !event.metaKey
      && !event.altKey
      && (
        event.key.length === 1
        || event.key === "Backspace"
        || event.key === "Delete"
      )
    ) {
      editable.value = "";
      oandaProviderTerminalDraft[field] = "";
      oandaProviderTerminalMaskedCarry[field] = false;
    }
    if (
      isValidateHotkey
      && !event.ctrlKey
      && !event.metaKey
      && !event.altKey
      && oandaProviderTerminalAllFieldsReady()
    ) {
      event.preventDefault();
      setOandaProviderFieldValue(field, editable.value || "");
      oandaProviderTerminalActiveField = "validate";
      void submitOandaProviderTerminalInput("1");
      return;
    }
    if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "v") {
      if (field === "apiKey" || field === "accountId" || field === "baseUrl") return;
      event.preventDefault();
      event.stopPropagation();
      return;
    }
    if (event.key === "Enter") {
      event.preventDefault();
      const rawValue = normalizedOandaEditableText(editable.value || "");
      setOandaProviderFieldValue(field, rawValue);
      if (!rawValue.trim()) {
        void typeOandaTerminalLog(`Missing ${oandaProviderTerminalFieldMeta(field).label}.`, "error");
        focusOandaProviderTerminalField(field);
        return;
      }
      if (field === "baseUrl" && oandaProviderTerminalAllFieldsReady()) {
        oandaProviderTerminalActiveField = "validate";
        void submitOandaProviderTerminalInput("1");
        return;
      }
      const nextField = oandaProviderTerminalNextField(field);
      renderOandaProviderTerminal();
      focusOandaProviderTerminalField(nextField);
    }
    return;
  }
  if (oandaProviderTerminalPhase === "editing" && oandaProviderTerminalActiveField === "validate" && isValidateHotkey) {
    event.preventDefault();
    void submitOandaProviderTerminalInput("1");
    return;
  }
  if (oandaProviderTerminalPhase === "post" && (isValidateHotkey || isOandaDigitTwoHotkey(event))) {
    event.preventDefault();
    void submitOandaProviderTerminalInput(isValidateHotkey ? "1" : "2");
  }
});
if (oandaProviderTerminalOutput) oandaProviderTerminalOutput.addEventListener("paste", (event) => {
  const editable = event.target instanceof Element ? event.target.closest("[data-oanda-input]") : null;
  if (!editable) return;
  const field = editable.getAttribute("data-oanda-input");
  if (field === "apiKey" || field === "accountId" || field === "baseUrl") return;
  event.preventDefault();
});
if (oandaProviderTerminalScrollbar && oandaProviderTerminalScrollbarThumb && oandaProviderTerminalOutput) {
  oandaProviderTerminalScrollbar.addEventListener("pointerdown", (event) => {
    if (oandaProviderTerminalScrollbar.classList.contains("is-hidden")) return;
    const railRect = oandaProviderTerminalScrollbar.getBoundingClientRect();
    const thumbRect = oandaProviderTerminalScrollbarThumb.getBoundingClientRect();
    const maxScrollTop = Math.max(oandaProviderTerminalOutput.scrollHeight - oandaProviderTerminalOutput.clientHeight, 0);
    if (maxScrollTop <= 0) return;
    if (event.target === oandaProviderTerminalScrollbarThumb) {
      oandaProviderTerminalScrollbarDrag = {
        pointerId: event.pointerId,
        startY: event.clientY,
        startScrollTop: oandaProviderTerminalOutput.scrollTop,
      };
      oandaProviderTerminalScrollbarThumb.classList.add("is-dragging");
      oandaProviderTerminalScrollbarThumb.setPointerCapture?.(event.pointerId);
      event.preventDefault();
      return;
    }
    const thumbHeight = thumbRect.height || 32;
    const offset = Math.min(Math.max(event.clientY - railRect.top - (thumbHeight / 2), 0), Math.max(railRect.height - thumbHeight, 0));
    const ratio = railRect.height > thumbHeight ? offset / (railRect.height - thumbHeight) : 0;
    oandaProviderTerminalOutput.scrollTop = ratio * maxScrollTop;
    syncOandaProviderTerminalScrollbar();
    event.preventDefault();
  });
  window.addEventListener("pointermove", (event) => {
    if (!oandaProviderTerminalScrollbarDrag) return;
    const railHeight = oandaProviderTerminalScrollbar.clientHeight;
    const thumbHeight = oandaProviderTerminalScrollbarThumb.getBoundingClientRect().height || 32;
    const maxScrollTop = Math.max(oandaProviderTerminalOutput.scrollHeight - oandaProviderTerminalOutput.clientHeight, 0);
    const travel = Math.max(railHeight - thumbHeight, 1);
    const deltaY = event.clientY - oandaProviderTerminalScrollbarDrag.startY;
    const deltaRatio = deltaY / travel;
    oandaProviderTerminalOutput.scrollTop = oandaProviderTerminalScrollbarDrag.startScrollTop + (deltaRatio * maxScrollTop);
    syncOandaProviderTerminalScrollbar();
  });
  window.addEventListener("pointerup", (event) => {
    if (!oandaProviderTerminalScrollbarDrag) return;
    if (oandaProviderTerminalScrollbarDrag.pointerId === event.pointerId) {
      oandaProviderTerminalScrollbarThumb.classList.remove("is-dragging");
      oandaProviderTerminalScrollbarDrag = null;
    }
  });
  window.addEventListener("resize", () => {
    window.requestAnimationFrame(syncOandaProviderTerminalScrollbar);
  });
}
