// Compact per-axis labels per mode (drawn directly on the gizmo branches).
const ALPHA_3D_AXIS_META = {
  candles3d: { x: "time", y: "pressure", z: "tick volume" },
  phase:     { x: "price[t]", y: "price[t+τ]", z: "price[t+2τ]" },
  heightmap: { x: "time", y: "density", z: "price" },
  manifold:  { x: "ret 5", y: "vol 20", z: "ret 20" },
  lattice:   { x: "hash a", y: "hash b", z: "hash c" },
};

const alpha3dGizmoAxes = document.getElementById("alpha3dGizmoAxes");

function alpha3dCurrentAxisLabels() {
  const meta = ALPHA_3D_AXIS_META[alpha3dState.mode] || ALPHA_3D_AXIS_META.candles3d;
  return { x: meta.x, y: meta.y, z: meta.z };
}

function updateAlpha3dGizmo() {
  if (!alpha3dGizmoAxes) return;
  const yaw = alpha3dState.camera.yaw;
  const pitch = alpha3dState.camera.pitch;
  const dist = Math.max(1, alpha3dState.camera.dist || 2.15);
  const cosY = Math.cos(yaw);
  const sinY = Math.sin(yaw);
  const cosP = Math.cos(pitch);
  const sinP = Math.sin(pitch);
  const eye = [
    dist * cosP * cosY,
    dist * cosP * sinY,
    dist * sinP,
  ];
  const view = alpha3dLookAt(eye, [0, 0, 0], [0, 0, 1]);

  const R = 36;
  const project = (vx, vy, vz) => ({
    x: alpha3dMulMat4Vec4(view, [vx, vy, vz, 1])[0] * R,
    y: -alpha3dMulMat4Vec4(view, [vx, vy, vz, 1])[1] * R,
    depth: alpha3dMulMat4Vec4(view, [vx, vy, vz, 1])[2],
  });

  const axes = [
    { id: "x", v: project(1, 0, 0), label: "X" },
    { id: "y", v: project(0, 1, 0), label: "Y" },
    { id: "z", v: project(0, 0, 1), label: "Z" },
  ];
  // Back-to-front so the closest branch ends on top
  axes.sort((a, b) => a.v.depth - b.v.depth);

  const ns = "http://www.w3.org/2000/svg";
  alpha3dGizmoAxes.innerHTML = "";
  for (const a of axes) {
    const line = document.createElementNS(ns, "line");
    line.setAttribute("class", `gz-line axis-${a.id}`);
    line.setAttribute("x1", "0"); line.setAttribute("y1", "0");
    line.setAttribute("x2", a.v.x.toFixed(2));
    line.setAttribute("y2", a.v.y.toFixed(2));
    alpha3dGizmoAxes.appendChild(line);

    // Place the label slightly past the branch tip, along its direction.
    const len = Math.hypot(a.v.x, a.v.y) || 1;
    const tx = a.v.x + (a.v.x / len) * 11;
    const ty = a.v.y + (a.v.y / len) * 11;
    const txt = document.createElementNS(ns, "text");
    txt.setAttribute("class", `gz-label axis-${a.id}`);
    txt.setAttribute("x", tx.toFixed(2));
    txt.setAttribute("y", ty.toFixed(2));
    txt.textContent = a.label;
    alpha3dGizmoAxes.appendChild(txt);
  }
}

function updateAlpha3dAxisLabels() {
  // Labels live directly on the gizmo; refresh next frame.
  updateAlpha3dGizmo();
}

function updateAlpha3dLegend() {
  // Kept for backwards compat — now a no-op since the gizmo replaces the panel.
  if (!alpha3dLegend) return;
  const cfg = ALPHA_3D_LEGEND[alpha3dState.mode] || ALPHA_3D_LEGEND.candles3d;
  alpha3dLegendTitle.textContent = cfg.title;
  alpha3dLegendDesc.textContent  = cfg.desc;
  alpha3dLegendAxes.innerHTML = "";
  // For candles3d, override Z label with the active Z metric
  const isCandles = alpha3dState.mode === "candles3d";
  const zMeta = isCandles ? ALPHA_3D_Z_METRICS[alpha3dState.zMetric] : null;
  for (const k of ["x", "y", "z"]) {
    const dt = document.createElement("dt");
    dt.className = `axis-${k}`;
    dt.textContent = cfg[k].label;
    const dd = document.createElement("dd");
    dd.textContent = (k === "z" && zMeta) ? zMeta.short : cfg[k].text;
    alpha3dLegendAxes.appendChild(dt);
    alpha3dLegendAxes.appendChild(dd);
  }
  alpha3dLegendColor.innerHTML = "";
  for (const item of cfg.colors) {
    const sw = document.createElement("span");
    sw.className = "swatch";
    sw.style.background = item.swatch;
    const lab = document.createElement("span");
    lab.textContent = item.label;
    alpha3dLegendColor.appendChild(sw);
    alpha3dLegendColor.appendChild(lab);
    alpha3dLegendColor.appendChild(document.createTextNode("  "));
  }
  const candles = alphaDocState?.candles || [];
  const n = candles.length;
  const metaTail = isCandles && zMeta ? `Z: ${zMeta.label} · ${cfg.meta}` : cfg.meta;
  alpha3dLegendMeta.textContent = `${metaTail} · ${n.toLocaleString()} bars`;
}

function alpha3dModeLabel(mode = alpha3dState.mode) {
  const cfg = ALPHA_3D_LEGEND[mode] || ALPHA_3D_LEGEND.candles3d;
  return cfg?.title || mode || "3D view";
}

function selectedAlpha3dModeArtifact(mode = alpha3dState.mode) {
  const manifest = selectedForgeJobManifest || {};
  const artifacts = Array.isArray(manifest.artifacts_3d)
    ? manifest.artifacts_3d
    : Array.isArray(manifest.mcp_result?.artifacts_3d)
      ? manifest.mcp_result.artifacts_3d
      : [];
  return artifacts.find((artifact) => String(artifact?.mode || "") === String(mode)) || null;
}

function alpha3dSelectionSummary() {
  const sel = alpha3dState?.selection || null;
  if (!sel) return null;
  const artifact = selectedAlpha3dModeArtifact(sel.mode);
  const mapping = selectedVisualMappingSummary();
  return {
    mode: sel.mode,
    vertex_index: sel.vertexIndex,
    point_index: sel.pointIndex,
    bar_index: sel.barIndex,
    cell: sel.cell || null,
    role: sel.role || null,
    value: sel.value || null,
    world: sel.world || null,
    screen: sel.screen || null,
    artifact_hash: artifact?.hash || null,
    artifact_path: artifact?.path || null,
    mapping_hash: mapping?.hash || null,
    mapping_path: mapping?.path || null,
    selected_at_ms: sel.selectedAtMs || null,
  };
}

function alpha3dResultMetricChips(manifest, job) {
  const chips = [];
  const status = job?.status || manifest.status || alphaRunState.phase || "idle";
  if (status) chips.push(["Status", status]);
  const bars = manifest.bars || job?.bars || alphaDocState.candles.length;
  if (bars) chips.push(["Bars", formatCount(bars)]);
  const holdout = manifest.holdout || {};
  if (holdout.target_hit_pct != null) chips.push(["Holdout", `${Number(holdout.target_hit_pct).toFixed(1)}%`]);
  if (holdout.trades != null) chips.push(["Trades", formatCount(holdout.trades)]);
  const report = alphaRunState.report || {};
  const pnl = manifest.holdout_total_pnl_points ?? report.holdout_total_pnl_points;
  if (pnl != null && Number.isFinite(Number(pnl))) chips.push(["PnL", `${Number(pnl).toFixed(2)} pts`]);
  const programHash = manifest.program_hash || manifest.strategy_hash || report.strategy_hash;
  if (programHash) chips.push(["Hash", shortHash(programHash)]);
  const selection = alpha3dSelectionSummary();
  if (selection) {
    const pick = selection.bar_index != null
      ? `bar ${formatCount(selection.bar_index)}`
      : selection.cell
        ? `cell ${selection.cell}`
        : `pt ${formatCount(selection.point_index ?? selection.vertex_index)}`;
    chips.push(["Pick", pick]);
  }
  return chips.slice(0, 5);
}

function updateAlpha3dResultOverlay() {
  if (!alpha3dResultOverlay) return;
  const manifest = selectedForgeJobManifest || {};
  const job = currentForgeJob();
  const mapping = selectedVisualMappingSummary();
  const artifact = selectedAlpha3dModeArtifact(alpha3dState.mode);
  const cfg = ALPHA_3D_LEGEND[alpha3dState.mode] || ALPHA_3D_LEGEND.candles3d;
  alpha3dResultOverlay.innerHTML = "";
  alpha3dResultOverlay.classList.toggle("has-mapping", !!mapping.available);
  alpha3dResultOverlay.classList.remove("is-running");

  const bars = alphaDocState?.candles?.length || 0;
  const parts = [];
  parts.push(mapping.available ? alpha3dModeLabel() : "Default");
  if (bars) parts.push(`${formatCount(bars)} bars`);
  if (mapping.available && mapping.hash) parts.push(`map ${shortHash(mapping.hash)}`);
  const selection = alpha3dSelectionSummary();
  if (selection) {
    const sel = selection.bar_index != null
      ? `bar ${formatCount(selection.bar_index)}`
      : selection.cell
        ? `cell ${selection.cell}`
        : `pt ${formatCount(selection.point_index ?? selection.vertex_index)}`;
    parts.push(sel);
  }
  alpha3dResultOverlay.appendChild(createUiEl("span", "alpha-3d-result-line", parts.join(" · ")));
}

